INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jaxxstorm/landlord/openspec-onboard', 'community', 'jaxxstorm', 'landlord', 'jaxxstorm/landlord', 'openspec-onboard', 0, 0, 47, '2026-03-08T01:57:15.385Z', '2026-03-08T02:05:49.047Z', 'f764e94014ec70ccd261ab580debbaa6ce74eff2877bffc80734e64fb70bb397', '{"id":"jaxxstorm/landlord/openspec-onboard","name":"openspec-onboard","description":{"en":"The openspec-onboard skill guides users through their first OpenSpec workflow cycle, explaining each step while performing real work in their codebase, benefiting developers and project owners.","zh":"openspec-onboard 是一个技术指导，帮助用户完成 OpenSpec 工作流循环，包括初始化和各阶段工作","ja":"openspec-onboard は、OpenSpec ワークフローを完了するための技術ガイドです。初期化と各段階の作業を含みます","ko":"openspec-onboard 는 OpenSpec 워크플로우 사이클을 완료하는 기술 가이드입니다. 초기화 및 단계별 작업을 포함합니다","es":"El agente openspec-onboard guía al usuario a través de su primer ciclo de trabajo completo de OpenSpec. Incluye la inicialización de OpenSpec y la ejecución de comandos de CLI.","fr":"L''agent openspec-onboard guide l''utilisateur à travers son premier cycle de travail complet d''OpenSpec. Il inclut l''initialisation d''OpenSpec et l''exécution de commandes de CLI.","de":"Der Agent openspec-onboard führt den Benutzer durch seinen ersten vollständigen OpenSpec-Arbeitszyklus. Enthält die Initialisierung von OpenSpec und die Ausführung von CLI-Befehlen.","pt":"O openspec-onboard é um guia de configuração que ajuda os desenvolvedores a inicializar o OpenSpec e executar seu primeiro ciclo de trabalho.","ru":"openspec-onboard - это руководство по настройке, которое помогает разработчикам инициализировать OpenSpec и выполнить свой первый рабочий цикл.","ar":"openspec-onboard هو دليل إعداد يساعد المطورين على تهيئة OpenSpec و تشغيل دورة عملهم الأولى."},"seo":{"title":{"en":"openspec-onboard: Onboarding Guide for AI Agents | AI Age...","zh":"openspec-onboard 设置指南 - AI 工具","ja":"openspec-onboard セットアップガイド - AI エージェント","ko":"openspec-onboard 설정 가이드 - AI 에이전트","es":"Guía de configuración de openspec-onboard para desarrolla...","fr":"Guide d''intégration openspec-onboard pour les développeurs","de":"Einrichtungsleitfaden für openspec-onboard-Entwickler","pt":"Guia de Configuração do openspec-onboard","ru":"Настройка openspec-onboard: ИИ Агенты для разработчиков","ar":"دليل إعداد openspec-onboard: أدوات ذكاء اصطناعي لل مطورين"},"description":{"en":"Get started with openspec-onboard and discover how to guide users through their first complete OpenSpec workflow cycle - learn more and initiate setup now","zh":"通过 openspec-onboard 技术指导，完成 OpenSpec 工作流循环，学习初始化和阶段性工作","ja":"openspec-onboard を使用して OpenSpec ワークフローを完了し、初期化と各段階の作業について学びます","ko":"openspec-onboard 기술을 통해 OpenSpec 워크플ロー 사이클을 완료하고 초기화 및 단계별 작업을 배우세요","es":"Aprende a configurar openspec-onboard con nuestra guía paso a paso para desarrolladores. Incluye comandos de CLI y mejores prácticas.","fr":"Découvrez comment configurer openspec-onboard avec notre guide étape par étape pour les développeurs. Inclut des commandes CLI et des meilleures pratiques.","de":"Erfahren Sie, wie Sie openspec-onboard mit unserem Schritt-für-Schritt-Leitfaden für Entwickler konfigurieren. Enthält CLI-Befehle und Best Practices.","pt":"Aprenda a configurar o openspec-onboard com nosso guia passo a passo. Inicialize OpenSpec e execute seu primeiro ciclo de trabalho.","ru":"Узнайте, как настроить openspec-onboard с нашей пошаговой инструкцией. Инициализируйте OpenSpec и выполните свой первый рабочий цикл.","ar":"تعلم كيفية إعداد openspec-onboard مع دليلنا خطوة بخطوة. قم بتهيئة OpenSpec و قم بتشغيل دورة عملك الأولى."},"definition":{"en":"openspec-onboard is a skill that assists in initializing and setting up OpenSpec in a project, walking users through a complete workflow cycle.","zh":"openspec-onboard 是一种 AI 工具，指导用户完成 OpenSpec 工作流循环","ja":"openspec-onboard は、OpenSpec ワークフローを完了するための AI エージェントです","ko":"openspec-onboard 는 OpenSpec 워크플로우 사이클을 완료하는 AI 에이전트입니다","es":"openspec-onboard es un agente de inteligencia artificial que ayuda a los desarrolladores a configurar y utilizar OpenSpec en su proyecto.","fr":"openspec-onboard est un agent d''intelligence artificielle qui aide les développeurs à configurer et à utiliser OpenSpec dans leur projet.","de":"openspec-onboard ist ein KI-Agent, der Entwicklern hilft, OpenSpec in ihrem Projekt zu konfigurieren und zu verwenden.","pt":"O openspec-onboard é um recurso que guia os desenvolvedores através do primeiro ciclo de trabalho do OpenSpec.","ru":"openspec-onboard - это функция, которая проводит разработчиков через первый рабочий цикл OpenSpec.","ar":"openspec-onboard هو ميزة توجيه المطورين خلال دورة العمل الأولى من OpenSpec."},"features":{"en":["Checks OpenSpec initialization status using `openspec status --json` command","Provides guidance on running `openspec init` for project setup","Explains each step of the OpenSpec workflow cycle","Performs real work in the user''s codebase during the onboarding process","Handles conditional logic for uninitialized OpenSpec projects"],"zh":["检查 OpenSpec 初始化状态","运行 openspec init 命令进行初始化","完成 OpenSpec 工作流循环","使用 openspec status 命令检查状态","支持 JSON 输出","阶段性工作指导"],"ja":["OpenSpec の初期化状態を確認する","openspec init コマンドを実行して初期化する","OpenSpec ワークフローを完了する","openspec status コマンドを使用して状態を確認する","JSON 出力をサポートする","各段階の作業をガイドする"],"ko":["OpenSpec 초기화 상태 확인","openspec init 명령어로 초기화","OpenSpec 워크플로우 사이클 완료","openspec status 명령어로 상태 확인","JSON 출력 지원","단계별 작업 가이드"],"es":["Inicialización de OpenSpec con el comando `openspec init`","Ejecución de comandos de CLI para verificar el estado de OpenSpec","Guía paso a paso para el ciclo de trabajo de OpenSpec","Compatibilidad con la línea de comandos para una integración fluida","Soporte para desarrolladores en la configuración y uso de OpenSpec"],"fr":["Initialisation d''OpenSpec avec la commande `openspec init`","Exécution de commandes de CLI pour vérifier l''état d''OpenSpec","Guide étape par étape pour le cycle de travail d''OpenSpec","Compatibilité avec la ligne de commande pour une intégration fluide","Support pour les développeurs dans la configuration et l''utilisation d''OpenSpec"],"de":["Initialisierung von OpenSpec mit dem Befehl `openspec init`","Ausführung von CLI-Befehlen zum Überprüfen des OpenSpec-Status","Schritt-für-Schritt-Anleitung für den OpenSpec-Arbeitszyklus","Kompatibilität mit der Kommandozeile für eine nahtlose Integration","Unterstützung für Entwickler bei der Konfiguration und Verwendung von OpenSpec"],"pt":["Verificação de inicialização do OpenSpec","Execução do comando `openspec init`","Ciclo de trabalho do OpenSpec","Uso do comando `openspec status --json`"],"ru":["Проверка инициализации OpenSpec","Выполнение команды `openspec init`","Рабочий цикл OpenSpec","Использование команды `openspec status --json`"],"ar":["التحقق من تهيئة OpenSpec","تشغيل الأمر `openspec init`","دورة العمل من OpenSpec","استخدام الأمر `openspec status --json`"]},"keywords":{"en":["how to use openspec-onboard","openspec-onboard setup guide","what is openspec-onboard","openspec-onboard alternative","openspec-onboard vs openspec","openspec-onboard install","openspec workflow cycle","openspec initialization","openspec project setup"],"zh":["openspec-onboard","AI 工具","OpenSpec","工作流循环","初始化","openspec init","openspec status","JSON 输出"],"ja":["openspec-onboard","AI エージェント","OpenSpec","ワークフロー","初期化","openspec init","openspec status","JSON 出力"],"ko":["openspec-onboard","AI 에이전트","OpenSpec","워크플로우","초기화","openspec init","openspec status","JSON 출력"],"es":["openspec-onboard","configuración de openspec","guía de openspec","comandos de CLI","desarrollo de software","herramientas de inteligencia artificial","agentes de IA para desarrolladores","openspec para desarrolladores","configuración de proyectos"],"fr":["openspec-onboard","configuration d''openspec","guide d''openspec","commandes de CLI","développement de logiciels","outils d''intelligence artificielle","agents d''IA pour les développeurs","openspec pour les développeurs","configuration de projets"],"de":["openspec-onboard","Konfiguration von OpenSpec","Anleitung für OpenSpec","CLI-Befehle","Software-Entwicklung","KI-Tools","KI-Agenten für Entwickler","OpenSpec für Entwickler","Projekt-Konfiguration"],"pt":["openspec-onboard","configuração do openspec","guia de configuração","OpenSpec","desenvolvedores","ciclo de trabalho","comandos CLI"],"ru":["openspec-onboard","настройка openspec","руководство по настройке","OpenSpec","разработчики","рабочий цикл","команды CLI","ИИ Агенты"],"ar":["openspec-onboard","إعداد openspec","دليل الإعداد","OpenSpec","مطورين","دورة العمل","أوامر CLI","أدوات ذكاء اصطناعي"]}},"owner":"jaxxstorm","repo":"landlord","repoPath":"jaxxstorm/landlord","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.385Z","topics":[],"category":"community","skillMd":{"name":"openspec-onboard","description":"Guided onboarding for OpenSpec - walk through a complete workflow cycle with narration and real codebase work.","version":"1.0","bodyPreview":"Guide the user through their first complete OpenSpec workflow cycle. This is a teaching experience—you''ll do real work in their codebase while explaining each step.\n\n---\n\n## Preflight\n\nBefore starting, check if OpenSpec is initialized:\n\n```bash\nopenspec status --json 2>&1 || echo \"NOT_INITIALIZED\"\n```\n\n**If not initialized:**\n> OpenSpec isn''t set up in this project yet. Run `openspec init` first, then come back to `/opsx:onboard`.\n\nStop here if not initialized.\n\n---\n\n## Phase 1: Welcome\n\nDisplay","body":"Guide the user through their first complete OpenSpec workflow cycle. This is a teaching experience—you''ll do real work in their codebase while explaining each step.\n\n---\n\n## Preflight\n\nBefore starting, check if OpenSpec is initialized:\n\n```bash\nopenspec status --json 2>&1 || echo \"NOT_INITIALIZED\"\n```\n\n**If not initialized:**\n> OpenSpec isn''t set up in this project yet. Run `openspec init` first, then come back to `/opsx:onboard`.\n\nStop here if not initialized.\n\n---\n\n## Phase 1: Welcome\n\nDisplay:\n\n```\n## Welcome to OpenSpec!\n\nI''ll walk you through a complete change cycle—from idea to implementation—using a real task in your codebase. Along the way, you''ll learn the workflow by doing it.\n\n**What we''ll do:**\n1. Pick a small, real task in your codebase\n2. Explore the problem briefly\n3. Create a change (the container for our work)\n4. Build the artifacts: proposal → specs → design → tasks\n5. Implement the tasks\n6. Archive the completed change\n\n**Time:** ~15-20 minutes\n\nLet''s start by finding something to work on.\n```\n\n---\n\n## Phase 2: Task Selection\n\n### Codebase Analysis\n\nScan the codebase for small improvement opportunities. Look for:\n\n1. **TODO/FIXME comments** - Search for `TODO`, `FIXME`, `HACK`, `XXX` in code files\n2. **Missing error handling** - `catch` blocks that swallow errors, risky operations without try-catch\n3. **Functions without tests** - Cross-reference `src/` with test directories\n4. **Type issues** - `any` types in TypeScript files (`: any`, `as any`)\n5. **Debug artifacts** - `console.log`, `console.debug`, `debugger` statements in non-debug code\n6. **Missing validation** - User input handlers without validation\n\nAlso check recent git activity:\n```bash\ngit log --oneline -10 2>/dev/null || echo \"No git history\"\n```\n\n### Present Suggestions\n\nFrom your analysis, present 3-4 specific suggestions:\n\n```\n## Task Suggestions\n\nBased on scanning your codebase, here are some good starter tasks:\n\n**1. [Most promising task]**\n   Location: `src/path/to/file.ts:42`\n   Scope: ~1-2 files, ~20-30 lines\n   Why it''s good: [brief reason]\n\n**2. [Second task]**\n   Location: `src/another/file.ts`\n   Scope: ~1 file, ~15 lines\n   Why it''s good: [brief reason]\n\n**3. [Third task]**\n   Location: [location]\n   Scope: [estimate]\n   Why it''s good: [brief reason]\n\n**4. Something else?**\n   Tell me what you''d like to work on.\n\nWhich task interests you? (Pick a number or describe your own)\n```\n\n**If nothing found:** Fall back to asking what the user wants to build:\n> I didn''t find obvious quick wins in your codebase. What''s something small you''ve been meaning to add or fix?\n\n### Scope Guardrail\n\nIf the user picks or describes something too large (major feature, multi-day work):\n\n```\nThat''s a valuable task, but it''s probably larger than ideal for your first OpenSpec run-through.\n\nFor learning the workflow, smaller is better—it lets you see the full cycle without getting stuck in implementation details.\n\n**Options:**\n1. **Slice it smaller** - What''s the smallest useful piece of [their task]? Maybe just [specific slice]?\n2. **Pick something else** - One of the other suggestions, or a different small task?\n3. **Do it anyway** - If you really want to tackle this, we can. Just know it''ll take longer.\n\nWhat would you prefer?\n```\n\nLet the user override if they insist—this is a soft guardrail.\n\n---\n\n## Phase 3: Explore Demo\n\nOnce a task is selected, briefly demonstrate explore mode:\n\n```\nBefore we create a change, let me quickly show you **explore mode**—it''s how you think through problems before committing to a direction.\n```\n\nSpend 1-2 minutes investigating the relevant code:\n- Read the file(s) involved\n- Draw a quick ASCII diagram if it helps\n- Note any considerations\n\n```\n## Quick Exploration\n\n[Your brief analysis—what you found, any considerations]\n\n┌─────────────────────────────────────────┐\n│   [Optional: ASCII diagram if helpful]  │\n└─────────────────────────────────────────┘\n\nExplore mode (`/opsx:explore`) is for this kind of thinking—investigating before implementing. You can use it anytime you need to think through a problem.\n\nNow let''s create a change to hold our work.\n```\n\n**PAUSE** - Wait for user acknowledgment before proceeding.\n\n---\n\n## Phase 4: Create the Change\n\n**EXPLAIN:**\n```\n## Creating a Change\n\nA \"change\" in OpenSpec is a container for all the thinking and planning around a piece of work. It lives in `openspec/changes/<name>/` and holds your artifacts—proposal, specs, design, tasks.\n\nLet me create one for our task.\n```\n\n**DO:** Create the change with a derived kebab-case name:\n```bash\nopenspec new change \"<derived-name>\"\n```\n\n**SHOW:**\n```\nCreated: `openspec/changes/<name>/`\n\nThe folder structure:\n```\nopenspec/changes/<name>/\n├── proposal.md    ← Why we''re doing this (empty, we''ll fill it)\n├── design.md      ← How we''ll build it (empty)\n├── specs/         ← Detailed requirements (empty)\n└── tasks.md       ← Implementation checklist (empty)\n```\n\nNow let''s fill in the first artifact—the proposal.\n```\n\n---\n\n## Phase 5: Proposal\n\n**EXPLAIN:**\n```\n## The Proposal\n\nThe proposal captures **why** we''re making this change and **what** it involves at a high level. It''s the \"elevator pitch\" for the work.\n\nI''ll draft one based on our task.\n```\n\n**DO:** Draft the proposal content (don''t save yet):\n\n```\nHere''s a draft proposal:\n\n---\n\n## Why\n\n[1-2 sentences explaining the problem/opportunity]\n\n## What Changes\n\n[Bullet points of what will be different]\n\n## Capabilities\n\n### New Capabilities\n- `<capability-name>`: [brief description]\n\n### Modified Capabilities\n<!-- If modifying existing behavior -->\n\n## Impact\n\n- `src/path/to/file.ts`: [what changes]\n- [other files if applicable]\n\n---\n\nDoes this capture the intent? I can adjust before we save it.\n```\n\n**PAUSE** - Wait for user approval/feedback.\n\nAfter approval, save the proposal:\n```bash\nopenspec instructions proposal --change \"<name>\" --json\n```\nThen write the content to `openspec/changes/<name>/proposal.md`.\n\n```\nProposal saved. This is your \"why\" document—you can always come back and refine it as understanding evolves.\n\nNext up: specs.\n```\n\n---\n\n## Phase 6: Specs\n\n**EXPLAIN:**\n```\n## Specs\n\nSpecs define **what** we''re building in precise, testable terms. They use a requirement/scenario format that makes expected behavior crystal clear.\n\nFor a small task like this, we might only need one spec file.\n```\n\n**DO:** Create the spec file:\n```bash\nmkdir -p openspec/changes/<name>/specs/<capability-name>\n```\n\nDraft the spec content:\n\n```\nHere''s the spec:\n\n---\n\n## ADDED Requirements\n\n### Requirement: <Name>\n\n<Description of what the system should do>\n\n#### Scenario: <Scenario name>\n\n- **WHEN** <trigger condition>\n- **THEN** <expected outcome>\n- **AND** <additional outcome if needed>\n\n---\n\nThis format—WHEN/THEN/AND—makes requirements testable. You can literally read them as test cases.\n```\n\nSave to `openspec/changes/<name>/specs/<capability>/spec.md`.\n\n---\n\n## Phase 7: Design\n\n**EXPLAIN:**\n```\n## Design\n\nThe design captures **how** we''ll build it—technical decisions, tradeoffs, approach.\n\nFor small changes, this might be brief. That''s fine—not every change needs deep design discussion.\n```\n\n**DO:** Draft design.md:\n\n```\nHere''s the design:\n\n---\n\n## Context\n\n[Brief context about the current state]\n\n## Goals / Non-Goals\n\n**Goals:**\n- [What we''re trying to achieve]\n\n**Non-Goals:**\n- [What''s explicitly out of scope]\n\n## Decisions\n\n### Decision 1: [Key decision]\n\n[Explanation of approach and rationale]\n\n---\n\nFor a small task, this captures the key decisions without over-engineering.\n```\n\nSave to `openspec/changes/<name>/design.md`.\n\n---\n\n## Phase 8: Tasks\n\n**EXPLAIN:**\n```\n## Tasks\n\nFinally, we break the work into implementation tasks—checkboxes that drive the apply phase.\n\nThese should be small, clear, and in logical order.\n```\n\n**DO:** Generate tasks based on specs and design:\n\n```\nHere are the implementation tasks:\n\n---\n\n## 1. [Category or file]\n\n- [ ] 1.1 [Specific task]\n- [ ] 1.2 [Specific task]\n\n## 2. Verify\n\n- [ ] 2.1 [Verification step]\n\n---\n\nEach checkbox becomes a unit of work in the apply phase. Ready to implement?\n```\n\n**PAUSE** - Wait for user to confirm they''re ready to implement.\n\nSave to `openspec/changes/<name>/tasks.md`.\n\n---\n\n## Phase 9: Apply (Implementation)\n\n**EXPLAIN:**\n```\n## Implementation\n\nNow we implement each task, checking them off as we go. I''ll announce each one and occasionally note how the specs/design informed the approach.\n```\n\n**DO:** For each task:\n\n1. Announce: \"Working on task N: [description]\"\n2. Implement the change in the codebase\n3. Reference specs/design naturally: \"The spec says X, so I''m doing Y\"\n4. Mark complete in tasks.md: `- [ ]` → `- [x]`\n5. Brief status: \"✓ Task N complete\"\n\nKeep narration light—don''t over-explain every line of code.\n\nAfter all tasks:\n\n```\n## Implementation Complete\n\nAll tasks done:\n- [x] Task 1\n- [x] Task 2\n- [x] ...\n\nThe change is implemented! One more step—let''s archive it.\n```\n\n---\n\n## Phase 10: Archive\n\n**EXPLAIN:**\n```\n## Archiving\n\nWhen a change is complete, we archive it. This moves it from `openspec/changes/` to `openspec/changes/archive/YYYY-MM-DD-<name>/`.\n\nArchived changes become your project''s decision history—you can always find them later to understand why something was built a certain way.\n```\n\n**DO:**\n```bash\nopenspec archive \"<name>\"\n```\n\n**SHOW:**\n```\nArchived to: `openspec/changes/archive/YYYY-MM-DD-<name>/`\n\nThe change is now part of your project''s history. The code is in your codebase, the decision record is preserved.\n```\n\n---\n\n## Phase 11: Recap & Next Steps\n\n```\n## Congratulations!\n\nYou just completed a full OpenSpec cycle:\n\n1. **Explore** - Thought through the problem\n2. **New** - Created a change container\n3. **Proposal** - Captured WHY\n4. **Specs** - Defined WHAT in detail\n5. **Design** - Decided HOW\n6. **Tasks** - Broke it into steps\n7. **Apply** - Implemented the work\n8. **Archive** - Preserved the record\n\nThis same rhythm works for any size change—a small fix or a major feature.\n\n---\n\n## Command Reference\n\n| Command | What it does |\n|---------|--------------|\n| `/opsx:explore` | Think through problems before/during work |\n| `/opsx:new` | Start a new change, step through artifacts |\n| `/opsx:ff` | Fast-forward: create all artifacts at once |\n| `/opsx:continue` | Continue working on an existing change |\n| `/opsx:apply` | Implement tasks from a change |\n| `/opsx:verify` | Verify implementation matches artifacts |\n| `/opsx:archive` | Archive a completed change |\n\n---\n\n## What''s Next?\n\nTry `/opsx:new` or `/opsx:ff` on something you actually want to build. You''ve got the rhythm now!\n```\n\n---\n\n## Graceful Exit Handling\n\n### User wants to stop mid-way\n\nIf the user says they need to stop, want to pause, or seem disengaged:\n\n```\nNo problem! Your change is saved at `openspec/changes/<name>/`.\n\nTo pick up where we left off later:\n- `/opsx:continue <name>` - Resume artifact creation\n- `/opsx:apply <name>` - Jump to implementation (if tasks exist)\n\nThe work won''t be lost. Come back whenever you''re ready.\n```\n\nExit gracefully without pressure.\n\n### User just wants command reference\n\nIf the user says they just want to see the commands or skip the tutorial:\n\n```\n## OpenSpec Quick Reference\n\n| Command | What it does |\n|---------|--------------|\n| `/opsx:explore` | Think through problems (no code changes) |\n| `/opsx:new <name>` | Start a new change, step by step |\n| `/opsx:ff <name>` | Fast-forward: all artifacts at once |\n| `/opsx:continue <name>` | Continue an existing change |\n| `/opsx:apply <name>` | Implement tasks |\n| `/opsx:verify <name>` | Verify implementation |\n| `/opsx:archive <name>` | Archive when done |\n\nTry `/opsx:new` to start your first change, or `/opsx:ff` if you want to move fast.\n```\n\nExit gracefully.\n\n---\n\n## Guardrails\n\n- **Follow the EXPLAIN → DO → SHOW → PAUSE pattern** at key transitions (after explore, after proposal draft, after tasks, after archive)\n- **Keep narration light** during implementation—teach without lecturing\n- **Don''t skip phases** even if the change is small—the goal is teaching the workflow\n- **Pause for acknowledgment** at marked points, but don''t over-pause\n- **Handle exits gracefully**—never pressure the user to continue\n- **Use real codebase tasks**—don''t simulate or use fake examples\n- **Adjust scope gently**—guide toward smaller tasks but respect user choice\n"},"lastSynced":"2026-03-08T02:05:49.047Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing guided OpenSpec workflow integration.","zh":"非常适合需要指导的 OpenSpec 工作流集成的开发代理。","ja":"OpenSpec ワークフロー統合を必要とする開発エージェントに最適です。","ko":"OpenSpec 워크플로 통합을 필요로 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan integración de flujo de trabajo OpenSpec guiada.","fr":"Parfait pour les agents de développement ayant besoin d''une intégration de workflow OpenSpec guidée.","de":"Perfekt für Entwicklungssagenten, die eine guidierte OpenSpec-Workflow-Integration benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de integração de fluxo de trabalho OpenSpec orientada.","ru":"Идеально для агентов разработки, которым необходима интеграция рабочего процесса OpenSpec с руководством.","ar":"مثالي للوكلاء الناشئين الذين يحتاجون إلى توجيه في عملية عمل OpenSpec."},"recommendation":{"en":"Empowers agents to streamline OpenSpec initialization and workflow cycles, utilizing command-line interfaces like `openspec init` and `openspec status --json` for seamless project setup and status checks.","zh":"赋予代理简化 OpenSpec 初始化和工作流周期的能力，利用命令行接口（如 `openspec init` 和 `openspec status --json`）进行无缝的项目设置和状态检查。","ja":"OpenSpec 初期化とワークフローサイクルを簡素化するエージェントの能力を提供します。`openspec init` および `openspec status --json` などのコマンドラインインターフェイスを使用して、プロジェクトの設定とステータスチェックをシームレスに行うことができます。","ko":"OpenSpec 초기화 및 워크플로 사이클을 간소화하는 에이전트의 능력을 제공합니다. `openspec init` 및 `openspec status --json`와 같은 명령줄 인터페이스를 사용하여 프로젝트 설정 및 상태 확인을 무결점으로 수행할 수 있습니다.","es":"Habilita a los agentes a optimizar la inicialización y los ciclos de trabajo de OpenSpec, utilizando interfaces de línea de comandos como `openspec init` y `openspec status --json` para una configuración de proyecto y comprobaciones de estado sin problemas.","fr":"Permet aux agents de rationaliser l''initialisation et les cycles de travail OpenSpec, en utilisant des interfaces de ligne de commande comme `openspec init` et `openspec status --json` pour une configuration de projet et des vérifications d''état sans accroc.","de":"Ermächtigt Agenten, die Initialisierung und die Arbeitszyklen von OpenSpec zu optimieren, indem es die Verwendung von Befehlszeilen-Schnittstellen wie `openspec init` und `openspec status --json` für eine reibungslose Projektsetup und Statusprüfungen ermöglicht.","pt":"Permite que os agentes racionalizem a inicialização OpenSpec e os ciclos de fluxo de trabalho, utilizando interfaces de linha de comando como `openspec init` e `openspec status --json` para configuração de projeto sem problemas e verificações de status.","ru":"Позволяет агентам оптимизировать инициализацию OpenSpec и циклы рабочего процесса, используя интерфейсы командной строки, такие как `openspec init` и `openspec status --json`, для бесшовной настройки проекта и проверки статуса.","ar":"يمكن للوكلاء بفضلها تسهيل عملية 초기化 OpenSpec ودورات عمل Flux ، باستخدام واجهات سطر الأوامر مثل `openspec init` و `openspec status --json` من أجل إعداد مشروع بدون مشاكل وفحص الحالة."},"useCases":{"en":["Initializing OpenSpec in new projects","Guiding users through their first OpenSpec workflow cycle","Performing real work in codebases while explaining each step"],"zh":["在新项目中初始化 OpenSpec","指导用户完成他们的第一个 OpenSpec 工作流周期","在代码库中执行实际工作，同时解释每一步"],"ja":["新しいプロジェクトで OpenSpec を初期化する","ユーザーが最初の OpenSpec ワークフローサイクルを完了するためのガイダンス","コードベースで実際の作業を実行しながら、各ステップを説明する"],"ko":["새 프로젝트에서 OpenSpec 초기화","사용자가 첫 번째 OpenSpec 워크플로 사이클을 완료하도록 안내","코드베이스에서 실제 작업을 수행하면서 각 단계를 설명"],"es":["Inicialización de OpenSpec en nuevos proyectos","Guiar a los usuarios a través de su primer ciclo de trabajo OpenSpec","Realizar un trabajo real en los códigos mientras se explica cada paso"],"fr":["Initialisation d''OpenSpec dans de nouveaux projets","Guider les utilisateurs à travers leur premier cycle de travail OpenSpec","Effectuer un travail réel dans les codes tout en expliquant chaque étape"],"de":["Initialisierung von OpenSpec in neuen Projekten","Benutzer durch ihren ersten OpenSpec-Arbeitszyklus führen","Ausführen von echter Arbeit in Codebasen, während jeder Schritt erklärt wird"],"pt":["Inicializar OpenSpec em novos projetos","Orientar os usuários em seu primeiro ciclo de fluxo de trabalho OpenSpec","Realizar trabalho real em repositórios de código enquanto explica cada etapa"],"ru":["Инициализировать OpenSpec в новых проектах","Направлять пользователей через их первый цикл рабочего процесса OpenSpec","Выполнять实际ную работу в кодовых базах, объясняя каждый шаг"],"ar":["تشغيل OpenSpec في المشاريع الجديدة","توجيه المستخدمين خلال دورة عمل OpenSpec الأولى","إجراء عمل فعلي في قواعد البيانات الرقمية مع شرح كل خطوة"]},"limitations":{"en":["Requires OpenSpec installation","Needs command-line access for initialization and status checks"],"zh":["需要 OpenSpec 安装","需要命令行访问以进行初始化和状态检查"],"ja":["OpenSpec のインストールが必要","初期化とステータスチェックのためにコマンドラインアクセスが必要"],"ko":["OpenSpec 설치가 필요","초기화 및 상태 확인을 위해 명령줄 액세스가 필요"],"es":["Requiere instalación de OpenSpec","Necesita acceso a la línea de comandos para la inicialización y las comprobaciones de estado"],"fr":["Nécessite l''installation d''OpenSpec","Nécessite un accès à la ligne de commande pour l''initialisation et les vérifications d''état"],"de":["Erfordert OpenSpec-Installation","Benötigt Zugriff auf die Befehlszeile für Initialisierung und Statusprüfungen"],"pt":["Exige instalação OpenSpec","Necessita acesso à linha de comando para inicialização e verificações de status"],"ru":["Требует установки OpenSpec","Требует доступа к командной строке для инициализации и проверки статуса"],"ar":["يتطلب تثبيت OpenSpec","يحتاج إلى وصول إلى سطر الأوامر من أجل التشغيل والتحقق من الحالة"]},"version":4},"contentHash":"f764e94014ec70ccd261ab580debbaa6ce74eff2877bffc80734e64fb70bb397","qualityScore":47}');
