INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jaxxstorm/landlord/openspec-onboard', 'openspec-onboard', 'jaxxstorm', 'landlord', 'community', 'openspec-onboard jaxxstorm landlord community The openspec-onboard skill guides users through their first OpenSpec workflow cycle, explaining each step while performing real work in their codebase, benefiting developers and project owners. openspec-onboard 是一个技术指导，帮助用户完成 OpenSpec 工作流循环，包括初始化和各阶段工作 openspec-onboard は、OpenSpec ワークフローを完了するための技術ガイドです。初期化と各段階の作業を含みます openspec-onboard 는 OpenSpec 워크플로우 사이클을 완료하는 기술 가이드입니다. 초기화 및 단계별 작업을 포함합니다 El agente openspec-onboard guía al usuario a través de su primer ciclo de trabajo completo de OpenSpec. Incluye la inicialización de OpenSpec y la ejecución de comandos de CLI. L''agent openspec-onboard guide l''utilisateur à travers son premier cycle de travail complet d''OpenSpec. Il inclut l''initialisation d''OpenSpec et l''exécution de commandes de CLI. Der Agent openspec-onboard führt den Benutzer durch seinen ersten vollständigen OpenSpec-Arbeitszyklus. Enthält die Initialisierung von OpenSpec und die Ausführung von CLI-Befehlen. O openspec-onboard é um guia de configuração que ajuda os desenvolvedores a inicializar o OpenSpec e executar seu primeiro ciclo de trabalho. openspec-onboard - это руководство по настройке, которое помогает разработчикам инициализировать OpenSpec и выполнить свой первый рабочий цикл. openspec-onboard هو دليل إعداد يساعد المطورين على تهيئة OpenSpec و تشغيل دورة عملهم الأولى. how to use openspec-onboard openspec-onboard setup guide what is openspec-onboard openspec-onboard alternative openspec-onboard vs openspec openspec-onboard install openspec workflow cycle openspec initialization openspec project setup openspec-onboard AI 工具 OpenSpec 工作流循环 初始化 openspec init openspec status JSON 输出 Checks OpenSpec initialization status using `openspec status --json` command Provides guidance on running `openspec init` for project setup Explains each step of the OpenSpec workflow cycle Performs real work in the user''s codebase during the onboarding process Handles conditional logic for uninitialized OpenSpec projects openspec-onboard is a skill that assists in initializing and setting up OpenSpec in a project, walking users through a complete workflow cycle.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dukefromearth/codex-autopilot/prompt-rewrite', 'community', 'dukefromearth', 'codex-autopilot', 'dukefromearth/codex-autopilot', 'prompt-rewrite', 0, 0, 47, '2026-03-08T01:57:15.387Z', '2026-03-08T02:05:54.388Z', 'ba3fcbd84d6f8cc117cdd316a95617979ca678ff49d1bbc0765b10c884ba6f2c', '{"id":"dukefromearth/codex-autopilot/prompt-rewrite","name":"prompt-rewrite","description":{"en":"The prompt-rewrite skill rewrites rough user goals into executable briefs for multi-agent workflows, preserving intent and surfacing unknowns. It benefits developers and project managers seeking to create concrete deliverables and definition-of-done.","zh":"Prompt Rewrite 技术可以将粗糙的用户目标转化为清晰的执行计划，优化 AIエージェント工作流","ja":"Prompt Rewrite は、AIエージェントのための実行可能なブリーフを作成するために、粗いユーザーゴールを具体的な目標に変換する技術です","ko":"Prompt Rewrite 기능은 사용자의 목표를 구체적인 실행 계획으로 변환하여 AI 에이전트의 개발 프로세스를 최적화합니다","es":"El reescritura de prompts permite convertir objetivos de usuario en briefs ejecutables con resultados concretos y alcance definido para flujos de trabajo de multiagentes de IA","fr":"La réécriture de prompts permet de convertir les objectifs utilisateur en briefs exécutables avec des résultats concrets et une portée définie pour les flux de travail multi-agents d''IA","de":"Die Neufassung von Prompts ermöglicht die Umwandlung von Benutzerzielen in ausführbare Briefings mit konkreten Ergebnissen und definiertem Umfang für Multiagenten-Workflows von KI","pt":"O skill de prompt rewrite permite reescrever metas de usuário em briefs executáveis para fluxos de trabalho de multiagentes, preservando a intenção e definindo entregáveis concretos","ru":"Навык prompt rewrite позволяет переписать цели пользователя в выполнимые брифы для рабочих процессов многоагентных систем, сохраняя намерение и определяя конкретные результаты","ar":"تمكن مهارة إعادة كتابة التحفيز من إعادة كتابة أهداف المستخدم إلى مذكرات قابلة للتنفيذ لتدفقات العمل متعددة الوكلاء، مع الحفاظ على القصد وتحديد النتائج المحددة"},"seo":{"title":{"en":"prompt-rewrite: Execution-Ready Brief Setup Guide | AI Ag...","zh":"Prompt Rewrite Setup Guide - AIエージェント工作流优化","ja":"Prompt Rewrite ベストプラクティス - AIエージェントのための実行可能なブリーフを作成","ko":"Prompt Rewrite 구축 가이드 - AI 에이전트를 위한 구체적인 목표 설정","es":"Guía de configuración para reescribir prompts de agentes ...","fr":"Guide de mise en œuvre de la réécriture de prompts pour l...","de":"Einrichtungsleitfaden für die Neufassung von Prompts für ...","pt":"Guia de Configuração do Prompt Rewrite para Ferramentas d...","ru":"Настройка ИИ Агентов: Промежуточное Руководство по Prompt...","ar":"دليل إعداد إعادة كتابة التحفيز للوكلاء الذكية"},"description":{"en":"Transform rough user goals into crisp briefs with prompt-rewrite. Learn how to preserve intent, surface unknowns, and achieve scope control. Get started now!","zh":"了解 Prompt Rewrite 技术，优化 AIエージェント工作流，实现高效的执行和安全的范围控制","ja":"Prompt Rewrite を使用して AIエージェントの実行可能なブリーフを作成し、開発効率を向上させる","ko":"Prompt Rewrite 기능을 사용하여 AI 에이전트의 구체적인 목표를 설정하고, 개발 프로세스를 최적화 하세요","es":"Aprende a reescribir objetivos de usuario en briefs ejecutables para flujos de trabajo de multiagentes de IA con nuestra guía de mejores prácticas","fr":"Découvrez comment réécrire les objectifs utilisateur en briefs exécutables pour les flux de travail multi-agents d''IA avec notre guide de bonnes pratiques","de":"Erfahren Sie, wie Sie Benutzerziele in ausführbare Briefings für Multiagenten-Workflows von KI umschreiben können, mit unserer Leitfaden für Best Practices","pt":"Aprenda a reescrever metas de usuário em briefs executáveis para fluxos de trabalho de multiagentes com o skill de prompt rewrite","ru":"Изучите, как переписать цели пользователя в выполнимые брифы для рабочих процессов многоагентных систем с помощью навыка prompt rewrite для ИИ Агентов","ar":"تعلم كيفية إعادة كتابة أهداف المستخدم إلى مذكرات قابلة للتنفيذ لتدفقات العمل متعددة الوكلاء باستخدام مهارة إعادة كتابة التحفيز للوكلاء الذكية"},"definition":{"en":"prompt-rewrite is a skill that rewrites user goals into execution-ready briefs, prioritizing intent preservation, scope control, and clarifying questions.","zh":"Prompt Rewrite 是一种将用户目标转化为执行计划的技术，用于优化 AIエージェント工作流","ja":"Prompt Rewrite は、ユーザーゴールを実行可能なブリーフに変換する技術であり、AIエージェントの開発に使用されます","ko":"Prompt Rewrite 는 사용자의 목표를 실행 가능한 계획으로 변환하는 기술로, AI 에이전트의 개발에서 사용됩니다","es":"La reescritura de prompts es una técnica para convertir objetivos de usuario en briefs ejecutables para flujos de trabajo de multiagentes de IA","fr":"La réécriture de prompts est une technique pour convertir les objectifs utilisateur en briefs exécutables pour les flux de travail multi-agents d''IA","de":"Die Neufassung von Prompts ist eine Technik zur Umwandlung von Benutzerzielen in ausführbare Briefings für Multiagenten-Workflows von KI","pt":"O prompt rewrite é uma técnica para reescrever metas de usuário em briefs executáveis para fluxos de trabalho de multiagentes","ru":"Промежуточный руководство по prompt rewrite - это техника для переписи целей пользователя в выполнимые брифы для рабочих процессов многоагентных систем","ar":"إعادة كتابة التحفيز هي تقنية لتحويل أهداف المستخدم إلى مذكرات قابلة للتنفيذ لتدفقات العمل متعددة الوكلاء"},"features":{"en":["Preserves user intent without introducing new requirements","Surfaces unknowns with high-leverage clarifying questions","Prepares concrete deliverables, scope, and definition-of-done","Prioritizes safety and scope control, avoiding ''do everything'' rewrites","Rewrites rough user goals into crisp, execution-ready briefs"],"zh":["将用户目标转化为清晰的执行计划","优化 AIエージェント工作流","实现高效的执行和安全的范围控制","使用具体的 deliverables 和定义的 done 条件","支持多个高效的 clarifying questions"],"ja":["ユーザーゴールを実行可能なブリーフに変換する","AIエージェントの開発プロセスを最適化する","効率的な実行と安全な範囲制御を実現する","具体的な deliverables と定義された done 条件を使用する","複数の高レバレルの clarifying questions をサポートする"],"ko":["사용자의 목표를 구체적인 실행 계획으로 변환","AI 에이전트의 개발 프로세스를 최적화","효율적인 실행과 안전한 범위 제어를 구현","구체적인 deliverables 와 정의된 done 조건을 사용","다수의 효율적인 clarifying questions 를 지원"],"es":["Preservación de la intención del usuario","Definición de resultados concretos y alcance","Identificación de desconocidos con preguntas clarificadoras","Control de seguridad y alcance para evitar reescrituras excesivas","Briefs ejecutables para flujos de trabajo de multiagentes de IA"],"fr":["Préservation de l''intention de l''utilisateur","Définition de résultats concrets et de portée","Identification d''inconnues avec des questions clarificatrices","Contrôle de sécurité et de portée pour éviter des réécritures excessives","Briefs exécutables pour les flux de travail multi-agents d''IA"],"de":["Erhaltung der Benutzerintention","Definition von konkreten Ergebnissen und Umfang","Identifizierung von Unbekannten mit Klarstellungsfragen","Sicherheits- und Umfangskontrolle zur Vermeidung übermäßiger Neufassungen","Ausführbare Briefings für Multiagenten-Workflows von KI"],"pt":["Preservação da intenção do usuário","Definição de entregáveis concretos","Controle de escopo e segurança","Perguntas clarificadoras para superfícies desconhecidas"],"ru":["Сохранение намерения пользователя","Определение конкретных результатов","Контроль объема и безопасности","Ясные вопросы для неизвестных поверхностей"],"ar":["الحفاظ على قصد المستخدم","تحديد نتائج محددة","مراقبة النطاق والأمان","أسئلة توضيحية لأسطح غير معروفة"]},"keywords":{"en":["how to use prompt-rewrite","what is prompt-rewrite","prompt-rewrite alternative","prompt-rewrite vs workflow management","prompt-rewrite install guide","prompt-rewrite setup tutorial","multi-agent workflow optimization","execution-ready brief creation","scope control and management"],"zh":["Prompt Rewrite","AIエージェント","工作流优化","执行计划","范围控制","clarifying questions","deliverables","done 条件"],"ja":["Prompt Rewrite","AIエージェント","開発プロセス最適化","実行可能なブリーフ","範囲制御","clarifying questions","deliverables","done 条件"],"ko":["Prompt Rewrite","AI 에이전트","개발 프로세스 최적화","실행 계획","범위 제어","clarifying questions","deliverables","done 조건"],"es":["reescritura de prompts","agentes de IA","flujos de trabajo de multiagentes","briefs ejecutables","preservación de la intención","definición de resultados","control de seguridad","herramientas de IA"],"fr":["réécriture de prompts","outils d''IA","flux de travail multi-agents","briefs exécutables","préservation de l''intention","définition de résultats","contrôle de sécurité","agents d''IA"],"de":["Neufassung von Prompts","KI-Agents","Multiagenten-Workflows","ausführbare Briefings","Erhaltung der Benutzerintention","Definition von Ergebnissen","Sicherheitskontrolle","KI-Tools"],"pt":["prompt rewrite","ferramentas de ia","fluxos de trabalho de multiagentes","briefs executáveis","preservação da intenção","definição de entregáveis","controle de escopo","segurança"],"ru":["prompt rewrite","ИИ агенты","рабочие процессы многоагентных систем","выполняемые брифы","сохранение намерения","определение результатов","контроль объема","безопасность"],"ar":["إعادة كتابة التحفيز","الوكلاء الذكية","تدفقات العمل متعددة الوكلاء","مذكرات قابلة للتنفيذ","الحفاظ على القصد","تحديد النتائج","مراقبة النطاق","الأمان"]}},"owner":"dukefromearth","repo":"codex-autopilot","repoPath":"dukefromearth/codex-autopilot","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.387Z","topics":[],"category":"community","skillMd":{"name":"prompt-rewrite","description":"Rewrite and clarify a users goal before starting a multi-agent workflow; produce a tighter goal plus constraints, acceptance criteria, assumptions, and any clarifying questions.","bodyPreview":"# Prompt Rewrite\n\nYou rewrite a rough user goal into a crisp, execution-ready brief for this repo''s multi-agent workflow.\n\n## Priorities\n\n- Preserve intent; do not introduce new requirements.\n- Make the goal executable: concrete deliverables, scope, and definition-of-done.\n- Surface unknowns with a few high-leverage clarifying questions (≤5) only when needed.\n- Prefer safety and scope control; avoid “do everything” rewrites.\n\n## Rewrite checklist\n\n- Objective: what outcome should exist when done","body":"# Prompt Rewrite\n\nYou rewrite a rough user goal into a crisp, execution-ready brief for this repo''s multi-agent workflow.\n\n## Priorities\n\n- Preserve intent; do not introduce new requirements.\n- Make the goal executable: concrete deliverables, scope, and definition-of-done.\n- Surface unknowns with a few high-leverage clarifying questions (≤5) only when needed.\n- Prefer safety and scope control; avoid “do everything” rewrites.\n\n## Rewrite checklist\n\n- Objective: what outcome should exist when done?\n- Deliverables: what artifacts/files/commands should change?\n- Constraints: time, safety, approvals, network/tool access, environments.\n- Acceptance criteria: how to verify completion.\n- Out of scope: explicitly name what not to do.\n- Assumptions: minimal-safe defaults when information is missing.\n\n## Questions (when necessary)\n\n- Ask only questions that materially change scope, risk, or approach.\n- Prefer yes/no or multiple-choice framing when possible.\n- If a question is unanswered, keep the rewrite conservative and add a minimal assumption.\n\n## Output discipline\n\n- Follow the caller’s output schema exactly and output JSON only.\n- Keep `rewrittenGoal` concise; avoid lengthy prose.\n"},"lastSynced":"2026-03-08T02:05:54.388Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code requiring precise task definition and executable briefs for multi-agent workflows.","zh":"适合于像Cursor、Windsurf和Claude Code这样的AI代理，需要精确的任务定义和可执行的简报用于多代理工作流。","ja":"Cursor、Windsurf、Claude CodeなどのAIエージェントに適しています。これらは、多エージェントのワークフローで、正確なタスク定義と実行可能なブリーフを必要とします。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에게 적합합니다. 이러한 에이전트는 다중 에이전트 워크플ロー에서 정확한 작업 정의와 실행 가능한 브리핑을 필요로 합니다.","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que requieren una definición de tarea precisa y breves ejecutables para flujos de trabajo de multiagente.","fr":"Idéal pour les agents d''IA comme Cursor, Windsurf et Claude Code nécessitant une définition de tâche précise et des briefs exécutables pour les flux de travail multi-agents.","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die eine präzise Aufgabendefinition und ausführbare Kurzbeschreibungen für Multi-Agent-Workflows erfordern.","pt":"Ideal para Agentes de IA como Cursor, Windsurf e Claude Code que exigem definição precisa de tarefas e breves executáveis para fluxos de trabalho de multiagentes.","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, требующих точного определения задач и исполняемых брифов для рабочих процессов мультиагентов.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code الذين يتطلبون تعريفًا دقيقًا لل任务 والمداخل القابلة للتنفيذ لمجموعات عمل متعددة الوكلاء."},"recommendation":{"en":"Empowers agents to rewrite rough user goals into crisp, execution-ready briefs, preserving intent and surfacing unknowns with clarifying questions, utilizing concrete deliverables and definition-of-done protocols.","zh":"赋予代理人将粗糙的用户目标转化为清晰、可执行的简报的能力，保留意图并通过阐明问题来揭示未知，利用具体的交付物和已完成定义协议。","ja":"エージェントに、ユーザーの漠然とした目標を明確で実行可能なブリーフに書き直す能力を付与します。意図を保持し、具体的な成果物と完了の定義プロトコルを使用して、明確化する質問で未知を浮き彫りにします。","ko":"에이전트에게 사용자의 모호한 목표를 분명하고 실행 가능한 브리핑으로 다시 작성할 수 있는 능력을 부여합니다. 의도를 유지하고 구체적인 성과물과 완료 정의 프로토콜을 사용하여 澄明하는 질문으로 알려지지 않은 것을浮き彫りに합니다.","es":"Habilita a los agentes a reescribir objetivos de usuario poco claros en breves listos para la ejecución, preservando la intención y sacando a la luz lo desconocido con preguntas aclaratorias, utilizando entregables concretos y protocolos de definición de lo hecho.","fr":"Permet aux agents de réécrire les objectifs utilisateur peu clairs en briefs prêts à l''exécution, en préservant l''intention et en mettant en évidence les inconnues avec des questions clarificatrices, en utilisant des livrables concrets et des protocoles de définition de ce qui est fait.","de":"Ermöglicht es Agents, ungenaue Benutzerziele in ausführbare Kurzbeschreibungen umzuschreiben, die Absicht zu bewahren und Unbekanntes durch gezielte Klarstellungsfragen aufzudecken, unter Verwendung konkreter Ergebnisse und Definitionen von Fertigstellung.","pt":"Habilita os agentes a reescrever metas de usuário vagas em breves prontos para execução, preservando a intenção e expondo desconhecidos com perguntas esclarecedoras, utilizando entregas concretas e protocolos de definição de conclusão.","ru":"Наделяет агентов возможностью переписать неясные цели пользователя в четкие, готовые к исполнению брифы, сохраняя намерение и выявляя неизвестные с помощью уточняющих вопросов, используя конкретные результаты и протоколы определения завершения.","ar":"تمكن الوكلاء من إعادة كتابة أهداف المستخدم الغامضة في مداخل جاهزة للتنفيذ، مع الحفاظ على النية وraises غير معروفين مع أسئلة توضيحية، باستخدام entregas ملموسة وبروتوكولات تعريف الإنجاز."},"useCases":{"en":["Rewriting ambiguous user requests into actionable tasks","Generating executable briefs for multi-agent workflows","Surfacing unknowns with targeted clarifying questions"],"zh":["将模糊的用户请求重写为可执行的任务","为多代理工作流生成可执行的简报","使用有针对性的澄明问题来揭示未知"],"ja":["ユーザーの曖昧なリクエストを実行可能なタスクに書き直す","多エージェントのワークフロー用の実行可能なブリーフを生成する","ターゲットを絞った明確化する質問で未知を浮き彫りにする"],"ko":["사용자의 모호한 요청을 실행 가능한 작업으로 다시 작성하기","다중 에이전트 워크플로우를 위한 실행 가능한 브리핑 생성하기","목적을 가진 澄明하는 질문으로 알려지지 않은 것을浮き彫りに하기"],"es":["Reescribir solicitudes de usuario ambiguas en tareas accionables","Generar breves ejecutables para flujos de trabajo de multiagente","Sacar a la luz lo desconocido con preguntas clarificatorias dirigidas"],"fr":["Réécrire les demandes utilisateur ambiguës en tâches actionnables","Générer des briefs exécutables pour les flux de travail multi-agents","Mettre en évidence les inconnues avec des questions clarificatrices ciblées"],"de":["Umschreiben ungenauer Benutzeranfragen in handhabbare Aufgaben","Erstellen ausführbarer Kurzbeschreibungen für Multi-Agent-Workflows","Aufdecken von Unbekanntem mit gezielten Klarstellungsfragen"],"pt":["Reescrever solicitações de usuário ambíguas em tarefas ações","Gerar breves executáveis para fluxos de trabalho de multiagentes","Expor desconhecidos com perguntas esclarecedoras direcionadas"],"ru":["Переписать неясные запросы пользователя в действенные задачи","Генерировать исполняемые брифы для рабочих процессов мультиагентов","Выявить неизвестные с помощью целевых уточняющих вопросов"],"ar":["إعادة كتابة طلبات المستخدم الغامضة في مهام قابلة للتنفيذ","توليد مداخل قابلة للتنفيذ لمجموعات عمل متعددة الوكلاء","إظهار غير معروفين مع أسئلة توضيحية محددة"]},"limitations":{"en":["Prefer safety and scope control, avoiding ''do everything'' rewrites","Limited to 5 high-leverage clarifying questions"],"zh":["更倾向于安全和范围控制，避免''做所有事''的重写","仅限5个高杠杆的澄明问题"],"ja":["安全とスコープのコントロールを優先し、''すべてのことを行う''リライトを回避する","5つのハイレバレッジの明確化する質問に限定される"],"ko":["보안과 범위 제어를 선호하며 ''모든 것을 수행''하는 다시 작성하기를 피함","5개의 고레버리지澄明하는 질문으로 제한됨"],"es":["Preferir la seguridad y el control de alcance, evitando reescrituras de ''hacer todo''","Limitado a 5 preguntas clarificatorias de alto impacto"],"fr":["Préférer la sécurité et le contrôle de portée, en évitant les réécritures de ''faire tout''","Limité à 5 questions clarificatrices à haut rendement"],"de":["Sicherheit und Umfangskontrolle bevorzugen, ''Alles tun''-Umschreibungen vermeiden","Begrenzt auf 5 hochwirksame Klarstellungsfragen"],"pt":["Preferir segurança e controle de escopo, evitando reescritas de ''faça tudo''","Limitado a 5 perguntas esclarecedoras de alto impacto"],"ru":["Предпочитать безопасность и контроль объема, избегая переписывания ''сделать все''","Ограничено 5 уточняющими вопросами высокого приоритета"],"ar":["الاعتماد على السلامة ومراقبة النطاق، وتجنب إعادة كتابة ''كل شيء''","محدود بـ 5 أسئلة توضيحية عالية التأثير"]},"version":4},"contentHash":"ba3fcbd84d6f8cc117cdd316a95617979ca678ff49d1bbc0765b10c884ba6f2c","qualityScore":47}');
