INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dukefromearth/codex-autopilot/prompt-rewrite', 'prompt-rewrite', 'dukefromearth', 'codex-autopilot', 'community', 'prompt-rewrite dukefromearth codex-autopilot community The prompt-rewrite skill rewrites rough user goals into executable briefs for multi-agent workflows, preserving intent and surfacing unknowns. It benefits developers and project managers seeking to create concrete deliverables and definition-of-done. Prompt Rewrite 技术可以将粗糙的用户目标转化为清晰的执行计划，优化 AIエージェント工作流 Prompt Rewrite は、AIエージェントのための実行可能なブリーフを作成するために、粗いユーザーゴールを具体的な目標に変換する技術です Prompt Rewrite 기능은 사용자의 목표를 구체적인 실행 계획으로 변환하여 AI 에이전트의 개발 프로세스를 최적화합니다 El reescritura de prompts permite convertir objetivos de usuario en briefs ejecutables con resultados concretos y alcance definido para flujos de trabajo de multiagentes de IA La réécriture de prompts permet de convertir les objectifs utilisateur en briefs exécutables avec des résultats concrets et une portée définie pour les flux de travail multi-agents d''IA Die Neufassung von Prompts ermöglicht die Umwandlung von Benutzerzielen in ausführbare Briefings mit konkreten Ergebnissen und definiertem Umfang für Multiagenten-Workflows von KI O skill de prompt rewrite permite reescrever metas de usuário em briefs executáveis para fluxos de trabalho de multiagentes, preservando a intenção e definindo entregáveis concretos Навык prompt rewrite позволяет переписать цели пользователя в выполнимые брифы для рабочих процессов многоагентных систем, сохраняя намерение и определяя конкретные результаты تمكن مهارة إعادة كتابة التحفيز من إعادة كتابة أهداف المستخدم إلى مذكرات قابلة للتنفيذ لتدفقات العمل متعددة الوكلاء، مع الحفاظ على القصد وتحديد النتائج المحددة how to use prompt-rewrite what is prompt-rewrite prompt-rewrite alternative prompt-rewrite vs workflow management prompt-rewrite install guide prompt-rewrite setup tutorial multi-agent workflow optimization execution-ready brief creation scope control and management Prompt Rewrite AIエージェント 工作流优化 执行计划 范围控制 clarifying questions deliverables done 条件 Preserves user intent without introducing new requirements Surfaces unknowns with high-leverage clarifying questions Prepares concrete deliverables, scope, and definition-of-done Prioritizes safety and scope control, avoiding ''do everything'' rewrites Rewrites rough user goals into crisp, execution-ready briefs prompt-rewrite is a skill that rewrites user goals into execution-ready briefs, prioritizing intent preservation, scope control, and clarifying questions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('matsuni-kk/mini-app-agent/core-rule-maintenance', 'community', 'matsuni-kk', 'mini-app-agent', 'matsuni-kk/mini-app-agent', 'core-rule-maintenance', 0, 0, 47, '2026-03-08T01:57:15.387Z', '2026-03-08T02:05:56.300Z', '8e327c265912b55624a5fc941e92fbad475ca98889c205a330bacc25aa46f49b', '{"id":"matsuni-kk/mini-app-agent/core-rule-maintenance","name":"core-rule-maintenance","description":{"en":"The core-rule-maintenance skill enables AI agents to optimize workflow by managing core principles, outcome types, and quality goals. It benefits developers by streamlining the preflight process and ensuring consistency across CLAUDE.md and AGENTS.md files.","zh":"核心规则维护是AIエージェント的关键组成部分，涉及CLAUDE.md和AGENTS.md文件的精心管理","ja":"コア規則メンテナンスはAIエージェントの重要な構成要素であり、CLAUDE.mdとAGENTS.mdファイルの慎重な管理を伴う","ko":"코어 규칙 유지 보수는 AI 에이전트의 핵심 구성 요소이며 CLAUDE.md 및 AGENTS.md 파일의 신중한 관리가 포함됩니다","es":"El mantenimiento de reglas básicas es crucial para el funcionamiento de los Agentes de IA. Conoce los pasos para configurar y mantener las reglas básicas","fr":"La maintenance des règles de base est essentielle pour le fonctionnement des outils d''IA. Découvrez les étapes pour configurer et maintenir les règles de base","de":"Die Wartung von Grundregeln ist für den Betrieb von KI-Agents entscheidend. Erfahren Sie, wie Sie die Grundregeln konfigurieren und warten können","pt":"A manutenção de regras core é fundamental para Ferramentas de IA. Este guia aborda a configuração e os melhores práticas.","ru":"Поддержка основных правил необходима для ИИ Агентов. Это руководство охватывает настройку и лучшие практики.","ar":"صيانة القواعد الأساسية ضرورية للأدوات الذكية. هذا الدليل يغطي الإعداد وأفضل الممارسات."},"seo":{"title":{"en":"core-rule-maintenance: Workflow Optimization Setup Guide ...","zh":"核心规则维护设置指南","ja":"コア規則メンテナンスのベストプラクティス","ko":"코어 규칙 유지 보수 설정 가이드","es":"Guía de configuración de mantenimiento de reglas básicas ...","fr":"Guide de configuration de la maintenance des règles de ba...","de":"Einrichtungsleitfaden für die Wartung von Grundregeln für...","pt":"Guia de Configuração de Manutenção de Regras Core","ru":"Руководство по настройке поддержки основных правил","ar":"دليل إعداد صيانة القواعد الأساسية"},"description":{"en":"Discover how to streamline your workflow with core-rule-maintenance. Learn how to implement preflight checks, manage CLAUDE.md and AGENTS.md files, and optim...","zh":"了解核心规则维护的重要性和实施方法，优化AIエージェント的性能","ja":"コア規則メンテナンスの重要性と実施方法を学び、AIエージェントのパフォーマンスを最適化する","ko":"코어 규칙 유지 보수의 중요성과 구현 방법을 알아보고 AI 에이전트의 성능을 최적화하세요","es":"Aprende a configurar y mantener las reglas básicas para Agentes de IA con nuestra guía paso a paso","fr":"Découvrez comment configurer et maintenir les règles de base pour les outils d''IA avec notre guide étape par étape","de":"Erfahren Sie, wie Sie die Grundregeln für KI-Agents konfigurieren und warten können, Schritt für Schritt","pt":"Aprenda a configurar a manutenção de regras core para Ferramentas de IA com este guia passo a passo","ru":"Узнайте, как настроить поддержку основных правил для ИИ Агентов с помощью этого пошагового руководства","ar":"تعلم كيفية إعداد صيانة القواعد الأساسية للأدوات الذكية مع هذا الدليل خطوة بخطوة"},"definition":{"en":"core-rule-maintenance is a workflow optimization skill that ensures consistency and accuracy in AI agent development by managing core principles, outcome types, and quality goals.","zh":"核心规则维护是指对AIエージェント的核心规则和配置文件进行维护和更新的过程","ja":"コア規則メンテナンスとは、AIエージェントのコア規則と設定ファイルを維持および更新するプロセスである","ko":"코어 규칙 유지 보수는 AI 에이전트의 핵심 규칙 및 구성 파일을 유지 및 업데이트하는 프로세스입니다","es":"Mantenimiento de reglas básicas para Agentes de IA: proceso de configuración y actualización de reglas para garantizar el funcionamiento óptimo","fr":"Maintenance des règles de base pour les outils d''IA: processus de configuration et de mise à jour des règles pour assurer un fonctionnement optimal","de":"Wartung von Grundregeln für KI-Agents: Prozess der Konfiguration und Aktualisierung von Regeln für einen optimalen Betrieb","pt":"Manutenção de regras core é o processo de atualização e gerenciamento de regras para Ferramentas de IA","ru":"Поддержка основных правил - это процесс обновления и управления правилами для ИИ Агентов","ar":"صيانة القواعد الأساسية هي عملية تحديث وإدارة القواعد للأدوات الذكية"},"features":{"en":["Manages CLAUDE.md files for core principles, outcome types, and quality goals","Optimizes AGENTS.md files for agent definitions and asynchronous updates","Performs preflight checks to ensure consistency and accuracy","Supports synchronization with .cursor, .claude, and .codex files","Enables workflow indexing and path dictionary management","Streamlines the development process with automated checks and updates"],"zh":["支持CLAUDE.md和AGENTS.md文件的管理","提供Preflight检查以确保配置文件的一致性","允许对核心规则和配置文件进行更新和维护","集成WF索引和パス辞書以优化AIエージェント的性能","支持多语言环境，包括中文、日文和韩文"],"ja":["CLAUDE.mdとAGENTS.mdファイルの管理をサポート","Preflightチェックを提供して設定ファイルの一貫性を確保","コア規則と設定ファイルの更新とメンテナンスを許可","WF索引とパス辞書を統合してAIエージェントのパフォーマンスを最適化","多言語環境をサポート、包括中国語、日語、韓国語"],"ko":["CLAUDE.md 및 AGENTS.md 파일 관리 지원","설정 파일 일관성을 보장하기 위한 Preflight 확인 제공","코어 규칙 및 구성 파일 업데이트 및 유지 보수 허용","WF 색인 및 경로 사전 통합을 통해 AI 에이전트 성능 최적화","다국어 환경 지원, 중국어, 일본어 및 한국어 포함"],"es":["Configuración de reglas básicas para Agentes de IA","Actualización de reglas en CLAUDE.md y AGENTS.md","Verificación de la documentación y los cambios solicitados","Identificación de habilidades y subagentes afectados","Uso de la herramienta de preflight para verificar los cambios"],"fr":["Configuration des règles de base pour les outils d''IA","Mise à jour des règles dans CLAUDE.md et AGENTS.md","Vérification de la documentation et des changements demandés","Identification des compétences et des sous-agents affectés","Utilisation de l''outil de preflight pour vérifier les changements"],"de":["Konfiguration von Grundregeln für KI-Agents","Aktualisierung von Regeln in CLAUDE.md und AGENTS.md","Überprüfung der Dokumentation und der angeforderten Änderungen","Identifizierung der Fähigkeiten und Subagenten, die betroffen sind","Verwendung des Preflight-Tools zur Überprüfung der Änderungen"],"pt":["Configuração de regras core com CLAUDE.md","Gerenciamento de agentes com AGENTS.md","Integração com .cursor e .claude","Atualização de índices de workflow e dicionários de caminho","Verificação de documentos antes de alterações"],"ru":["Настройка основных правил с помощью CLAUDE.md","Управление агентами с помощью AGENTS.md","Интеграция с .cursor и .claude","Обновление индексов рабочего процесса и словарей путей","Проверка документов перед внесением изменений"],"ar":["إعداد قواعد أساسية مع CLAUDE.md","إدارة الوكلاء مع AGENTS.md","التكامل مع .cursor و .claude","تحديث فهرس سير العمل وقواميس المسار","فحص الوثائق قبل إجراء التغييرات"]},"keywords":{"en":["how to use core-rule-maintenance","core-rule-maintenance setup guide","core-rule-maintenance alternative","core-rule-maintenance vs workflow automation","what is core-rule-maintenance","core-rule-maintenance install","core-rule-maintenance workflow optimization","AI agent skill development","CLAUDE.md file management","AGENTS.md file optimization"],"zh":["核心规则维护","AIエージェント","CLAUDE.md","AGENTS.md","Preflight检查","WF索引","パス辞書","多语言环境"],"ja":["コア規則メンテナンス","AIエージェント","CLAUDE.md","AGENTS.md","Preflightチェック","WF索引","パス辞書","多言語環境"],"ko":["코어 규칙 유지 보수","AI 에이전트","CLAUDE.md","AGENTS.md","Preflight 확인","WF 색인","경로 사전","다국어 환경"],"es":["mantenimiento de reglas básicas para Agentes de IA","configuración de reglas para Agentes de IA","Agentes de IA","herramientas de IA","reglas básicas para Agentes de IA","preflight para Agentes de IA"],"fr":["maintenance des règles de base pour les outils d''IA","configuration des règles pour les outils d''IA","outils d''IA","règles de base pour les outils d''IA","preflight pour les outils d''IA","compétences pour les outils d''IA"],"de":["Wartung von Grundregeln für KI-Agents","Konfiguration von Grundregeln für KI-Agents","KI-Agents","KI-Tools","Grundregeln für KI-Agents","Preflight für KI-Agents","Fähigkeiten für KI-Agents"],"pt":["manutenção de regras core","ferramentas de ia","configuração de regras","gerenciamento de agentes","integração com cursor","atualização de índices de workflow","ia é ferramentas"],"ru":["поддержка основных правил","ии агенты","настройка правил","управление агентами","интеграция с cursor","обновление индексов рабочего процесса","ии инструменты"],"ar":["صيانة قواعد أساسية","أدوات ذكية","إعداد قواعد","إدارة وكلاء","التكامل مع cursor","تحديث فهرس سير العمل","أدوات ذكية إعداد"]}},"owner":"matsuni-kk","repo":"mini-app-agent","repoPath":"matsuni-kk/mini-app-agent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.387Z","topics":[],"category":"community","skillMd":{"name":"core-rule-maintenance","description":"CLAUDE.md/AGENTS.md等のコアルールファイルの保守・更新を対話で行い、3環境同期と整合性を維持したまま反映する。CLAUDE.md更新、コアルール変更、ルール追加、パス辞書更新、ワークフロー索引更新を依頼されたときに使用する。","bodyPreview":"# Core Rule Maintenance Workflow\n\n## 対象ファイル\n\n| ファイル | 役割 | 同期先 |\n|----------|------|--------|\n| CLAUDE.md | コア原則、成果物タイプ、品質ゴール、Skill選択ポリシー、WF索引、パス辞書 | .cursor/.claude/.codex |\n| AGENTS.md | エージェント定義（Cursor専用、非同期） | .cursor のみ |\n\n## Instructions\n\n1. Preflight:\n   - ドキュメント精査原則（Preflight必須）：変更前に必ず以下を実施すること。\n     - 現在のCLAUDE.md/AGENTS.mdを全て読み込む。\n     - 変更依頼の背景・理由・期待される効果を確認する。\n     - 影響を受けるSkills/Subagentsを特定する。\n     - これらを完了するまで変更を開始しない。\n   - 変更対象（section=コア原則/成果物タイプ/品質ゴール/WF索引/パス辞書等）、変更範囲、理由を確認する（推","body":"# Core Rule Maintenance Workflow\n\n## 対象ファイル\n\n| ファイル | 役割 | 同期先 |\n|----------|------|--------|\n| CLAUDE.md | コア原則、成果物タイプ、品質ゴール、Skill選択ポリシー、WF索引、パス辞書 | .cursor/.claude/.codex |\n| AGENTS.md | エージェント定義（Cursor専用、非同期） | .cursor のみ |\n\n## Instructions\n\n1. Preflight:\n   - ドキュメント精査原則（Preflight必須）：変更前に必ず以下を実施すること。\n     - 現在のCLAUDE.md/AGENTS.mdを全て読み込む。\n     - 変更依頼の背景・理由・期待される効果を確認する。\n     - 影響を受けるSkills/Subagentsを特定する。\n     - これらを完了するまで変更を開始しない。\n   - 変更対象（section=コア原則/成果物タイプ/品質ゴール/WF索引/パス辞書等）、変更範囲、理由を確認する（推測しない）。\n   - `./assets/claude_md_structure.md` を参照し、CLAUDE.mdの構造を把握する（テンプレートファースト）。\n\n2. 変更種別の判断:\n   - 以下の変更種別を特定し、それぞれの手順に従う:\n     - **Section 1-5 変更**: コア原則/成果物タイプ/品質ゴール/Skill選択ポリシー/成果物分類\n     - **Section 6 変更**: ワークフロー索引（WF連携マップ）\n     - **Section 7 変更**: パス辞書（root/dirs/patterns/meta）\n     - **複合変更**: 複数セクションにまたがる変更\n\n3. 生成（変更実施）:\n    - `./questions/core_rule_maintenance_questions.md` に従い入力を確定する。\n    - 既存の構造・フォーマットを崩さない（最小差分で修正）。\n    - CLAUDE.mdの必須セクション区切りを維持する。\n    - 変更内容:\n      - **WF索引変更時**: 該当フェーズに追記/修正、矢印（→）で連携を表現\n      - **パス辞書変更時**: dirs/patterns/metaの適切な箇所に追記、変数参照の整合性を確認\n      - **コア原則変更時**: 全Skillsへの影響を確認し、必要なら各SKILL.mdとtriggersも更新する\n      - **Skill運用ルール変更時**: 「Skillは原則必須」「どうしてもskillsに該当がない場合のみ省略可」「Skill完了後はtriggersで次へ必ず進む」などの運用原則は、必ずCLAUDE.mdの `## 1. コア原則` に記載する（Section 4だけに置かない）\n\n4. 整合性チェック:\n   - パス辞書変更時:\n     - 変数参照（`{{patterns.xxx}}`等）が正しく解決されることを確認\n     - 循環参照がないことを確認\n     - 実際のファイルパスとして有効であることを確認\n   - WF索引変更時:\n     - 参照先Skillが存在することを確認\n     - 連携フロー（→）の整合性を確認\n     - 各SkillのNext Action triggersと整合していることを確認\n\n5. 3環境同期（Skills/Assets統一）:\n    - CLAUDE.md変更後は `python3 scripts/update_agent_master.py --source claude --force` で同期を実施する（Claude起点）。\n    - 同期内容: CLAUDE.mdからAGENTS.md等の派生ルールを再生成し、`.claude/skills` / `.claude/commands` を各環境へ同期する（`SKILL.md` だけでなく `assets/` `questions/` `evaluation/` `triggers/` `scripts/` も含めて統一する）。\n    - 備考: `.cursor/.codex/.opencode/.github` 側のskillsを直接編集しない（起点で変更→同期で統一）。AGENTS.mdは生成対象だが、Cursor専用の運用ファイルとして扱う（手動で直接編集しない）。\n\n6. QC（必須）:\n   - `./evaluation/evaluation_criteria.md` を参照し、以下を自己評価する:\n     - 必須セクション維持\n     - パス辞書の変数参照整合性\n     - WF索引とSkillsのNext Action triggers整合性\n     - 3環境同期の実施\n   - 評価結果を成果物末尾に追記する（修正有無/理由）。\n   - 重大な問題がある場合は修正し、再評価する（最大3回）。\n\n7. バックログ反映:\n   - 次アクション（影響Skillsの更新、レビュー依頼等）を抽出しバックログへ反映する。\n   - 反映先・編集制約・差分提示は AGENTS.md / CLAUDE.md の全体ルールに従う。\n\nsubagent_policy:\n  - 単なる評価目的のqa-xxxサブエージェントはAgents/に作成しない\n  - 評価は `./evaluation/evaluation_criteria.md` を参照したインライン評価を基本とする\n  - ただし変更が広範/高リスク、またはユーザー要望がある場合は `qa-skill-qc` / `red-team-feedback-loop` 等の既存Subagentを並列実行してレビュー強度を上げてもよい（新規Agent作成はしない）\n\n## Resources\n- questions: ./questions/core_rule_maintenance_questions.md\n- assets: ./assets/claude_md_structure.md\n- assets: ./assets/path_dictionary_guide.md\n- assets: ./assets/workflow_index_guide.md\n- evaluation: ./evaluation/evaluation_criteria.md\n- triggers: ./triggers/next_action_triggers.md\n- scripts: scripts/update_agent_master.py\n\n## Next Action\n- triggers: ./triggers/next_action_triggers.md\n\n起動条件に従い、条件を満たすSkillを自動実行する。\n"},"lastSynced":"2026-03-08T02:05:56.300Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Cursor, Windsurf, and Claude Code needing streamlined workflow management through core principle optimization and quality goal consistency.","zh":"非常适合像 Cursor、Windsurf 和 Claude Code 这样的 AI Agent，需要通过核心原则优化和质量目标一致性来简化工作流管理。","ja":"Cursor、Windsurf、Claude Code などの AI Agent に最適で、コア原則の最適化と品質目標の整合性を通じてワークフロー管理を簡素化する必要があるエージェントに適しています。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에 적합하며, 핵심 원칙 최적화 및 품질 목표 일관성을 통해 워크플로우 관리를 간소화하는 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA como Cursor, Windsurf y Claude Code que necesitan una gestión de flujo de trabajo optimizada a través de la optimización de principios básicos y la consistencia de objetivos de calidad.","fr":"Parfait pour les agents IA comme Cursor, Windsurf et Claude Code ayant besoin d''une gestion de workflow optimisée via l''optimisation des principes fondamentaux et la cohérence des objectifs de qualité.","de":"Perfekt für KI-Agents wie Cursor, Windsurf und Claude Code, die eine optimierte Workflow-Verwaltung durch die Optimierung von Grundprinzipien und Qualitätszielen benötigen.","pt":"Perfeito para Agentes de IA como Cursor, Windsurf e Claude Code que necessitam de gerenciamento de fluxo de trabalho otimizado por meio da otimização de princípios fundamentais e consistência de metas de qualidade.","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, которым необходим оптимизированный менеджмент рабочего процесса посредством оптимизации основных принципов и согласованности целей качества.","ar":"مثالي للوكلاء الذكيين مثل Cursor و Windsurf و Claude Code الذين يحتاجون إلى إدارة تدفق العمل المُستَخدَم من خلال تحسين المبادئ الأساسية وثبات أهداف الجودة."},"recommendation":{"en":"Empowers agents to maintain consistency across CLAUDE.md and AGENTS.md files by optimizing core principles, outcome types, and quality goals, utilizing preflight processes and WF indexing for seamless integration with .cursor, .claude, and .codex files.","zh":"赋予代理维护 CLAUDE.md 和 AGENTS.md 文件的一致性，通过优化核心原则、结果类型和质量目标，利用预检过程和 WF 索引实现与 .cursor、.claude 和 .codex 文件的无缝集成。","ja":"CLAUDE.md と AGENTS.md ファイルの整合性を維持するためにエージェントをEmpowerし、コア原則、結果タイプ、品質目標を最適化し、事前チェックプロセスと WF インデックスを使用して、.cursor、.claude、.codex ファイルとのシームレスな統合を実現します。","ko":"에이전트가 CLAUDE.md 및 AGENTS.md 파일에 대해 일관성을 유지하도록 하며, 핵심 원칙, 결과 유형 및 품질 목표를 최적화하고, 사전 점검 프로세스 및 WF 색인을 사용하여 .cursor, .claude 및 .codex 파일과 무缝하게 통합할 수 있습니다.","es":"Habilita a los agentes a mantener la consistencia en los archivos CLAUDE.md y AGENTS.md optimizando los principios básicos, los tipos de resultados y los objetivos de calidad, utilizando procesos de preflight y indexación de WF para una integración sin problemas con los archivos .cursor, .claude y .codex.","fr":"Permet aux agents de maintenir la cohérence entre les fichiers CLAUDE.md et AGENTS.md en optimisant les principes fondamentaux, les types de résultats et les objectifs de qualité, en utilisant des processus de prévol et d''indexation de WF pour une intégration transparente avec les fichiers .cursor, .claude et .codex.","de":"Ermöglicht es Agents, Konsistenz über die Dateien CLAUDE.md und AGENTS.md hinweg zu bewahren, indem sie grundlegende Prinzipien, Ergebnistypen und Qualitätsziele optimieren, unter Nutzung von Preflight-Prozessen und WF-Indexierung für eine nahtlose Integration mit .cursor-, .claude- und .codex-Dateien.","pt":"Habilita os agentes a manter a consistência em todo o CLAUDE.md e AGENTS.md arquivos, otimizando princípios fundamentais, tipos de resultados e metas de qualidade, utilizando processos de pré-voo e indexação de WF para integração perfeita com arquivos .cursor, .claude e .codex.","ru":"Наделяет агентов возможностью поддерживать согласованность во всех файлах CLAUDE.md и AGENTS.md, оптимизируя основные принципы, типы результатов и цели качества, используя предварительные процессы и индексацию WF для бесшовной интеграции с файлами .cursor, .claude и .codex.","ar":"يُمكِّن الوكلاء من الحفاظ على الاتساق على مستوى ملفات CLAUDE.md و AGENTS.md من خلال تحسين المبادئ الأساسية وأنواع النتائج وأهداف الجودة، واستخدام العمليات المسبقة وفهرسة WF من أجل التكامل السلس مع الملفات .cursor و .claude و .codex."},"useCases":{"en":["Automating preflight checks for CLAUDE.md and AGENTS.md files","Streamlining workflow by managing core principles and quality goals","Ensuring consistency across agent definitions in AGENTS.md files"],"zh":["自动执行CLAUDE.md和AGENTS.md文件的预检检查","通过管理核心原则和质量目标来简化工作流程","确保AGENTS.md文件中代理定义的一致性"],"ja":["CLAUDE.md と AGENTS.md ファイルの事前チェックを自動化する","コア原則と品質目標を管理してワークフローを簡素化する","AGENTS.md ファイル内のエージェント定義の整合性を確保する"],"ko":["CLAUDE.md 및 AGENTS.md 파일의 사전 점검을 자동화합니다","핵심 원칙 및 품질 목표를 관리하여 워크플로우를 간소화합니다","에이전트 정의의 일관성을 AGENTS.md 파일에서 보장합니다"],"es":["Automatizar controles de preflight para archivos CLAUDE.md y AGENTS.md","Optimizar el flujo de trabajo gestionando principios básicos y objetivos de calidad","Garantizar la consistencia en las definiciones de agentes en archivos AGENTS.md"],"fr":["Automatiser les vérifications de prévol pour les fichiers CLAUDE.md et AGENTS.md","Optimiser le workflow en gérant les principes fondamentaux et les objectifs de qualité","Assurer la cohérence entre les définitions d''agents dans les fichiers AGENTS.md"],"de":["Automatisieren von Preflight-Prüfungen für CLAUDE.md- und AGENTS.md-Dateien","Optimieren des Workflows durch die Verwaltung von Grundprinzipien und Qualitätszielen","Sicherstellen der Konsistenz zwischen Agentendefinitionen in AGENTS.md-Dateien"],"pt":["Automatizar verificações pré-voo para arquivos CLAUDE.md e AGENTS.md","Otimizar o fluxo de trabalho, gerenciando princípios fundamentais e metas de qualidade","Garantir a consistência em todo o arquivo AGENTS.md de definições de agentes"],"ru":["Автоматизировать предварительные проверки для файлов CLAUDE.md и AGENTS.md","Оптимизировать рабочий процесс, управляя основными принципами и целями качества","Обеспечить согласованность во всех файлах AGENTS.md определений агентов"],"ar":["توفير عمليات فحص مسبقة للأرشيف CLAUDE.md و AGENTS.md","تحسين تدفق العمل من خلال إدارة المبادئ الأساسية وأهداف الجودة","ضمان الاتساق عبر كل تعريفات الوكلاء في ملفات AGENTS.md"]},"limitations":{"en":["Requires access to CLAUDE.md and AGENTS.md files","Limited to agents compatible with .cursor, .claude, and .codex file formats"],"zh":["需要访问CLAUDE.md和AGENTS.md文件","仅限与.cursor、.claude和.codex文件格式兼容的代理"],"ja":["CLAUDE.md と AGENTS.md ファイルへのアクセスが必要",".cursor、.claude、.codex ファイル形式と互換性のあるエージェントのみに限られる"],"ko":["CLAUDE.md 및 AGENTS.md 파일에 대한 액세스가 필요합니다",".cursor, .claude 및 .codex 파일 형식과 호환되는 에이전트만 해당됩니다"],"es":["Requiere acceso a los archivos CLAUDE.md y AGENTS.md","Limitado a agentes compatibles con los formatos de archivo .cursor, .claude y .codex"],"fr":["Nécessite l''accès aux fichiers CLAUDE.md et AGENTS.md","Limité aux agents compatibles avec les formats de fichiers .cursor, .claude et .codex"],"de":["Benötigt Zugriff auf CLAUDE.md- und AGENTS.md-Dateien","Begrenzt auf Agents, die mit den Dateiformaten .cursor, .claude und .codex kompatibel sind"],"pt":["Requer acesso aos arquivos CLAUDE.md e AGENTS.md","Limitado a agentes compatíveis com formatos de arquivo .cursor, .claude e .codex"],"ru":["Требует доступа к файлам CLAUDE.md и AGENTS.md","Ограничен агентами, совместимыми с форматами файлов .cursor, .claude и .codex"],"ar":["يتطلب الوصول إلى ملفات CLAUDE.md و AGENTS.md","محدود بالوكلاء المتوافقة مع تنسيقات الملفات .cursor و .claude و .codex"]},"version":4},"contentHash":"8e327c265912b55624a5fc941e92fbad475ca98889c205a330bacc25aa46f49b","qualityScore":47}');
