INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('matsuni-kk/mini-app-agent/core-rule-maintenance', 'core-rule-maintenance', 'matsuni-kk', 'mini-app-agent', 'community', 'core-rule-maintenance matsuni-kk mini-app-agent community The core-rule-maintenance skill enables AI agents to optimize workflow by managing core principles, outcome types, and quality goals. It benefits developers by streamlining the preflight process and ensuring consistency across CLAUDE.md and AGENTS.md files. 核心规则维护是AIエージェント的关键组成部分，涉及CLAUDE.md和AGENTS.md文件的精心管理 コア規則メンテナンスはAIエージェントの重要な構成要素であり、CLAUDE.mdとAGENTS.mdファイルの慎重な管理を伴う 코어 규칙 유지 보수는 AI 에이전트의 핵심 구성 요소이며 CLAUDE.md 및 AGENTS.md 파일의 신중한 관리가 포함됩니다 El mantenimiento de reglas básicas es crucial para el funcionamiento de los Agentes de IA. Conoce los pasos para configurar y mantener las reglas básicas La maintenance des règles de base est essentielle pour le fonctionnement des outils d''IA. Découvrez les étapes pour configurer et maintenir les règles de base Die Wartung von Grundregeln ist für den Betrieb von KI-Agents entscheidend. Erfahren Sie, wie Sie die Grundregeln konfigurieren und warten können A manutenção de regras core é fundamental para Ferramentas de IA. Este guia aborda a configuração e os melhores práticas. Поддержка основных правил необходима для ИИ Агентов. Это руководство охватывает настройку и лучшие практики. صيانة القواعد الأساسية ضرورية للأدوات الذكية. هذا الدليل يغطي الإعداد وأفضل الممارسات. how to use core-rule-maintenance core-rule-maintenance setup guide core-rule-maintenance alternative core-rule-maintenance vs workflow automation what is core-rule-maintenance core-rule-maintenance install core-rule-maintenance workflow optimization AI agent skill development CLAUDE.md file management AGENTS.md file optimization 核心规则维护 AIエージェント CLAUDE.md AGENTS.md Preflight检查 WF索引 パス辞書 多语言环境 Manages CLAUDE.md files for core principles, outcome types, and quality goals Optimizes AGENTS.md files for agent definitions and asynchronous updates Performs preflight checks to ensure consistency and accuracy Supports synchronization with .cursor, .claude, and .codex files Enables workflow indexing and path dictionary management Streamlines the development process with automated checks and updates core-rule-maintenance is a workflow optimization skill that ensures consistency and accuracy in AI agent development by managing core principles, outcome types, and quality goals.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HSn0918/kubernetes-mcp/kubernetes-mcp-usage', 'community', 'HSn0918', 'kubernetes-mcp', 'HSn0918/kubernetes-mcp', 'kubernetes-mcp-usage', 0, 0, 47, '2026-03-08T01:57:15.405Z', '2026-03-08T02:06:53.918Z', '995989eb9114eb02826270c8632b92078060f6fa1b3aab1f7897a5ae6c0b8736', '{"id":"HSn0918/kubernetes-mcp/kubernetes-mcp-usage","name":"kubernetes-mcp-usage","description":{"en":"The kubernetes-mcp-usage skill enables users to operate Kubernetes through MCP, allowing connection, resource discovery, and cluster state inspection. This skill benefits developers and DevOps teams.","zh":"Kubernetes MCP 使用指南提供连接检查清单和故障排除步骤，帮助开发者高效管理集群。","ja":"Kubernetes MCP 利用ガイドでは、接続確認チェックリストとトラブルシューティング手順を提供し、開発者が効率的にクラスターを管理できるようにします。","ko":"쿠버네티스 MCP 사용설명서는 연결 확인 체크리스트와 문제 해결 단계를 제공하여 개발자가 효율적으로 클러스터를 관리할 수 있도록 합니다.","es":"Guía técnica para operar Kubernetes con kubernetes-mcp-usage. Conecta clientes MCP y descubre recursos de forma sencilla","fr":"Guide technique pour exploiter Kubernetes avec kubernetes-mcp-usage. Connectez les clients MCP et découvrez les ressources de manière simple","de":"Technische Anleitung zum Betreiben von Kubernetes mit kubernetes-mcp-usage. Verbinden Sie MCP-Clients und entdecken Sie Ressourcen auf einfache Weise","pt":"O skill de uso do MCP permite conectar ao servidor Kubernetes e realizar operações de troubleshooting","ru":"ИИ Агент Kubernetes MCP Usage позволяет подключаться к серверу и выполнять операции по устранению неполадок","ar":"مهارة استخدام MCP تمكنك من الاتصال بخادم Kubernetes والقيام بعمليات معالجة الأخطاء"},"seo":{"title":{"en":"kubernetes-mcp-usage: Kubernetes MCP Setup Guide | AI Age...","zh":"Kubernetes MCP 使用设置指南","ja":"Kubernetes MCP 利用ガイド - ベストプラクティス","ko":"쿠버네티스 MCP 사용설명서 - 연결 및 문제 해결","es":"Guía de configuración de kubernetes-mcp-usage para desarr...","fr":"Guide de mise en route de kubernetes-mcp-usage pour les d...","de":"Einrichtungsleitfaden für kubernetes-mcp-usage-Entwickler","pt":"Guia de Configuração do Kubernetes MCP Usage","ru":"Настройка ИИ Агента Kubernetes MCP Usage","ar":"دليل إعداد Kubernetes MCP Usage"},"description":{"en":"Discover how to operate Kubernetes through kubernetes-mcp-usage. Learn to connect, troubleshoot, and inspect cluster state with our expert guide.","zh":"了解 Kubernetes MCP 的连接检查清单和故障排除步骤，实现高效的集群管理，AIエージェント","ja":"Kubernetes MCP を使用してクラスターを操作する方法を学び、効率的なクラスター管理を実現する - AIエージェント","ko":"쿠버네티스 MCP를 사용하여 클러스터를 운영하는 방법을 알아보고 효율적인 클러스터 관리를 실현하세요 - AI 도구","es":"Aprende a utilizar kubernetes-mcp-usage para operar Kubernetes de forma efectiva. Conecta clientes MCP y descubre recursos con facilidad","fr":"Découvrez comment utiliser kubernetes-mcp-usage pour exploiter Kubernetes de manière efficace. Connectez les clients MCP et découvrez les ressources avec fac...","de":"Erfahren Sie, wie Sie kubernetes-mcp-usage verwenden, um Kubernetes effektiv zu betreiben. Verbinden Sie MCP-Clients und entdecken Sie Ressourcen mit Leichti...","pt":"Aprenda a operar o Kubernetes com o skill de uso do MCP, incluindo conexão ao servidor e troubleshooting","ru":"Узнайте, как использовать ИИ Агент Kubernetes MCP Usage для управления кластером и устранения неполадок","ar":"تعلم كيفية تشغيل Kubernetes باستخدام مهارة استخدام MCP، بما في ذلك الاتصال بالخادم ومعالجة الأخطاء"},"definition":{"en":"kubernetes-mcp-usage is a skill that facilitates Kubernetes operation through MCP, enabling connections, resource discovery, and cluster state inspection via stdio, SSE, or streamable protocols.","zh":"Kubernetes MCP 是一种用于操作 Kubernetes 集群的工具，提供连接检查和故障排除功能。","ja":"Kubernetes MCP は、Kubernetes クラスターを操作するためのツールであり、接続確認とトラブルシューティング機能を提供します。","ko":"쿠버네티스 MCP는 쿠버네티스 클러스터를 운영하기 위한 도구로 연결 확인 및 문제 해결 기능을 제공합니다.","es":"kubernetes-mcp-usage es una habilidad que permite a los desarrolladores operar Kubernetes a través de la conexión de clientes MCP","fr":"kubernetes-mcp-usage est une compétence qui permet aux développeurs d''exploiter Kubernetes via la connexion de clients MCP","de":"kubernetes-mcp-usage ist eine Fähigkeit, die es Entwicklern ermöglicht, Kubernetes über die Verbindung von MCP-Clients zu betreiben","pt":"O que é o Kubernetes MCP Usage? É um skill que permite operar o Kubernetes através do MCP","ru":"Что такое ИИ Агент Kubernetes MCP Usage? Это навык, который позволяет управлять кластером Kubernetes через MCP","ar":"ما هي مهارة استخدام MCP؟ هي مهارة تمكنك من تشغيل Kubernetes من خلال MCP"},"features":{"en":["Connects MCP client to server via stdio, SSE, or streamable protocols","Discovers resources and inspects cluster state","Checks logs, events, and metrics for troubleshooting","Troubleshoots failed tool calls and parameter mismatch","Supports binary command with local kubeconfig via stdio","Utilizes POST /mcp endpoint for streamable connections"],"zh":["连接检查清单","故障排除步骤","stdio 和 streamable 连接支持","资源发现和集群状态检查","日志/事件/指标检查"],"ja":["接続確認チェックリスト","トラブルシューティング手順","stdio と streamable 接続サポート","リソース発見とクラスター状態の確認","ログ/イベント/メトリクスの確認"],"ko":["연결 확인 체크리스트","문제 해결 단계","stdio 및 streamable 연결 지원","리소스 발견 및 클러스터 상태 확인","로그/이벤트/메트릭스 확인"],"es":["Conexión de clientes MCP a través de stdio, sse o streamable","Descubrimiento de recursos y inspección del estado del clúster","Verificación de registros y eventos","Solución de problemas de llamadas de herramientas fallidas y discrepancias de parámetros"],"fr":["Connexion de clients MCP via stdio, sse ou streamable","Découverte de ressources et inspection de l''état du cluster","Vérification des journaux et des événements","Dépannage des appels d''outils échoués et des discordances de paramètres"],"de":["Verbindung von MCP-Clients über stdio, sse oder streamable","Entdeckung von Ressourcen und Überprüfung des Clusterzustands","Überprüfung von Protokollen und Ereignissen","Fehlerbehebung bei fehlgeschlagenen Toolaufrufen und Parametern"],"pt":["Conexão ao servidor via stdio, sse ou streamable","Descoberta de recursos e inspeção do estado do cluster","Verificação de logs, eventos e métricas","Troubleshooting de chamadas de ferramentas com falha e discrepância de parâmetros"],"ru":["Подключение к серверу через stdio, sse или streamable","Обнаружение ресурсов и инспекция состояния кластера","Проверка журналов, событий и метрик","Устранение неполадок вызовов инструментов с ошибками и несоответствием параметров"],"ar":["الاتصال بالخادم عبر stdio، sse أو streamable","اكتشاف الموارد وتحقيق حالة Cluster","فحص السجلات والأحداث والمتغيرات","معالجة الأخطاء في مكالمات الأدوات والمعلمات غير المتوافقة"]},"keywords":{"en":["how to use kubernetes-mcp-usage","kubernetes-mcp-usage setup guide","kubernetes-mcp-usage alternative","kubernetes-mcp-usage vs kubectl","kubernetes-mcp-usage install","kubernetes mcp connection checklist","troubleshooting kubernetes-mcp-usage","kubernetes-mcp-usage for DevOps teams","kubernetes-mcp-usage and kubeconfig","kubernetes-mcp-usage streamable protocol"],"zh":["Kubernetes MCP","Kubernetes 集群管理","AIエージェント","连接检查清单","故障排除","stdio","streamable"],"ja":["Kubernetes MCP","Kubernetes クラスター管理","AIエージェント","接続確認チェックリスト","トラブルシューティング","stdio","streamable"],"ko":["쿠버네티스 MCP","쿠버네티스 클러스터 관리","AI 도구","연결 확인 체크리스트","문제 해결","stdio","streamable"],"es":["kubernetes-mcp-usage","operar kubernetes","conexión de clientes MCP","descubrimiento de recursos","inspección del estado del clúster","Herramientas de desarrollo de kubernetes","Agentes de inteligencia artificial para kubernetes"],"fr":["kubernetes-mcp-usage","exploiter kubernetes","connexion de clients MCP","découverte de ressources","inspection de l''état du cluster","Outils de développement de kubernetes","Agents d''intelligence artificielle pour kubernetes"],"de":["kubernetes-mcp-usage","kubernetes betreiben","Verbindung von MCP-Clients","Entdeckung von Ressourcen","Überprüfung des Clusterzustands","Entwicklungstools für kubernetes","Künstliche Intelligenz-Agenten für kubernetes"],"pt":["kubernetes mcp usage","guias de configuração kubernetes","troubleshooting kubernetes","conexão ao servidor kubernetes","descoberta de recursos kubernetes","verificação de logs kubernetes"],"ru":["kubernetes mcp usage","настройка кubernetes","устранение неполадок kubernetes","подключение к серверу kubernetes","обнаружение ресурсов kubernetes","проверка журналов kubernetes"],"ar":["استخدام kubernetes mcp","دليل إعداد كوبيرنتس","معالجة الأخطاء في كوبيرنتس","الاتصال بخادم كوبيرنتس","اكتشاف موارد كوبيرنتس","فحص سجلات كوبيرنتس"]}},"owner":"HSn0918","repo":"kubernetes-mcp","repoPath":"HSn0918/kubernetes-mcp","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.405Z","topics":[],"category":"community","skillMd":{"name":"kubernetes-mcp-usage","description":"Usage guide skill for kubernetes-mcp MCP server. Use when connecting the MCP server to clients, troubleshooting tool calls, and selecting the right Kubernetes tools for diagnosis and operations.","bodyPreview":"# Kubernetes MCP Usage Guide\n\n## When to Use\nUse this skill when the user wants to operate Kubernetes through `kubernetes-mcp`:\n- connect MCP client to this server (`stdio`, `sse`, `streamable`);\n- discover resources, inspect cluster state, check logs/events/metrics;\n- troubleshoot failed tool calls and parameter mismatch.\n\n## Connection Checklist\n1. Confirm server is reachable:\n   - `stdio`: binary command works with local kubeconfig.\n   - `streamable`: endpoint is `POST /mcp`.\n2. Confirm Kuber","body":"# Kubernetes MCP Usage Guide\n\n## When to Use\nUse this skill when the user wants to operate Kubernetes through `kubernetes-mcp`:\n- connect MCP client to this server (`stdio`, `sse`, `streamable`);\n- discover resources, inspect cluster state, check logs/events/metrics;\n- troubleshoot failed tool calls and parameter mismatch.\n\n## Connection Checklist\n1. Confirm server is reachable:\n   - `stdio`: binary command works with local kubeconfig.\n   - `streamable`: endpoint is `POST /mcp`.\n2. Confirm Kubernetes auth is valid:\n   - explicit `--kubeconfig` or in-cluster service account.\n3. Prefer smallest-scope query first:\n   - namespace + kind filters before wide cluster scans.\n\n## Recommended Tool Flow\n1. Health and inventory:\n   - `GET_CLUSTER_INFO`\n   - `LIST_NAMESPACES`\n2. Resource location:\n   - `SEARCH_RESOURCES` (supports `name=...`, `label=...`, `annotation=...`, wildcard `*`)\n   - `LIST_K8S_RESOURCES`\n3. Deep inspection:\n   - `GET_K8S_RESOURCE` / `DESCRIBE_K8S_RESOURCE`\n   - `GET_EVENTS`\n4. Runtime diagnosis:\n   - `GET_POD_LOGS`\n   - `GET_POD_METRICS`, `GET_NODE_METRICS`, `GET_TOP_CONSUMERS`\n\n## Practical Query Patterns\n- Find all pods in namespace:\n  - `SEARCH_RESOURCES {\"kinds\":\"Pod\",\"namespaces\":\"mcp-system\",\"query\":\"name=*\"}`\n- Find by label wildcard:\n  - `SEARCH_RESOURCES {\"query\":\"label=app:nginx-*\",\"namespaces\":\"default\"}`\n- Find by annotation:\n  - `SEARCH_RESOURCES {\"query\":\"annotation=team:platform\",\"namespaces\":\"default\"}`\n- List known kind explicitly:\n  - `LIST_K8S_RESOURCES {\"kind\":\"Pod\",\"apiVersion\":\"v1\",\"namespace\":\"default\"}`\n- List namespace resources by discovery:\n  - `LIST_K8S_RESOURCES {\"namespace\":\"default\"}`\n\n## Error Handling Guidance\n- If listing fails with missing `apiVersion`:\n  - provide both `kind` and `apiVersion`, or omit `kind` for discovery listing.\n- If search returns empty unexpectedly:\n  - check `kinds` value (`Pod`/`pods` both accepted),\n  - verify namespace scope,\n  - test with `query:\"name=*\"` first.\n- If metrics tools fail:\n  - confirm metrics-server is installed and accessible.\n\n## Safety\n- Avoid destructive actions (`DELETE`, large apply) unless user explicitly requests.\n- For changes, prefer `VALIDATE_MANIFEST` and `DIFF_MANIFEST` before `APPLY_MANIFEST`.\n"},"lastSynced":"2026-03-08T02:06:53.918Z","agentAnalysis":{"suitability":{"en":"Ideal for Cloud Agents requiring seamless Kubernetes integration through MCP for resource discovery and cluster state inspection","zh":"适用于需要通过MCP实现无缝Kubernetes集成的云代理，用于资源发现和集群状态检查","ja":"MCPを介したシームレスなKubernetes統合を必要とするCloud Agentsに適しています。リソースの検出とクラスタ状態の検査に使用されます","ko":"MCP를 통해 무중단 Kubernetes 통합을 필요로 하는 클라우드 에이전트에 적합합니다. 리소스 검색 및 클러스터 상태 감시를 위해 사용됩니다","es":"Ideal para Agentes en la Nube que requieren una integración perfecta con Kubernetes a través de MCP para el descubrimiento de recursos y la inspección del estado del clúster","fr":"Idéal pour les agents Cloud nécessitant une intégration transparente avec Kubernetes via MCP pour la découverte de ressources et l''inspection de l''état du cluster","de":"Ideal für Cloud-Agents, die eine nahtlose Kubernetes-Integration über MCP für die Ressourcenerkennung und die Clusterzustandsprüfung benötigen","pt":"Ideal para Agentes de Nuvem que exigem integração sem interrupções com Kubernetes por meio do MCP para descoberta de recursos e inspeção do estado do cluster","ru":"Идеально для облачных агентов, требующих бесшовной интеграции с Kubernetes через MCP для обнаружения ресурсов и инспекции состояния кластера","ar":"مثالي لعميل السحابة الذي يتطلب تكاملًا بدون انقطاع مع Kubernetes من خلال MCP للكشف عن الموارد وتفتيش حالة المجموعة"},"recommendation":{"en":"Empowers agents to connect MCP clients to Kubernetes servers via stdio, sse, or streamable protocols, enabling resource discovery, cluster state inspection, and log/event/metric checking through kubernetes-mcp-usage","zh":"赋予代理连接MCP客户端到Kubernetes服务器的能力，通过stdio、sse或可流化协议，实现资源发现、集群状态检查以及通过kubernetes-mcp-usage进行日志/事件/指标检查","ja":"エージェントに、stdio、sse、またはストリーミング可能なプロトコルを介してMCPクライアントをKubernetesサーバーに接続する機能を提供します。リソースの検出、クラスタ状態の検査、kubernetes-mcp-usageを介したログ/イベント/メトリックの確認が可能になります","ko":"에이전트에 MCP 클라이언트를 Kubernetes 서버에 연결할 수 있는 능력을 부여하여 stdio, sse 또는 스트리밍 가능한 프로토콜을 통해 리소스 검색, 클러스터 상태 감시 및 kubernetes-mcp-usage를 통해 로그/이벤트/메트릭 확인을 구현합니다","es":"Habilita a los agentes a conectar clientes MCP a servidores Kubernetes a través de stdio, sse o protocolos transmisibles, lo que permite el descubrimiento de recursos, la inspección del estado del clúster y la comprobación de registros/eventos/métricas a través de kubernetes-mcp-usage","fr":"Permet aux agents de connecter les clients MCP aux serveurs Kubernetes via stdio, sse ou des protocoles transmissibles, permettant ainsi la découverte de ressources, l''inspection de l''état du cluster et la vérification des journaux/événements/métriques via kubernetes-mcp-usage","de":"Ermächtigt die Agenten, MCP-Clients mit Kubernetes-Servern über stdio, sse oder streambare Protokolle zu verbinden, wodurch die Ressourcenerkennung, die Clusterzustandsprüfung und die Überprüfung von Protokollen/Ereignissen/Metriken über kubernetes-mcp-usage ermöglicht wird","pt":"Habilita os agentes a conectar clientes MCP a servidores Kubernetes via stdio, sse ou protocolos transmissíveis, permitindo a descoberta de recursos, a inspeção do estado do cluster e a verificação de logs/eventos/métricas por meio do kubernetes-mcp-usage","ru":"Позволяет агентам подключать клиентов MCP к серверам Kubernetes через stdio, sse или передаваемые протоколы, обеспечивая обнаружение ресурсов, инспекцию состояния кластера и проверку журналов/событий/метрик через kubernetes-mcp-usage","ar":"تمكن العميل من подключ عملاء MCP إلى خوادم Kubernetes من خلال stdio أو sse أو بروتوكولات قابلة للبث، وتمكين الكشف عن الموارد وتفتيش حالة المجموعة وتنفيذ عمليات فحص السجلات والأحداث والأرقام من خلال kubernetes-mcp-usage"},"useCases":{"en":["Connecting MCP clients to Kubernetes servers","Discovering resources and inspecting cluster states","Troubleshooting failed tool calls and parameter mismatches"],"zh":["连接MCP客户端到Kubernetes服务器","发现资源和检查集群状态","解决工具调用失败和参数不匹配的问题"],"ja":["MCPクライアントをKubernetesサーバーに接続する","リソースを発見してクラスタ状態を検査する","ツール呼び出しの失敗やパラメータの不一致をトラブルシューティングする"],"ko":["MCP 클라이언트를 Kubernetes 서버에 연결하는 것","리소스를 발견하고 클러스터 상태를 검사하는 것","도구 호출 실패 및 매개 변수 불일치를 해결하는 것"],"es":["Conectar clientes MCP a servidores Kubernetes","Descubrir recursos e inspeccionar estados de clúster","Solucionar errores en llamadas de herramientas y discrepancias de parámetros"],"fr":["Connecter les clients MCP aux serveurs Kubernetes","Découvrir les ressources et inspecter les états du cluster","Résoudre les appels d''outils échoués et les discordances de paramètres"],"de":["MCP-Clients mit Kubernetes-Servern verbinden","Ressourcen erkennen und Clusterzustände prüfen","Fehlerhafte Toolaufrufe und Parameterdiskrepanzen beheben"],"pt":["Conectar clientes MCP a servidores Kubernetes","Descobrir recursos e inspecionar estados de cluster","Solucionar problemas de chamadas de ferramentas com falhas e discrepâncias de parâmetros"],"ru":["Подключение клиентов MCP к серверам Kubernetes","Обнаружение ресурсов и инспекция состояний кластера","Устранение неисправностей вызовов инструментов и несоответствий параметров"],"ar":["التوصيل بعملاء MCP إلى خوادم Kubernetes","اكتشاف الموارد وتفتيش حالات المجموعة","معالجة مشاكل呼叫ات الأدوات الفاشلة واختلافات المعاملات"]},"limitations":{"en":["Requires reachable Kubernetes server","Confirmed kubeconfig for stdio connections","Accessible endpoint for streamable connections"],"zh":["需要可达的Kubernetes服务器","确认的kubeconfig用于stdio连接","可访问的端点用于可流化连接"],"ja":["到達可能なKubernetesサーバーが必要","stdio接続用に確認されたkubeconfig","ストリーミング可能な接続用にアクセス可能なエンドポイント"],"ko":["도달 가능한 Kubernetes 서버가 필요","stdio 연결을 위한 확인된 kubeconfig","스트리밍 가능한 연결을 위한 접근 가능한 엔드포인트"],"es":["Requiere un servidor Kubernetes accesible","kubeconfig confirmada para conexiones stdio","Punto de conexión accesible para conexiones transmisibles"],"fr":["Nécessite un serveur Kubernetes accessible","kubeconfig confirmée pour les connexions stdio","Point de terminaison accessible pour les connexions transmissibles"],"de":["Benötigt einen erreichbaren Kubernetes-Server","Bestätigte kubeconfig für stdio-Verbindungen","Zugänglicher Endpunkt für streambare Verbindungen"],"pt":["Exige servidor Kubernetes acessível","kubeconfig confirmado para conexões stdio","Ponto de extremidade acessível para conexões transmissíveis"],"ru":["Требуется доступный сервер Kubernetes","Подтвержденный kubeconfig для подключений stdio","Доступная конечная точка для передаваемых подключений"],"ar":["يتطلب خادم Kubernetes يمكن الوصول إليه","kubeconfig مؤكد للاتصالات stdio","نقطة نهاية قابلة للوصول للاتصالات القابلة للبث"]},"version":4},"contentHash":"995989eb9114eb02826270c8632b92078060f6fa1b3aab1f7897a5ae6c0b8736","qualityScore":47}');
