INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HSn0918/kubernetes-mcp/kubernetes-mcp-usage', 'kubernetes-mcp-usage', 'HSn0918', 'kubernetes-mcp', 'community', 'kubernetes-mcp-usage HSn0918 kubernetes-mcp community The kubernetes-mcp-usage skill enables users to operate Kubernetes through MCP, allowing connection, resource discovery, and cluster state inspection. This skill benefits developers and DevOps teams. Kubernetes MCP 使用指南提供连接检查清单和故障排除步骤，帮助开发者高效管理集群。 Kubernetes MCP 利用ガイドでは、接続確認チェックリストとトラブルシューティング手順を提供し、開発者が効率的にクラスターを管理できるようにします。 쿠버네티스 MCP 사용설명서는 연결 확인 체크리스트와 문제 해결 단계를 제공하여 개발자가 효율적으로 클러스터를 관리할 수 있도록 합니다. Guía técnica para operar Kubernetes con kubernetes-mcp-usage. Conecta clientes MCP y descubre recursos de forma sencilla Guide technique pour exploiter Kubernetes avec kubernetes-mcp-usage. Connectez les clients MCP et découvrez les ressources de manière simple Technische Anleitung zum Betreiben von Kubernetes mit kubernetes-mcp-usage. Verbinden Sie MCP-Clients und entdecken Sie Ressourcen auf einfache Weise O skill de uso do MCP permite conectar ao servidor Kubernetes e realizar operações de troubleshooting ИИ Агент Kubernetes MCP Usage позволяет подключаться к серверу и выполнять операции по устранению неполадок مهارة استخدام MCP تمكنك من الاتصال بخادم Kubernetes والقيام بعمليات معالجة الأخطاء how to use kubernetes-mcp-usage kubernetes-mcp-usage setup guide kubernetes-mcp-usage alternative kubernetes-mcp-usage vs kubectl kubernetes-mcp-usage install kubernetes mcp connection checklist troubleshooting kubernetes-mcp-usage kubernetes-mcp-usage for DevOps teams kubernetes-mcp-usage and kubeconfig kubernetes-mcp-usage streamable protocol Kubernetes MCP Kubernetes 集群管理 AIエージェント 连接检查清单 故障排除 stdio streamable Connects MCP client to server via stdio, SSE, or streamable protocols Discovers resources and inspects cluster state Checks logs, events, and metrics for troubleshooting Troubleshoots failed tool calls and parameter mismatch Supports binary command with local kubeconfig via stdio Utilizes POST /mcp endpoint for streamable connections kubernetes-mcp-usage is a skill that facilitates Kubernetes operation through MCP, enabling connections, resource discovery, and cluster state inspection via stdio, SSE, or streamable protocols.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anyulled/superhero-battle-arena/java-architect', 'community', 'anyulled', 'superhero-battle-arena', 'anyulled/superhero-battle-arena', 'java-architect', 0, 0, 47, '2026-03-08T01:57:15.418Z', '2026-03-08T02:07:19.202Z', '1f4bb89974e8761a2c0bed93dc46776f8f7ccd1e10d52174d1dd5ed8ad13752f', '{"id":"anyulled/superhero-battle-arena/java-architect","name":"java-architect","description":{"en":"The java-architect skill empowers senior Java developers to craft robust, cloud-native applications using Spring Boot 3.x and Java 21 LTS. It benefits developers seeking expertise in microservices architecture and reactive programming.","zh":"Java Architect AIエージェント是一种高级Java开发工具，专注于Spring Boot和微服务架构","ja":"JavaアーキテクトAIエージェントは、高度なJava開発ツールで、Spring Bootとミクロサービスアーキテクチャに特化しています","ko":"자바 아키텍트 AI 에이전트는 고급 자바 개발 도구로 스프링 부트와 마이크로 서비스 아키텍처에 중점을 둡니다","es":"Java Architect es un experto en aplicaciones de Spring Boot con experiencia en arquitectura de microservicios y desarrollo cloud-native","fr":"Java Architect est un expert en applications Spring Boot avec une expérience dans l''architecture de microservices et le développement cloud-native","de":"Java Architect ist ein Experte für Spring-Boot-Anwendungen mit Erfahrung in der Mikroservices-Architektur und der cloud-nativen Entwicklung","pt":"O Java Architect é um especialista em aplicações Java de nível empresarial com Spring Boot 3.x e microserviços escaláveis","ru":"ИИ Агент Java Architect - это senior-специалист по разработке企业-приложений на Java с Spring Boot 3.x и микросервисной архитектурой","ar":"معماري جافا هو خبير في تطبيقات جافا المؤسسية مع Spring Boot 3.x وتصميم微خدمات معمارية جافا"},"seo":{"title":{"en":"java-architect: Spring Boot 3.x Expertise for AI Agents |...","zh":"Java Architect Setup Guide - AIエージェント开发最佳实践","ja":"Javaアーキテクトベストプラクティス - AIエージェント開発ガイド","ko":"자바 아키텍트 설