INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anyulled/superhero-battle-arena/java-architect', 'java-architect', 'anyulled', 'superhero-battle-arena', 'community', 'java-architect anyulled superhero-battle-arena community The java-architect skill empowers senior Java developers to craft robust, cloud-native applications using Spring Boot 3.x and Java 21 LTS. It benefits developers seeking expertise in microservices architecture and reactive programming. Java Architect AIエージェント是一种高级Java开发工具，专注于Spring Boot和微服务架构 JavaアーキテクトAIエージェントは、高度なJava開発ツールで、Spring Bootとミクロサービスアーキテクチャに特化しています 자바 아키텍트 AI 에이전트는 고급 자바 개발 도구로 스프링 부트와 마이크로 서비스 아키텍처에 중점을 둡니다 Java Architect es un experto en aplicaciones de Spring Boot con experiencia en arquitectura de microservicios y desarrollo cloud-native Java Architect est un expert en applications Spring Boot avec une expérience dans l''architecture de microservices et le développement cloud-native Java Architect ist ein Experte für Spring-Boot-Anwendungen mit Erfahrung in der Mikroservices-Architektur und der cloud-nativen Entwicklung O Java Architect é um especialista em aplicações Java de nível empresarial com Spring Boot 3.x e microserviços escaláveis ИИ Агент Java Architect - это senior-специалист по разработке企业-приложений на Java с Spring Boot 3.x и микросервисной архитектурой معماري جافا هو خبير في تطبيقات جافا المؤسسية مع Spring Boot 3.x وتصميم微خدمات معمارية جافا how to use java-architect java-architect setup guide java-architect alternative java-architect vs Spring Boot what is java-architect java-architect install java-architect tutorial java-architect microservices java-architect reactive programming Java Architect AIエージェント Spring Boot开发 微服务架构 云原生开发 Project Reactor Clean Architecture SOLID原则 生产就绪模式 Builds scalable microservices using Spring Boot 3.x Applies Clean Architecture and SOLID principles Utilizes reactive programming with Project Reactor Develops cloud-native applications with Java 21 LTS Implements production-ready patterns for enterprise-grade applications java-architect is a senior Java architect skill with expertise in enterprise-grade Spring Boot applications, microservices architecture, and cloud-native development using Java 21 LTS and Project Reactor.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('StrayDragon/oratio/openspec-verify-change', 'community', 'StrayDragon', 'oratio', 'StrayDragon/oratio', 'openspec-verify-change', 0, 0, 47, '2026-03-08T01:57:15.423Z', '2026-03-08T02:07:25.960Z', 'a10061f96348d38acfa3956f7902414b46cc3acf7ef595e8c827fad5a1ee7647', '{"id":"StrayDragon/oratio/openspec-verify-change","name":"openspec-verify-change","description":{"en":"openspec-verify-change is a self-hosted tool that verifies implementation against change artifacts, benefiting developers by ensuring consistency across specs, tasks, and design.","zh":"openspec-verify-change工具用于验证实现是否与变更工件一致，支持命令行界面和JSON输出","ja":"openspec-verify-change AIエージェントは、実装が変更アーティファクトと一致するかを検証し、CLIとJSON出力をサポートします","ko":"openspec-verify-change AI 도구는 구현이 변경 아티팩트와 일치하는지 검증하며, CLI와 JSON 출력을 지원합니다","es":"openspec-verify-change es una herramienta de verificación de cambios para proyectos de desarrollo que utiliza CLI y JSON","fr":"openspec-verify-change est un outil de vérification de modifications pour les projets de développement utilisant CLI et JSON","de":"openspec-verify-change ist ein Überprüfungstool für Änderungen in Entwicklungsprojekten, das CLI und JSON verwendet","pt":"O openspec-verify-change é uma ferramenta de verificação de mudanças para desenvolvedores que ajuda a garantir a consistência entre as alterações e os artefatos","ru":"openspec-verify-change - это инструмент для проверки изменений для разработчиков, который помогает обеспечить согласованность между изменениями и артефактами с помощью ИИ Агентов","ar":"openspec-verify-change هو أداة التحقق من التغييرات للمطورين التي تساعد على ضمان الاتساق بين التغييرات والمنفذات مع الوكلاء الذكاء الاصطناعي"},"seo":{"title":{"en":"openspec-verify-change: Verification Setup Guide for AI A...","zh":"openspec-verify-change 工具配置指南","ja":"openspec-verify-change AIエージェントのセットアップガイド","ko":"openspec-verify-change AI 도구 설정 가이드","es":"Guía de configuración de openspec-verify-change para herr...","fr":"Guide de mise en œuvre d''openspec-verify-change pour les ...","de":"Einrichtungsleitfaden für openspec-verify-change bei AI-T...","pt":"Guia de Configuração do openspec-verify-change: Ferrament...","ru":"Настройка openspec-verify-change: Инструмент для проверки...","ar":"دليل إعداد openspec-verify-change: أداة التحقق من التغيير..."},"description":{"en":"Discover how openspec-verify-change streamlines verification processes with JSON outputs and AskUserQuestion tools - get started now!","zh":"了解openspec-verify-change工具的功能和设置方法，实现变更验证和项目管理","ja":"openspec-verify-change AIエージェントを使用して変更の検証とプロジェクト管理を実現する","ko":"openspec-verify-change AI 도구를 사용하여 변경 사항을 검증하고 프로젝트를 관리하는 방법을 알아보세요","es":"Aprende a configurar openspec-verify-change para verificar cambios en proyectos de desarrollo con herramientas de AI","fr":"Découvrez comment configurer openspec-verify-change pour vérifier les modifications dans les projets de développement avec des outils d''IA","de":"Erfahren Sie, wie Sie openspec-verify-change einrichten, um Änderungen in Entwicklungsprojekten mit AI-Tools zu überprüfen","pt":"Aprenda a configurar o openspec-verify-change, uma ferramenta de verificação de mudanças para desenvolvedores, e melhore a eficiência do seu workflow","ru":"Узнайте, как настроить openspec-verify-change, инструмент для проверки изменений для разработчиков, и повысьте эффективность своего рабочего процесса с помощ...","ar":"تعرف على كيفية إعداد openspec-verify-change، أداة التحقق من التغييرات للمطورين، ورفع كفاءة سير العمل الخاص بك مع الوكلاء الذكاء الاصطناعي"},"definition":{"en":"openspec-verify-change is a cross-platform, privacy-focused speech-to-text input tool for verifying changes against implementation artifacts.","zh":"openspec-verify-change工具是一种用于验证实现与变更工件一致性的命令行工具","ja":"openspec-verify-change AIエージェントは、実装と変更アーティファクトの一致性を検証するためのCLIツールです","ko":"openspec-verify-change AI 도구는 구현과 변경 아티팩트의 일치성을 검증하는 CLI 도구입니다","es":"openspec-verify-change es una herramienta de verificación de cambios que garantiza la coherencia con los artefactos de proyecto","fr":"openspec-verify-change est un outil de vérification de modifications qui assure la cohérence avec les artefacts de projet","de":"openspec-verify-change ist ein Überprüfungstool für Änderungen, das die Konsistenz mit den Projektartefakten sicherstellt","pt":"O openspec-verify-change é uma ferramenta de linha de comando que verifica a implementação de mudanças em relação aos artefatos","ru":"openspec-verify-change - это командная утилита, которая проверяет реализацию изменений в отношении артефактов с помощью ИИ Агентов","ar":"openspec-verify-change هو أداة سطر الأوامر التي تحقق من تنفيذ التغييرات فيما يتعلق بالمنفذات مع الوكلاء الذكاء الاصطناعي"},"features":{"en":["Runs `openspec list --json` to retrieve available changes","Utilizes AskUserQuestion tool for user selection of changes","Displays changes with implementation tasks and schema usage","Checks status with `openspec status --change <name> --json` to understand schema","Loads change directories and artifacts for verification"],"zh":["支持命令行界面","输出JSON格式的结果","可以列出可用的变更","支持用户选择变更","可以获取变更目录和加载工件","支持检查状态以了解schema"],"ja":["CLIをサポート","JSON形式の結果を出力","利用可能な変更をリストする","ユーザーが変更を選択できる","変更ディレクトリとアーティファクトを取得する","ステータスを確認してスキーマを理解する"],"ko":["CLI를 지원","JSON 형식의 결과를 출력","사용 가능한 변경 사항을 목록화","사용자가 변경 사항을 선택할 수 있음","변경 디렉토리와 아티팩트를 가져옴","상태를 확인하여 스키마를 이해"],"es":["Verificación de cambios con CLI","Uso de JSON para parsear artefactos de proyecto","Compatibilidad con múltiples esquemas de trabajo","Selección de cambios por parte del usuario","Integración con herramientas de AI"],"fr":["Vérification de modifications avec CLI","Utilisation de JSON pour parser les artefacts de projet","Compatibilité avec plusieurs schémas de travail","Sélection de modifications par l''utilisateur","Intégration avec des outils d''IA"],"de":["Überprüfung von Änderungen mit CLI","Verwendung von JSON zum Parsen von Projektartefakten","Kompatibilität mit mehreren Arbeitsabläufen","Auswahl von Änderungen durch den Benutzer","Integration mit AI-Tools"],"pt":["Verificação de mudanças em relação aos artefatos","Suporte a múltiplos esquemas de trabalho","Integração com a ferramenta AskUserQuestion","Exibição de mudanças em andamento","Suporte a formato JSON"],"ru":["Проверка изменений в отношении артефактов","Поддержка нескольких схем работы","Интеграция с инструментом AskUserQuestion","Отображение изменений в процессе","Поддержка формата JSON с помощью ИИ Агентов"],"ar":["التحقق من التغييرات فيما يتعلق بالمنفذات","دعم مخططات العمل المتعددة","التكامل مع أداة AskUserQuestion","عرض التغييرات الجارية","دعم تنسيق JSON مع الوكلاء الذكاء الاصطناعي"]},"keywords":{"en":["how to use openspec-verify-change","openspec-verify-change setup guide","openspec-verify-change alternative tools","what is openspec-verify-change","openspec-verify-change vs spec-driven workflow","openspec-verify-change install for AI agents"],"zh":["openspec-verify-change","变更验证","命令行工具","JSON输出","CLI","项目管理","变更管理","实现验证"],"ja":["openspec-verify-change","変更検証","CLIツール","JSON出力","AIエージェント","プロジェクト管理","変更管理","実装検証"],"ko":["openspec-verify-change","변경 검증","CLI 도구","JSON 출력","AI 도구","프로젝트 관리","변경 관리","구현 검증"],"es":["herramientas de AI","openspec-verify-change","verificación de cambios","CLI","JSON","desarrollo de software","integración con AI","configuración de openspec-verify-change"],"fr":["outils d''IA","openspec-verify-change","vérification de modifications","CLI","JSON","développement de logiciels","intégration avec l''IA","configuration d''openspec-verify-change"],"de":["AI-Tools","openspec-verify-change","Überprüfung von Änderungen","CLI","JSON","Softwareentwicklung","Integration mit AI","Einrichtung von openspec-verify-change"],"pt":["openspec-verify-change","ferramenta de verificação de mudanças","desenvolvimento de software","linha de comando","JSON","AskUserQuestion","esquemas de trabalho"],"ru":["openspec-verify-change","инструмент для проверки изменений","разработка программного обеспечения","командная утилита","JSON","AskUserQuestion","схемы работы","ИИ Агенты"],"ar":["openspec-verify-change","أداة التحقق من التغييرات","تطوير البرمجيات","سطر الأوامر","JSON","AskUserQuestion","مخططات العمل","الوكلاء الذكاء الاصطناعي"]}},"owner":"StrayDragon","repo":"oratio","repoPath":"StrayDragon/oratio","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.423Z","topics":[],"category":"community","skillMd":{"name":"openspec-verify-change","description":"Verify implementation matches change artifacts. Use when the user wants to validate that implementation is complete, correct, and coherent before archiving.","version":"1.0","bodyPreview":"验证实现是否与变更工件（specs、tasks、design）一致。\n\n**输入**：可选指定变更名称。如果省略，先判断是否可从对话上下文推断；若含糊或不明确，必须提示可用的变更。\n\n**步骤**\n\n1. **如果未提供变更名称，提示进行选择**\n\n   运行 `openspec list --json` 以获取可用变更。使用 **AskUserQuestion 工具** 让用户选择。\n\n   显示具有实施任务的变更（存在 tasks 工件）。\n   如可用，包含每个变更使用的 schema。\n   将未完成任务的变更标记为“(进行中)”。\n\n   **重要**：不要猜测或自动选择变更。始终让用户选择。\n\n2. **检查状态以了解 schema**\n   ```bash\n   openspec status --change \"<name>\" --json\n   ```\n   解析 JSON 以了解：\n   - `schemaName`：正在使用的工作流（例如 \"spec-driven\"、\"tdd\"）\n   - 该变更存在的工件\n\n3. **获取变更目录并加载工件**\n\n   ```b","body":"验证实现是否与变更工件（specs、tasks、design）一致。\n\n**输入**：可选指定变更名称。如果省略，先判断是否可从对话上下文推断；若含糊或不明确，必须提示可用的变更。\n\n**步骤**\n\n1. **如果未提供变更名称，提示进行选择**\n\n   运行 `openspec list --json` 以获取可用变更。使用 **AskUserQuestion 工具** 让用户选择。\n\n   显示具有实施任务的变更（存在 tasks 工件）。\n   如可用，包含每个变更使用的 schema。\n   将未完成任务的变更标记为“(进行中)”。\n\n   **重要**：不要猜测或自动选择变更。始终让用户选择。\n\n2. **检查状态以了解 schema**\n   ```bash\n   openspec status --change \"<name>\" --json\n   ```\n   解析 JSON 以了解：\n   - `schemaName`：正在使用的工作流（例如 \"spec-driven\"、\"tdd\"）\n   - 该变更存在的工件\n\n3. **获取变更目录并加载工件**\n\n   ```bash\n   openspec instructions apply --change \"<name>\" --json\n   ```\n\n   这会返回变更目录和上下文文件。从 `contextFiles` 读取所有可用工件。\n\n4. **初始化验证报告结构**\n\n   创建包含三个维度的报告结构：\n   - **Completeness**：跟踪任务和规范覆盖\n   - **Correctness**：跟踪需求实现和场景覆盖\n   - **Coherence**：跟踪设计遵循和模式一致性\n\n   每个维度可以有 CRITICAL、WARNING 或 SUGGESTION 问题。\n\n5. **验证完整性**\n\n   **任务完成情况**：\n   - 如果 contextFiles 中存在 tasks.md，读取它\n   - 解析复选框：`- [ ]`（未完成） vs `- [x]`（完成）\n   - 统计完成数与总数\n   - 如果存在未完成任务：\n     - 为每个未完成任务添加 CRITICAL 问题\n     - 推荐：\"Complete task: <description>\" 或 \"Mark as done if already implemented\"\n\n   **规范覆盖**：\n   - 如果 `openspec/changes/<name>/specs/` 中存在增量规范：\n     - 提取所有需求（标记为 \"### Requirement:\"）\n     - 对每个需求：\n       - 搜索代码库中与需求相关的关键词\n       - 评估是否可能存在实现\n     - 如果需求看起来未实现：\n       - 添加 CRITICAL 问题：\"Requirement not found: <requirement name>\"\n       - 推荐：\"Implement requirement X: <description>\"\n\n6. **验证正确性**\n\n   **需求实现映射**：\n   - 对每个增量规范中的需求：\n     - 搜索代码库中的实现证据\n     - 如找到，记录文件路径和行范围\n     - 评估实现是否符合需求意图\n     - 如果发现偏差：\n       - 添加 WARNING：\"Implementation may diverge from spec: <details>\"\n       - 推荐：\"Review <file>:<lines> against requirement X\"\n\n   **场景覆盖**：\n   - 对每个增量规范中的场景（标记为 \"#### Scenario:\"）：\n     - 检查代码是否处理了条件\n     - 检查是否存在覆盖该场景的测试\n     - 如果场景看起来未覆盖：\n       - 添加 WARNING：\"Scenario not covered: <scenario name>\"\n       - 推荐：\"Add test or implementation for scenario: <description>\"\n\n7. **验证一致性**\n\n   **设计遵循**：\n   - 如果 contextFiles 中存在 design.md：\n     - 提取关键决策（查找 \"Decision:\"、\"Approach:\"、\"Architecture:\" 等部分）\n     - 验证实现是否遵循这些决策\n     - 如果发现矛盾：\n       - 添加 WARNING：\"Design decision not followed: <decision>\"\n       - 推荐：\"Update implementation or revise design.md to match reality\"\n   - 如果没有 design.md：跳过设计遵循检查，并注明 \"No design.md to verify against\"\n\n   **代码模式一致性**：\n   - 检查新代码是否符合项目模式\n   - 检查文件命名、目录结构、编码风格\n   - 如果发现显著偏离：\n     - 添加 SUGGESTION：\"Code pattern deviation: <details>\"\n     - 推荐：\"Consider following project pattern: <example>\"\n\n8. **生成验证报告**\n\n   **Summary Scorecard**:\n   ```\n   ## Verification Report: <change-name>\n\n   ### Summary\n   | Dimension    | Status           |\n   |--------------|------------------|\n   | Completeness | X/Y tasks, N reqs|\n   | Correctness  | M/N reqs covered |\n   | Coherence    | Followed/Issues  |\n   ```\n\n   **Issues by Priority**:\n\n   1. **CRITICAL** (Must fix before archive):\n      - Incomplete tasks\n      - Missing requirement implementations\n      - Each with specific, actionable recommendation\n\n   2. **WARNING** (Should fix):\n      - Spec/design divergences\n      - Missing scenario coverage\n      - Each with specific recommendation\n\n   3. **SUGGESTION** (Nice to fix):\n      - Pattern inconsistencies\n      - Minor improvements\n      - Each with specific recommendation\n\n   **Final Assessment**:\n   - If CRITICAL issues: \"X critical issue(s) found. Fix before archiving.\"\n   - If only warnings: \"No critical issues. Y warning(s) to consider. Ready for archive (with noted improvements).\"\n   - If all clear: \"All checks passed. Ready for archive.\"\n\n**Verification Heuristics**\n\n- **Completeness**：聚焦客观检查项（复选框、需求列表）\n- **Correctness**：使用关键词搜索、文件路径分析、合理推断——无需绝对确定\n- **Coherence**：关注明显不一致，不吹毛求疵\n- **False Positives**：不确定时，优先 SUGGESTION，其次 WARNING，再到 CRITICAL\n- **Actionability**：每个问题都必须给出具体建议，并在可行时附文件/行号引用\n\n**Graceful Degradation**\n\n- 如果只有 tasks.md：仅验证任务完成情况，跳过规范/设计检查\n- 如果有 tasks + specs：验证完整性和正确性，跳过设计\n- 如果工件齐全：验证三个维度\n- 始终说明跳过了哪些检查及原因\n\n**Output Format**\n\n使用清晰的 Markdown：\n- Summary scorecard 表格\n- 按优先级分组的问题列表 (CRITICAL/WARNING/SUGGESTION)\n- 代码引用格式：`file.ts:123`\n- 具体、可执行的建议\n- 不要使用含糊建议，如 \"consider reviewing\"\n\n"},"lastSynced":"2026-03-08T02:07:25.960Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring precise implementation verification against change artifacts.","zh":"适用于需要对变更 artifact 进行精确实现验证的开发代理。","ja":"開発エージェントが変更アーティファクトに対して正確な実装検証を必要とする場合に最適です。","ko":"변경 artifact에 대해 정확한 구현 검증이 필요한 개발 에이전트에게 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren una verificación de implementación precisa contra artefactos de cambio.","fr":"Idéal pour les Agents de Développement nécessitant une vérification d''implémentation précise contre les artefacts de modification.","de":"Ideal für Entwicklungsmittel benötigende Agenten, die eine präzise Implementierungsverifizierung gegen Änderungsartefakte erfordern.","pt":"Ideal para Agentes de Desenvolvimento que exigem verificação de implementação precisa contra artefatos de alteração.","ru":"Идеально для агентов разработки, требующих точной верификации реализации против артефактов изменений.","ar":"مثالي لعميل التطوير الذين يتطلبون التحقق الدقيق للتطبيق ضد مكونات التغيير."},"recommendation":{"en":"Empowers agents to ensure consistency across specs, tasks, and design using the openspec-verify-change tool, which leverages JSON output from openspec list and status commands, and utilizes the AskUserQuestion tool for user input.","zh":"赋予代理确保跨规格、任务和设计的一致性，使用 openspec-verify-change 工具，该工具利用 openspec list 和 status 命令的 JSON 输出，并利用 AskUserQuestion 工具进行用户输入。","ja":"エージェントが、openspec-verify-change ツールを使用して、仕様、タスク、設計間の一貫性を確保できるようにします。このツールは、openspec list と status コマンドの JSON 出力を利用し、AskUserQuestion ツールを使用してユーザー入力を取得します。","ko":"에이전트가 openspec-verify-change 툴을 사용하여 사양, 태스크, 디자인 간的一致성을 보장할 수 있도록 합니다. 이 툴은 openspec list 및 status 명령의 JSON 출력을 활용하며, AskUserQuestion 툴을 사용하여 사용자 입력을 받습니다.","es":"Habilita a los agentes para garantizar la coherencia a través de especificaciones, tareas y diseño utilizando la herramienta openspec-verify-change, que aprovecha la salida JSON de los comandos openspec list y status, y utiliza la herramienta AskUserQuestion para la entrada del usuario.","fr":"Permet aux agents de s''assurer de la cohérence à travers les spécifications, les tâches et la conception en utilisant l''outil openspec-verify-change, qui exploite la sortie JSON des commandes openspec list et status, et utilise l''outil AskUserQuestion pour la saisie utilisateur.","de":"Ermächtigt die Agenten, die Konsistenz über Spezifikationen, Aufgaben und Design hinweg sicherzustellen, indem sie das Tool openspec-verify-change verwenden, das die JSON-Ausgabe der openspec-Befehle list und status nutzt und das Tool AskUserQuestion für die Benutzereingabe verwendet.","pt":"Habilita os agentes a garantir a consistência em todo o specs, tarefas e design usando a ferramenta openspec-verify-change, que aproveita a saída JSON da lista openspec e comandos de status, e utiliza a ferramenta AskUserQuestion para entrada do usuário.","ru":"Наделяет агентов возможностью обеспечить согласованность во всей спецификации, задачах и дизайне, используя инструмент openspec-verify-change, который использует выходные данные JSON из команд openspec list и status, и использует инструмент AskUserQuestion для ввода пользователя.","ar":"يعزز الوكلاء لضمان الاتساق عبر المواصفات والمهام والتصميم باستخدام أداة openspec-verify-change، التي تستفيد من الإخراج JSON من قائمة openspec وأوامر الحالة، وتستخدم أداة AskUserQuestion لإدخال المستخدم."},"useCases":{"en":["Verifying implementation against change artifacts","Ensuring consistency across specs, tasks, and design","Automating checks for unfinished tasks in change artifacts"],"zh":["验证实现是否符合变更 artifact","确保跨规格、任务和设计的一致性","自动检查变更 artifact 中未完成的任务"],"ja":["変更アーティファクトに対する実装の検証","仕様、タスク、設計間の一貫性を確保","変更アーティファクト中の未完了タスクの自動チェック"],"ko":["변경 artifact에 대한 구현 검증","사양, 태스크, 디자인 간的一致성을 보장","변경 artifact 중 미완료 태스크에 대한 자동 체크"],"es":["Verificar la implementación contra artefactos de cambio","Garantizar la coherencia a través de especificaciones, tareas y diseño","Automatizar comprobaciones para tareas incompletas en artefactos de cambio"],"fr":["Vérifier l''implémentation contre les artefacts de modification","Assurer la cohérence à travers les spécifications, les tâches et la conception","Automatiser les vérifications pour les tâches incomplètes dans les artefacts de modification"],"de":["Implementierung gegen Änderungsartefakte überprüfen","Konsistenz über Spezifikationen, Aufgaben und Design sicherstellen","Automatisierung von Prüfungen für unvollständige Aufgaben in Änderungsartefakten"],"pt":["Verificar a implementação contra artefatos de alteração","Garantir a consistência em todo o specs, tarefas e design","Automatizar verificações para tarefas inacabadas em artefatos de alteração"],"ru":["Проверка реализации против артефактов изменений","Обеспечение согласованности во всей спецификации, задачах и дизайне","Автоматизация проверок незавершенных задач в артефактах изменений"],"ar":["التحقق من التطبيق ضد مكونات التغيير","ضمان الاتساق عبر المواصفات والمهام والتصميم","تأتمتة الفحوصات للأعمال غير المكتملة في مكونات التغيير"]},"limitations":{"en":["Requires self-hosted openspec-verify-change tool","Needs user input for change selection","Dependent on openspec list and status commands for functionality"],"zh":["需要自托管的 openspec-verify-change 工具","需要用户输入来选择变更","依赖 openspec list 和 status 命令来实现功能"],"ja":["セルフホストされた openspec-verify-change ツールが必要","変更の選択にはユーザー入力が必要","機能を実現するために openspec list と status コマンドに依存"],"ko":["자체 호스팅된 openspec-verify-change 툴이 필요","변경 선택을 위해 사용자 입력이 필요","기능을 구현하기 위해 openspec list 및 status 명령에 의존"],"es":["Requiere la herramienta openspec-verify-change alojada en el propio servidor","Necesita la entrada del usuario para la selección de cambios","Dependiente de los comandos openspec list y status para la funcionalidad"],"fr":["Nécessite l''outil openspec-verify-change autonome","A besoin de la saisie utilisateur pour la sélection des modifications","Dépend des commandes openspec list et status pour la fonctionnalité"],"de":["Benötigt das Tool openspec-verify-change, das selbst gehostet wird","Benötigt die Benutzereingabe für die Änderungsauswahl","Abhängig von den openspec-Befehlen list und status für die Funktionalität"],"pt":["Exige a ferramenta openspec-verify-change auto-hospedada","Necessita entrada do usuário para seleção de alteração","Dependente de comandos openspec list e status para funcionalidade"],"ru":["Требует самохозяйственной инструмент openspec-verify-change","Требует ввода пользователя для выбора изменения","Зависит от команд openspec list и status для функциональности"],"ar":["يتطلب أداة openspec-verify-change المضيفة ذاتيًا","يحتاج إلى إدخال المستخدم لتحديد التغيير","يعتمد على أوامر openspec قائمة والحالة للوظيفة"]},"version":4},"contentHash":"a10061f96348d38acfa3956f7902414b46cc3acf7ef595e8c827fad5a1ee7647","qualityScore":47}');
