INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('StrayDragon/oratio/openspec-verify-change', 'openspec-verify-change', 'StrayDragon', 'oratio', 'community', 'openspec-verify-change StrayDragon oratio community openspec-verify-change is a self-hosted tool that verifies implementation against change artifacts, benefiting developers by ensuring consistency across specs, tasks, and design. openspec-verify-change工具用于验证实现是否与变更工件一致，支持命令行界面和JSON输出 openspec-verify-change AIエージェントは、実装が変更アーティファクトと一致するかを検証し、CLIとJSON出力をサポートします openspec-verify-change AI 도구는 구현이 변경 아티팩트와 일치하는지 검증하며, CLI와 JSON 출력을 지원합니다 openspec-verify-change es una herramienta de verificación de cambios para proyectos de desarrollo que utiliza CLI y JSON openspec-verify-change est un outil de vérification de modifications pour les projets de développement utilisant CLI et JSON openspec-verify-change ist ein Überprüfungstool für Änderungen in Entwicklungsprojekten, das CLI und JSON verwendet O openspec-verify-change é uma ferramenta de verificação de mudanças para desenvolvedores que ajuda a garantir a consistência entre as alterações e os artefatos openspec-verify-change - это инструмент для проверки изменений для разработчиков, который помогает обеспечить согласованность между изменениями и артефактами с помощью ИИ Агентов openspec-verify-change هو أداة التحقق من التغييرات للمطورين التي تساعد على ضمان الاتساق بين التغييرات والمنفذات مع الوكلاء الذكاء الاصطناعي how to use openspec-verify-change openspec-verify-change setup guide openspec-verify-change alternative tools what is openspec-verify-change openspec-verify-change vs spec-driven workflow openspec-verify-change install for AI agents openspec-verify-change 变更验证 命令行工具 JSON输出 CLI 项目管理 变更管理 实现验证 Runs `openspec list --json` to retrieve available changes Utilizes AskUserQuestion tool for user selection of changes Displays changes with implementation tasks and schema usage Checks status with `openspec status --change <name> --json` to understand schema Loads change directories and artifacts for verification openspec-verify-change is a cross-platform, privacy-focused speech-to-text input tool for verifying changes against implementation artifacts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Just-DX/maintenance-management-system/nestjs-repository-pattern', 'community', 'Just-DX', 'maintenance-management-system', 'Just-DX/maintenance-management-system', 'nestjs-repository-pattern', 0, 0, 47, '2026-03-08T01:57:15.434Z', '2026-03-08T02:07:35.669Z', 'd0e2e5466d6ba2c146186bf69fca5e6b7d6fd55a4b203225a0716e18cdfa6615', '{"id":"Just-DX/maintenance-management-system/nestjs-repository-pattern","name":"nestjs-repository-pattern","description":{"en":"The nestjs-repository-pattern skill provides guidelines for implementing the repository pattern in NestJS applications with Prisma ORM, benefiting developers who want to create clean and maintainable architecture.","zh":"NestJS 仓库模式最佳实践指南，使用 Prisma ORM 实现干净的架构","ja":"NestJS リポジトリパターンのベストプラクティスガイド。Prisma ORM を使用してクリーンなアーキテクチャを実現します","ko":"NestJS 리포지토리 패턴 설정 가이드. Prisma ORM을 사용하여 깨끗한 아키텍처를 구현합니다","es":"El patrón de repositorio NestJS es una guía para implementar una arquitectura limpia en aplicaciones con Prisma ORM","fr":"Le modèle de répository NestJS est un guide pour mettre en œuvre une architecture propre dans les applications avec Prisma ORM","de":"Das NestJS-Repository-Muster ist ein Leitfaden für die Implementierung einer sauberen Architektur in Anwendungen mit Prisma ORM","pt":"O padrão de repositório NestJS é uma abordagem para implementar uma arquitetura limpa e escalável com Prisma ORM","ru":"Шаблон репозитория NestJS - это подход к реализации чистой и масштабируемой архитектуры с Prisma ORM","ar":"نمط المستودع NestJS هو نهج لتنفيذ هيكل نظيف وقابل للتوسعة مع Prisma ORM"},"seo":{"title":{"en":"nestjs-repository-pattern: Best Practices for Clean Archi...","zh":"NestJS 仓库模式最佳实践指南","ja":"NestJS リポジトリパターンのベストプラクティスガイド","ko":"NestJS 리포지토리 패턴 설정 가이드","es":"Patrón de Repositorio NestJS: Guía de Configuración","fr":"Modèle de Répository NestJS: Meilleures Pratiques","de":"NestJS-Repository-Muster: Einrichtungsleitfaden","pt":"Padrão de Repositório NestJS: Guia de Configuração","ru":"ИИ Агенты: Шаблон репозитория NestJS - Руководство по нас...","ar":"وكلاء الذكاء الاصطناعي: نمط مستودع NestJS - دليل الإعداد"},"description":{"en":"Learn how to implement the repository pattern in NestJS with Prisma ORM. Get expert guidelines for clean architecture and database access.","zh":"了解如何在 NestJS 应用中实现仓库模式，使用 Prisma ORM 实现干净的架构","ja":"NestJS アプリケーションでリポジトリ パターンを実装する方法を参照してください。Prisma ORM を使用してクリーンなアーキテクチャを実現します","ko":"NestJS 애플리케이션에서 리포지토리 패턴을 구현하는 방법을 알아보세요. Prisma ORM을 사용하여 깨끗한 아키텍처를 구현합니다","es":"Aprende a implementar el patrón de repositorio en aplicaciones NestJS con Prisma ORM para una arquitectura limpia","fr":"Découvrez comment mettre en œuvre le modèle de répository dans les applications NestJS avec Prisma ORM pour une architecture propre","de":"Erfahren Sie, wie Sie das Repository-Muster in NestJS-Anwendungen mit Prisma ORM für eine saubere Architektur implementieren","pt":"Aprenda a implementar o padrão de repositório no NestJS com Prisma ORM para uma arquitetura limpa e escalável","ru":"Узнайте, как реализовать шаблон репозитория в NestJS с Prisma ORM для чистой и масштабируемой архитектуры","ar":"تعرف على كيفية تنفيذ نمط المستودع في NestJS مع Prisma ORM لتحقيق هيكل نظيف وقابل للتوسعة"},"definition":{"en":"nestjs-repository-pattern is a set of guidelines for implementing the repository pattern in NestJS applications, focusing on clean architecture and database access with Prisma ORM.","zh":"NestJS 仓库模式是一种软件设计模式，使用 Prisma ORM 实现数据访问层","ja":"NestJS リポジトリパターンは、Prisma ORM を使用してデータ アクセス層を実装するソフトウェア設計パターンです","ko":"NestJS 리포지토리 패턴은 Prisma ORM을 사용하여 데이터 접근 계층을 구현하는 소프트웨어 디자인 패턴입니다","es":"El patrón de repositorio es un diseño de arquitectura que separa la lógica de acceso a datos","fr":"Le modèle de répository est un modèle d''architecture qui sépare la logique d''accès aux données","de":"Das Repository-Muster ist ein Architekturmuster, das die Datenzugriffslogik trennt","pt":"O padrão de repositório NestJS é um padrão de design que separa a lógica de negócios da lógica de acesso a dados","ru":"Шаблон репозитория NestJS - это шаблон проектирования, который отделяет бизнес-логику от логики доступа к данным","ar":"نمط المستودع NestJS هو نمط تصميم يفصل المنطق التجاري عن منطق الوصول إلى البيانات"},"features":{"en":["Implements data access layers with Prisma ORM","Provides guidelines for writing queries for User, Asset, Site, and other entities","Supports transaction support for database operations","Organizes code for testability and maintainability","Refactors services that contain direct Prisma/DB calls","Creates new NestJS modules with database access"],"zh":["使用 Prisma ORM 实现数据访问层","实现干净的架构","支持事务","提高代码的可测试性和可维护性","适用于 User、Asset、Site 等实体的查询"],"ja":["Prisma ORM を使用してデータ アクセス層を実装","クリーンなアーキテクチャを実現","トランザクションのサポート","コードのテスト性とメンテナンス性を向上","User、Asset、Site などのエンティティのクエリに適しています"],"ko":["Prisma ORM을 사용하여 데이터 접근 계층을 구현","깨끗한 아키텍처를 구현","트랜잭션 지원","코드의 테스트 가능성과 유지 보수성을 향상","User, Asset, Siteなどの 엔티티의 쿼리에 적합"],"es":["Implementación de capas de acceso a datos con Prisma ORM","Soporte para transacciones","Organización de código para pruebas y mantenimiento","Creación de módulos NestJS con acceso a bases de datos","Refactorización de servicios con llamadas directas a Prisma/DB"],"fr":["Mise en œuvre de couches d''accès aux données avec Prisma ORM","Prise en charge des transactions","Organisation de code pour les tests et la maintenance","Création de modules NestJS avec accès aux bases de données","Refactorisation de services avec des appels directs à Prisma/DB"],"de":["Implementierung von Datenzugriffsschichten mit Prisma ORM","Unterstützung für Transaktionen","Organisation von Code für Tests und Wartung","Erstellung von NestJS-Modulen mit Datenbankzugriff","Refaktorisierung von Diensten mit direkten Prisma/DB-Aufrufen"],"pt":["Implementação de camadas de acesso a dados com Prisma ORM","Separação da lógica de negócios da lógica de acesso a dados","Suporte a transações","Organização de código para testabilidade e manutenção","Integração com entidades de usuário, ativo e site"],"ru":["Реализация слоев доступа к данным с Prisma ORM","Отделение бизнес-логики от логики доступа к данным","Поддержка транзакций","Организация кода для тестирования и поддержки","Интеграция с сущностями пользователя, актива и сайта"],"ar":["تنفيذ طبقات الوصول إلى البيانات مع Prisma ORM","فصل المنطق التجاري عن منطق الوصول إلى البيانات","دعم المعاملات","تنظيم الكود لاختبارها وصيانتها","التكامل مع كيانات المستخدم والمنضم والموقع"]},"keywords":{"en":["how to use nestjs-repository-pattern","nestjs-repository-pattern best practices","nestjs-repository-pattern vs typeorm","nestjs-repository-pattern setup guide","nestjs-repository-pattern install","what is nestjs-repository-pattern","nestjs-repository-pattern alternative","nestjs-repository-pattern prisma orm","clean architecture nestjs","repository pattern nestjs"],"zh":["NestJS 仓库模式","Prisma ORM","干净的架构","数据访问层","事务支持","可测试性","可维护性","AIエージェント"],"ja":["NestJS リポジトリパターン","Prisma ORM","クリーンなアーキテクチャ","データ アクセス層","トランザクション サポート","テスト性","メンテナンス性","AIエージェント"],"ko":["NestJS 리포지토리 패턴","Prisma ORM","깨끗한 아키텍처","데이터 접근 계층","트랜잭션 지원","테스트 가능성","유지 보수성","AI 도구"],"es":["patrón de repositorio NestJS","Prisma ORM","arquitectura limpia","acceso a datos","transacciones","pruebas y mantenimiento","NestJS y Prisma","diseño de arquitectura","desarrollo de aplicaciones"],"fr":["modèle de répository NestJS","Prisma ORM","architecture propre","accès aux données","transactions","tests et maintenance","NestJS et Prisma","conception d''architecture","développement d''applications"],"de":["NestJS-Repository-Muster","Prisma ORM","saubere Architektur","Datenzugriff","Transaktionen","Tests und Wartung","NestJS und Prisma","Architekturdesign","Anwendungsentwicklung"],"pt":["NestJS","Prisma ORM","padrão de repositório","arquitetura limpa","escalabilidade","camadas de acesso a dados","lógica de negócios","transações"],"ru":["NestJS","Prisma ORM","шаблон репозитория","чистая архитектура","масштабируемость","слои доступа к данным","бизнес-логика","транзакции"],"ar":["NestJS","Prisma ORM","نمط المستودع","هيكل نظيف","قابل للتوسعة","طبقات الوصول إلى البيانات","منطق تجاري","معاملات"]}},"owner":"Just-DX","repo":"maintenance-management-system","repoPath":"Just-DX/maintenance-management-system","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.434Z","topics":[],"category":"community","skillMd":{"name":"nestjs-repository-pattern","description":"NestJS Repository Pattern architecture and best practices for api-app. Use this skill when implementing data access layers, separating business logic from database queries, or refactoring services to use repositories. Applies to NestJS backend modules using Prisma ORM.","version":"1.0.0","bodyPreview":"# NestJS Repository Pattern Best Practices\n\nClean architecture guidelines for implementing repository pattern in NestJS applications with Prisma ORM.\n\n## When to Apply\n\nReference these guidelines when:\n- Creating new NestJS modules with database access\n- Refactoring services that contain direct Prisma/DB calls\n- Implementing data access layers\n- Writing queries for User, Asset, Site, or other entities\n- Setting up transaction support\n- Organizing code for testability and maintainability\n\n## Core","body":"# NestJS Repository Pattern Best Practices\n\nClean architecture guidelines for implementing repository pattern in NestJS applications with Prisma ORM.\n\n## When to Apply\n\nReference these guidelines when:\n- Creating new NestJS modules with database access\n- Refactoring services that contain direct Prisma/DB calls\n- Implementing data access layers\n- Writing queries for User, Asset, Site, or other entities\n- Setting up transaction support\n- Organizing code for testability and maintainability\n\n## Core Principles\n\n### 1. Separation of Concerns (CRITICAL)\n\n**Rule**: All Prisma/DB queries MUST live in repository classes, not in services or controllers.\n\n```typescript\n// ❌ INCORRECT: Direct Prisma call in service\n@Injectable()\nexport class AssetService {\n  async findById(id: string) {\n    return await prisma.asset.findFirst({ where: { id } })\n  }\n}\n\n// ✅ CORRECT: Repository handles data access\n@Injectable()\nexport class AssetsRepository {\n  async findById(id: string, siteId: string, select?: Prisma.AssetSelect) {\n    return prisma.asset.findFirst({ where: { id, siteId }, select })\n  }\n}\n\n@Injectable()\nexport class AssetService {\n  constructor(private readonly assetsRepo: AssetsRepository) {}\n  \n  async findById(id: string, siteId: string) {\n    const asset = await this.assetsRepo.findById(id, siteId, this.select)\n    if (!asset) throw new NotFoundException(''Asset not found'')\n    return asset\n  }\n}\n```\n\n**Why**: Enables testing, reusability, and clear architectural boundaries.\n\n### 2. Repository Ownership (CRITICAL)\n\n**Rule**: Each entity gets ONE repository. The repository is owned by the module that manages that entity as its \"main table.\"\n\n**Entity Ownership Map**:\n\n| Entity | Repository | Module | Location |\n|--------|-----------|---------|----------|\n| User | UsersRepository | users | `modules/users/repositories/users.repository.ts` |\n| Asset | AssetsRepository | assets | `modules/assets/repositories/assets.repository.ts` |\n| Site | SitesRepository | site | `modules/site/repositories/sites.repository.ts` |\n\n**Cross-Module Usage**:\n```typescript\n// ✅ CORRECT: Auth module imports users module to access UsersRepository\n@Module({\n  imports: [UsersModule], // Import the module\n  providers: [AuthService],\n})\nexport class AuthModule {}\n\n@Injectable()\nexport class AuthService {\n  constructor(\n    private readonly usersRepo: UsersRepository // Inject from imported module\n  ) {}\n}\n```\n\n**Anti-Pattern**:\n```typescript\n// ❌ INCORRECT: Duplicating user queries in auth.repository.ts\n// If you need user queries, use UsersRepository from users module\n```\n\n### 3. Repository Content (HIGH)\n\n**Rule**: Repositories contain ONLY data access code. No business logic, no HTTP exceptions.\n\n```typescript\n// ✅ CORRECT: Repository returns null, no exceptions\n@Injectable()\nexport class UsersRepository {\n  async findById(id: string): Promise<User | null> {\n    return prisma.user.findUnique({ where: { id } })\n    // Returns null if not found - let service decide what to do\n  }\n}\n\n// ✅ CORRECT: Service adds business logic and HTTP exceptions\n@Injectable()\nexport class UserService {\n  async getUser(id: string): Promise<UserDto> {\n    const user = await this.usersRepo.findById(id)\n    if (!user) {\n      throw new NotFoundException(''User not found'') // HTTP exception\n    }\n    if (!user.isActive) {\n      throw new ForbiddenException(''User is inactive'') // Business rule\n    }\n    return this.transformToDto(user) // Business logic\n  }\n}\n```\n\n### 4. Method Naming Conventions (HIGH)\n\n**Rule**: Use consistent prefixes that signal behavior.\n\n**Repository Methods**:\n- `find*` - Returns `null` if not found\n- `create` - Creates and returns record\n- `update` - Updates and returns record  \n- `softDelete` / `delete` - Deletes record\n- `count` - Returns count\n\n```typescript\n@Injectable()\nexport class UsersRepository {\n  // Returns null if not found\n  async findById(id: string): Promise<User | null>\n  async findByEmail(email: string): Promise<User | null>\n  \n  // Returns created/updated record\n  async create(data: CreateData): Promise<User>\n  async update(id: string, data: UpdateData): Promise<User>\n  \n  // Soft delete\n  async softDelete(id: string): Promise<User>\n}\n```\n\n**Service Methods**:\n- `find*` - May return null or throw (business decision)\n- `get*` - Expected to exist, throws if not found\n- `create` / `update` / `remove` - Operations with validation\n\n```typescript\n@Injectable()\nexport class UserService {\n  // Throws NotFoundException if not found\n  async getUser(id: string): Promise<UserDto>\n  \n  // Returns null or record\n  async findUserByEmail(email: string): Promise<UserDto | null>\n}\n```\n\n### 5. Transaction Support (HIGH)\n\n**Rule**: All repository methods MUST accept optional transaction parameter.\n\n```typescript\n// ✅ CORRECT: Repository accepts optional transaction\n@Injectable()\nexport class UsersRepository {\n  async findById(\n    id: string,\n    tx?: Prisma.TransactionClient // Optional transaction\n  ): Promise<User | null> {\n    const db = tx ?? prisma // Use transaction if provided, else prisma\n    return db.user.findUnique({ where: { id } })\n  }\n  \n  async upsertUserProfile(\n    payload: CreateUserData,\n    tx?: Prisma.TransactionClient\n  ) {\n    const db = tx ?? prisma\n    \n    // If already in transaction, execute directly\n    if (tx) {\n      return tx.user.upsert({ /* ... */ })\n    }\n    \n    // Otherwise create new transaction\n    return prisma.$transaction(async (innerTx) => {\n      return innerTx.user.upsert({ /* ... */ })\n    })\n  }\n}\n\n// ✅ CORRECT: Service coordinates transactions\n@Injectable()\nexport class UserService {\n  async complexOperation(userId: string) {\n    return prisma.$transaction(async (tx) => {\n      const user = await this.usersRepo.findById(userId, tx)\n      const sites = await this.sitesRepo.findByUser(userId, tx)\n      // All operations use same transaction\n      return { user, sites }\n    })\n  }\n}\n```\n\n### 6. Error Handling (MEDIUM)\n\n**Rule**: Repositories return null or throw Prisma errors. Services transform to HTTP exceptions.\n\n```typescript\n// ✅ CORRECT: Repository doesn''t catch errors\n@Injectable()\nexport class AssetsRepository {\n  async create(data: CreateAssetData) {\n    return prisma.asset.create({ data }) // Prisma errors bubble up\n  }\n}\n\n// ✅ CORRECT: Service catches and transforms errors\n@Injectable()\nexport class AssetService {\n  async create(dto: CreateAssetDto) {\n    try {\n      return await this.assetsRepo.create({\n        name: dto.name.trim(), // Business logic\n        code: dto.code.trim(),\n        /* ... */\n      })\n    } catch (error) {\n      if (error instanceof Prisma.PrismaClientKnownRequestError) {\n        if (error.code === ''P2002'') {\n          throw new ConflictException(''Asset already exists'') // HTTP exception\n        }\n      }\n      throw error\n    }\n  }\n}\n```\n\n### 7. Module Organization (MEDIUM)\n\n**Rule**: Follow consistent folder structure for repositories.\n\n```\nmodules/\n├── users/\n│   ├── users.module.ts           # Exports UsersRepository\n│   └── repositories/\n│       └── users.repository.ts   # All User queries\n├── assets/\n│   ├── assets.module.ts          # Provides AssetsRepository\n│   ├── controllers/\n│   │   └── asset.controller.ts\n│   ├── services/\n│   │   └── asset.service.ts      # Uses AssetsRepository\n│   └── repositories/\n│       └── assets.repository.ts  # All Asset queries\n└── site/\n    ├── site.module.ts\n    ├── controllers/\n    ├── services/\n    └── repositories/\n        └── sites.repository.ts\n```\n\n### 8. Dependency Injection (MEDIUM)\n\n**Rule**: Repositories are provided at module level and injected into services.\n\n```typescript\n// ✅ CORRECT: Module setup\n@Module({\n  imports: [ListModule, AuthModule],\n  controllers: [AssetController],\n  providers: [AssetService, AssetsRepository], // Provide repository\n  exports: [AssetService, AssetsRepository], // Export for other modules\n})\nexport class AssetsModule {}\n\n// ✅ CORRECT: Service injection\n@Injectable()\nexport class AssetService {\n  constructor(\n    private readonly assetsRepo: AssetsRepository // Inject repository\n  ) {}\n}\n```\n\n## Common Patterns\n\n### Pattern 1: Simple CRUD\n\n```typescript\n// Repository\n@Injectable()\nexport class AssetsRepository {\n  async findById(id: string, siteId: string, select?: Prisma.AssetSelect) {\n    return prisma.asset.findFirst({ where: { id, siteId, isDeleted: false }, select })\n  }\n  \n  async create(data: CreateAssetData, select?: Prisma.AssetSelect) {\n    return prisma.asset.create({ data, select })\n  }\n  \n  async update(id: string, data: Prisma.AssetUpdateInput, select?: Prisma.AssetSelect) {\n    return prisma.asset.update({ where: { id }, data, select })\n  }\n  \n  async softDelete(id: string) {\n    return prisma.asset.update({ where: { id }, data: { isDeleted: true } })\n  }\n}\n\n// Service\n@Injectable()\nexport class AssetService {\n  constructor(private readonly assetsRepo: AssetsRepository) {}\n  \n  async findById(siteId: string, id: string): Promise<AssetDto> {\n    const asset = await this.assetsRepo.findById(id, siteId, this.select)\n    if (!asset) throw new NotFoundException(''Asset not found'')\n    return asset\n  }\n  \n  async create(siteId: string, dto: CreateAssetDto): Promise<AssetDto> {\n    try {\n      return await this.assetsRepo.create({\n        siteId,\n        name: dto.name.trim(),\n        code: dto.code.trim(),\n      }, this.select)\n    } catch (error) {\n      this.handlePrismaError(error)\n    }\n  }\n}\n```\n\n### Pattern 2: Complex Queries with Relations\n\n```typescript\n// Repository\n@Injectable()\nexport class UsersRepository {\n  async findUserRolesByIdAndSite(\n    userId: string,\n    siteId: string,\n    tenantId: string,\n    appScopes: AppScope[]\n  ) {\n    return prisma.userRole.findMany({\n      where: {\n        userId,\n        siteId,\n        role: { siteId, appScope: { in: appScopes } }\n      },\n      select: {\n        role: {\n          select: {\n            id: true,\n            code: true,\n            name: true,\n            rolePermissions: {\n              where: { permission: { tenantId, appScope: { in: appScopes } } },\n              select: { permission: { select: { code: true } } }\n            }\n          }\n        }\n      }\n    })\n  }\n}\n```\n\n### Pattern 3: Assertion Helper\n\n```typescript\n// Service helper method\nprivate async assertExists(siteId: string, id: string): Promise<void> {\n  const asset = await this.assetsRepo.findById(id, siteId, { id: true })\n  if (!asset) {\n    throw new NotFoundException(''Asset not found'')\n  }\n}\n\n// Usage\nasync update(siteId: string, id: string, dto: UpdateAssetDto) {\n  await this.assertExists(siteId, id) // Throws if not found\n  return this.assetsRepo.update(id, { /* ... */ })\n}\n```\n\n## When NOT to Use Repository\n\n- **read-only utilities**: Simple helper functions that don''t need injection\n- **One-off scripts**: Migration scripts or seeders (can use Prisma directly)\n- **ListService delegate**: List/pagination queries can pass Prisma delegate to ListService\n\n## Migration Checklist\n\nWhen refactoring existing code to use repositories:\n\n1. ✅ Create repository file in `repositories/` folder\n2. ✅ Move all Prisma queries from service to repository\n3. ✅ Add transaction support (`tx?: Prisma.TransactionClient`) to all methods\n4. ✅ Make repositories return null for not-found cases\n5. ✅ Update service to inject repository\n6. ✅ Add HTTP exceptions in service layer\n7. ✅ Update module to provide/export repository\n8. ✅ Verify no direct Prisma calls remain in service\n9. ✅ Check cross-module dependencies (import correct module)\n10. ✅ Run tests and check for compilation errors\n\n## Related Documentation\n\n- See `apps/api-app/REFACTORING_SUMMARY.md` for implementation details\n- See `apps/api-app/ARCHITECTURE.md` for module structure\n- See `docs/ARCHITECTURE.md` for overall system architecture\n"},"lastSynced":"2026-03-08T02:07:35.669Z","agentAnalysis":{"suitability":{"en":"Perfect for Full-Stack Agents needing clean architecture guidelines for NestJS applications with Prisma ORM","zh":"适合需要为NestJS应用程序提供干净架构指南且使用Prisma ORM的全栈代理","ja":"NestJSアプリケーションにクリーンアーキテクチャのガイドラインを提供する必要があるPrisma ORMを使用するフルスタックエージェントに適しています","ko":"NestJS 애플리케이션에 깨끗한 아키텍처 가이드라인을 제공해야 하며 Prisma ORM을 사용하는 풀스택 에이전트에게 적합합니다","es":"Perfecto para agentes Full-Stack que necesitan directrices de arquitectura limpia para aplicaciones NestJS con Prisma ORM","fr":"Parfait pour les agents Full-Stack ayant besoin de directives d''architecture propre pour les applications NestJS avec Prisma ORM","de":"Perfekt für Full-Stack-Agents, die saubere Architektur-Richtlinien für NestJS-Anwendungen mit Prisma ORM benötigen","pt":"Perfeito para Agentes Full-Stack que necessitam de diretrizes de arquitetura limpa para aplicações NestJS com Prisma ORM","ru":"Идеально для агентов Full-Stack, которым необходимы рекомендации по чистой архитектуре для приложений NestJS с Prisma ORM","ar":"مثالي للوكلاء كامل الحزمة الذين يحتاجون إلى إرشادات هندسة نظيفة لتطبيقات NestJS مع Prisma ORM"},"recommendation":{"en":"Empowers agents to implement the repository pattern, providing a maintainable data access layer with Prisma ORM, and enabling clean architecture for NestJS modules, services, and database transactions","zh":"赋予代理实现存储库模式的能力，提供具有Prisma ORM的可维护数据访问层，并为NestJS模块、服务和数据库事务启用干净架构","ja":"エージェントがリポジトリパターンを実装することを可能にし、Prisma ORMを使用したメンテナブルなデータアクセスレイヤーを提供し、NestJSモジュール、サービス、データベーストランザクションのクリーンアーキテクチャを有効にします","ko":"에이전트가 저장소 패턴을 구현할 수 있도록 하며 Prisma ORM을 사용하여 유지 관리 가능한 데이터 액세스 계층을 제공하고 NestJS 모듈, 서비스 및 데이터베이스 트랜잭션에 대한 깨끗한 아키텍처를 활성화합니다","es":"Habilita a los agentes a implementar el patrón de repositorio, proporcionando una capa de acceso a datos mantenible con Prisma ORM, y permitiendo una arquitectura limpia para módulos, servicios y transacciones de base de datos de NestJS","fr":"Permet aux agents de mettre en œuvre le modèle de repository, fournissant une couche d''accès aux données maintenable avec Prisma ORM, et permettant une architecture propre pour les modules, services et transactions de base de données NestJS","de":"Ermächtigt die Agenten, das Repository-Muster zu implementieren, eine wartbare Datenzugriffsschicht mit Prisma ORM bereitzustellen und eine saubere Architektur für NestJS-Module, -Dienste und Datenbanktransaktionen zu ermöglichen","pt":"Habilita os agentes a implementar o padrão de repositório, fornecendo uma camada de acesso a dados mantida com Prisma ORM, e permitindo arquitetura limpa para módulos, serviços e transações de banco de dados NestJS","ru":"Позволяет агентам реализовать шаблон репозитория, предоставляя поддерживаемый слой доступа к данным с помощью Prisma ORM, и обеспечивающий чистую архитектуру для модулей, сервисов и транзакций базы данных NestJS","ar":"يسمح للوكلاء بتنفيذ نمط المستودع، وتوفير طبقة وصول إلى البيانات القابلة للصيانة مع Prisma ORM، وتمكين الهندسة النظيفة للوحدات والنماذج وعملية قاعدة البيانات NestJS"},"useCases":{"en":["Implementing data access layers for User, Asset, and Site entities","Refactoring services to remove direct Prisma/DB calls","Setting up transaction support for NestJS applications","Organizing code for testability and maintainability"],"zh":["为用户、资产和站点实体实现数据访问层","重构服务以删除直接Prisma/DB调用","为NestJS应用程序设置事务支持","组织代码以实现可测试性和可维护性"],"ja":["ユーザー、資産、サイトエンティティのデータアクセスレイヤーを実装する","サービスをリファクタリングしてPrisma/DBへの直接呼び出しを削除する","NestJSアプリケーションのトランザクションサポートを設定する","テスト性とメンテナンス性のためにコードを整理する"],"ko":["사용자, 자산, 사이트 엔티티에 대한 데이터 액세스 계층을 구현하는 것","서비스를 리팩토링하여 Prisma/DB에 대한 직접 호출을 제거","NestJS 애플리케이션에 대한 트랜잭션 지원을 설정","테스트 가능성 및 유지 보수성을 위해 코드를 조직"],"es":["Implementar capas de acceso a datos para entidades de usuario, activo y sitio","Reorganizar servicios para eliminar llamadas directas a Prisma/BD","Configurar soporte de transacciones para aplicaciones NestJS","Organizar el código para pruebas y mantenimiento"],"fr":["Mettre en œuvre des couches d''accès aux données pour les entités utilisateur, actif et site","Réorganiser les services pour supprimer les appels directs à Prisma/BD","Configurer la prise en charge des transactions pour les applications NestJS","Organiser le code pour les tests et la maintenabilité"],"de":["Implementierung von Datenzugriffsschichten für Benutzer-, Vermögens- und Standortentitäten","Umstrukturierung von Diensten, um direkte Prisma/DB-Aufrufe zu entfernen","Einrichtung der Transaktionsunterstützung für NestJS-Anwendungen","Organisation des Codes für Testbarkeit und Wartbarkeit"],"pt":["Implementação de camadas de acesso a dados para entidades de Usuário, Ativo e Site","Reestruturação de serviços para remover chamadas diretas Prisma/DB","Configuração do suporte a transações para aplicações NestJS","Organização de código para testabilidade e manutenção"],"ru":["Реализация слоев доступа к данным для сущностей Пользователь, Актив и Сайт","Перестройка сервисов для удаления прямых вызовов Prisma/БД","Настройка поддержки транзакций для приложений NestJS","Организация кода для тестирования и поддержки"],"ar":["تنفيذ طبقات الوصول إلى البيانات للكيانات المستخدم، الأصل، والموقع","إعادة هيكلة الخدمات لإزالة المكالمات المباشرة Prisma/DB","تكوين دعم المعاملات لتطبيقات NestJS","تنظيم رمز البرامج لاختبارها وصيانتها"]},"limitations":{"en":["Requires NestJS and Prisma ORM setup","Limited to NestJS applications"],"zh":["需要NestJS和Prisma ORM设置","仅限NestJS应用程序"],"ja":["NestJSとPrisma ORMの設定が必要","NestJSアプリケーションに限定"],"ko":["NestJS 및 Prisma ORM 설정이 필요","NestJS 애플리케이션으로 제한"],"es":["Requiere configuración de NestJS y Prisma ORM","Limitado a aplicaciones NestJS"],"fr":["Nécessite une configuration de NestJS et Prisma ORM","Limité aux applications NestJS"],"de":["Benötigt eine Konfiguration von NestJS und Prisma ORM","Begrenzt auf NestJS-Anwendungen"],"pt":["Exige configuração do NestJS e Prisma ORM","Limitado a aplicações NestJS"],"ru":["Требует настройки NestJS и Prisma ORM","Ограничен для приложений NestJS"],"ar":["يتطلب إعداد NestJS و Prisma ORM","محدود لتطبيقات NestJS"]},"version":4},"contentHash":"d0e2e5466d6ba2c146186bf69fca5e6b7d6fd55a4b203225a0716e18cdfa6615","qualityScore":47}');
