INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Just-DX/maintenance-management-system/nestjs-repository-pattern', 'nestjs-repository-pattern', 'Just-DX', 'maintenance-management-system', 'community', 'nestjs-repository-pattern Just-DX maintenance-management-system community The nestjs-repository-pattern skill provides guidelines for implementing the repository pattern in NestJS applications with Prisma ORM, benefiting developers who want to create clean and maintainable architecture. NestJS 仓库模式最佳实践指南，使用 Prisma ORM 实现干净的架构 NestJS リポジトリパターンのベストプラクティスガイド。Prisma ORM を使用してクリーンなアーキテクチャを実現します NestJS 리포지토리 패턴 설정 가이드. Prisma ORM을 사용하여 깨끗한 아키텍처를 구현합니다 El patrón de repositorio NestJS es una guía para implementar una arquitectura limpia en aplicaciones con Prisma ORM Le modèle de répository NestJS est un guide pour mettre en œuvre une architecture propre dans les applications avec Prisma ORM Das NestJS-Repository-Muster ist ein Leitfaden für die Implementierung einer sauberen Architektur in Anwendungen mit Prisma ORM O padrão de repositório NestJS é uma abordagem para implementar uma arquitetura limpa e escalável com Prisma ORM Шаблон репозитория NestJS - это подход к реализации чистой и масштабируемой архитектуры с Prisma ORM نمط المستودع NestJS هو نهج لتنفيذ هيكل نظيف وقابل للتوسعة مع Prisma ORM how to use nestjs-repository-pattern nestjs-repository-pattern best practices nestjs-repository-pattern vs typeorm nestjs-repository-pattern setup guide nestjs-repository-pattern install what is nestjs-repository-pattern nestjs-repository-pattern alternative nestjs-repository-pattern prisma orm clean architecture nestjs repository pattern nestjs NestJS 仓库模式 Prisma ORM 干净的架构 数据访问层 事务支持 可测试性 可维护性 AIエージェント Implements data access layers with Prisma ORM Provides guidelines for writing queries for User, Asset, Site, and other entities Supports transaction support for database operations Organizes code for testability and maintainability Refactors services that contain direct Prisma/DB calls Creates new NestJS modules with database access nestjs-repository-pattern is a set of guidelines for implementing the repository pattern in NestJS applications, focusing on clean architecture and database access with Prisma ORM.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mgnfy-view/morpho-vault-v2-adapters/scaffold-contract', 'community', 'mgnfy-view', 'morpho-vault-v2-adapters', 'mgnfy-view/morpho-vault-v2-adapters', 'scaffold-contract', 0, 0, 47, '2026-03-08T01:57:15.432Z', '2026-03-08T02:08:51.375Z', '875a02b5e84738c28b665a16f275b6297685516dba04ae787bff908b966fb6d1', '{"id":"mgnfy-view/morpho-vault-v2-adapters/scaffold-contract","name":"scaffold-contract","description":{"en":"The scaffold-contract skill creates a new Solidity module skeleton with a standard structure and NatSpec documentation for DeFi protocol development, benefiting developers and auditors alike.","zh":"scaffold-contract 是一个创建标准化 Solidity 模块的 AI 工具，适用于 DeFi 协议开发，包括 NatSpec 文档","ja":"scaffold-contract は、DeFi プロトコル開発用の標準的な Solidity モジュールを作成する AI ツールです。NatSpec ドキュメントを含みます","ko":"scaffold-contract는 DeFi 프로토콜 개발을 위한 표준 Solidity 모듈을 생성하는 AI 도구입니다. NatSpec 문서 포함","es":"El scaffold-contract es una herramienta para crear un esqueleto de módulo de Solidity con una estructura estándar para DeFi","fr":"Le scaffold-contract est un outil pour créer un squelette de module Solidity avec une structure standard pour DeFi","de":"Der scaffold-contract ist ein Tool zum Erstellen eines Solidity-Modul-Gerüsts mit einer standardmäßigen Struktur für DeFi","pt":"O scaffold-contract é uma habilidade que cria um esqueleto de módulo Solidity com estrutura padrão e documentação NatSpec para desenvolvimento de protocolos DeFi. Ele se concentra apenas na estrutura e interfaces, não no comportamento ou testes.","ru":"ИИ Агент scaffold-contract - это навык, который создает скелет модуля Solidity с стандартной структурой и документацией NatSpec для разработки DeFi протоколов. Он фокусируется только на структуре и интерфейсах, не на поведении или тестах.","ar":"سcaffold-contract هو مهارة تقوم بإنشاء هيكل لمODULE Solidity مع هيكل قياسي وت