INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mgnfy-view/morpho-vault-v2-adapters/scaffold-contract', 'scaffold-contract', 'mgnfy-view', 'morpho-vault-v2-adapters', 'community', 'scaffold-contract mgnfy-view morpho-vault-v2-adapters community The scaffold-contract skill creates a new Solidity module skeleton with a standard structure and NatSpec documentation for DeFi protocol development, benefiting developers and auditors alike. scaffold-contract 是一个创建标准化 Solidity 模块的 AI 工具，适用于 DeFi 协议开发，包括 NatSpec 文档 scaffold-contract は、DeFi プロトコル開発用の標準的な Solidity モジュールを作成する AI ツールです。NatSpec ドキュメントを含みます scaffold-contract는 DeFi 프로토콜 개발을 위한 표준 Solidity 모듈을 생성하는 AI 도구입니다. NatSpec 문서 포함 El scaffold-contract es una herramienta para crear un esqueleto de módulo de Solidity con una estructura estándar para DeFi Le scaffold-contract est un outil pour créer un squelette de module Solidity avec une structure standard pour DeFi Der scaffold-contract ist ein Tool zum Erstellen eines Solidity-Modul-Gerüsts mit einer standardmäßigen Struktur für DeFi O scaffold-contract é uma habilidade que cria um esqueleto de módulo Solidity com estrutura padrão e documentação NatSpec para desenvolvimento de protocolos DeFi. Ele se concentra apenas na estrutura e interfaces, não no comportamento ou testes. ИИ Агент scaffold-contract - это навык, который создает скелет модуля Solidity с стандартной структурой и документацией NatSpec для разработки DeFi протоколов. Он фокусируется только на структуре и интерфейсах, не на поведении или тестах. سcaffold-contract هو مهارة تقوم بإنشاء هيكل لمODULE Solidity مع هيكل قياسي وتوثيق NatSpec لتنمية بروتوكولات DeFi. انها تركز فقط على الهيكل والواجهات، وليس على السلوك أو الاختبارات. how to use scaffold-contract scaffold-contract for DeFi protocol development Morpho vault v2 adapters Solidity module skeleton NatSpec documentation scaffold-contract setup guide scaffold-contract alternative DeFi protocol development tools scaffold-contract DeFi 协议开发 Solidity 模块 NatSpec 文档 Morpho vault v2 AI 工具 AI 에ージェント DeFi 协议 Solidity 开发 Creates a new Solidity module skeleton with a standard, audit-friendly structure Includes NatSpec documentation for clear and concise contract documentation Supports Morpho vault v2 adapters for popular DeFi protocols Helps establish a consistent layout before implementation begins Prepares a contract surface for spec-to-implementation scaffold-contract is a skill that generates a standard, audit-friendly Solidity module structure for DeFi protocol development with Morpho vault v2 adapters.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Ejyke90/naija-conflict-tracker/openspec-explore', 'community', 'Ejyke90', 'naija-conflict-tracker', 'Ejyke90/naija-conflict-tracker', 'openspec-explore', 0, 0, 47, '2026-03-08T01:57:15.468Z', '2026-03-08T02:09:30.851Z', '23091ef47b180412e8bfaa0731dca58fdf0a06e24f04461eadb75e2ab475aa68', '{"id":"Ejyke90/naija-conflict-tracker/openspec-explore","name":"openspec-explore","description":{"en":"The openspec-explore skill enables developers to enter exploration mode, investigating codebases and creating OpenSpec artifacts without writing code. It benefits developers who need to think critically and design solutions before implementation.","zh":"openspec-explore允许您探索代码库而不实施更改，阅读文件、搜索代码和调查代码库","ja":"openspec-exploreはコードベースを探索することを許可し、ファイルを読み、コードを検索し、コードベースを調査する","ko":"openspec-explore를 통해 코드베이스를 탐색하면서 변경을 구현하지 않으며, 파일을 읽고 코드를 검색하고 코드베이스를 조사한다","es":"Openspec-explore es un modo de exploración que permite a los desarrolladores investigar y diseñar sin implementar código, con capacidades como lectura de archivos y búsqueda de código.","fr":"Openspec-explore est un mode d''exploration qui permet aux développeurs d''investiguer et de concevoir sans implémenter de code, avec des capacités comme la lecture de fichiers et la recherche de code","de":"Openspec-explore ist ein Explorationsmodus, der es Entwicklern ermöglicht, zu untersuchen und zu entwerfen, ohne Code zu implementieren, mit Fähigkeiten wie Dateilesen und Code-Suche","pt":"O openspec-explore é um modo de exploração que permite aos desenvolvedores investigar o código e criar propostas OpenSpec","ru":"openspec-explore - это режим изучения, который позволяет разработчикам исследовать код и создавать предложения OpenSpec","ar":"openspec-explore هو وضع استكشاف يسمح للمطورين بالتحقيق في الرموز وإنشاء مقترحات مواصفات مفتوحة"},"seo":{"title":{"en":"openspec-explore: Exploration Mode Setup Guide | AI Agent...","zh":"openspec-explore Setup Guide: AI工具探索模式","ja":"openspec-explore セットアップガイド: AIエージェントの探索モード","ko":"openspec-explore 설정 가이드: AI 에이전트 탐색 모드","es":"Guía de configuración de openspec-explore para desarrolla...","fr":"Mode d''exploration openspec-explore : Guide de démarrage","de":"Openspec-Explore-Setup-Anleitung für Entwickler","pt":"Guia de Configuração do openspec-explore: Modo de Explora...","ru":"Настройка openspec-explore: Режим Изучения для ИИ Агентов","ar":"دليل إعداد openspec-explore: режим الاستكشاف المتقدم للوك..."},"description":{"en":"Discover how openspec-explore helps you think deeply and visualize freely without implementing code. Learn how to use explore mode effectively and create Ope...","zh":"了解openspec-explore的功能和限制，探索代码库而不实施更改","ja":"openspec-exploreの機能と制限を学び、コードベースを探索して変更を実施しない","ko":"openspec-explore의 기능과 제한을 알아보고 코드베이스를 탐색하면서 변경을 구현하지 않는다","es":"Aprende a usar openspec-explore para investigar y diseñar sin implementar código, con características como lectura de archivos y búsqueda de código","fr":"Découvrez comment utiliser openspec-explore pour investiguer et concevoir sans implémenter de code, avec des fonctionnalités comme la lecture de fichiers et ...","de":"Erfahren Sie, wie Sie openspec-explore verwenden, um zu untersuchen und zu entwerfen, ohne Code zu implementieren, mit Funktionen wie Dateilesen und Code-Suche","pt":"Aprenda a usar o openspec-explore para explorar códigos e criar artefatos OpenSpec sem implementar recursos","ru":"Узнайте, как использовать openspec-explore для изучения кода и создания артефактов OpenSpec без реализации функций","ar":"تعلم كيفية استخدام openspec-explore لاستكشاف الرموز وإنشاء مواصفات مفتوحة دون تنفيذ الميزات"},"definition":{"en":"openspec-explore is a skill that allows developers to enter a mode of deep thinking and free visualization, enabling them to investigate codebases and create OpenSpec proposals, designs, and specs without implementing code.","zh":"openspec-explore是一种AI工具探索模式，允许用户探索代码库而不实施更改","ja":"openspec-exploreはAIエージェントの探索モードで、ユーザーがコードベースを探索することを許可する","ko":"openspec-explore는 AI 에이전트의 탐색 모드로서 사용자가 코드베이스를 탐색하면서 변경을 구현하지 않는다","es":"Openspec-explore es un modo de exploración que permite a los desarrolladores pensar y visualizar libremente, sin implementar código","fr":"Openspec-explore est un mode d''exploration qui permet aux développeurs de réfléchir et de visualiser librement, sans implémenter de code","de":"Openspec-explore ist ein Explorationsmodus, der es Entwicklern ermöglicht, frei zu denken und zu visualisieren, ohne Code zu implementieren","pt":"O que é openspec-explore? Um modo de exploração para investigar códigos e criar artefatos OpenSpec","ru":"Что такое openspec-explore? Режим изучения для исследования кода и создания артефактов OpenSpec","ar":"ما هو openspec-explore؟ وضع استكشاف للتحقيق في الرموز وإنشاء مواصفات مفتوحة"},"features":{"en":["Enables exploration mode for deep thinking and free visualization","Allows reading files and searching code within the codebase","Supports creation of OpenSpec artifacts such as proposals, designs, and specs","Reminds users to exit explore mode before implementing code changes","Integrates with commands like /opsx:new or /opsx:ff for change implementation"],"zh":["探索代码库而不实施更改","阅读文件和搜索代码","调查代码库","创建OpenSpec文档","限制代码实施"],"ja":["コードベースを探索して変更を実施しない","ファイルを読みコードを検索する","コードベースを調査する","OpenSpecドキュメントを作成する","コードの実施を制限する"],"ko":["코드베이스를 탐색하면서 변경을 구현하지 않음","파일을 읽고 코드를 검색함","코드베이스를 조사함","OpenSpec 문서를 생성함","코드 구현을 제한함"],"es":["Lectura de archivos","Búsqueda de código","Creación de artefactos OpenSpec","Investigación de la base de código","Diseño y visualización libre"],"fr":["Lecture de fichiers","Recherche de code","Création d''artefacts OpenSpec","Investigation de la base de code","Conception et visualisation libre"],"de":["Dateilesen","Code-Suche","Erstellung von OpenSpec-Artefakten","Untersuchung der Codebasis","Entwurf und freie Visualisierung"],"pt":["Exploração de código sem implementação","Criação de propostas OpenSpec","Investigação do código com leitura de arquivos","Busca de código para investigação","Restrição de escrita de código para evitar implementação"],"ru":["Изучение кода без реализации","Создание предложений OpenSpec","Изучение кода с чтением файлов","Поиск кода для исследования","Ограничение записи кода для предотвращения реализации"],"ar":["استكشاف الرموز دون تنفيذ","إنشاء مقترحات مواصفات مفتوحة","التحقيق في الرموز مع قراءة الملفات","بحث الرموز للتحقيق","تحديد كتابة الرموز لمنع التنفيذ"]},"keywords":{"en":["how to use openspec-explore","openspec-explore alternative","openspec-explore setup guide","what is openspec-explore","openspec-explore vs design tools","openspec-explore installation"],"zh":["openspec-explore","AI工具","代码库探索","OpenSpec","代码搜索","文件阅读","代码调查","AI开发工具"],"ja":["openspec-explore","AIエージェント","コードベース探索","OpenSpec","コード検索","ファイル読み","コード調査","AI開発ツール"],"ko":["openspec-explore","AI 에이전트","코드베이스 탐색","OpenSpec","코드 검색","파일 읽기","코드 조사","AI 개발 도구"],"es":["openspec-explore","herramientas de AI para desarrolladores","modos de exploración","diseño de software","investigación de código","creación de artefactos OpenSpec","desarrollo de software","AI agents para desarrolladores"],"fr":["openspec-explore","outils d''IA pour développeurs","modes d''exploration","conception de logiciels","recherche de code","création d''artefacts OpenSpec","développement de logiciels","agents d''IA pour développeurs"],"de":["openspec-explore","AI-Tools für Entwickler","Explorationsmodi","Software-Design","Code-Untersuchung","Erstellung von OpenSpec-Artefakten","Software-Entwicklung","AI-Agents für Entwickler"],"pt":["openspec-explore","modo de exploração","arteatos OpenSpec","desenvolvimento de software","ferramentas de desenvolvimento","exploração de código","criação de propostas"],"ru":["openspec-explore","режим изучения","артефакты OpenSpec","разработка программного обеспечения","инструменты разработки","изучение кода","создание предложений"],"ar":["openspec-explore","وضع الاستكشاف","مواصفات مفتوحة","تطوير البرمجيات","أدوات التطوير","استكشاف الرموز","إنشاء مقترحات"]}},"owner":"Ejyke90","repo":"naija-conflict-tracker","repoPath":"Ejyke90/naija-conflict-tracker","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.468Z","topics":[],"category":"community","skillMd":{"name":"openspec-explore","description":"Enter explore mode - a thinking partner for exploring ideas, investigating problems, and clarifying requirements. Use when the user wants to think through something before or during a change.","version":"1.0","bodyPreview":"Enter explore mode. Think deeply. Visualize freely. Follow the conversation wherever it goes.\n\n**IMPORTANT: Explore mode is for thinking, not implementing.** You may read files, search code, and investigate the codebase, but you must NEVER write code or implement features. If the user asks you to implement something, remind them to exit explore mode first (e.g., start a change with `/opsx:new` or `/opsx:ff`). You MAY create OpenSpec artifacts (proposals, designs, specs) if the user asks—that''s c","body":"Enter explore mode. Think deeply. Visualize freely. Follow the conversation wherever it goes.\n\n**IMPORTANT: Explore mode is for thinking, not implementing.** You may read files, search code, and investigate the codebase, but you must NEVER write code or implement features. If the user asks you to implement something, remind them to exit explore mode first (e.g., start a change with `/opsx:new` or `/opsx:ff`). You MAY create OpenSpec artifacts (proposals, designs, specs) if the user asks—that''s capturing thinking, not implementing.\n\n**This is a stance, not a workflow.** There are no fixed steps, no required sequence, no mandatory outputs. You''re a thinking partner helping the user explore.\n\n---\n\n## The Stance\n\n- **Curious, not prescriptive** - Ask questions that emerge naturally, don''t follow a script\n- **Open threads, not interrogations** - Surface multiple interesting directions and let the user follow what resonates. Don''t funnel them through a single path of questions.\n- **Visual** - Use ASCII diagrams liberally when they''d help clarify thinking\n- **Adaptive** - Follow interesting threads, pivot when new information emerges\n- **Patient** - Don''t rush to conclusions, let the shape of the problem emerge\n- **Grounded** - Explore the actual codebase when relevant, don''t just theorize\n\n---\n\n## What You Might Do\n\nDepending on what the user brings, you might:\n\n**Explore the problem space**\n- Ask clarifying questions that emerge from what they said\n- Challenge assumptions\n- Reframe the problem\n- Find analogies\n\n**Investigate the codebase**\n- Map existing architecture relevant to the discussion\n- Find integration points\n- Identify patterns already in use\n- Surface hidden complexity\n\n**Compare options**\n- Brainstorm multiple approaches\n- Build comparison tables\n- Sketch tradeoffs\n- Recommend a path (if asked)\n\n**Visualize**\n```\n┌─────────────────────────────────────────┐\n│     Use ASCII diagrams liberally        │\n├─────────────────────────────────────────┤\n│                                         │\n│   ┌────────┐         ┌────────┐        │\n│   │ State  │────────▶│ State  │        │\n│   │   A    │         │   B    │        │\n│   └────────┘         └────────┘        │\n│                                         │\n│   System diagrams, state machines,      │\n│   data flows, architecture sketches,    │\n│   dependency graphs, comparison tables  │\n│                                         │\n└─────────────────────────────────────────┘\n```\n\n**Surface risks and unknowns**\n- Identify what could go wrong\n- Find gaps in understanding\n- Suggest spikes or investigations\n\n---\n\n## OpenSpec Awareness\n\nYou have full context of the OpenSpec system. Use it naturally, don''t force it.\n\n### Check for context\n\nAt the start, quickly check what exists:\n```bash\nopenspec list --json\n```\n\nThis tells you:\n- If there are active changes\n- Their names, schemas, and status\n- What the user might be working on\n\n### When no change exists\n\nThink freely. When insights crystallize, you might offer:\n\n- \"This feels solid enough to start a change. Want me to create one?\"\n  → Can transition to `/opsx:new` or `/opsx:ff`\n- Or keep exploring - no pressure to formalize\n\n### When a change exists\n\nIf the user mentions a change or you detect one is relevant:\n\n1. **Read existing artifacts for context**\n   - `openspec/changes/<name>/proposal.md`\n   - `openspec/changes/<name>/design.md`\n   - `openspec/changes/<name>/tasks.md`\n   - etc.\n\n2. **Reference them naturally in conversation**\n   - \"Your design mentions using Redis, but we just realized SQLite fits better...\"\n   - \"The proposal scopes this to premium users, but we''re now thinking everyone...\"\n\n3. **Offer to capture when decisions are made**\n\n   | Insight Type | Where to Capture |\n   |--------------|------------------|\n   | New requirement discovered | `specs/<capability>/spec.md` |\n   | Requirement changed | `specs/<capability>/spec.md` |\n   | Design decision made | `design.md` |\n   | Scope changed | `proposal.md` |\n   | New work identified | `tasks.md` |\n   | Assumption invalidated | Relevant artifact |\n\n   Example offers:\n   - \"That''s a design decision. Capture it in design.md?\"\n   - \"This is a new requirement. Add it to specs?\"\n   - \"This changes scope. Update the proposal?\"\n\n4. **The user decides** - Offer and move on. Don''t pressure. Don''t auto-capture.\n\n---\n\n## What You Don''t Have To Do\n\n- Follow a script\n- Ask the same questions every time\n- Produce a specific artifact\n- Reach a conclusion\n- Stay on topic if a tangent is valuable\n- Be brief (this is thinking time)\n\n---\n\n## Handling Different Entry Points\n\n**User brings a vague idea:**\n```\nUser: I''m thinking about adding real-time collaboration\n\nYou: Real-time collab is a big space. Let me think about this...\n\n      COLLABORATION SPECTRUM\n      ════════════════════════════════════════════\n\n      Awareness          Coordination         Sync\n          │                   │                 │\n          ▼                   ▼                 ▼\n      ┌────────┐         ┌────────┐        ┌────────┐\n      │Presence│         │Cursors │        │  CRDT  │\n      │  \"3    │         │ Multi  │        │Conflict│\n      │online\" │         │ select │        │  free  │\n      └────────┘         └────────┘        └────────┘\n          │                   │                 │\n       trivial            moderate           complex\n\n      Where''s your head at?\n```\n\n**User brings a specific problem:**\n```\nUser: The auth system is a mess\n\nYou: [reads codebase]\n\n     ┌─────────────────────────────────────────────┐\n     │              CURRENT AUTH FLOW              │\n     └─────────────────────────────────────────────┘\n                        │\n          ┌─────────────┼─────────────┐\n          ▼             ▼             ▼\n     ┌─────────┐  ┌─────────┐  ┌─────────┐\n     │ Google  │  │  GitHub │  │  Email  │\n     │  OAuth  │  │  OAuth  │  │  Magic  │\n     └────┬────┘  └────┬────┘  └────┬────┘\n          │             │             │\n          └─────────────┼─────────────┘\n                        ▼\n                  ┌───────────┐\n                  │  Session  │\n                  └─────┬─────┘\n                        │\n                        ▼\n                  ┌───────────┐\n                  │   Perms   │\n                  └───────────┘\n\n     I see three tangles. Which one''s burning?\n```\n\n**User is stuck mid-implementation:**\n```\nUser: /opsx:explore add-auth-system\n      The OAuth integration is more complex than expected\n\nYou: [reads change artifacts]\n\n     You''re on task 4: \"Implement OAuth flow\"\n\n     Let me trace what''s involved...\n\n     [draws diagram, explores options, suggests paths]\n\n     Want to update the design to reflect this?\n     Or add a spike task to investigate?\n```\n\n**User wants to compare options:**\n```\nUser: Should we use Postgres or SQLite?\n\nYou: Generic answer is boring. What''s the context?\n\nUser: A CLI tool that tracks local dev environments\n\nYou: That changes everything.\n\n     ┌─────────────────────────────────────────────────┐\n     │         CLI TOOL DATA STORAGE                  │\n     └─────────────────────────────────────────────────┘\n\n     Key constraints:\n     • No daemon running\n     • Must work offline\n     • Single user\n\n                  SQLite          Postgres\n     Deployment   embedded ✓      needs server ✗\n     Offline      yes ✓           no ✗\n     Single file  yes ✓           no ✗\n\n     SQLite. Not even close.\n\n     Unless... is there a sync component?\n```\n\n---\n\n## Ending Discovery\n\nThere''s no required ending. Discovery might:\n\n- **Flow into action**: \"Ready to start? /opsx:new or /opsx:ff\"\n- **Result in artifact updates**: \"Updated design.md with these decisions\"\n- **Just provide clarity**: User has what they need, moves on\n- **Continue later**: \"We can pick this up anytime\"\n\nWhen it feels like things are crystallizing, you might summarize:\n\n```\n## What We Figured Out\n\n**The problem**: [crystallized understanding]\n\n**The approach**: [if one emerged]\n\n**Open questions**: [if any remain]\n\n**Next steps** (if ready):\n- Create a change: /opsx:new <name>\n- Fast-forward to tasks: /opsx:ff <name>\n- Keep exploring: just keep talking\n```\n\nBut this summary is optional. Sometimes the thinking IS the value.\n\n---\n\n## Guardrails\n\n- **Don''t implement** - Never write code or implement features. Creating OpenSpec artifacts is fine, writing application code is not.\n- **Don''t fake understanding** - If something is unclear, dig deeper\n- **Don''t rush** - Discovery is thinking time, not task time\n- **Don''t force structure** - Let patterns emerge naturally\n- **Don''t auto-capture** - Offer to save insights, don''t just do it\n- **Do visualize** - A good diagram is worth many paragraphs\n- **Do explore the codebase** - Ground discussions in reality\n- **Do question assumptions** - Including the user''s and your own\n"},"lastSynced":"2026-03-08T02:09:30.851Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing advanced exploration and OpenSpec artifact creation capabilities.","zh":"适合需要高级探索和OpenSpec工件创建能力的代码分析代理。","ja":"コード分析エージェントが高度な探索とOpenSpecアーティファクトの作成機能を必要とする場合に最適です。","ko":"고급 탐색 및 OpenSpec 아티팩트 생성 기능이 필요한 코드 분석 에이전트에 적합합니다.","es":"Perfecto para agentes de análisis de código que necesitan capacidades de exploración avanzada y creación de artefactos OpenSpec.","fr":"Parfait pour les agents d''analyse de code nécessitant une exploration avancée et des capacités de création d''artefacts OpenSpec.","de":"Perfekt für Code-Analyse-Agents, die erweiterte Exploration- und OpenSpec-Artifact-Erstellungsfunktionen benötigen.","pt":"Perfeito para Agentes de Análise de Código que necessitam de exploração avançada e capacidades de criação de artifact OpenSpec.","ru":"Идеально подходит для агентов анализа кода, требующих расширенного исследования и возможностей создания артефактов OpenSpec.","ar":"مثالي للوكلاء قليلي التعقيد الذين يحتاجون إلى استكشاف متقدم وإنشاء ميزات OpenSpec."},"recommendation":{"en":"Empowers agents to think critically and design solutions through exploration mode, utilizing codebase investigation and OpenSpec artifact creation, including proposals, designs, and specs, all while adhering to the protocol of never writing code or implementing features during this mode.","zh":"赋予代理通过探索模式批判性地思考和设计解决方案的能力，利用代码库调查和OpenSpec工件创建，包括提案、设计和规格，所有这些都遵循在此模式下永远不编写代码或实现功能的协议。","ja":"エージェントが探索モードを介して批判的に考え、ソリューションを設計できるようにし、コードベースの調査とOpenSpecアーティファクトの作成（提案、設計、仕様書など）を実施し、常にこのモードではコードを書いたり機能を実装したりしないというプロトコルに従います。","ko":"에이전트가 탐색 모드를 통해 비판적으로 생각하고 솔루션을 설계할 수 있도록 하며, 코드베이스 조사 및 OpenSpec 아티팩트 생성(제안, 설계, 사양 등)을 수행하며, 이 모드에서 코드를 작성하거나 기능을 구현하지 않는다는 프로토콜을 준수합니다.","es":"Habilita a los agentes a pensar críticamente y diseñar soluciones a través del modo de exploración, utilizando la investigación de la base de código y la creación de artefactos OpenSpec, incluyendo propuestas, diseños y especificaciones, todo mientras se adhiere al protocolo de nunca escribir código o implementar características durante este modo.","fr":"Permet aux agents de réfléchir de manière critique et de concevoir des solutions via le mode d''exploration, en utilisant l''investigation du codebase et la création d''artefacts OpenSpec, y compris les propositions, les conceptions et les spécifications, tout en respectant le protocole de ne jamais écrire de code ou mettre en œuvre des fonctionnalités pendant ce mode.","de":"Ermöglicht es den Agenten, kritisch zu denken und Lösungen durch den Explorationsmodus zu entwerfen, indem sie die Untersuchung des Codebases und die Erstellung von OpenSpec-Artifacts nutzen, einschließlich Vorschlägen, Entwürfen und Spezifikationen, alles unter Einhaltung des Protokolls, während dieses Modus keinen Code zu schreiben oder Funktionen umzusetzen.","pt":"Habilita os agentes a pensar criticamente e projetar soluções por meio do modo de exploração, utilizando investigação de codebase e criação de artifact OpenSpec, incluindo propostas, projetos e especificações, todos enquanto aderem ao protocolo de nunca escrever código ou implementar recursos durante este modo.","ru":"Наделяет агентов возможностью критического мышления и проектирования решений в режиме исследования, используя расследование кодовой базы и создание артефактов OpenSpec, включая предложения, проекты и спецификации, все при этом соблюдая протокол о том, чтобы не писать код или реализовывать функции в этом режиме.","ar":"يمكن للوكلاء التفكير بشكل نقدي وتصميم حلول من خلال وضع الاستكشاف، باستخدام التحقيق في قاعدة الشفرة وإنشاء ميزات OpenSpec، بما في ذلك المقترحات والتصاميم والمواصفات، وكل ذلك مع اتباع البروتوكول الذي لا يسمح بكتابه الشفرة أو تنفيذ الميزات خلال هذا الوضع."},"useCases":{"en":["Investigating codebases without implementation","Creating OpenSpec artifacts such as proposals and designs","Enabling critical thinking and solution design before implementation"],"zh":["在不实现的情况下调查代码库","创建OpenSpec工件，例如提案和设计","在实现之前启用批判性思维和解决方案设计"],"ja":["実装せずにコードベースを調査する","提案や設計などのOpenSpecアーティファクトを作成する","実装前に批判的思考とソリューション設計を可能にする"],"ko":["구현하지 않고 코드베이스를 조사하는 것","제안이나 설계 같은 OpenSpec 아티팩트를 생성하는 것","구현 전에 비판적 사고와 솔루션 설계를 가능하게 하는 것"],"es":["Investigar bases de código sin implementación","Crear artefactos OpenSpec como propuestas y diseños","Habilitar el pensamiento crítico y el diseño de soluciones antes de la implementación"],"fr":["Investiguer les bases de code sans mise en œuvre","Créer des artefacts OpenSpec tels que des propositions et des conceptions","Permettre la réflexion critique et la conception de solutions avant la mise en œuvre"],"de":["Untersuchen von Codebasen ohne Implementierung","Erstellen von OpenSpec-Artifacts wie Vorschlägen und Entwürfen","Ermöglichen von kritischem Denken und Lösungsentwurf vor der Implementierung"],"pt":["Investigação de codebases sem implementação","Criação de artifacts OpenSpec, como propostas e projetos","Habilitação do pensamento crítico e design de soluções antes da implementação"],"ru":["Изучение кодовых баз без реализации","Создание артефактов OpenSpec, таких как предложения и проекты","Включение критического мышления и проектирования решений до реализации"],"ar":["التحقيق في قواعد الشفرة بدون تنفيذ","إنشاء ميزات OpenSpec، مثل المقترحات والتصاميم","تمكين التفكير النقدي وتصميم الحلول قبل التنفيذ"]},"limitations":{"en":["Must not write code or implement features during exploration mode","Requires exiting explore mode to start implementation with commands like /opsx:new or /opsx:ff"],"zh":["在探索模式期间必须不编写代码或实现功能","需要退出探索模式以使用/opsx：new或/opsx：ff等命令开始实现"],"ja":["探索モード期间にはコードを書いたり機能を実装してはならない","実装を開始するために/opsx：newや/opsx：ffなどのコマンドで探索モードを終了する必要がある"],"ko":["탐색 모드 동안에는 코드를 작성하거나 기능을 구현할 수 없다","구현을 시작하려면 /opsx：new 또는 /opsx：ff와 같은 명령으로 탐색 모드를 종료해야 한다"],"es":["No debe escribir código o implementar características durante el modo de exploración","Requiere salir del modo de exploración para iniciar la implementación con comandos como /opsx:new o /opsx:ff"],"fr":["Ne doit pas écrire de code ou mettre en œuvre des fonctionnalités pendant le mode d''exploration","Nécessite de quitter le mode d''exploration pour commencer la mise en œuvre avec des commandes comme /opsx:new ou /opsx:ff"],"de":["Darf während des Explorationsmodus keinen Code schreiben oder Funktionen umsetzen","Benötigt das Verlassen des Explorationsmodus, um die Implementierung mit Befehlen wie /opsx:new oder /opsx:ff zu starten"],"pt":["Não deve escrever código ou implementar recursos durante o modo de exploração","Requer sair do modo de exploração para iniciar a implementação com comandos como /opsx:new ou /opsx:ff"],"ru":["Не должно писать код или реализовывать функции в режиме исследования","Требует выхода из режима исследования для начала реализации с помощью команд, таких как /opsx:new или /opsx:ff"],"ar":["لا يجب كتابه الشفرة أو تنفيذ الميزات خلال وضع الاستكشاف","يتطلب الخروج من وضع الاستكشاف لبدء التنفيذ باستخدام أوامر مثل /opsx:new أو /opsx:ff"]},"version":4},"contentHash":"23091ef47b180412e8bfaa0731dca58fdf0a06e24f04461eadb75e2ab475aa68","qualityScore":47}');
DELETE FROM skills_fts WHERE id = 'Ejyke90/naija-conflict-tracker/openspec-explore';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Ejyke90/naija-conflict-tracker/openspec-explore', 'openspec-explore', 'Ejyke90', 'naija-conflict-tracker', 'community', 'openspec-explore Ejyke90 naija-conflict-tracker community The openspec-explore skill enables developers to enter exploration mode, investigating codebases and creating OpenSpec artifacts without writing code. It benefits developers who need to think critically and design solutions before implementation. openspec-explore允许您探索代码库而不实施更改，阅读文件、搜索代码和调查代码库 openspec-exploreはコードベースを探索することを許可し、ファイルを読み、コードを検索し、コードベースを調査する openspec-explore를 통해 코드베이스를 탐색하면서 변경을 구현하지 않으며, 파일을 읽고 코드를 검색하고 코드베이스를 조사한다 Openspec-explore es un modo de exploración que permite a los desarrolladores investigar y diseñar sin implementar código, con capacidades como lectura de archivos y búsqueda de código. Openspec-explore est un mode d''exploration qui permet aux développeurs d''investiguer et de concevoir sans implémenter de code, avec des capacités comme la lecture de fichiers et la recherche de code Openspec-explore ist ein Explorationsmodus, der es Entwicklern ermöglicht, zu untersuchen und zu entwerfen, ohne Code zu implementieren, mit Fähigkeiten wie Dateilesen und Code-Suche O openspec-explore é um modo de exploração que permite aos desenvolvedores investigar o código e criar propostas OpenSpec openspec-explore - это режим изучения, который позволяет разработчикам исследовать код и создавать предложения OpenSpec openspec-explore هو وضع استكشاف يسمح للمطورين بالتحقيق في الرموز وإنشاء مقترحات مواصفات مفتوحة how to use openspec-explore openspec-explore alternative openspec-explore setup guide what is openspec-explore openspec-explore vs design tools openspec-explore installation openspec-explore AI工具 代码库探索 OpenSpec 代码搜索 文件阅读 代码调查 AI开发工具 Enables exploration mode for deep thinking and free visualization Allows reading files and searching code within the codebase Supports creation of OpenSpec artifacts such as proposals, designs, and specs Reminds users to exit explore mode before implementing code changes Integrates with commands like /opsx:new or /opsx:ff for change implementation openspec-explore is a skill that allows developers to enter a mode of deep thinking and free visualization, enabling them to investigate codebases and create OpenSpec proposals, designs, and specs without implementing code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Bald0Wang/DeepSeek-Oracle/oracle-actionizer', 'community', 'Bald0Wang', 'DeepSeek-Oracle', 'Bald0Wang/DeepSeek-Oracle', 'oracle-actionizer', 0, 0, 47, '2026-03-08T01:57:15.470Z', '2026-03-08T02:09:34.145Z', '5a62220f3715ce649707e0071171168538a8abf294c42c41969cff6ad13ca9ea', '{"id":"Bald0Wang/DeepSeek-Oracle/oracle-actionizer","name":"oracle-actionizer","description":{"en":"The oracle-actionizer skill automates task creation from abstract guidance, utilizing deepseek language models. It benefits developers and users seeking efficient task management solutions.","zh":"Oracle Actionizer 是一个基于 DeepSeek 的命理分析系统，能够将抽象指导转化为具体任务。它支持姻缘推算和时间范围的设定","ja":"Oracle Actionizer は、DeepSeek を使用した命理分析システムで、抽象的な指示を具体的なタスクに変換します。姻缘推算や時間範囲の設定もサポートしています","ko":"Oracle Actionizer는 DeepSeek를 기반으로 하는 사주 분석 시스템으로 추상적인 지침을 구체적인 작업으로 변환합니다. 또한姻缘 추측과 시간 범위 설정을 지원합니다","es":"Oracle-actionizer es un sistema de análisis de orientación que utiliza modelos de lenguaje como deepseek para convertir orientación abstracta en tareas concretas.","fr":"Oracle-actionizer est un système d''analyse de conseils qui utilise des modèles de langage tels que deepseek pour convertir des conseils abstraits en tâches concrètes.","de":"Oracle-actionizer ist ein Analyse-System für Anweisungen, das Sprachmodelle wie deepseek verwendet, um abstrakte Anweisungen in konkrete Aufgaben umzuwandeln.","pt":"O Oracle Actionizer é um sistema de análise de destino que utiliza deepseek para converter orientações abstratas em tarefas concretas. Ele suporta a extração de intenções açãoaveis e a criação de tarefas com janelas de tempo sugeridas.","ru":"ИИ Агент Oracle Actionizer - это система анализа судьбы, которая использует deepseek для преобразования абстрактных рекомендаций в конкретные задачи. Он поддерживает извлечение аCTIONABLE намерений и создание задач с предложенными временными окнами.","ar":"Oracle Actionizer هو نظام تحليل المصير الذي يستخدم deepseek لتحويل التوجيهات المجردة إلى مهام ملموسة. وهو يدعم استخراج النيات القابلة للتنفيذ وإنشاء مهام مع نوافذ زمنية مقترحة."},"seo":{"title":{"en":"Oracle-Actionizer: Task Automation Setup Guide | AI Agent...","zh":"Oracle Actionizer 设置指南：基于 DeepSeek 的命理分析系统","ja":"Oracle Actionizer のベストプラクティス：AIエージェントによる命理分析","ko":"Oracle Actionizer 사용법: DeepSeek 기반의 운세 분석 도구","es":"Guía de configuración de oracle-actionizer para desarroll...","fr":"Guide de démarrage rapide pour oracle-actionizer","de":"Einrichtungsleitfaden für oracle-actionizer: AI-Tool für ...","pt":"Guia de Configuração do Oracle Actionizer para Desenvolve...","ru":"Настройка ИИ Агента Oracle Actionizer: Руководство для Ра...","ar":"دليل إعداد Oracle Actionizer لملحقات الذكاء الاصطناعي"},"description":{"en":"Unlock the power of oracle-actionizer, convert abstract guidance into concrete tasks. Learn how to setup and utilize this AI agent skill for efficient task m...","zh":"了解 Oracle Actionizer 如何将抽象指导转化为具体任务，并发现其基于 DeepSeek 的命理分析系统的强大功能","ja":"Oracle Actionizer を使用して抽象的な指示を具体的なタスクに変換し、AIエージェントによる命理分析の強みを発見してください","ko":"Oracle Actionizer를 사용하여 추상적인 지침을 구체적인 작업으로 변환하고 DeepSeek 기반의 사주 분석 시스템의 강력한 기능을 발견하세요","es":"Aprende a utilizar oracle-actionizer para convertir orientación abstracta en tareas concretas. Descubre sus características y beneficios para desarrolladores.","fr":"Découvrez comment utiliser oracle-actionizer pour convertir des conseils abstraits en tâches concrètes. Explorez ses fonctionnalités et avantages pour les dé...","de":"Erfahren Sie, wie Sie oracle-actionizer nutzen können, um abstrakte Anweisungen in konkrete Aufgaben umzuwandeln. Entdecken Sie seine Funktionen und Vorteile...","pt":"Aprenda a configurar o Oracle Actionizer, um sistema de análise de destino baseado em deepseek, para converter orientações abstratas em tarefas concretas","ru":"Узнайте, как настроить ИИ Агент Oracle Actionizer, систему анализа судьбы на основе deepseek, для преобразования абстрактных рекомендаций в конкретные задачи","ar":"تعلم كيفية إعداد Oracle Actionizer، نظام تحليل المصير القائم على deepseek، لتحويل التوجيهات المجردة إلى مهام ملموسة"},"definition":{"en":"oracle-actionizer is a task automation system that converts abstract guidance into actionable tasks using deep language models like deepseek.","zh":"Oracle Actionizer 是一个使用 DeepSeek 等大语言模型进行命理分析的系统","ja":"Oracle Actionizer は、DeepSeek などの大規模言語モデルを使用した命理分析システムです","ko":"Oracle Actionizer는 DeepSeek와 같은 대규모 언어 모델을 사용하여 사주 분석을 수행하는 시스템입니다","es":"Oracle-actionizer es un agente de inteligencia artificial que convierte orientación abstracta en tareas concretas utilizando modelos de lenguaje avanzados.","fr":"Oracle-actionizer est un agent d''intelligence artificielle qui convertit des conseils abstraits en tâches concrètes en utilisant des modèles de langage avancés.","de":"Oracle-actionizer ist ein KI-Agent, der abstrakte Anweisungen in konkrete Aufgaben umwandelt, indem er fortschrittliche Sprachmodelle verwendet.","pt":"O Oracle Actionizer é um sistema de análise de destino que converte orientações abstratas em tarefas concretas utilizando deepseek","ru":"ИИ Агент Oracle Actionizer - это система анализа судьбы, которая преобразует абстрактные рекомендации в конкретные задачи с помощью deepseek","ar":"Oracle Actionizer هو نظام تحليل المصير الذي يحول التوجيهات المجردة إلى مهام ملموسة باستخدام deepseek"},"features":{"en":["Extracts actionable intents from guidance text","Converts each intent into a small, manageable task","Adds suggested time window and expected duration for each task","Includes one-line rationale and gentle notes for task context","Returns 3-5 tasks with specific details for efficient completion"],"zh":["基于 DeepSeek 的命理分析","抽象指导转化为具体任务","支持姻缘推算","时间范围设定","可选的用户约束设置"],"ja":["DeepSeek を使用した命理分析","抽象的な指示を具体的なタスクに変換","姻缘推算のサポート","時間範囲の設定","ユーザー制約の設定（任意）"],"ko":["DeepSeek 기반의 사주 분석","추상적인 지침을 구체적인 작업으로 변환","姻缘 추측 지원","시간 범위 설정","사용자 제약 설정（선택 사항）"],"es":["Utiliza modelos de lenguaje como deepseek para analizar orientación","Convierte orientación abstracta en tareas concretas","Incluye una función de horizonte de tiempo para programar tareas","Permite agregar restricciones de usuario para personalizar tareas","Genera tareas con una línea de razonamiento y una nota amigable"],"fr":["Utilise des modèles de langage tels que deepseek pour analyser des conseils","Convertit des conseils abstraits en tâches concrètes","Inclut une fonction d''horizon de temps pour planifier des tâches","Permet d''ajouter des contraintes d''utilisateur pour personnaliser des tâches","Génère des tâches avec une ligne de raisonnement et une note amicale"],"de":["Verwendet Sprachmodelle wie deepseek, um Anweisungen zu analysieren","Wandelt abstrakte Anweisungen in konkrete Aufgaben um","Enthält eine Zeitraum-Funktion, um Aufgaben zu planen","Ermöglicht die Hinzufügung von Benutzereinschränkungen, um Aufgaben anzupassen","Erzeugt Aufgaben mit einer Begründungslinie und einer freundlichen Note"],"pt":["Extração de intenções açãoaveis da orientação","Criação de tarefas com janelas de tempo sugeridas","Suporte à análise de destino baseada em deepseek","Integração com sistemas de gerenciamento de tarefas","Customização de tarefas com base em restrições do usuário"],"ru":["Извлечение аCTIONABLE намерений из рекомендаций","Создание задач с предложенными временными окнами","Поддержка анализа судьбы на основе deepseek","Интеграция с системами управления задачами","Настройка задач на основе ограничений пользователя"],"ar":["استخراج النيات القابلة للتنفيذ من التوجيه","إنشاء مهام مع نوافذ زمنية مقترحة","دعم تحليل المصير القائم على deepseek","التكامل مع أنظمة إدارة المهام","تخصيص المهام بناءً على قيود المستخدم"]},"keywords":{"en":["how to use oracle-actionizer","oracle-actionizer setup guide","what is oracle-actionizer","oracle-actionizer alternative","oracle-actionizer vs task automation tools","install oracle-actionizer","deepseek language model integration"],"zh":["Oracle Actionizer","DeepSeek","命理分析","抽象指导转化","姻缘推算","AI工具","AIエージェント","大语言模型"],"ja":["Oracle Actionizer","DeepSeek","命理分析","抽象的な指示を具体的なタスクに変換","姻缘推算","AIエージェント","AIツール","大規模言語モデル"],"ko":["Oracle Actionizer","DeepSeek","사주 분석","추상적인 지침을 구체적인 작업으로 변환","姻缘 추측","AI 도구","AI 에이전트","대규모 언어 모델"],"es":["oracle-actionizer","agente de inteligencia artificial","análisis de orientación","modelos de lenguaje","deepseek","desarrollo de software","herramientas de desarrollo","programación de tareas"],"fr":["oracle-actionizer","agent d''intelligence artificielle","analyse de conseils","modèles de langage","deepseek","développement de logiciels","outils de développement","planification de tâches"],"de":["oracle-actionizer","KI-Agent","Anweisungsanalyse","Sprachmodelle","deepseek","Software-Entwicklung","Entwicklertools","Aufgabenplanung"],"pt":["Oracle Actionizer","análise de destino","deepseek","tarefas concretas","intenções açãoaveis","gerenciamento de tarefas","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["ИИ Агент Oracle Actionizer","анализ судьбы","deepseek","конкретные задачи","ACTIONABLE намерения","управление задачами","разработка программного обеспечения","инструменты разработки"],"ar":["Oracle Actionizer","تحليل المصير","deepseek","مهام ملموسة","النيات القابلة للتنفيذ","إدارة المهام","تطوير البرمجيات","أدوات التطوير"]}},"owner":"Bald0Wang","repo":"DeepSeek-Oracle","repoPath":"Bald0Wang/DeepSeek-Oracle","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.470Z","topics":[],"category":"community","skillMd":{"name":"oracle-actionizer","description":"Transform oracle guidance into concrete, calendar-ready tasks with suggested time windows, effort level, and practical notes. Use after ZiWei/MeiHua/Tarot outputs when users need execution plans.","bodyPreview":"# Oracle Actionizer\n\n## Overview\n\nConvert abstract guidance into concrete tasks users can actually complete.\n\n## Input Contract\n\n- `guidance_text`\n- `time_horizon` (today/this-week/this-month)\n- `user_constraints` (optional)\n\n## Workflow\n\n1. Extract actionable intents from guidance.\n2. Convert each intent into a small task.\n3. Add suggested time window and expected duration.\n4. Add one-line rationale and one gentle note.\n\n## Output Contract\n\nReturn 3-5 tasks in this shape:\n- `task`\n- `when`\n- `d","body":"# Oracle Actionizer\n\n## Overview\n\nConvert abstract guidance into concrete tasks users can actually complete.\n\n## Input Contract\n\n- `guidance_text`\n- `time_horizon` (today/this-week/this-month)\n- `user_constraints` (optional)\n\n## Workflow\n\n1. Extract actionable intents from guidance.\n2. Convert each intent into a small task.\n3. Add suggested time window and expected duration.\n4. Add one-line rationale and one gentle note.\n\n## Output Contract\n\nReturn 3-5 tasks in this shape:\n- `task`\n- `when`\n- `duration`\n- `note`\n\nAlso include:\n- `priority_order`\n- `first_step_under_10_min`\n\n## Quality Bar\n\n- Every task must be specific and finishable.\n- Avoid command tone; use suggestion tone.\n- Prefer behavior-level actions over abstract slogans.\n"},"lastSynced":"2026-03-08T02:09:34.145Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing to convert abstract guidance into actionable tasks, utilizing deepseek language models.","zh":"非常适合需要利用 deepseek 语言模型将抽象指导转换为可操作任务的 AI Agent。","ja":"抽象的なガイダンスを実践的なタスクに変換する必要がある AI Agent に最適です。deepseek 言語モデルを活用します。","ko":"추상적인 지침을 실행 가능한 작업으로 변환해야 하는 AI 에이전트에 완벽합니다. deepseek 언어 모델을 활용합니다.","es":"Ideal para AI Agents que necesitan convertir orientación abstracta en tareas accionables, utilizando los modelos de lenguaje deepseek.","fr":"Parfait pour les AI Agents ayant besoin de convertir des directives abstraites en tâches actionnables, en utilisant les modèles de langage deepseek.","de":"Perfekt für AI Agents, die abstrakte Anweisungen in umsetzbare Aufgaben umwandeln müssen, unter Verwendung der deepseek-Sprachmodelle.","pt":"Perfeito para Agentes de IA que precisam converter orientações abstratas em tarefas acionáveis, utilizando os modelos de linguagem deepseek.","ru":"Идеально подходит для ИИ-агентов, которым необходимо преобразовывать абстрактные указания в конкретные задачи, используя языковые модели deepseek.","ar":"مثالي لوكلاء الذكاء الاصطناعي الذين يحتاجون إلى تحويل التوجيهات المجردة إلى مهام قابلة للتنفيذ، باستخدام نماذج اللغة deepseek."},"recommendation":{"en":"Empowers agents to automate task creation from abstract guidance, providing a concrete output with suggested time windows, expected durations, and rationales, all leveraging deepseek language models and integrating with user constraints.","zh":"使 Agent 能够将抽象指导自动化创建为任务，提供具体的输出，包括建议的时间窗口、预期持续时间和理由，所有这些都利用 deepseek 语言模型并与用户约束集成。","ja":"抽象的なガイダンスからタスク作成を自動化する能力を Agent に付与し、提案された時間枠、予想される所要時間、理論的根拠を含む具体的な出力を提供します。これらはすべて deepseek 言語モデルを活用し、ユーザー制約と統合します。","ko":"에이전트가 추상적인 지침으로부터 작업 생성을 자동화할 수 있도록 하여, 제안된 시간대, 예상 기간 및 근거를 포함한 구체적인 출력을 제공합니다. 이 모든 것은 deepseek 언어 모델을 활용하고 사용자 제약 조건과 통합됩니다.","es":"Permite a los agentes automatizar la creación de tareas a partir de orientación abstracta, proporcionando una salida concreta con ventanas de tiempo sugeridas, duraciones esperadas y justificaciones, todo ello aprovechando los modelos de lenguaje deepseek e integrando las restricciones del usuario.","fr":"Permet aux agents d''automatiser la création de tâches à partir de directives abstraites, en fournissant un résultat concret avec des fenêtres temporelles suggérées, des durées attendues et des justifications, le tout en tirant parti des modèles de langage deepseek et en intégrant les contraintes de l''utilisateur.","de":"Ermöglicht es Agents, die Erstellung von Aufgaben aus abstrakten Anweisungen zu automatisieren, indem sie eine konkrete Ausgabe mit vorgeschlagenen Zeitfenstern, erwarteten Zeitdauern und Begründungen liefert, alles unter Nutzung der deepseek-Sprachmodelle und Integration von Benutzerbeschränkungen.","pt":"Capacita os agentes a automatizar a criação de tarefas a partir de orientações abstratas, fornecendo uma saída concreta com janelas de tempo sugeridas, durações esperadas e racionalizações, tudo aproveitando os modelos de linguagem deepseek e integrando-se com as restrições do usuário.","ru":"Позволяет агентам автоматизировать создание задач из абстрактных указаний, предоставляя конкретный результат с предлагаемыми временными окнами, ожидаемой продолжительностью и обоснованиями, все это с использованием языковых моделей deepseek и интеграцией с ограничениями пользователя.","ar":"يمكن الوكلاء من أتمتة إنشاء المهام من التوجيهات المجردة، وتقديم مخرجات ملموسة مع نوافذ زمنية مقترحة، ومدة متوقعة، والأسباب المنطقية، كل ذلك بالاستفادة من نماذج اللغة deepseek والتكامل مع قيود المستخدم."},"useCases":{"en":["Automating task generation from abstract project guidance","Generating concrete tasks with suggested time horizons and durations","Converting user constraints into actionable intents for efficient task management"],"zh":["从抽象项目指导自动化生成任务","生成具有建议时间范围和持续时间的具体任务","将用户约束转换为可操作的意图，以实现高效的任务管理"],"ja":["抽象的なプロジェクトガイダンスからのタスク生成の自動化","提案された時間的範囲と所要時間を備えた具体的なタスクの生成","効率的なタスク管理のためのユーザー制約の実践的な意図への変換"],"ko":["추상적인 프로젝트 지침으로부터 작업 생성 자동화","제안된 시간 범위와 기간을 가진 구체적인 작업 생성","효율적인 작업 관리를 위해 사용자 제약 조건을 실행 가능한 의도로 변환"],"es":["Automatización de la generación de tareas a partir de orientación abstracta de proyectos","Generación de tareas concretas con horizontes temporales y duraciones sugeridas","Conversión de restricciones del usuario en intenciones accionables para una gestión eficiente de tareas"],"fr":["Automatisation de la génération de tâches à partir de directives de projet abstraites","Génération de tâches concrètes avec des horizons temporels et des durées suggérés","Conversion des contraintes utilisateur en intentions actionnables pour une gestion efficace des tâches"],"de":["Automatisierung der Aufgabengenerierung aus abstrakten Projektanweisungen","Generierung konkreter Aufgaben mit vorgeschlagenen Zeithorizonten und Zeitdauern","Umwandlung von Benutzerbeschränkungen in umsetzbare Absichten für ein effizientes Aufgabenmanagement"],"pt":["Automatização da geração de tarefas a partir de orientações abstratas de projeto","Geração de tarefas concretas com horizontes de tempo e durações sugeridas","Conversão de restrições do usuário em intenções acionáveis para um gerenciamento de tarefas eficiente"],"ru":["Автоматизация генерации задач из абстрактных указаний по проекту","Генерация конкретных задач с предложенными временными горизонтами и продолжительностью","Преобразование пользовательских ограничений в действенные намерения для эффективного управления задачами"],"ar":["أتمتة إنشاء المهام من التوجيهات المجردة للمشروع","إنشاء مهام ملموسة مع آفاق زمنية مقترحة ومدة زمنية","تحويل قيود المستخدم إلى نوايا قابلة للتنفيذ لإدارة المهام بكفاءة"]},"limitations":{"en":["Requires input of guidance_text, time_horizon, and optional user_constraints","Output limited to 3-5 tasks per execution","Dependent on deepseek language model capabilities and limitations"],"zh":["需要输入 guidance_text、time_horizon 以及可选的 user_constraints","每次执行输出限制为 3-5 个任务","依赖于 deepseek 语言模型的能力和局限性"],"ja":["guidance_text、time_horizon、およびオプションの user_constraints の入力が必要","実行ごとの出力は 3～5 個のタスクに限定","deepseek 言語モデルの機能と制限に依存"],"ko":["guidance_text, time_horizon 및 선택적 user_constraints 입력 필요","실행당 출력은 3~5개의 작업으로 제한됨","deepseek 언어 모델의 기능과 제한 사항에 의존"],"es":["Requiere la entrada de guidance_text, time_horizon y user_constraints opcionales","La salida se limita a 3-5 tareas por ejecución","Depende de las capacidades y limitaciones del modelo de lenguaje deepseek"],"fr":["Nécessite la saisie de guidance_text, time_horizon et de user_constraints optionnels","Sortie limitée à 3-5 tâches par exécution","Dépend des capacités et limitations du modèle de langage deepseek"],"de":["Erfordert die Eingabe von guidance_text, time_horizon und optionalen user_constraints","Ausgabe ist auf 3-5 Aufgaben pro Ausführung begrenzt","Abhängig von den Fähigkeiten und Einschränkungen des deepseek-Sprachmodells"],"pt":["Requer a entrada de guidance_text, time_horizon e user_constraints opcionais","Saída limitada a 3-5 tarefas por execução","Dependente das capacidades e limitações do modelo de linguagem deepseek"],"ru":["Требует ввода guidance_text, time_horizon и необязательных user_constraints","Вывод ограничен 3-5 задачами за выполнение","Зависит от возможностей и ограничений языковой модели deepseek"],"ar":["يتطلب إدخال guidance_text، وtime_horizon، وuser_constraints الاختيارية","المخرجات محدودة بـ 3-5 مهام في كل تنفيذ","يعتمد على إمكانيات وقيود نموذج اللغة deepseek"]},"version":4},"contentHash":"5a62220f3715ce649707e0071171168538a8abf294c42c41969cff6ad13ca9ea","qualityScore":47}');
