INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Bald0Wang/DeepSeek-Oracle/oracle-actionizer', 'oracle-actionizer', 'Bald0Wang', 'DeepSeek-Oracle', 'community', 'oracle-actionizer Bald0Wang DeepSeek-Oracle community The oracle-actionizer skill automates task creation from abstract guidance, utilizing deepseek language models. It benefits developers and users seeking efficient task management solutions. Oracle Actionizer 是一个基于 DeepSeek 的命理分析系统，能够将抽象指导转化为具体任务。它支持姻缘推算和时间范围的设定 Oracle Actionizer は、DeepSeek を使用した命理分析システムで、抽象的な指示を具体的なタスクに変換します。姻缘推算や時間範囲の設定もサポートしています Oracle Actionizer는 DeepSeek를 기반으로 하는 사주 분석 시스템으로 추상적인 지침을 구체적인 작업으로 변환합니다. 또한姻缘 추측과 시간 범위 설정을 지원합니다 Oracle-actionizer es un sistema de análisis de orientación que utiliza modelos de lenguaje como deepseek para convertir orientación abstracta en tareas concretas. Oracle-actionizer est un système d''analyse de conseils qui utilise des modèles de langage tels que deepseek pour convertir des conseils abstraits en tâches concrètes. Oracle-actionizer ist ein Analyse-System für Anweisungen, das Sprachmodelle wie deepseek verwendet, um abstrakte Anweisungen in konkrete Aufgaben umzuwandeln. O Oracle Actionizer é um sistema de análise de destino que utiliza deepseek para converter orientações abstratas em tarefas concretas. Ele suporta a extração de intenções açãoaveis e a criação de tarefas com janelas de tempo sugeridas. ИИ Агент Oracle Actionizer - это система анализа судьбы, которая использует deepseek для преобразования абстрактных рекомендаций в конкретные задачи. Он поддерживает извлечение аCTIONABLE намерений и создание задач с предложенными временными окнами. Oracle Actionizer هو نظام تحليل المصير الذي يستخدم deepseek لتحويل التوجيهات المجردة إلى مهام ملموسة. وهو يدعم استخراج النيات القابلة للتنفيذ وإنشاء مهام مع نوافذ زمنية مقترحة. how to use oracle-actionizer oracle-actionizer setup guide what is oracle-actionizer oracle-actionizer alternative oracle-actionizer vs task automation tools install oracle-actionizer deepseek language model integration Oracle Actionizer DeepSeek 命理分析 抽象指导转化 姻缘推算 AI工具 AIエージェント 大语言模型 Extracts actionable intents from guidance text Converts each intent into a small, manageable task Adds suggested time window and expected duration for each task Includes one-line rationale and gentle notes for task context Returns 3-5 tasks with specific details for efficient completion oracle-actionizer is a task automation system that converts abstract guidance into actionable tasks using deep language models like deepseek.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Geeksfino/openskills/openskills-skill-authoring', 'community', 'Geeksfino', 'openskills', 'Geeksfino/openskills', 'openskills-skill-authoring', 0, 0, 47, '2026-03-08T01:57:15.471Z', '2026-03-08T02:09:35.315Z', 'a032ed982fcb8e3a431539b54498320e26a66c5869050c96955df4fbfe99e35b', '{"id":"Geeksfino/openskills/openskills-skill-authoring","name":"openskills-skill-authoring","description":{"en":"The openskills-skill-authoring skill enables AI agents to own skills with progressive disclosure of skill metadata, full content, and scripts/resources, using Rust runtime with TS/Python bindings.","zh":"openskills-skill-authoring技能提供Rust runtime和TS/Python绑定，支持进步披露的技能元数据和全内容脚本/资源","ja":"openskills-skill-authoringスキルはRust runtimeとTS/Pythonバインディングを提供し、スキルメタデータとフルコンテンツスクリプト/リソースの進歩的開示をサポートします","ko":"openskills-skill-authoring 스킬은 Rust runtime과 TS/Python 바인딩을 제공하며, 스킬 메타데이터와 전체 콘텐츠 스크립트/리소스의 진행적 공개를 지원합니다","es":"openskills-skill-authoring es un entorno de ejecución de Rust con enlaces de TS/Python para habilidades de Claude con divulgación progresiva de metadatos de habilidades","fr":"openskills-skill-authoring est un environnement d''exécution Rust avec des liens TS/Python pour les compétences de Claude avec divulgation progressive des métadonnées de compétences","de":"openskills-skill-authoring ist eine Laufzeitumgebung für Rust mit TS/Python-Verknüpfungen für Claude-Fähigkeiten mit schrittweiser Offenlegung von Fähigkeitsmetadaten","pt":"O openskills-skill-authoring é uma habilidade que permite criar e atualizar habilidades com suporte a Rust, TS e Python","ru":"Openskills-skill-authoring - навык для создания и обновления навыков с поддержкой Rust, TS и Python","ar":"openskills-skill-authoring هو مهارة تسمح بإنشاء وتحديث المهارات مع دعم لروست وTS وPython"},"seo":{"title":{"en":"openskills-skill-authoring: Setup Guide for AI Agents","zh":"openskills-skill-authoring 技术指南 - AIエージェント技能开发","ja":"openskills-skill-authoring セットアップガイド - AIエージェントのスキル作成","ko":"openskills-skill-authoring 개발자 가이드 - 인공지능 에이전트 스킬 제작","es":"Guía de configuración de openskills-skill-authoring para ...","fr":"Guide de mise en place d''openskills-skill-authoring pour ...","de":"Einrichtungsanleitung für openskills-skill-authoring für ...","pt":"Guia de Configuração para openskills-skill-authoring","ru":"Настройка ИИ Агентов с openskills-skill-authoring","ar":"دليل إعداد openskills-skill-authoring لتقنيات الإستخبارات..."},"description":{"en":"Discover how to create and update skills with openskills-skill-authoring. Learn to leverage Rust runtime, TS/Python bindings, and progressive disclosure for ...","zh":"了解openskills-skill-authoring技能的技术细节，包括Rust runtime、TS/Python绑定和进步披露的技能元数据","ja":"openskills-skill-authoringスキルの技術的な詳細を学びましょう。Rust runtime、TS/Pythonバインディング、スキルメタデータの進歩的開示など","ko":"openskills-skill-authoring 스킬의 기술적 세부 정보를 알아보세요. Rust runtime, TS/Python 바인딩, 스킬 메타데이터의 진행적 공개 등","es":"Aprende a crear y actualizar habilidades con openskills-skill-authoring, compatible con Rust y enlaces de TS/Python","fr":"Découvrez comment créer et mettre à jour des compétences avec openskills-skill-authoring, compatible avec Rust et des liens TS/Python","de":"Erfahren Sie, wie Sie Fähigkeiten mit openskills-skill-authoring erstellen und aktualisieren, kompatibel mit Rust und TS/Python-Verknüpfungen","pt":"Aprenda a criar e atualizar habilidades com openskills-skill-authoring, incluindo suporte a Seatbelt e WASM","ru":"Откройте для себя возможности создания и обновления навыков с помощью openskills-skill-authoring и ИИ Агентов","ar":"اكتشف كيفية إنشاء وتحديث المهارات باستخدام openskills-skill-authoring وتقنيات الإستخبارات الاصطناعية"},"definition":{"en":"openskills-skill-authoring is a skill authoring tool for AI agents, providing a Rust runtime with TS/Python bindings and support for Seatbelt and WASM sandboxing.","zh":"openskills-skill-authoring是AIエージェント技能开发的技术标准，定义了技能目录的结构和要求","ja":"openskills-skill-authoringはAIエージェントのスキル開発の技術的な標準であり、スキルディレクトリの構造と要件を定義します","ko":"openskills-skill-authoring은 인공지능 에이전트 스킬 개발을 위한 기술 표준으로, 스킬 디렉토리의 구조와 요구 사항을 정의합니다","es":"openskills-skill-authoring es un estándar de autoría de habilidades para Agentes de IA","fr":"openskills-skill-authoring est un standard de création de compétences pour les Outils d''IA","de":"openskills-skill-authoring ist ein Autorisierungsstandard für KI-Agents","pt":"O que é openskills-skill-authoring? É uma habilidade para criar e atualizar habilidades com metadados progressivos","ru":"Что такое openskills-skill-authoring? Это навык для создания и обновления навыков с прогрессивным раскрытием метаданных","ar":"ما هي openskills-skill-authoring؟ هي مهارة لإنشاء وتحديث المهارات مع الكشف التلقائي عن البيانات الوصفية"},"features":{"en":["Includes YAML frontmatter with name and description in SKILL.md","Supports optional scripts/, references/, and assets/ directories","Provides progressive disclosure of skill metadata and full content","Utilizes Rust runtime with TS/Python bindings for AI agents","Experimentally supports WASM and sandboxing for secure skill execution","Allows any agent to own skills with full execution flow control"],"zh":["Rust runtime支持","TS/Python绑定","进步披露的技能元数据","全内容脚本/资源支持","Seatbelt和WASM实验支持"],"ja":["Rust runtimeのサポート","TS/Pythonバインディング","スキルメタデータの進歩的開示","フルコンテンツスクリプト/リソースのサポート","SeatbeltとWASMの実験的サポート"],"ko":["Rust runtime 지원","TS/Python 바인딩","스킬 메타데이터의 진행적 공개","전체 콘텐츠 스크립트/리소스 지원","Seatbelt와 WASM의 실험적 지원"],"es":["Compatibilidad con Rust y enlaces de TS/Python","Divulgación progresiva de metadatos de habilidades","Compatibilidad con Seatbelt y experimentación con WASM y sandboxing","Estructura de habilidades con SKILL.md y carpetas de scripts y recursos","Soporte para habilidades personalizadas y actualizaciones"],"fr":["Compatibilité avec Rust et des liens TS/Python","Divulgation progressive des métadonnées de compétences","Compatibilité avec Seatbelt et expérimentation avec WASM et sandboxing","Structure de compétences avec SKILL.md et dossiers de scripts et de ressources","Prise en charge de compétences personnalisées et de mises à jour"],"de":["Kompatibilität mit Rust und TS/Python-Verknüpfungen","Schrittweise Offenlegung von Fähigkeitsmetadaten","Kompatibilität mit Seatbelt und experimentelle Unterstützung für WASM und sandboxing","Fähigkeitsstruktur mit SKILL.md und Ordnern für Skripte und Ressourcen","Unterstützung für benutzerdefinierte Fähigkeiten und Updates"],"pt":["Suporte a Rust, TS e Python","Metadados progressivos para habilidades","Suporte a Seatbelt e WASM","Sandboxing para segurança","Scripts e recursos personalizáveis"],"ru":["Поддержка Rust, TS и Python","Прогрессивное раскрытие метаданных для навыков","Поддержка Seatbelt и WASM","Сandboxing для безопасности","Настраиваемые скрипты и ресурсы"],"ar":["دعم لروست وTS وPython","بيانات وصفية تلقائية للمهارات","دعم لSeatbelt وWASM","حماية بالساند بوكس","سكريبتات وموارد قابلة للتخصيص"]},"keywords":{"en":["how to use openskills-skill-authoring","openskills-skill-authoring setup guide","openskills-skill-authoring alternative","openskills-skill-authoring vs Seatbelt","Rust runtime for AI agents","TS/Python bindings for skill authoring","progressive disclosure of skill metadata","WASM sandboxing for AI skills"],"zh":["openskills-skill-authoring","AIエージェント技能开发","Rust runtime","TS/Python绑定","进步披露的技能元数据","全内容脚本/资源","Seatbelt","WASM"],"ja":["openskills-skill-authoring","AIエージェントのスキル開発","Rust runtime","TS/Pythonバインディング","スキルメタデータの進歩的開示","フルコンテンツスクリプト/リソース","Seatbelt","WASM"],"ko":["openskills-skill-authoring","인공지능 에이전트 스킬 개발","Rust runtime","TS/Python 바인딩","스킬 메타데이터의 진행적 공개","전체 콘텐츠 스크립트/리소스","Seatbelt","WASM"],"es":["Agentes de IA","Herramientas de IA","openskills-skill-authoring","Rust","TS/Python","Claude","Habilidades personalizadas","Autoría de habilidades"],"fr":["Outils d''IA","Agents d''IA","openskills-skill-authoring","Rust","TS/Python","Claude","Compétences personnalisées","Création de compétences"],"de":["KI-Agents","KI-Tools","openskills-skill-authoring","Rust","TS/Python","Claude","Benutzerdefinierte Fähigkeiten","Fähigkeitsautor"],"pt":["openskills-skill-authoring","criar habilidades","atualizar habilidades","Rust","TS","Python","metadados progressivos","Seatbelt","WASM","sandboxing"],"ru":["openskills-skill-authoring","создание навыков","обновление навыков","Rust","TS","Python","прогрессивное раскрытие метаданных","Seatbelt","WASM","сandboxing"],"ar":["openskills-skill-authoring","إنشاء مهارات","تحديث مهارات","روست","TS","Python","بيانات وصفية تلقائية","Seatbelt","WASM","حماية بالساند بوكس"]}},"owner":"Geeksfino","repo":"openskills","repoPath":"Geeksfino/openskills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.471Z","topics":[],"category":"community","skillMd":{"name":"openskills-skill-authoring","description":"Create and refine OpenSkills-compatible skills (SKILL.md + optional resources) with strong metadata, clear activation triggers, and reliable execution guidance.","bodyPreview":"# OpenSkills Skill Authoring\n\nUse this skill when creating or updating skills under `examples/skills` or any OpenSkills-compatible skill directory.\n\n## Authoring Standard\n\nEach skill directory should include:\n\n- `SKILL.md` (required)\n- optional `scripts/`, `references/`, `assets/`\n\n## SKILL.md Requirements\n\n- YAML frontmatter with:\n  - `name`\n  - `description`\n- Body with concise instructions and practical execution flow.\n- Description must include both:\n  - what the skill does\n  - when to activ","body":"# OpenSkills Skill Authoring\n\nUse this skill when creating or updating skills under `examples/skills` or any OpenSkills-compatible skill directory.\n\n## Authoring Standard\n\nEach skill directory should include:\n\n- `SKILL.md` (required)\n- optional `scripts/`, `references/`, `assets/`\n\n## SKILL.md Requirements\n\n- YAML frontmatter with:\n  - `name`\n  - `description`\n- Body with concise instructions and practical execution flow.\n- Description must include both:\n  - what the skill does\n  - when to activate it\n\n## Writing Guidance\n\n1. Keep core instructions short; move details to `references/`.\n2. Prefer deterministic scripts for fragile or repetitive steps.\n3. Include explicit input/output expectations.\n4. Avoid vague names and ambiguous activation phrases.\n\n## Validation Flow\n\n1. Ensure directory name matches skill `name` semantics.\n2. Verify skill discovery and activation behavior in runtime or example agent.\n3. If scripts are present, verify paths and execution assumptions.\n\n## Output Format\n\n- Skill metadata quality review\n- Instruction clarity review\n- Activation trigger quality review\n- Suggested revisions\n"},"lastSynced":"2026-03-08T02:09:35.315Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing standardized skill development with progressive metadata disclosure and Rust runtime efficiency.","zh":"非常适合需要标准化技能开发、渐进式元数据披露以及Rust运行时效率的AI Agent。","ja":"標準化されたスキル開発、段階的なメタデータの開示、およびRustランタイムの効率性を必要とするAIエージェントに最適です。","ko":"표준화된 스킬 개발, 점진적인 메타데이터 공개 및 Rust 런타임 효율성이 필요한 AI 에이전트에 완벽합니다.","es":"Perfecto para AI Agents que necesitan un desarrollo de habilidades estandarizado con divulgación progresiva de metadatos y la eficiencia del runtime de Rust.","fr":"Parfait pour les AI Agents nécessitant un développement de compétences standardisé avec une divulgation progressive des métadonnées et l''efficacité d''exécution de Rust.","de":"Perfekt für AI Agents, die eine standardisierte Skill-Entwicklung mit fortschreitender Metadaten-Offenlegung und der Laufzeiteffizienz von Rust benötigen.","pt":"Perfeito para Agentes de IA que necessitam de um desenvolvimento de habilidades padronizado com divulgação progressiva de metadados e a eficiência de tempo de execução Rust.","ru":"Идеально подходит для ИИ-агентов, которым требуется стандартизированная разработка навыков с прогрессивным раскрытием метаданных и эффективностью среды выполнения Rust.","ar":"مثالي لوكلاء الذكاء الاصطناعي الذين يحتاجون إلى تطوير مهارات موحدة مع الكشف التدريجي للبيانات الوصفية وكفاءة وقت تشغيل Rust."},"recommendation":{"en":"Empowers agents to create and manage skills with structured content using YAML frontmatter, TS/Python bindings, and organized directory structures including scripts, references, and assets.","zh":"使Agent能够使用YAML frontmatter、TypeScript/Python绑定以及包含scripts、references和assets的组织化目录结构来创建和管理具有结构化内容的技能。","ja":"YAML frontmatter、TypeScript/Pythonバインディング、およびスクリプト、リファレンス、アセットを含む整理されたディレクトリ構造を使用して、構造化されたコンテンツでスキルを作成および管理する機能をエージェントに提供します。","ko":"YAML frontmatter, TypeScript/Python 바인딩 그리고 스크립트, 참조 및 애셋을 포함하는 체계化的인 디렉토리 구조를 사용하여 구조화된 콘텐츠로 스킬을 생성하고 관리할 수 있도록 에이전트에 권한을 부여합니다.","es":"Permite a los agentes crear y gestionar habilidades con contenido estructurado utilizando YAML frontmatter, bindings de TS/Python y estructuras de directorios organizadas que incluyen scripts, referencias y assets.","fr":"Permet aux agents de créer et de gérer des compétences avec un contenu structuré en utilisant le frontmatter YAML, les bindings TS/Python et des structures de répertoire organisées incluant des scripts, des références et des assets.","de":"Ermöglicht Agents das Erstellen und Verwalten von Skills mit strukturierten Inhalten unter Verwendung von YAML Frontmatter, TS/Python Bindings und organisierten Verzeichnisstrukturen, die Scripts, Referenzen und Assets enthalten.","pt":"Capacita os agentes a criar e gerenciar habilidades com conteúdo estruturado usando frontmatter YAML, bindings TS/Python e estruturas de diretórios organizadas incluindo scripts, referências e assets.","ru":"Позволяет агентам создавать и управлять навыками со структурированным содержимым, используя frontmatter YAML, привязки TS/Python и организованные структуры каталогов, включая скрипты, ссылки и ресурсы.","ar":"يمكن الوكلاء من إنشاء وإدارة المهارات بمحتوى منظم باستخدام frontmatter YAML، ووصلات TS/Python، وهياكل الدلائل المنظمة بما في ذلك البرامج النصية والمراجع والأصول."},"useCases":{"en":["Authoring new skills with SKILL.md requirements","Updating existing skills for OpenSkills compatibility","Organizing skill directories with scripts and assets"],"zh":["按照SKILL.md要求编写新技能","更新现有技能以实现OpenSkills兼容性","使用脚本和资源组织技能目录"],"ja":["SKILL.mdの要件に従った新しいスキルの作成","OpenSkills互換性のための既存スキルの更新","スクリプトとアセットを使用したスキルディレクトリの整理"],"ko":["SKILL.md 요구사항에 따른 새로운 스킬 작성","OpenSkills 호환성을 위한 기존 스킬 업데이트","스크립트 및 애셋을 사용한 스킬 디렉토리 구성"],"es":["Creación de nuevas habilidades con los requisitos de SKILL.md","Actualización de habilidades existentes para la compatibilidad con OpenSkills","Organización de directorios de habilidades con scripts y assets"],"fr":["Création de nouvelles compétences avec les exigences de SKILL.md","Mise à jour des compétences existantes pour la compatibilité OpenSkills","Organisation des répertoires de compétences avec des scripts et des assets"],"de":["Erstellen neuer Skills gemäß den SKILL.md-Anforderungen","Aktualisieren bestehender Skills für OpenSkills-Kompatibilität","Organisieren von Skill-Verzeichnissen mit Scripts und Assets"],"pt":["Criação de novas habilidades com requisitos SKILL.md","Atualização de habilidades existentes para compatibilidade com OpenSkills","Organização de diretórios de habilidades com scripts e assets"],"ru":["Создание новых навыков с требованиями SKILL.md","Обновление существующих навыков для совместимости с OpenSkills","Организация каталогов навыков со скриптами и ресурсами"],"ar":["إنشاء مهارات جديدة بمتطلبات SKILL.md","تحديث المهارات الحالية لتكون متوافقة مع OpenSkills","تنظيم دلائل المهارات مع البرامج النصية والأصول"]},"limitations":{"en":["Requires Rust runtime environment","Must adhere to SKILL.md format with YAML frontmatter and concise body instructions"],"zh":["需要Rust运行时环境","必须遵守包含YAML frontmatter和简洁正文说明的SKILL.md格式"],"ja":["Rustランタイム環境が必要","YAML frontmatterと簡潔な本文説明を含むSKILL.md形式に準拠する必要がある"],"ko":["Rust 런타임 환경이 필요함","YAML frontmatter와 간결한 본문 지침을 포함하는 SKILL.md 형식을 준수해야 함"],"es":["Requiere un entorno de ejecución de Rust","Debe adherirse al formato SKILL.md con YAML frontmatter e instrucciones concisas en el cuerpo"],"fr":["Nécessite un environnement d''exécution Rust","Doit respecter le format SKILL.md avec un frontmatter YAML et des instructions concises dans le corps"],"de":["Erfordert eine Rust-Laufzeitumgebung","Muss das SKILL.md-Format mit YAML-Frontmatter und prägnanten Hauptanweisungen einhalten"],"pt":["Requer um ambiente de tempo de execução Rust","Deve aderir ao formato SKILL.md com frontmatter YAML e instruções concisas no corpo"],"ru":["Требует среду выполнения Rust","Необходимо придерживаться формата SKILL.md с frontmatter YAML и краткими инструкциями в теле"],"ar":["يتطلب بيئة وقت تشغيل Rust","يجب الالتزام بتنسيق SKILL.md مع frontmatter YAML وتعليمات موجزة في الجسم"]},"version":4},"contentHash":"a032ed982fcb8e3a431539b54498320e26a66c5869050c96955df4fbfe99e35b","qualityScore":47}');
