INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Geeksfino/openskills/openskills-skill-authoring', 'openskills-skill-authoring', 'Geeksfino', 'openskills', 'community', 'openskills-skill-authoring Geeksfino openskills community The openskills-skill-authoring skill enables AI agents to own skills with progressive disclosure of skill metadata, full content, and scripts/resources, using Rust runtime with TS/Python bindings. openskills-skill-authoring技能提供Rust runtime和TS/Python绑定，支持进步披露的技能元数据和全内容脚本/资源 openskills-skill-authoringスキルはRust runtimeとTS/Pythonバインディングを提供し、スキルメタデータとフルコンテンツスクリプト/リソースの進歩的開示をサポートします openskills-skill-authoring 스킬은 Rust runtime과 TS/Python 바인딩을 제공하며, 스킬 메타데이터와 전체 콘텐츠 스크립트/리소스의 진행적 공개를 지원합니다 openskills-skill-authoring es un entorno de ejecución de Rust con enlaces de TS/Python para habilidades de Claude con divulgación progresiva de metadatos de habilidades openskills-skill-authoring est un environnement d''exécution Rust avec des liens TS/Python pour les compétences de Claude avec divulgation progressive des métadonnées de compétences openskills-skill-authoring ist eine Laufzeitumgebung für Rust mit TS/Python-Verknüpfungen für Claude-Fähigkeiten mit schrittweiser Offenlegung von Fähigkeitsmetadaten O openskills-skill-authoring é uma habilidade que permite criar e atualizar habilidades com suporte a Rust, TS e Python Openskills-skill-authoring - навык для создания и обновления навыков с поддержкой Rust, TS и Python openskills-skill-authoring هو مهارة تسمح بإنشاء وتحديث المهارات مع دعم لروست وTS وPython how to use openskills-skill-authoring openskills-skill-authoring setup guide openskills-skill-authoring alternative openskills-skill-authoring vs Seatbelt Rust runtime for AI agents TS/Python bindings for skill authoring progressive disclosure of skill metadata WASM sandboxing for AI skills openskills-skill-authoring AIエージェント技能开发 Rust runtime TS/Python绑定 进步披露的技能元数据 全内容脚本/资源 Seatbelt WASM Includes YAML frontmatter with name and description in SKILL.md Supports optional scripts/, references/, and assets/ directories Provides progressive disclosure of skill metadata and full content Utilizes Rust runtime with TS/Python bindings for AI agents Experimentally supports WASM and sandboxing for secure skill execution Allows any agent to own skills with full execution flow control openskills-skill-authoring is a skill authoring tool for AI agents, providing a Rust runtime with TS/Python bindings and support for Seatbelt and WASM sandboxing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sinelanguage/cursor-config-nextjs/next-static-site', 'community', 'sinelanguage', 'cursor-config-nextjs', 'sinelanguage/cursor-config-nextjs', 'next-static-site', 0, 0, 47, '2026-03-08T01:57:15.476Z', '2026-03-08T02:09:48.758Z', 'a3aeed0b57520ea7c47664cb28f9d1aeb8c7bbd88f3c33cbd00b5b5c79918d3a', '{"id":"sinelanguage/cursor-config-nextjs/next-static-site","name":"next-static-site","description":{"en":"The next-static-site skill generates a fully static site with Next.js, ideal for content-heavy sites with low personalization. It supports static hosting requirements and explicit output settings.","zh":"Next.js静态网站生成是使用Next.js框架生成静态网站的方法，通过配置静态输出和数据预取实现快速部署和优化。","ja":"Next.js静的サイト生成は、Next.jsフレームワークを使用して静的サイトを生成する方法で、静的出力とデータプリフェッチを設定することで迅速なデプロイと最適化を実現します。","ko":"Next.js 정적 사이트 생성은 Next.js 프레임워크를 사용하여 정적 사이트를 생성하는 방법으로, 정적 출력과 데이터 사전 가져오기를 설정하여 빠른 배포 및 최적화를 구현합니다.","es":"Next.js Static Site es una habilidad que permite generar sitios estáticos con Next.js, ideal para sitios con contenido pesado y requisitos de hospedaje estático","fr":"Next.js Static Site est une compétence qui permet de générer des sites statiques avec Next.js, idéal pour les sites avec un contenu lourd et des exigences d''hébergement statique","de":"Next.js Static Site ist eine Fähigkeit, die es ermöglicht, statische Seiten mit Next.js zu generieren, ideal für Seiten mit inhaltsreichen Inhalten und statischen Hosting-Anforderungen","pt":"O Next.js Static Site é uma ferramenta para criar sites estáticos com pré-renderização de rotas e configuração de saída estática.","ru":"Next.js Статический Сайт - это инструмент для создания статических сайтов с предварительной визуализацией маршрутов и настройкой статического вывода.","ar":"موقع إلكتروني ثابت Next.js هو أداة لإنشاء مواقع إلكترونية ثابتة مع ما قبل العرض مسبقاً للطرق وتكوين الإخراج الثابت."},"seo":{"title":{"en":"next-static-site: Static Site Generation Setup Guide | AI...","zh":"Next.js静态网站生成Setup Guide - AIエージェント","ja":"Next.js静的サイト生成Best Practices - AIエージェント","ko":"Next.js 정적 사이트 생성 가이드 - AI 에이전트","es":"Guía de configuración de sitios estáticos con Next.js","fr":"Guide de mise en place de sites statiques avec Next.js","de":"Einrichtungsanleitung für statische Seiten mit Next.js","pt":"Guia de Configuração do Next.js Static Site","ru":"Настройка Статического Сайта Next.js: ИИ Агенты","ar":"إعداد موقع إلكتروني ثابت مع Next.js: أدوات ذكاء اصطناعي"},"description":{"en":"Learn how to generate a fully static site with Next.js and explicit output settings. Get started with next-static-site today and optimize your content-heavy ...","zh":"使用Next.js生成静态网站，实现快速部署和优化。了解如何配置静态输出和数据预取。","ja":"Next.jsを使用して静的サイトを生成し、迅速なデプロイと最適化を実現します。静的出力とデータプリフェッチの設定方法をご紹介します。","ko":"Next.js를 사용하여 정적 사이트를 생성하고 빠른 배포 및 최적화를 구현합니다. 정적 출력 및 데이터 사전 가져오기 설정 방법을 알아보세요.","es":"Aprende a generar sitios estáticos con Next.js y mejora el rendimiento de tu sitio web con nuestra guía paso a paso","fr":"Découvrez comment générer des sites statiques avec Next.js et améliorez les performances de votre site web avec notre guide étape par étape","de":"Erfahren Sie, wie Sie mit Next.js statische Seiten generieren und die Leistung Ihrer Website mit unserer Schritt-für-Schritt-Anleitung verbessern","pt":"Aprenda a criar um site estático com Next.js, incluindo pré-renderização de rotas e configuração de saída estática","ru":"Узнайте, как создать статический сайт с помощью Next.js, включая предварительную визуализацию маршрутов и настройку статического вывода","ar":"تعلم كيفية إنشاء موقع إلكتروني ثابت مع Next.js، بما في ذلك ما قبل العرض مسبقاً للطرق وتكوين الإخراج الثابت"},"definition":{"en":"next-static-site is a skill that enables the generation of fully static sites with Next.js, using explicit output settings and static data fetching.","zh":"Next.js静态网站生成是使用Next.js框架生成静态网站的方法","ja":"Next.js静的サイト生成は、Next.jsフレームワークを使用して静的サイトを生成する方法","ko":"Next.js 정적 사이트 생성은 Next.js 프레임워크를 사용하여 정적 사이트를 생성하는 방법","es":"Next.js Static Site es una técnica de generación de sitios estáticos que utiliza Next.js para mejorar el rendimiento y la escalabilidad","fr":"Next.js Static Site est une technique de génération de sites statiques qui utilise Next.js pour améliorer les performances et la scalabilité","de":"Next.js Static Site ist eine Technik zur Generierung statischer Seiten, die Next.js verwendet, um die Leistung und Skalierbarkeit zu verbessern","pt":"O que é Next.js Static Site? Uma ferramenta para criar sites estáticos com Next.js","ru":"Что такое Next.js Статический Сайт? Инструмент для создания статических сайтов с помощью Next.js","ar":"ما هو موقع إلكتروني ثابت Next.js? أداة لإنشاء مواقع إلكترونية ثابتة مع Next.js"},"features":{"en":["Generates fully static sites with Next.js","Supports static data fetching in App Router or Pages Router","Configures next.config.ts for static output","Avoids server-only APIs for static-only routes","Optimizes for static hosting requirements"],"zh":["使用静态数据预取在App Router或Pages Router中","避免在静态路由中使用服务器端API","配置next.config.ts实现静态输出","支持静态主机托管要求","实现内容丰富的网站低个人化","支持静态网站生成的最佳实践"],"ja":["App RouterまたはPages Routerで静的データプリフェッチを使用","静的ルートではサーバー側APIを使用しない","静的出力を実現するためにnext.config.tsを設定","静的ホスティング要件をサポート","コンテンツ重視のサイトで低個人化を実現","静的サイト生成のベストプラクティスをサポート"],"ko":["App Router 또는 Pages Router에서 정적 데이터 사전 가져오기 사용","정적 루트에서는 서버 측 API 사용 안 함","정적 출력을 구현하기 위해 next.config.ts 설정","정적 호스팅 요구 사항 지원","내용이 풍부한 사이트에서 저 개인화를 구현","정적 사이트 생성의 최선의 관행 지원"],"es":["Generación de sitios estáticos con Next.js","Uso de datos estáticos en App Router o Pages Router","Evitación de APIs de servidor solo para rutas estáticas","Configuración de next.config.ts para salida estática","Compatibilidad con hospedaje estático"],"fr":["Génération de sites statiques avec Next.js","Utilisation de données statiques dans App Router ou Pages Router","Évitement des APIs de serveur uniquement pour les routes statiques","Configuration de next.config.ts pour une sortie statique","Compatibilité avec l''hébergement statique"],"de":["Generierung statischer Seiten mit Next.js","Verwendung von statischen Daten in App Router oder Pages Router","Vermeidung von Server-Only-APIs für statische Routen","Konfiguration von next.config.ts für statische Ausgabe","Kompatibilität mit statischem Hosting"],"pt":["Pré-renderização de rotas com App Router ou Pages Router","Configuração de saída estática com next.config.ts","Evitar APIs somente do servidor para rotas estáticas","Suporte a hospedagem estática"],"ru":["Предварительная визуализация маршрутов с помощью App Router или Pages Router","Настройка статического вывода с помощью next.config.ts","Избегание серверных API для статических маршрутов","Поддержка статического хостинга"],"ar":["ما قبل العرض مسبقاً للطرق مع App Router أو Pages Router","تكوين الإخراج الثابت مع next.config.ts","تجنب واجهات برمجة التطبيقات فقط للخادم للطرق الثابتة","دعم الاستضافة الثابتة"]},"keywords":{"en":["how to use next-static-site","next-static-site setup guide","next-static-site vs Gatsby","next-static-site install","what is next-static-site","next-static-site alternative","next-static-site tutorial","next-static-site static site generation","next-static-site next.js"],"zh":["Next.js静态网站生成","静态网站托管","Next.js配置","静态数据预取","服务器端API","静态输出","内容重视的网站","低个人化","AIエージェント"],"ja":["Next.js静的サイト生成","静的サイトホスティング","Next.js設定","静的データプリフェッチ","サーバー側API","静的出力","コンテンツ重視のサイト","低個人化","AIエージェント"],"ko":["Next.js 정적 사이트 생성","정적 사이트 호스팅","Next.js 설정","정적 데이터 사전 가져오기","서버 측 API","정적 출력","내용이 풍부한 사이트","저 개인화","AI 에이전트"],"es":["Next.js Static Site","sitios estáticos","generación de sitios estáticos","Next.js","hospedaje estático","rendimiento web","escalabilidad web","desarrollo web"],"fr":["Next.js Static Site","sites statiques","génération de sites statiques","Next.js","hébergement statique","performances web","scalabilité web","développement web"],"de":["Next.js Static Site","statische Seiten","Generierung statischer Seiten","Next.js","statisches Hosting","Web-Performance","Web-Skalierbarkeit","Web-Entwicklung"],"pt":["Next.js Static Site","pré-renderização de rotas","configuração de saída estática","hospedagem estática","desenvolvimento web estático","ferramentas de desenvolvimento web"],"ru":["Next.js Статический Сайт","предварительная визуализация маршрутов","настройка статического вывода","статический хостинг","разработка статических веб-сайтов","инструменты разработки веб-сайтов"],"ar":["موقع إلكتروني ثابت Next.js","ما قبل العرض مسبقاً للطرق","تكوين الإخراج الثابت","الاستضافة الثابتة","تطوير مواقع إلكترونية ثابتة","أدوات تطوير مواقع إلكترونية"]}},"owner":"sinelanguage","repo":"cursor-config-nextjs","repoPath":"sinelanguage/cursor-config-nextjs","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.476Z","topics":[],"category":"community","skillMd":{"name":"next-static-site","description":"Configure Next.js for static site generation and export.","bodyPreview":"# Next.js Static Site (SSG)\n\nGenerate a fully static site with Next.js and explicit output settings.\n\n## When to Use\n\n- Content-heavy sites with low personalization\n- Static hosting requirements\n\n## Inputs\n\n- Routes to pre-render\n- Data sources and build-time needs\n- Hosting requirements for static export\n\n## Instructions\n\n1. Use static data fetching in App Router or Pages Router.\n2. Avoid server-only APIs for static-only routes.\n3. Configure `next.config.ts` for static output if required.\n4. Va","body":"# Next.js Static Site (SSG)\n\nGenerate a fully static site with Next.js and explicit output settings.\n\n## When to Use\n\n- Content-heavy sites with low personalization\n- Static hosting requirements\n\n## Inputs\n\n- Routes to pre-render\n- Data sources and build-time needs\n- Hosting requirements for static export\n\n## Instructions\n\n1. Use static data fetching in App Router or Pages Router.\n2. Avoid server-only APIs for static-only routes.\n3. Configure `next.config.ts` for static output if required.\n4. Validate routing for static-only constraints.\n\n## Output\n\n- Static-ready routing, data fetching, and output configuration.\n"},"lastSynced":"2026-03-08T02:09:48.758Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents specializing in Next.js and requiring static site generation capabilities for content-heavy applications.","zh":"适合专门从事 Next.js 的前端代理，并且需要为内容重的应用程序提供静态站点生成功能的代理。","ja":"Next.js と静的サイト生成の機能を必要とするコンテンツ重のアプリケーションに特化したフロントエンドエージェントに適しています。","ko":"Next.js 및 정적 사이트 생성 기능이 필요한 콘텐츠가 많은 애플리케이션을専門とする 프론트엔드 에이전트에 적합합니다.","es":"Ideal para Agentes de Frontend que se especializan en Next.js y requieren capacidades de generación de sitios estáticos para aplicaciones con mucho contenido.","fr":"Idéal pour les agents Frontend spécialisés dans Next.js et nécessitant des capacités de génération de sites statiques pour des applications contenant beaucoup de contenu.","de":"Ideal für Frontend-Agents, die sich auf Next.js spezialisieren und statische Site-Generation-Funktionen für inhaltsreiche Anwendungen benötigen.","pt":"Ideal para Agentes de Frontend especializados em Next.js e que exigem capacidades de geração de sites estáticos para aplicações com muito conteúdo.","ru":"Идеально для агентов Frontend, специализирующихся на Next.js и требующих возможностей генерации статических сайтов для контентно-насыщенных приложений.","ar":"مثالي لوكلاء واجهة المستخدم المتخصصين في Next.js والذين يتطلبون إمكانيات توليد مواقع ثابتة لتنسيق التطبيقات الكثيفة المحتوى."},"recommendation":{"en":"Empowers agents to generate fully static sites with explicit output settings, leveraging Next.js static site generation (SSG) for content-heavy sites with low personalization, supporting static hosting requirements and utilizing static data fetching in App Router or Pages Router.","zh":"赋予代理生成全静态站点的能力，具有明确的输出设置，利用 Next.js 的静态站点生成（SSG）功能，支持内容重的站点和低个人化，满足静态托管要求，并在 App Router 或 Pages Router 中使用静态数据获取。","ja":"エージェントに、明示的な出力設定を使用して完全な静的サイトを生成する機能を提供します。Next.js の静的サイト生成（SSG）機能を使用して、コンテンツ重のサイトと低個人化をサポートし、静的ホスティングの要件を満たします。また、App Router または Pages Router で静的データ取得を使用します。","ko":"에이전트가 완전한 정적 사이트를 생성 할 수 있는 기능을 제공하며, 명시적인 출력 설정을 사용하여 Next.js의 정적 사이트 생성 (SSG) 기능을 활용하여 콘텐츠가 많은 사이트와 낮은 개인화를 지원하며, 정적 호스팅 요구 사항을 충족하고 App Router 또는 Pages Router에서 정적 데이터 가져오기를 사용합니다.","es":"Habilita a los agentes a generar sitios completamente estáticos con configuraciones de salida explícitas, aprovechando la generación de sitios estáticos de Next.js (SSG) para sitios con mucho contenido y poca personalización, que cumplen con los requisitos de alojamiento estático y utilizan la recuperación de datos estáticos en App Router o Pages Router.","fr":"Permet aux agents de générer des sites entièrement statiques avec des paramètres de sortie explicites, en exploitant la génération de sites statiques Next.js (SSG) pour les sites contenant beaucoup de contenu et ayant une faible personnalisation, qui répondent aux exigences d''hébergement statique et utilisent la récupération de données statiques dans App Router ou Pages Router.","de":"Ermächtigt Agenten, vollständig statische Sites mit expliziten Ausgabeeinstellungen zu generieren, indem Next.js statische Site-Generation (SSG) für inhaltsreiche Sites mit geringer Personalisierung nutzt, die statische Hosting-Anforderungen erfüllen und statisches DatenAbrufen in App Router oder Pages Router verwenden.","pt":"Habilita os agentes a gerar sites completamente estáticos com configurações de saída explícitas, aproveitando a geração de sites estáticos do Next.js (SSG) para sites com muito conteúdo e baixa personalização, suportando requisitos de hospedagem estática e utilizando busca de dados estática no App Router ou Pages Router.","ru":"Наделяет агентов возможностью генерировать полностью статические сайты с явными настройками вывода, используя статическую генерацию сайтов Next.js (SSG) для контентно-насыщенных сайтов с низкой персонализацией, поддерживая требования статического хостинга и используючи статическую выборку данных в App Router или Pages Router.","ar":"تمكّن الوكلاء من توليد مواقع ثابتة بالكامل مع إعدادات مخرجات صريحة، مستفيدة من توليد الموقع الثابت في Next.js (SSG) للمواقع الكثيفة المحتوى منخفضة التخصيص، داعمة لمتطلبات الاستضافة الثابتة وتستخدم استرجاع البيانات الثابت في App Router أو Pages Router."},"useCases":{"en":["Generating fully static sites for content-heavy applications","Configuring static output settings for Next.js projects","Optimizing static site performance for low-latency hosting"],"zh":["为内容重的应用程序生成完全静态站点","为 Next.js 项目配置静态输出设置","优化静态站点性能以实现低延迟托管"],"ja":["コンテンツ重のアプリケーション用の完全静的サイトの生成","Next.js プロジェクトの静的出力設定の構成","低遅延ホスティングのための静的サイトパフォーマンスの最適化"],"ko":["콘텐츠가 많은 애플리케이션을 위한 완전한 정적 사이트 생성","Next.js 프로젝트를 위한 정적 출력 설정 구성","저지연 호스팅을 위한 정적 사이트 성능 최적화"],"es":["Generar sitios completamente estáticos para aplicaciones con mucho contenido","Configurar configuraciones de salida estáticas para proyectos Next.js","Optimizar el rendimiento del sitio estático para hosting de baja latencia"],"fr":["Générer des sites entièrement statiques pour des applications contenant beaucoup de contenu","Configurer les paramètres de sortie statiques pour les projets Next.js","Optimiser les performances du site statique pour un hébergement à faible latence"],"de":["Vollständig statische Sites für inhaltsreiche Anwendungen generieren","Statische Ausgabeeinstellungen für Next.js-Projekte konfigurieren","Statische Site-Leistung für Hosting mit geringer Latenz optimieren"],"pt":["Gerar sites completamente estáticos para aplicações com muito conteúdo","Configurar configurações de saída estática para projetos Next.js","Otimizar o desempenho do site estático para hospedagem de baixa latência"],"ru":["Генерировать полностью статические сайты для контентно-насыщенных приложений","Настроить настройки статического вывода для проектов Next.js","Оптимизировать производительность статического сайта для хостинга с низкой задержкой"],"ar":["توليد مواقع ثابتة بالكامل لتطبيقات كثيفة المحتوى","تكوين إعدادات مخرجات ثابتة لمشاريع Next.js","تحسين أداء الموقع الثابت لاستضافة منخفضة التأخير"]},"limitations":{"en":["Limited to content-heavy sites with low personalization","Requires explicit output settings configuration","Static hosting requirements must be met"],"zh":["仅限于内容重的站点和低个人化","需要明确的输出设置配置","静态托管要求必须满足"],"ja":["コンテンツ重のサイトと低個人化に限定される","明示的な出力設定の構成が必要","静的ホスティングの要件を満たす必要がある"],"ko":["콘텐츠가 많은 사이트와 낮은 개인화에만 국한됨","명시적인 출력 설정 구성이 필요함","정적 호스팅 요구 사항을 충족해야 함"],"es":["Limitado a sitios con mucho contenido y poca personalización","Requiere configuración explícita de configuraciones de salida","Los requisitos de alojamiento estático deben cumplirse"],"fr":["Limité aux sites contenant beaucoup de contenu et ayant une faible personnalisation","Nécessite une configuration explicite des paramètres de sortie","Les exigences d''hébergement statique doivent être respectées"],"de":["Begrenzt auf inhaltsreiche Sites mit geringer Personalisierung","Benötigt explizite Konfiguration von Ausgabeeinstellungen","Statische Hosting-Anforderungen müssen erfüllt werden"],"pt":["Limitado a sites com muito conteúdo e baixa personalização","Exige configuração explícita de configurações de saída","Requisitos de hospedagem estática devem ser atendidos"],"ru":["Ограничен контентно-насыщенными сайтами с низкой персонализацией","Требует явной настройки настроек вывода","Требования статического хостинга должны быть выполнены"],"ar":["محدود لمواقع كثيفة المحتوى منخفضة التخصيص","يتطلب تكوين إعدادات مخرجات صريحة","يجب أن تتم 충족 متطلبات الاستضافة الثابتة"]},"version":4},"contentHash":"a3aeed0b57520ea7c47664cb28f9d1aeb8c7bbd88f3c33cbd00b5b5c79918d3a","qualityScore":47}');
