INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jfarid27/open-eth-terminal/open-eth-terminal-action-generator', 'open-eth-terminal-action-generator', 'jfarid27', 'open-eth-terminal', 'community', 'open-eth-terminal-action-generator jfarid27 open-eth-terminal community The open-eth-terminal-action-generator is a CLI-based tool for everyday retail traders, providing higher quality research in Ethereum financial markets by bundling API access. Open Eth Terminal Action Generator 是一个 CLI 基础的数据聚合工具，旨在为日常零售交易者提供高质量的 Ethereum 金融市场研究 Open Eth Terminal Action Generator は、日常の小売りトレーダーが Ethereum 金融市場で高品質の研究を実現できるように設計された CLI ベースのデータ集約ツールです Open Eth Terminal Action Generator는 일상적인 소매 투자자가 이더리움 금융 시장에서 높은 품질의 연구를 수행할 수 있는 CLI 기반의 데이터 집계 도구입니다 Open-eth-terminal-action-generator es una herramienta de agregación de datos de línea de comandos para traders que buscan investigaciones de alta calidad en los mercados financieros de Ethereum. Open-eth-terminal-action-generator est un outil de collecte de données en ligne de commande pour les traders qui recherchent des recherches de haute qualité sur les marchés financiers Ethereum. Open-eth-terminal-action-generator ist ein Befehlszeilen-Tool für Datenaggregation für Trader, die hochwertige Recherchen in den Ethereum-Finanzmärkten suchen. O open-eth-terminal-action-generator é uma ferramenta de agregação de dados em linha de comando para mercados financeiros Ethereum, permitindo que desenvolvedores criem novas ações para a aplicação. Открытый терминал Ethereum - это ИИ Агент, создающий новые действия для приложения, облегчая разработчикам доступ к информации о финансовых рынках open-eth-terminal-action-generator هو أداة تجميع البيانات في سطر الأوامر للأسواق المالية Ethereum، تمكن المطورين من إنشاء إجراءات جديدة للتطبيق how to use open-eth-terminal-action-generator open-eth-terminal-action-generator setup guide Ethereum financial market research tools CLI data aggregation for retail traders open-eth-terminal-action-generator alternative install open-eth-terminal-action-generator Open Eth Terminal Action Generator CLI 数据聚合工具 Ethereum 金融市场研究 高质量研究数据 API 访问 日常零售交易者 AIエージェント 金融市场数据 Generates actions for the open-eth-terminal application Provides CLI interface to organize and access financial market information Bundles API access for streamlined data aggregation Supports README.md file for detailed application information Familiarizes users with the goal of the application through SKILL.md content open-eth-terminal-action-generator is a command-line interface data aggregation tool for Ethereum financial markets research and analysis.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('abc21086999/maple_script/task_planner', 'community', 'abc21086999', 'maple_script', 'abc21086999/maple_script', 'task_planner', 0, 0, 47, '2026-03-08T01:57:15.568Z', '2026-03-08T02:11:43.169Z', 'a44305a305900f6e65984e6fce63be2e91d1d7d1433ac6408c00fbadfe860fab', '{"id":"abc21086999/maple_script/task_planner","name":"task_planner","description":{"en":"task_planner is a strategic architect that generates step-by-step action plans for users. It performs deep research into existing codebases to bridge the gap between user requirements and technical implementation.","zh":"任务规划器是一种 Strategic Architect，能够帮助用户将需求转化为技术实现。它通过对现有代码库的深入研究，产生一个分层的、逐步的行动计划","ja":"タスクプランナーは、ユーザーの要件を技術的な実装に変換するための戦略アーキテクトです。コードベースを深く調査し、階層的なステップバイステップのアクションプランを生成します","ko":"작업 계획자는 사용자의 요구를 기술적 구현으로 변환하는 전략 아키텍트입니다. 코드베이스를 깊이 조사하여 계층적인 단계별 작업 계획을 생성합니다","es":"Task_planner es un skill que ayuda a los arquitectos estratégicos a crear planes de acción jerárquicos para implementar requisitos de usuario en MapleScript","fr":"Task_planner est une compétence qui aide les architectes stratégiques à créer des plans d''action hiérarchiques pour mettre en œuvre les exigences utilisateur dans MapleScript","de":"Task_planner ist eine Fähigkeit, die strategische Architekten bei der Erstellung hierarchischer Aktionspläne zur Umsetzung von Benutzeranforderungen in MapleScript unterstützt","pt":"O task_planner é um planejador de tarefas para desenvolvedores que ajuda a criar planos de ação hierárquicos. Ele realiza investigações no código existente para produzir um plano de ação passo a passo.","ru":"ИИ Агенты task_planner - это планировщик задач для разработчиков, который помогает создавать иерархические планы действий. Он проводит расследование существующего кода для создания пошагового плана.","ar":"وكلاء الذكاء الاصطناعي task_planner هو مخطط مهام للطورين يساعد على إنشاء خطط عمل هرمية. يقوم بالتحقيقات في الكود الموجود لإنشاء خطة عمل خطوة بخطوة."},"seo":{"title":{"en":"task_planner: Strategic Architect Setup Guide | AI Agent ...","zh":"任务规划器设置指南 - MapleScript 项目优化","ja":"タスクプランナー導入ガイド - MapleScript プロジェクト最適化","ko":"작업 계획자 설정 가이드 - MapleScript 프로젝트 최적화","es":"Guía de configuración de task_planner para arquitectos es...","fr":"Guide de démarrage de task_planner pour les architectes s...","de":"Einrichtungsleitfaden für task_planner als strategischer ...","pt":"Guia de Configuração do task_planner: Planejador de Taref...","ru":"ИИ Агенты: task_planner - Руководство по Настройке Планир...","ar":"دليل إعداد task_planner: مخطط المهام للطورين"},"description":{"en":"Discover how task_planner bridges user requirements and technical implementation. Learn to create hierarchical action plans with codebase investigation","zh":"了解任务规划器的工作原理，如何将用户需求转化为技术实现，优化您的 MapleScript 项目","ja":"タスクプランナーの機能を理解し、ユーザーの要件を技術的な実装に変換することで、MapleScript プロジェクトを最適化する","ko":"작업 계획자의 작동 원리를 이해하고 사용자 요구를 기술적 구현으로 변환하여 MapleScript 프로젝트를 최적화하는 방법","es":"Aprende a utilizar task_planner para bridar la brecha entre requisitos de usuario y implementación técnica en MapleScript","fr":"Découvrez comment utiliser task_planner pour combler le fossé entre les exigences utilisateur et la mise en œuvre technique dans MapleScript","de":"Erfahren Sie, wie Sie task_planner verwenden, um die Lücke zwischen Benutzeranforderungen und technischer Implementierung in MapleScript zu schließen","pt":"Aprenda a configurar o task_planner, um planejador de tarefas para desenvolvedores, e melhore sua produtividade com um guia passo a passo","ru":"Узнайте, как настроить task_planner, планировщик задач для разработчиков, и повысьте свою производительность с помощью пошагового руководства","ar":"تعلم كيفية إعداد task_planner، مخطط المهام للطورين، ورفع إنتاجيتك مع دليل خطوة بخطوة"},"definition":{"en":"task_planner is a skill that produces hierarchical, step-by-step action plans for users to review, utilizing codebase investigation and research","zh":"任务规划器是一种 AI 工具，用于将用户需求转化为技术实现","ja":"タスクプランナーは、ユーザーの要件を技術的な実装に変換するための AI エージェントです","ko":"작업 계획자는 사용자의 요구를 기술적 구현으로 변환하는 AI 도구입니다","es":"Task_planner es una herramienta de inteligencia artificial que ayuda a planificar tareas y proyectos en MapleScript","fr":"Task_planner est un outil d''intelligence artificielle qui aide à planifier des tâches et des projets dans MapleScript","de":"Task_planner ist ein KI-Tool, das bei der Planung von Aufgaben und Projekten in MapleScript hilft","pt":"O task_planner é um planejador de tarefas que cria planos de ação hierárquicos para desenvolvedores","ru":"ИИ Агенты task_planner - это планировщик задач, который создает иерархические планы действий для разработчиков","ar":"وكلاء الذكاء الاصطناعي task_planner هو مخطط مهام يخلق خطط عمل هرمية للطورين"},"features":{"en":["Performs codebase investigation using search_file_content or read","Generates hierarchical, step-by-step action plans for user review","Utilizes deep research into existing codebases","Produces plans without writing implementation code immediately","Employs a mandatory codebase investigation workflow","Leverages MapleScript for strategic architecture"],"zh":["代码库调查","分层的、逐步的行动计划生成","使用 search_file_content 或 read_ 进行代码库分析","MapleScript 项目优化","技术实现规划"],"ja":["コードベースの調査","階層的なステップバイステップのアクションプランの生成","search_file_content または read_ を使用したコードベース分析","MapleScript プロジェクト最適化","技術的な実装計画"],"ko":["코드베이스 조사","계층적인 단계별 작업 계획 생성","search_file_content 또는 read_ 를 사용한 코드베이스 분석","MapleScript 프로젝트 최적화","기술적 구현 계획"],"es":["Investigación de código existente con search_file_content o read_","Creación de planes de acción jerárquicos para implementar requisitos de usuario","Compatibilidad con MapleScript","Análisis de requisitos de usuario y creación de planes de acción personalizados","Integración con herramientas de desarrollo como CLI"],"fr":["Recherche de code existant avec search_file_content ou read_","Création de plans d''action hiérarchiques pour mettre en œuvre les exigences utilisateur","Compatibilité avec MapleScript","Analyse des exigences utilisateur et création de plans d''action personnalisés","Intégration avec des outils de développement tels que CLI"],"de":["Untersuchung von bestehendem Code mit search_file_content oder read_","Erstellung hierarchischer Aktionspläne zur Umsetzung von Benutzeranforderungen","Kompatibilität mit MapleScript","Analyse von Benutzeranforderungen und Erstellung von individuellen Aktionsplänen","Integration mit Entwicklungstools wie CLI"],"pt":["Investigação no código existente","Criação de planos de ação hierárquicos","Uso de search_file_content ou read_ para investigação","Produção de plano de ação passo a passo","Integração com MapleScript"],"ru":["Расследование существующего кода","Создание иерархических планов действий","Использование search_file_content или read_ для расследования","Создание пошагового плана","Интеграция с MapleScript"],"ar":["التحقيقات في الكود الموجود","إنشاء خطط عمل هرمية","استخدام search_file_content أو read_ للتحقيق","إنشاء خطة عمل خطوة بخطوة","التكامل مع MapleScript"]},"keywords":{"en":["how to use task_planner","what is task_planner","task_planner alternative","task_planner vs strategic architect","task_planner install","task_planner setup guide","MapleScript task planner","codebase investigation tools","strategic architect for AI agents"],"zh":["任务规划器","MapleScript 项目优化","AI 工具","代码库调查","技术实现规划","search_file_content","read_","代码分析"],"ja":["タスクプランナー","MapleScript プロジェクト最適化","AI エージェント","コードベースの調査","技術的な実装計画","search_file_content","read_","コード分析"],"ko":["작업 계획자","MapleScript 프로젝트 최적화","AI 도구","코드베이스 조사","기술적 구현 계획","search_file_content","read_","코드 분석"],"es":["task_planner","MapleScript","arquitectos estratégicos","planificación de tareas","herramientas de inteligencia artificial","desarrollo de software","CLI","search_file_content","read_"],"fr":["task_planner","MapleScript","architectes stratégiques","planification de tâches","outils d''intelligence artificielle","développement de logiciels","CLI","search_file_content","read_"],"de":["task_planner","MapleScript","strategische Architekten","Aufgabenplanung","KI-Tools","Software-Entwicklung","CLI","search_file_content","read_"],"pt":["task_planner","planejador de tarefas","desenvolvedores","MapleScript","search_file_content","read_","investigação de código","planos de ação hierárquicos"],"ru":["ИИ Агенты","task_planner","планировщик задач","разработчики","MapleScript","search_file_content","read_","расследование кода","иерархические планы действий"],"ar":["وكلاء الذكاء الاصطناعي","task_planner","مخطط مهام","طورين","MapleScript","search_file_content","read_","التحقيق في الكود","خطط عمل هرمية"]}},"owner":"abc21086999","repo":"maple_script","repoPath":"abc21086999/maple_script","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.568Z","topics":[],"category":"community","skillMd":{"name":"task_planner","description":"A high-level orchestration skill that mandates a Research-First, Plan-Second, Approve-Third workflow, forcing the agent to investigate existing codebase utilities and present a detailed, hierarchical action list for user review before any code modifications are made.","bodyPreview":"# Strategic Architect & Task Planner for MapleScript\n\n## Objective\nYour sole purpose is to bridge the gap between user requirements and technical implementation. You must NEVER write implementation code immediately. Instead, you will perform deep research into the existing codebase and produce a hierarchical, step-by-step action plan for the user to review.\n\n## Workflow Requirements\n\n### 1. Codebase Investigation (Mandatory)\nBefore proposing any plan, you MUST use `search_file_content` or `read_","body":"# Strategic Architect & Task Planner for MapleScript\n\n## Objective\nYour sole purpose is to bridge the gap between user requirements and technical implementation. You must NEVER write implementation code immediately. Instead, you will perform deep research into the existing codebase and produce a hierarchical, step-by-step action plan for the user to review.\n\n## Workflow Requirements\n\n### 1. Codebase Investigation (Mandatory)\nBefore proposing any plan, you MUST use `search_file_content` or `read_file` to investigate the current project structure.\n- Locate relevant base classes (e.g., `src/MapleScript.py`).\n- Identify existing utility functions (e.g., in `src/utils/maple_vision.py` or `src/utils/xiao_controller.py`).\n- Ensure your plan aligns with established patterns (threading safety, logging, and settings management).\n\n### 2. Hierarchical Planning Structure\nYour output must follow a \"Grand Task > Sub-steps\" format:\n- **Major Milestone**: A high-level goal (e.g., \"Navigate to Boss Map\").\n  - **Detailed Action**: A specific, granular step (e.g., \"Press ''U'' key to open UI\").\n    - **Tool Reference**: Mention which existing function or file will be utilized for this step.\n\n### 3. Iterative Refinement\n- Present the plan clearly and wait for user feedback.\n- If the user requests a change to a specific step, update only that part of the plan and re-submit for approval.\n- Do not proceed to the \"Implementation Phase\" until the user explicitly says \"Approved\" or \"Proceed\".\n\n## Output Format Example\n\n### 🎯 Project Goal\n[Clear summary of what we are trying to achieve]\n\n### 🔍 Research & References\n- Confirmed `xiao_controller.py` supports the required input methods.\n- Identified `MapleGrind.py` as a reference for similar logic.\n\n### 📋 Hierarchical Action List\n1. **[Major Step 1]**\n   - 1.1 **[Sub-action A]**: Detailed description of what happens.\n     - *Technical Note: Uses `self.vision.find_image()`*\n   - 1.2 **[Sub-action B]**: ...\n2. **[Major Step 2]**\n   - ...\n\n### ⚠️ Assumptions\n- List any assumptions about the game state or user configuration.\n\n---\n**Please review this plan. You can request modifications for any specific step. Reply with \"Approved\" to begin implementation.**\n"},"lastSynced":"2026-03-08T02:11:43.169Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude Code and AutoGPT requiring strategic planning and technical implementation bridging.","zh":"适用于需要战略规划和技术实现桥接的AI代理，如Claude Code和AutoGPT","ja":"Claude CodeやAutoGPTのような戦略的計画と技術的実装のブリッジングを必要とするAIエージェントに最適","ko":"클라우드 코드 및 오토지피티와 같은 전략적 계획 및 기술적 구현 브리징을 필요한 AI 에이전트에게 적합","es":"Ideal para agentes de IA como Claude Code y AutoGPT que requieren planificación estratégica y implementación técnica de conexión.","fr":"Idéal pour les agents IA comme Claude Code et AutoGPT nécessitant une planification stratégique et une mise en œuvre technique de connexion.","de":"Ideal für KI-Agents wie Claude Code und AutoGPT, die strategische Planung und technische Implementierung zur Verbindung benötigen.","pt":"Ideal para agentes de IA como Claude Code e AutoGPT que requerem planejamento estratégico e implementação técnica de ponte.","ru":"Идеально подходит для агентов ИИ, таких как Claude Code и AutoGPT, требующих стратегического планирования и технической реализации моста.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Claude Code و AutoGPT الذين يحتاجون إلى التخطيط الاستراتيجي والتنفيذ الفني للجسر."},"recommendation":{"en":"Empowers agents to generate hierarchical, step-by-step action plans by performing deep research into existing codebases, utilizing protocols like `search_file_content` and `read_file`, and leveraging technical implementation details to bridge user requirements.","zh":"赋予代理生成分层、逐步操作计划的能力，通过对现有代码库进行深入研究，利用诸如`search_file_content`和`read_file`的协议，并利用技术实现细节来桥接用户需求","ja":"エージェントに階層的なステップバイステップのアクションプランを生成する能力を付与し、コードベースを深く調査し、`search_file_content`や`read_file`などのプロトコルを利用し、技術的実装の詳細を利用してユーザーの要件をブリッジングする","ko":"에이전트가 계층적이고 단계별로 액션 플랜을 생성할 수 있는 능력을 부여하여 기존 코드베이스를 심층적으로 조사하고 `search_file_content` 및 `read_file`와 같은 프로토콜을 활용하여 기술적 구현 세부 사항을 활용하여 사용자 요구 사항을 브리징","es":"Habilita a los agentes a generar planes de acción jerárquicos y paso a paso realizando una investigación profunda en las bases de código existentes, utilizando protocolos como `search_file_content` y `read_file`, y aprovechando los detalles de la implementación técnica para cubrir los requisitos del usuario.","fr":"Permet aux agents de générer des plans d''action hiérarchiques et étape par étape en effectuant une recherche approfondie dans les bases de code existantes, en utilisant des protocoles tels que `search_file_content` et `read_file`, et en exploitant les détails de la mise en œuvre technique pour répondre aux exigences de l''utilisateur.","de":"Ermöglicht es den Agents, hierarchische, schrittweise Aktionspläne zu generieren, indem sie eine tiefe Recherche in bestehenden Codebasen durchführen, Protokolle wie `search_file_content` und `read_file` nutzen und technische Implementierungsdetails ausnutzen, um die Benutzeranforderungen zu erfüllen.","pt":"Habilita os agentes a gerar planos de ação hierárquicos, passo a passo, realizando uma pesquisa profunda em codebases existentes, utilizando protocolos como `search_file_content` e `read_file`, e aproveitando detalhes de implementação técnica para atender aos requisitos do usuário.","ru":"Позволяет агентам генерировать иерархические, пошаговые планы действий, выполняя глубокое исследование существующих кодовых баз, используя протоколы, такие как `search_file_content` и `read_file`, и используя технические детали реализации для удовлетворения требований пользователя.","ar":"تمكين العميل من توليد خطط عمل هرمية خطوة بخطوة من خلال إجراء بحث عميق في قواعد الكود الموجودة، واستخدام بروتوكولات مثل `search_file_content` و `read_file` ، وتحقيق تفاصيل التنفيذ الفني لتلبية متطلبات المستخدم."},"useCases":{"en":["Automating task planning for complex projects","Generating step-by-step guides for users","Debugging existing codebases to identify implementation gaps"],"zh":["复杂项目的任务规划自动化","为用户生成逐步指南","调试现有代码库以确定实现差距"],"ja":["複雑なプロジェクトのタスクプランニングの自動化","ユーザー向けのステップバイステップガイドの生成","既存のコードベースのデバッグによる実装ギャップの特定"],"ko":["복잡한 프로젝트의 태스크 계획 자동화","사용자용 단계별 가이드 생성","기존 코드베이스 디버깅을 통한 구현 격차 식별"],"es":["Automatización de la planificación de tareas para proyectos complejos","Generación de guías paso a paso para los usuarios","Depuración de bases de código existentes para identificar brechas de implementación"],"fr":["Automatisation de la planification de tâches pour les projets complexes","Génération de guides étape par étape pour les utilisateurs","Débogage des bases de code existantes pour identifier les lacunes d''implémentation"],"de":["Automatisierung der Aufgabenplanung für komplexe Projekte","Generierung von Schritt-für-Schritt-Anleitungen für Benutzer","Fehlersuche in bestehenden Codebasen, um Implementierungslücken zu identifizieren"],"pt":["Automatizar o planejamento de tarefas para projetos complexos","Gerar guias passo a passo para os usuários","Depurar codebases existentes para identificar lacunas de implementação"],"ru":["Автоматизировать планирование задач для сложных проектов","Генерировать пошаговые руководства для пользователей","Отладить существующие кодовые базы, чтобы выявить пробелы в реализации"],"ar":["تحسين تخطيط المهام للمشاريع المعقدة","توليد دليلاً خطوة خطوة للمستخدمين","تصحيح الأعطال في قواعد الكود الموجودة للتعرف على فجوات التنفيذ"]},"limitations":{"en":["Requires access to existing codebases","Never writes implementation code immediately","Mandatory codebase investigation using specific protocols"],"zh":["需要访问现有代码库","不能立即编写实现代码","必须使用特定协议进行代码库调查"],"ja":["既存のコードベースへのアクセスが必要","実装コードをすぐに書き込むことはできない","特定のプロトコルを使用したコードベースの調査が必須"],"ko":["기존 코드베이스에 대한 액세스가 필요","구현 코드를 즉시 작성할 수 없음","특정 프로토콜을 사용한 코드베이스 조사 필수"],"es":["Requiere acceso a bases de código existentes","Nunca escribe el código de implementación inmediatamente","Investigación obligatoria de la base de código utilizando protocolos específicos"],"fr":["Nécessite un accès aux bases de code existantes","Ne rédige jamais le code d''implémentation immédiatement","Investigation obligatoire de la base de code en utilisant des protocoles spécifiques"],"de":["Erfordert Zugriff auf bestehende Codebasen","Schreibt niemals sofort den Implementierungscode","Verpflichtende Untersuchung der Codebasis unter Verwendung spezifischer Protokolle"],"pt":["Requer acesso a codebases existentes","Nunca escreve o código de implementação imediatamente","Investigação obrigatória da codebase usando protocolos específicos"],"ru":["Требует доступа к существующим кодовым базам","Никогда не пишет код реализации сразу","Обязательное расследование кодовой базы с использованием определенных протоколов"],"ar":["يتطلب الوصول إلى قواعد الكود الموجودة","أبدا لا يكتب رمز التنفيذ على الفور","تحقيق إجباري في قاعدة الكود باستخدام بروتوكولات محددة"]},"version":4},"contentHash":"a44305a305900f6e65984e6fce63be2e91d1d7d1433ac6408c00fbadfe860fab","qualityScore":47}');
