INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('abc21086999/maple_script/task_planner', 'task_planner', 'abc21086999', 'maple_script', 'community', 'task_planner abc21086999 maple_script community task_planner is a strategic architect that generates step-by-step action plans for users. It performs deep research into existing codebases to bridge the gap between user requirements and technical implementation. 任务规划器是一种 Strategic Architect，能够帮助用户将需求转化为技术实现。它通过对现有代码库的深入研究，产生一个分层的、逐步的行动计划 タスクプランナーは、ユーザーの要件を技術的な実装に変換するための戦略アーキテクトです。コードベースを深く調査し、階層的なステップバイステップのアクションプランを生成します 작업 계획자는 사용자의 요구를 기술적 구현으로 변환하는 전략 아키텍트입니다. 코드베이스를 깊이 조사하여 계층적인 단계별 작업 계획을 생성합니다 Task_planner es un skill que ayuda a los arquitectos estratégicos a crear planes de acción jerárquicos para implementar requisitos de usuario en MapleScript Task_planner est une compétence qui aide les architectes stratégiques à créer des plans d''action hiérarchiques pour mettre en œuvre les exigences utilisateur dans MapleScript Task_planner ist eine Fähigkeit, die strategische Architekten bei der Erstellung hierarchischer Aktionspläne zur Umsetzung von Benutzeranforderungen in MapleScript unterstützt O task_planner é um planejador de tarefas para desenvolvedores que ajuda a criar planos de ação hierárquicos. Ele realiza investigações no código existente para produzir um plano de ação passo a passo. ИИ Агенты task_planner - это планировщик задач для разработчиков, который помогает создавать иерархические планы действий. Он проводит расследование существующего кода для создания пошагового плана. وكلاء الذكاء الاصطناعي task_planner هو مخطط مهام للطورين يساعد على إنشاء خطط عمل هرمية. يقوم بالتحقيقات في الكود الموجود لإنشاء خطة عمل خطوة بخطوة. how to use task_planner what is task_planner task_planner alternative task_planner vs strategic architect task_planner install task_planner setup guide MapleScript task planner codebase investigation tools strategic architect for AI agents 任务规划器 MapleScript 项目优化 AI 工具 代码库调查 技术实现规划 search_file_content read_ 代码分析 Performs codebase investigation using search_file_content or read Generates hierarchical, step-by-step action plans for user review Utilizes deep research into existing codebases Produces plans without writing implementation code immediately Employs a mandatory codebase investigation workflow Leverages MapleScript for strategic architecture task_planner is a skill that produces hierarchical, step-by-step action plans for users to review, utilizing codebase investigation and research');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('magicappdev/magicappdev/building-ui', 'community', 'magicappdev', 'magicappdev', 'magicappdev/magicappdev', 'building-ui', 0, 0, 47, '2026-03-08T01:57:15.631Z', '2026-03-08T02:13:34.539Z', '6c480bb7eed58f573cb220652a3ca956a4c08eee8ee6ae0f717a1fe043c10efc', '{"id":"magicappdev/magicappdev/building-ui","name":"building-ui","description":{"en":"building-ui is a comprehensive platform for rapid development, customization, and deployment of apps across web and mobile platforms, utilizing Turborepo and Expo-inspired UI guidelines.","zh":"Building-UI是MagicAppDev的综合monorepo-based全栈应用构建平台，使用Turborepo进行高效的monorepo管理","ja":"Building-UIは、MagicAppDevの包括的なmonorepoベースのフルスタックアプリ開発プラットフォームで、Turborepoを使用して効率的なmonorepo管理を行う","ko":"Building-UI는 MagicAppDev의 포괄적인 모노레포 기반 풀스택 앱 빌딩 플랫폼으로 Turborepo를 사용하여 효율적인 모노레포 관리를 수행","es":"Building-ui es una plataforma de desarrollo de aplicaciones fullstack que utiliza Turborepo para una gestión de monorepo eficiente","fr":"Building-ui est une plateforme de développement d''applications fullstack qui utilise Turborepo pour une gestion de monorepo efficace","de":"Building-ui ist eine Fullstack-Anwendungs-Entwicklungsplattform, die Turborepo für eine effiziente Monorepo-Verwaltung verwendet","pt":"O building-ui é uma plataforma de desenvolvimento de aplicações fullstack que utiliza Turborepo para gerenciamento de monorepo eficiente. Permite desenvolver UI personalizadas para web e mobile.","ru":"Building-ui — это платформа для создания полнофункциональных приложений, использующая Turborepo для эффективного управления монорепозиторием. Позволяет разрабатывать индивидуальные интерфейсы для веба и мобильных устройств.","ar":"building-ui هو منصة لإنشاء تطبيقات كاملة تستخدم Turborepo لإدارة مونوريبوزيتوري فعالة. تمكن من إنشاء واجهات مستخدم مخصصة للويب والجوال"},"seo":{"title":{"en":"building-ui: Monorepo-Based Fullstack App Building Setup ...","zh":"Building-UI Setup Guide: 使用Turborepo和Expo构建全栈应用","ja":"Building-UI セットアップガイド: TurborepoとExpoによるフルスタックアプリ開発","ko":"Building-UI 설정 가이드: Turborepo와 Expo를 사용한 풀스택 앱 빌딩","es":"Guía de configuración de building-ui para desarrolladores","fr":"Guide de démarrage de building-ui pour les développeurs","de":"Einrichtungsleitfaden für building-ui-Entwickler","pt":"Guia de Configuração de building-ui: Desenvolvimento de U...","ru":"Настройка building-ui: Руководство по созданию UI с помощ...","ar":"دليل إعداد building-ui: بناء واجهة المستخدم مع Turborepo ..."},"description":{"en":"Discover how building-ui leverages Turborepo for efficient monorepo management and Expo-inspired UI guidelines to streamline app development - get started now!","zh":"使用MagicAppDev的Building-UI技能，快速构建和部署跨平台应用，利用Turborepo进行高效的monorepo管理","ja":"MagicAppDevのBuilding-UIスキルを使用して、Turborepoによる効率的なmonorepo管理で、クロスプラットフォームアプリを迅速に構築してデプロイ","ko":"MagicAppDev의 Building-UI 스킬을 사용하여 Turborepo를 통한 효율적인 모노레포 관리로 크로스 플랫폼 앱을 빠르게 빌드하고 배포","es":"Aprende a utilizar building-ui con Turborepo para desarrollar aplicaciones fullstack de manera eficiente","fr":"Découvrez comment utiliser building-ui avec Turborepo pour développer des applications fullstack de manière efficace","de":"Erfahren Sie, wie Sie building-ui mit Turborepo verwenden, um Fullstack-Anwendungen effizient zu entwickeln","pt":"Aprenda a configurar o building-ui para desenvolver aplicações fullstack com Turborepo e Expo. Desenvolva UI personalizadas para web e mobile.","ru":"Узнайте, как настроить building-ui для создания полнофункциональных приложений с помощью Turborepo и Expo. Разрабатывайте индивидуальные интерфейсы для веба ...","ar":"تعرف على كيفية إعداد building-ui لإنشاء تطبيقات كاملة مع Turborepo و Expo. قم بإنشاء واجهات مستخدم مخصصة للويب والجوال مع أدوات الذكاء الاصطناعي"},"definition":{"en":"building-ui is a monorepo-based fullstack app building platform that enables efficient development and deployment of apps across various platforms.","zh":"Building-UI是用于构建和部署跨平台应用的AI工具，使用Turborepo进行monorepo管理","ja":"Building-UIは、クロスプラットフォームアプリを構築してデプロイするためのAIエージェントで、Turborepoを使用してmonorepo管理を行う","ko":"Building-UI는 크로스 플랫폼 앱을 빌드하고 배포하기 위한 AI 도구로 Turborepo를 사용하여 모노레포 관리를 수행","es":"Building-ui es una herramienta de desarrollo de aplicaciones que permite la creación de interfaces de usuario personalizadas","fr":"Building-ui est un outil de développement d''applications qui permet la création d''interfaces utilisateur personnalisées","de":"Building-ui ist ein Entwicklungstool für Anwendungen, das die Erstellung von benutzerdefinierten Benutzeroberflächen ermöglicht","pt":"O building-ui é uma plataforma de desenvolvimento de UI que utiliza Turborepo e Expo para criar aplicações fullstack personalizadas.","ru":"Building-ui — это платформа для создания интерфейсов, использующая Turborepo и Expo для разработки индивидуальных полнофункциональных приложений.","ar":"building-ui هو منصة لإنشاء واجهات مستخدم تستخدم Turborepo و Expo لإنشاء تطبيقات كاملة مخصصة"},"features":{"en":["Utilizes Turborepo for efficient monorepo management","Follows Expo UI guidelines for consistent app design","Supports dynamic routes, query parameters, and folder organization via route-structure.md","Enables native tab bar with NativeTabs and migration from JS tabs","Provides SF Symbols with expo-symbols for icon customization"],"zh":["使用Turborepo进行高效的monorepo管理","支持Expo UI Guidelines","提供Route file conventions和dynamic routes","支持Native iOS controls，如Switch、Slider和SegmentedControl","提供SF Symbols和expo-symbols集成","支持Native tab bar和NativeTabs"],"ja":["Turborepoを使用した効率的なmonorepo管理","Expo UI Guidelinesをサポート","Route file conventionsとdynamic routesを提供","Native iOS controls zoals Switch、SliderとSegmentedControlをサポート","SF Symbolsとexpo-symbolsの統合を提供","Native tab barとNativeTabsをサポート"],"ko":["Turborepo를 사용한 효율적인 모노레포 관리","Expo UI 가이드라인 지원","Route 파일 규칙 및 동적 라우트 제공","네이티브 iOS 컨트롤 지원(스위치, 슬라이더, 세그먼트 컨트롤 등)","SF 심볼과 expo-symbols 통합 제공","네이티브 탭 바와 네이티브 탭 지원"],"es":["Utiliza Turborepo para la gestión de monorepo","Soporte para Expo UI Guidelines","Route file conventions y dynamic routes","Native tab bar con NativeTabs","Soporte para SF Symbols con expo-symbols"],"fr":["Utilise Turborepo pour la gestion de monorepo","Prise en charge des directives de conception Expo UI","Conventions de fichiers de route et routes dynamiques","Barre de tabs native avec NativeTabs","Prise en charge des symboles SF avec expo-symbols"],"de":["Verwaltet Monorepos mit Turborepo","Unterstützung für Expo-UI-Richtlinien","Route-Dateikonventionen und dynamische Routen","Native Tab-Leiste mit NativeTabs","Unterstützung für SF-Symbole mit expo-symbols"],"pt":["Utiliza Turborepo para gerenciamento de monorepo eficiente","Desenvolvimento de UI personalizadas para web e mobile com Expo","Suporte a SF Symbols com expo-symbols","Controles nativos para iOS, incluindo Switch, Slider e SegmentedControl","Suporte a rotas dinâmicas e parâmetros de consulta"],"ru":["Использует Turborepo для эффективного управления монорепозиторием","Разработка индивидуальных интерфейсов для веба и мобильных устройств с помощью Expo","Поддержка SF Symbols с expo-symbols","Нативные контролы для iOS, включая Switch, Slider и SegmentedControl","Поддержка динамических маршрутов и параметров запроса"],"ar":["استخدام Turborepo لإدارة مونوريبوزيتوري فعالة","إنشاء واجهات مستخدم مخصصة للويب والجوال مع Expo","دعم SF Symbols مع expo-symbols","التحكمات الأصلية لنظام iOS، بما في ذلك Switch و Slider و SegmentedControl","دعم الطرق الديناميكية وparameters الاستعلام"]},"keywords":{"en":["how to use building-ui","building-ui alternative","building-ui vs Expo","building-ui install","building-ui setup guide","what is building-ui","Turborepo monorepo management","Expo-inspired UI guidelines","fullstack app development"],"zh":["Building-UI","Turborepo","Expo","monorepo管理","跨平台应用","AI工具","MagicAppDev","全栈应用构建","Expo UI Guidelines","Route file conventions"],"ja":["Building-UI","Turborepo","Expo","monorepo管理","クロスプラットフォームアプリ","AIエージェント","MagicAppDev","フルスタックアプリ開発","Expo UI Guidelines","Route file conventions"],"ko":["Building-UI","Turborepo","Expo","모노레포 관리","크로스 플랫폼 앱","AI 도구","MagicAppDev","풀스택 앱 빌딩","Expo UI 가이드라인","Route 파일 규칙"],"es":["building-ui","Turborepo","Expo UI Guidelines","desarrollo de aplicaciones fullstack","monorepo","interfaces de usuario personalizadas","herramientas de desarrollo de aplicaciones"],"fr":["building-ui","Turborepo","directives de conception Expo UI","développement d''applications fullstack","monorepo","interfaces utilisateur personnalisées","outils de développement d''applications"],"de":["building-ui","Turborepo","Expo-UI-Richtlinien","Fullstack-Anwendungs-Entwicklung","Monorepo","benutzerdefinierte Benutzeroberflächen","Entwicklungstools für Anwendungen"],"pt":["building-ui","Turborepo","Expo","desenvolvimento de UI","aplicações fullstack","SF Symbols","controles nativos para iOS","rotas dinâmicas","parâmetros de consulta"],"ru":["building-ui","Turborepo","Expo","создание интерфейсов","полнофункциональные приложения","SF Symbols","нативные контролы для iOS","динамические маршруты","параметры запроса","ИИ Агенты"],"ar":["building-ui","Turborepo","Expo","إنشاء واجهات مستخدم","تطبيقات كاملة","SF Symbols","التحكمات الأصلية لنظام iOS","الطرق الديناميكية","parameters الاستعلام","أدوات الذكاء الاصطناعي"]}},"owner":"magicappdev","repo":"magicappdev","repoPath":"magicappdev/magicappdev","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.631Z","topics":[],"category":"community","skillMd":{"name":"building-ui","description":"Complete guide for building beautiful apps with Expo Router. Covers fundamentals, styling, components, navigation, animations, patterns, and native tabs.","version":"1.0.0","bodyPreview":"# Expo UI Guidelines\n\n## References\n\nConsult these resources as needed:\n\n- ./references/route-structure.md -- Route file conventions, dynamic routes, query parameters, groups, and folder organization\n- ./references/tabs.md -- Native tab bar with NativeTabs, migration from JS tabs, iOS 26 features\n- ./references/icons.md -- SF Symbols with expo-symbols, common icon names, animations, and weights\n- ./references/controls.md -- Native iOS controls: Switch, Slider, SegmentedControl, DateTimePicker, P","body":"# Expo UI Guidelines\n\n## References\n\nConsult these resources as needed:\n\n- ./references/route-structure.md -- Route file conventions, dynamic routes, query parameters, groups, and folder organization\n- ./references/tabs.md -- Native tab bar with NativeTabs, migration from JS tabs, iOS 26 features\n- ./references/icons.md -- SF Symbols with expo-symbols, common icon names, animations, and weights\n- ./references/controls.md -- Native iOS controls: Switch, Slider, SegmentedControl, DateTimePicker, Picker\n- ./references/visual-effects.md -- Blur effects with expo-blur and liquid glass with expo-glass-effect\n- ./references/animations.md -- Reanimated animations: entering, exiting, layout, scroll-driven, and gestures\n- ./references/search.md -- Search bar integration with headers, useSearch hook, and filtering patterns\n- ./references/gradients.md -- CSS gradients using experimental_backgroundImage (New Architecture only)\n- ./references/media.md -- Media handling for Expo Router including camera, audio, video, and file saving\n- ./references/storage.md -- Data storage patterns including SQLite, AsyncStorage, and SecureStore\n- ./references/webgpu-three.md -- 3D graphics, games, and GPU-powered visualizations with WebGPU and Three.js\n\n## Running the App\n\n**CRITICAL: Always try Expo Go first before creating custom builds.**\n\nMost Expo apps work in Expo Go without any custom native code. Before running `npx expo run:ios` or `npx expo run:android`:\n\n1. **Start with Expo Go**: Run `npx expo start` and scan the QR code with Expo Go\n2. **Check if features work**: Test your app thoroughly in Expo Go\n3. **Only create custom builds when required** - see below\n\n### When Custom Builds Are Required\n\nYou need `npx expo run:ios/android` or `eas build` ONLY when using:\n\n- **Local Expo modules** (custom native code in `modules/`)\n- **Apple targets** (widgets, app clips, extensions via `@bacons/apple-targets`)\n- **Third-party native modules** not included in Expo Go\n- **Custom native configuration** that can''t be expressed in `app.json`\n\n### When Expo Go Works\n\nExpo Go supports a huge range of features out of the box:\n\n- All `expo-*` packages (camera, location, notifications, etc.)\n- Expo Router navigation\n- Most UI libraries (reanimated, gesture handler, etc.)\n- Push notifications, deep links, and more\n\n**If you''re unsure, try Expo Go first.** Creating custom builds adds complexity, slower iteration, and requires Xcode/Android Studio setup.\n\n## Code Style\n\n- Be cautious of unterminated strings. Ensure nested backticks are escaped; never forget to escape quotes correctly.\n- Always use import statements at the top of the file.\n- Always use kebab-case for file names, e.g. `comment-card.tsx`\n- Always remove old route files when moving or restructuring navigation\n- Never use special characters in file names\n- Configure tsconfig.json with path aliases, and prefer aliases over relative imports for refactors.\n\n## Routes\n\nSee `./references/route-structure.md` for detailed route conventions.\n\n- Routes belong in the `app` directory.\n- Never co-locate components, types, or utilities in the app directory. This is an anti-pattern.\n- Ensure the app always has a route that matches \"/\", it may be inside a group route.\n\n## Library Preferences\n\n- Never use modules removed from React Native such as Picker, WebView, SafeAreaView, or AsyncStorage\n- Never use legacy expo-permissions\n- `expo-audio` not `expo-av`\n- `expo-video` not `expo-av`\n- `expo-symbols` not `@expo/vector-icons`\n- `react-native-safe-area-context` not react-native SafeAreaView\n- `process.env.EXPO_OS` not `Platform.OS`\n- `React.use` not `React.useContext`\n- `expo-image` Image component instead of intrinsic element `img`\n- `expo-glass-effect` for liquid glass backdrops\n\n## Responsiveness\n\n- Always wrap root component in a scroll view for responsiveness\n- Use `<ScrollView contentInsetAdjustmentBehavior=\"automatic\" />` instead of `<SafeAreaView>` for smarter safe area insets\n- `contentInsetAdjustmentBehavior=\"automatic\"` should be applied to FlatList and SectionList as well\n- Use flexbox instead of Dimensions API\n- ALWAYS prefer `useWindowDimensions` over `Dimensions.get()` to measure screen size\n\n## Behavior\n\n- Use expo-haptics conditionally on iOS to make more delightful experiences\n- Use views with built-in haptics like `<Switch />` from React Native and `@react-native-community/datetimepicker`\n- When a route belongs to a Stack, its first child should almost always be a ScrollView with `contentInsetAdjustmentBehavior=\"automatic\"` set\n- Prefer `headerSearchBarOptions` in Stack.Screen options to add a search bar\n- Use the `<Text selectable />` prop on text containing data that could be copied\n- Consider formatting large numbers like 1.4M or 38k\n- Never use intrinsic elements like ''img'' or ''div'' unless in a webview or Expo DOM component\n\n# Styling\n\nFollow Apple Human Interface Guidelines.\n\n## General Styling Rules\n\n- Prefer flex gap over margin and padding styles\n- Prefer padding over margin where possible\n- Always account for safe area, either with stack headers, tabs, or ScrollView/FlatList `contentInsetAdjustmentBehavior=\"automatic\"`\n- Ensure both top and bottom safe area insets are accounted for\n- Inline styles not StyleSheet.create unless reusing styles is faster\n- Add entering and exiting animations for state changes\n- Use `{ borderCurve: ''continuous'' }` for rounded corners unless creating a capsule shape\n- ALWAYS use a navigation stack title instead of a custom text element on the page\n- When padding a ScrollView, use `contentContainerStyle` padding and gap instead of padding on the ScrollView itself (reduces clipping)\n- CSS and Tailwind are not supported - use inline styles\n\n## Text Styling\n\n- Add the `selectable` prop to every `<Text/>` element displaying important data or error messages\n- Counters should use `{ fontVariant: ''tabular-nums'' }` for alignment\n\n## Shadows\n\nUse CSS `boxShadow` style prop. NEVER use legacy React Native shadow or elevation styles.\n\n```tsx\n<View style={{ boxShadow: \"0 1px 2px rgba(0, 0, 0, 0.05)\" }} />\n```\n\n''inset'' shadows are supported.\n\n# Navigation\n\n## Link\n\nUse `<Link href=\"/path\" />` from ''expo-router'' for navigation between routes.\n\n```tsx\nimport { Link } from ''expo-router'';\n\n// Basic link\n<Link href=\"/path\" />\n\n// Wrapping custom components\n<Link href=\"/path\" asChild>\n  <Pressable>...</Pressable>\n</Link>\n```\n\nWhenever possible, include a `<Link.Preview>` to follow iOS conventions. Add context menus and previews frequently to enhance navigation.\n\n## Stack\n\n- ALWAYS use `_layout.tsx` files to define stacks\n- Use Stack from ''expo-router/stack'' for native navigation stacks\n\n### Page Title\n\nSet the page title in Stack.Screen options:\n\n```tsx\n<Stack.Screen options={{ title: \"Home\" }} />\n```\n\n## Context Menus\n\nAdd long press context menus to Link components:\n\n```tsx\nimport { Link } from \"expo-router\";\n\n<Link href=\"/settings\" asChild>\n  <Link.Trigger>\n    <Pressable>\n      <Card />\n    </Pressable>\n  </Link.Trigger>\n  <Link.Menu>\n    <Link.MenuAction\n      title=\"Share\"\n      icon=\"square.and.arrow.up\"\n      onPress={handleSharePress}\n    />\n    <Link.MenuAction\n      title=\"Block\"\n      icon=\"nosign\"\n      destructive\n      onPress={handleBlockPress}\n    />\n    <Link.Menu title=\"More\" icon=\"ellipsis\">\n      <Link.MenuAction title=\"Copy\" icon=\"doc.on.doc\" onPress={() => {}} />\n      <Link.MenuAction\n        title=\"Delete\"\n        icon=\"trash\"\n        destructive\n        onPress={() => {}}\n      />\n    </Link.Menu>\n  </Link.Menu>\n</Link>;\n```\n\n## Link Previews\n\nUse link previews frequently to enhance navigation:\n\n```tsx\n<Link href=\"/settings\">\n  <Link.Trigger>\n    <Pressable>\n      <Card />\n    </Pressable>\n  </Link.Trigger>\n  <Link.Preview />\n</Link>\n```\n\nLink preview can be used with context menus.\n\n## Modal\n\nPresent a screen as a modal:\n\n```tsx\n<Stack.Screen name=\"modal\" options={{ presentation: \"modal\" }} />\n```\n\nPrefer this to building a custom modal component.\n\n## Sheet\n\nPresent a screen as a dynamic form sheet:\n\n```tsx\n<Stack.Screen\n  name=\"sheet\"\n  options={{\n    presentation: \"formSheet\",\n    sheetGrabberVisible: true,\n    sheetAllowedDetents: [0.5, 1.0],\n    contentStyle: { backgroundColor: \"transparent\" },\n  }}\n/>\n```\n\n- Using `contentStyle: { backgroundColor: \"transparent\" }` makes the background liquid glass on iOS 26+.\n\n## Common route structure\n\nA standard app layout with tabs and stacks inside each tab:\n\n```\napp/\n  _layout.tsx — <NativeTabs />\n  (index,search)/\n    _layout.tsx — <Stack />\n    index.tsx — Main list\n    search.tsx — Search view\n```\n\n```tsx\n// app/_layout.tsx\nimport { NativeTabs, Icon, Label } from \"expo-router/unstable-native-tabs\";\nimport { Theme } from \"../components/theme\";\n\nexport default function Layout() {\n  return (\n    <Theme>\n      <NativeTabs>\n        <NativeTabs.Trigger name=\"(index)\">\n          <Icon sf=\"list.dash\" />\n          <Label>Items</Label>\n        </NativeTabs.Trigger>\n        <NativeTabs.Trigger name=\"(search)\" role=\"search\" />\n      </NativeTabs>\n    </Theme>\n  );\n}\n```\n\nCreate a shared group route so both tabs can push common screens:\n\n```tsx\n// app/(index,search)/_layout.tsx\nimport { PlatformColor } from \"react-native\";\nimport { Stack } from \"expo-router/stack\";\n\nexport default function Layout({ segment }) {\n  const screen = segment.match(/\\((.*)\\)/)?.[1]!;\n  const titles: Record<string, string> = { index: \"Items\", search: \"Search\" };\n\n  return (\n    <Stack\n      screenOptions={{\n        headerTransparent: true,\n        headerShadowVisible: false,\n        headerLargeTitleShadowVisible: false,\n        headerLargeStyle: { backgroundColor: \"transparent\" },\n        headerTitleStyle: { color: PlatformColor(\"label\") },\n        headerLargeTitle: true,\n        headerBlurEffect: \"none\",\n        headerBackButtonDisplayMode: \"minimal\",\n      }}\n    >\n      <Stack.Screen name={screen} options={{ title: titles[screen] }} />\n      <Stack.Screen name=\"i/[id]\" options={{ headerLargeTitle: false }} />\n    </Stack>\n  );\n}\n```\n"},"lastSynced":"2026-03-08T02:13:34.539Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing rapid development and customization of cross-platform apps using Turborepo and Expo-inspired UI guidelines.","zh":"非常适合需要快速开发和定制跨平台应用的前端代理，使用Turborepo和Expo启发的UI指南。","ja":"フロントエンドエージェントがクロスプラットフォームアプリを迅速に開発およびカスタマイズする必要がある場合に最適です。TurborepoとExpoに触発されたUIガイドラインを使用します。","ko":"프론트엔드 에이전트가 터보레포와 엑スポ启发의 UI 가이드라인을 사용하여 크로스 플랫폼 앱을 빠르게 개발하고 사용자 정의하는 데 적합합니다.","es":"Perfecto para agentes Frontend que necesitan un desarrollo y personalización rápidos de aplicaciones de varias plataformas utilizando Turborepo y pautas de interfaz de usuario inspiradas en Expo.","fr":"Parfait pour les agents Frontend qui ont besoin d''un développement et de personnalisation rapides d''applications multi-plateformes en utilisant Turborepo et des directives d''interface utilisateur inspirées par Expo.","de":"Perfekt für Frontend-Agents, die eine schnelle Entwicklung und Anpassung von Cross-Platform-Anwendungen mit Turborepo und Expo-inspirierten Benutzeroberflächenrichtlinien benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de desenvolvimento e personalização rápidos de aplicativos cross-plataforma usando Turborepo e diretrizes de UI inspiradas no Expo.","ru":"Идеально подходит для агентов Frontend, которым необходим быстрое развитие и настройка кроссплатформенных приложений с использованием Turborepo и руководств по UI, вдохновленных Expo.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى تطوير وتخصيص سريع لتطبيقات متعددة المنصات باستخدام Turborepo وإرشادات واجهة المستخدم التي تحملها Expo."},"recommendation":{"en":"Empowers agents to build and deploy apps across web and mobile platforms, leveraging Expo UI guidelines, NativeTabs, and SF Symbols with expo-symbols, while utilizing Turborepo for efficient development.","zh":"赋予代理构建和部署跨网络和移动平台的应用能力，利用Expo UI指南、NativeTabs和SF Symbols与expo-symbols，同时利用Turborepo进行高效开发。","ja":"エージェントがExpo UIガイドライン、NativeTabs、およびSF Symbolsとexpo-symbolsを使用して、Webおよびモバイルプラットフォームのアプリを構築およびデプロイする能力を提供し、Turborepoを使用して効率的な開発を行います。","ko":"에이전트가 엑スポ UI 가이드라인, 네이티브 탭, SF 심볼 및 엑スポ 심볼을 사용하여 웹 및 모바일 플랫폼의 애플리케이션을 구축 및 배포할 수 있는 기능을 제공하며, 터보레포를 사용하여 효율적인 개발을 수행합니다.","es":"Permite a los agentes crear y implementar aplicaciones en plataformas web y móviles, aprovechando las pautas de interfaz de usuario de Expo, NativeTabs y SF Symbols con expo-symbols, mientras utiliza Turborepo para un desarrollo eficiente.","fr":"Permet aux agents de créer et de déployer des applications sur les plateformes web et mobile, en exploitant les directives d''interface utilisateur d''Expo, NativeTabs et SF Symbols avec expo-symbols, tout en utilisant Turborepo pour un développement efficient.","de":"Ermöglicht es Agenten, Anwendungen über Web- und Mobilplattformen hinweg zu erstellen und bereitzustellen, indem es die Benutzeroberflächenrichtlinien von Expo, NativeTabs und SF Symbols mit expo-symbols nutzt, während Turborepo für eine effiziente Entwicklung verwendet wird.","pt":"Habilita os agentes a construir e implantar aplicativos em plataformas web e móvel, aproveitando as diretrizes de UI do Expo, NativeTabs e SF Symbols com expo-symbols, ao mesmo tempo em que utiliza o Turborepo para desenvolvimento eficiente.","ru":"Наделяет агентов возможностью создавать и развертывать приложения на веб- и мобильных платформах, используя руководства по UI от Expo, NativeTabs и SF Symbols с expo-symbols, а также используя Turborepo для эффективного развития.","ar":"يمنح الوكلاء القدرة على بناء وتوزيع تطبيقات عبر منصات الويب والأجهزة المحمولة، مستفيدًا من إرشادات واجهة المستخدم في Expo و NativeTabs و SF Symbols مع expo-symbols، مع استخدام Turborepo من أجل التطوير الفعال."},"useCases":{"en":["Customizing native iOS controls such as Switch, Slider, and SegmentedControl","Implementing dynamic routes and query parameters using route file conventions","Designing intuitive tab bars with NativeTabs and migrating from JS tabs"],"zh":["自定义原生iOS控件，如Switch、Slider和SegmentedControl","使用路由文件约定实现动态路由和查询参数","使用NativeTabs设计直观的标签栏，并从JS标签迁移"],"ja":["ネイティブiOSコントロール（Switch、Slider、SegmentedControlなど）をカスタマイズする","ルートファイル規約を使用して動的ルーティングとクエリパラメータを実装する","ネイティブタブを使用して直感的なタブバーを設計し、JSタブから移行する"],"ko":["네이티브 iOS 컨트롤(스위치, 슬라이더, 세그먼트 컨트롤 등)을 사용자 정의합니다.","라우팅 파일 규칙을 사용하여 동적 라우팅 및 쿼리 파라미터를 구현합니다.","네이티브 탭을 사용하여直관적인 탭 바를 설계하고, JS 탭에서 마이그레이션합니다."],"es":["Personalizar controles nativos de iOS como Switch, Slider y SegmentedControl","Implementar rutas dinámicas y parámetros de consulta utilizando convenciones de archivos de rutas","Diseñar barras de pestañas intuitivas con NativeTabs y migrar desde JS tabs"],"fr":["Personnaliser les contrôles natifs iOS tels que Switch, Slider et SegmentedControl","Mettre en œuvre des routes dynamiques et des paramètres de requête en utilisant les conventions de fichiers de routes","Concevoir des barres d''onglets intuitives avec NativeTabs et migrer depuis les onglets JS"],"de":["Native iOS-Steuerungselemente wie Switch, Slider und SegmentedControl anpassen","Dynamische Routen und Abfrageparameter mithilfe von Routendateikonventionen implementieren","Intuitive Registerkarten mit NativeTabs entwerfen und von JS-Registerkarten migrieren"],"pt":["Personalizar controles nativos do iOS, como Switch, Slider e SegmentedControl","Implementar rotas dinâmicas e parâmetros de consulta usando convenções de arquivos de rota","Projetar barras de guias intuitivas com NativeTabs e migrar de guias JS"],"ru":["Настроить родные элементы управления iOS, такие как Switch, Slider и SegmentedControl","Реализовать динамические маршруты и параметры запроса с использованием соглашений о файлах маршрутов","Разработать интуитивно понятные панели вкладок с помощью NativeTabs и перенести с вкладок JS"],"ar":["تخصيص عناصر التحكم الأصلية في iOS مثل Switch و Slider و SegmentedControl","تنفيذ مسارات ديناميكية ومعلمات استعلام باستخدام اتفاقيات ملفات المسار","تصميم شريط تبويب直觉 مع NativeTabs والهجرة من علامات JS"]},"limitations":{"en":["Requires knowledge of Expo UI guidelines and Turborepo","Limited to web and mobile platforms","Dependent on Expo-inspired UI guidelines and NativeTabs"],"zh":["需要了解Expo UI指南和Turborepo","仅限于网络和移动平台","依赖于Expo启发的UI指南和NativeTabs"],"ja":["Expo UIガイドラインとTurborepoの知識が必要","Webおよびモバイルプラットフォームに限定される","Expoに触発されたUIガイドラインとネイティブタブに依存する"],"ko":["엑スポ UI 가이드라인 및 터보레포에 대한 지식이 필요합니다.","웹 및 모바일 플랫폼으로 제한됩니다.","엑スポ启发의 UI 가이드라인 및 네이티브 탭에 의존합니다."],"es":["Requiere conocimiento de las pautas de interfaz de usuario de Expo y Turborepo","Limitado a plataformas web y móviles","Dependiente de las pautas de interfaz de usuario inspiradas en Expo y NativeTabs"],"fr":["Nécessite une connaissance des directives d''interface utilisateur d''Expo et de Turborepo","Limité aux plateformes web et mobile","Dépendant des directives d''interface utilisateur inspirées par Expo et NativeTabs"],"de":["Benötigt Kenntnisse der Benutzeroberflächenrichtlinien von Expo und Turborepo","Begrenzt auf Web- und Mobilplattformen","Abhängig von den Benutzeroberflächenrichtlinien, die von Expo und NativeTabs inspiriert sind"],"pt":["Exige conhecimento das diretrizes de UI do Expo e Turborepo","Limitado a plataformas web e móvel","Dependente das diretrizes de UI inspiradas no Expo e NativeTabs"],"ru":["Требует знания руководств по UI от Expo и Turborepo","Ограничен веб- и мобильными платформами","Зависит от руководств по UI, вдохновленных Expo, и NativeTabs"],"ar":["يتطلب معرفة إرشادات واجهة المستخدم في Expo و Turborepo","محدود بالمنصات على الويب والأجهزة المحمولة","يعتمد على إرشادات واجهة المستخدم التي تحملها Expo و NativeTabs"]},"version":4},"contentHash":"6c480bb7eed58f573cb220652a3ca956a4c08eee8ee6ae0f717a1fe043c10efc","qualityScore":47}');
