INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('magicappdev/magicappdev/building-ui', 'building-ui', 'magicappdev', 'magicappdev', 'community', 'building-ui magicappdev magicappdev community building-ui is a comprehensive platform for rapid development, customization, and deployment of apps across web and mobile platforms, utilizing Turborepo and Expo-inspired UI guidelines. Building-UI是MagicAppDev的综合monorepo-based全栈应用构建平台，使用Turborepo进行高效的monorepo管理 Building-UIは、MagicAppDevの包括的なmonorepoベースのフルスタックアプリ開発プラットフォームで、Turborepoを使用して効率的なmonorepo管理を行う Building-UI는 MagicAppDev의 포괄적인 모노레포 기반 풀스택 앱 빌딩 플랫폼으로 Turborepo를 사용하여 효율적인 모노레포 관리를 수행 Building-ui es una plataforma de desarrollo de aplicaciones fullstack que utiliza Turborepo para una gestión de monorepo eficiente Building-ui est une plateforme de développement d''applications fullstack qui utilise Turborepo pour une gestion de monorepo efficace Building-ui ist eine Fullstack-Anwendungs-Entwicklungsplattform, die Turborepo für eine effiziente Monorepo-Verwaltung verwendet O building-ui é uma plataforma de desenvolvimento de aplicações fullstack que utiliza Turborepo para gerenciamento de monorepo eficiente. Permite desenvolver UI personalizadas para web e mobile. Building-ui — это платформа для создания полнофункциональных приложений, использующая Turborepo для эффективного управления монорепозиторием. Позволяет разрабатывать индивидуальные интерфейсы для веба и мобильных устройств. building-ui هو منصة لإنشاء تطبيقات كاملة تستخدم Turborepo لإدارة مونوريبوزيتوري فعالة. تمكن من إنشاء واجهات مستخدم مخصصة للويب والجوال how to use building-ui building-ui alternative building-ui vs Expo building-ui install building-ui setup guide what is building-ui Turborepo monorepo management Expo-inspired UI guidelines fullstack app development Building-UI Turborepo Expo monorepo管理 跨平台应用 AI工具 MagicAppDev 全栈应用构建 Expo UI Guidelines Route file conventions Utilizes Turborepo for efficient monorepo management Follows Expo UI guidelines for consistent app design Supports dynamic routes, query parameters, and folder organization via route-structure.md Enables native tab bar with NativeTabs and migration from JS tabs Provides SF Symbols with expo-symbols for icon customization building-ui is a monorepo-based fullstack app building platform that enables efficient development and deployment of apps across various platforms.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ronnycoding/my-personal-assistant/scan-inbox', 'community', 'ronnycoding', 'my-personal-assistant', 'ronnycoding/my-personal-assistant', 'scan-inbox', 0, 0, 47, '2026-03-08T01:57:15.642Z', '2026-03-08T02:13:42.418Z', '8e8fd8774abcb67765faf3309c0a8839dc25867b41fe74125e816f8152729f36', '{"id":"ronnycoding/my-personal-assistant/scan-inbox","name":"scan-inbox","description":{"en":"The scan-inbox skill analyzes Apple Mail inboxes to identify unread and priority messages. It benefits macOS users seeking to automate their email management.","zh":"scan-inbox 技能分析 Apple Mail 收件箱，识别未读、可执行和优先消息，支持 Claude Code 和 Gemini CLI","ja":"scan-inbox スキルは Apple Mail の受信トレイを分析し、未読の可実行および優先メッセージを識別し、Claude Code と Gemini CLI をサポートします","ko":"scan-inbox 기능은 Apple Mail 받은 편지함을 분석하여 읽지 않은 실행 가능한 메시지와 우선 순위 메시지를 식별하며 Claude Code와 Gemini CLI를 지원합니다","es":"El agente de inteligencia artificial scan-inbox analiza tu bandeja de entrada de Apple Mail para identificar mensajes no leídos y urgentes. Utiliza Claude Code y Gemini CLI para automatizar flujos de trabajo personalizados en macOS","fr":"L''agent d''intelligence artificielle scan-inbox analyse votre boîte de réception Apple Mail pour identifier les messages non lus et urgents. Il utilise Claude Code et Gemini CLI pour automatiser des flux de travail personnalisés sur macOS","de":"Der KI-Agent scan-inbox analysiert Ihr Apple Mail-Postfach, um ungelesene und dringende Nachrichten zu identifizieren. Er verwendet Claude Code und Gemini CLI, um benutzerdefinierte Workflows auf macOS zu automatisieren","pt":"O Scan-Inbox é uma ferramenta de AI que analisa a caixa de entrada do Apple Mail para identificar mensagens não lidas, ações e prioridades dentro de um intervalo de tempo específico.","ru":"Scan-Inbox - это инструмент ИИ, который анализирует входящие сообщения в Apple Mail, чтобы выявит