INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('KignLeon/joesmith-website/monorepo-architect', 'monorepo-architect', 'KignLeon', 'joesmith-website', 'community', 'monorepo-architect KignLeon joesmith-website community The monorepo-architect skill provides expertise in monorepo architecture, build systems, and dependency management at scale, benefiting development teams. It masters tools like Nx, Turborepo, Bazel, and Lerna. Monorepo架构专家提供Nx、Turborepo和Lerna的设置和优化服务，提升多项目开发效率 モノレポアーキテクトは、Nx、Turborepo、Bazelを使用した多プロジェクト開発の効率化を支援 모노레포 아키텍트는 Nx, Turborepo, Bazel을 사용하여 다중 프로젝트 개발을 효율화합니다 El monorepo-architect es un experto en arquitectura de monorepo, sistemas de compilación y gestión de dependencias a gran escala Le monorepo-architect est un expert en architecture de monorepo, systèmes de build et gestion de dépendances à grande échelle Der Monorepo-Architekt ist ein Experte für Monorepo-Architektur, Build-Systeme und Abhängigkeitsverwaltung im großen Maßstab O monorepo-architect é um especialista em arquitetura de monorepo, sistemas de compilação e gerenciamento de dependências em escala ИИ Агент монорепозитория - эксперт в области архитектуры монорепозитория, систем сборки и управления зависимостями в масштабе مونوريبوزيتوري أركيتكت هو خبير في مجال هندسة مونوريبوزيتوري و أنظمة البناء و إدارة التبعيات على نطاق واسع how to use monorepo-architect monorepo-architect setup guide monorepo-architect vs Lerna monorepo-architect install what is monorepo-architect monorepo-architect alternative to Bazel monorepo-architect and Turborepo monorepo-architect for AI agents monorepo-architect expert monorepo-architect tutorial monorepo架构 Nx Turborepo Lerna 多项目开发 依赖管理 构建系统 大规模开发 monorepo设置 monorepo优化 Masters Nx for efficient multi-project development Utilizes Turborepo for optimized build systems Leverages Bazel for scalable dependency management Supports Lerna for streamlined monorepo setup Optimizes build workflows across teams using PROACTIVELY Provides expertise in monorepo architecture at scale monorepo-architect is an expert in designing and implementing monorepo architectures, leveraging tools like Nx, Turborepo, Bazel, and Lerna for efficient development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('runkids/skillshare/skillshare', 'community', 'runkids', 'skillshare', 'runkids/skillshare', 'skillshare', 0, 0, 47, '2026-03-08T01:57:15.654Z', '2026-03-08T02:13:54.921Z', 'd77e6210916d1f408a6fa4bb472b97f5f5b3738861514148d103b2445fd3b163', '{"id":"runkids/skillshare/skillshare","name":"skillshare","description":{"en":"Skillshare syncs skills across all AI CLI tools with one command, supporting tools like Claude Code, OpenClaw, and OpenCode. It benefits developers by simplifying team sharing and project setup.","zh":"Skillshare CLI 是一个用于同步所有 AI 命令行工具的技能的工具，支持 Claude Code、OpenClaw、OpenCode 等","ja":"Skillshare CLI は、すべての AI コマンドラインツールのスキルを同期するツールです。Claude Code、OpenClaw、OpenCode などをサポート","ko":"Skillshare CLI는 모든 AI 명령줄 도구의 스킬을 동기화하는 도구입니다. Claude Code, OpenClaw, OpenCode 등 지원","es":"Skillshare es una herramienta que permite sincronizar habilidades en herramientas de CLI de AI. Soporta Claude Code, OpenClaw, OpenCode y más","fr":"Skillshare est un outil qui permet de synchroniser les compétences dans les outils CLI d''IA. Il prend en charge Claude Code, OpenClaw, OpenCode et plus","de":"Skillshare ist ein Tool, das die Synchronisierung von Fähigkeiten in AI-CLI-Tools ermöglicht. Es unterstützt Claude Code, OpenClaw, OpenCode und mehr","pt":"O Skillshare é uma ferramenta que sincroniza habilidades em ferramentas de CLI de IA. Ele suporta Claude Code, OpenClaw, OpenCode e mais.","ru":"Skillshare — это инструмент, который синхронизирует навыки в инструментах CLI ИИ. Он поддерживает Claude Code, OpenClaw, OpenCode и другие.","ar":"Skillshare هو أداة لمزامنة المهارات في أدوات CLI للوكلاء الذكية. يدعم Claude Code و OpenClaw و OpenCode وغيرها."},"seo":{"title":{"en":"Skillshare: Sync AI CLI Tools with One Command | AI Agent...","zh":"Skillshare CLI 工具：AIエージェント同步设置指南","ja":"Skillshare CLI ツール：AIエージェント同期設定ガイド","ko":"Skillshare CLI 도구: AI 에이전트 동기화 설정 가이드","es":"Guía de configuración de Skillshare: sincroniza habilidad...","fr":"Guide de configuration de Skillshare : synchroniser les c...","de":"Skillshare-Setup-Anleitung: Fähigkeiten in AI-CLI-Tools s...","pt":"Guia de Configuração do Skillshare: Sincronize Habilidade...","ru":"Руководство по настройке Skillshare: синхронизация навыко...","ar":"دليل إعداد Skillshare: مزامنة المهارات في أدوات CLI للوكل..."},"description":{"en":"Discover how to simplify team sharing across AI CLI tools like Claude Code and OpenClaw with skillshare. Get started now and streamline your workflow!","zh":"使用 Skillshare CLI 同步所有 AI 命令行工具的技能，并简化团队共享。支持 Claude Code、OpenClaw、OpenCode 等","ja":"Skillshare CLI を使用してすべての AI コマンドラインツールのスキルを同期し、チームシェアを簡素化します。Claude Code、OpenClaw、OpenCode などをサポート","ko":"Skillshare CLI를 사용하여 모든 AI 명령줄 도구의 스킬을 동기화하고 팀 공유를 간소화합니다. Claude Code, OpenClaw, OpenCode 등 지원","es":"Descubre cómo configurar Skillshare para sincronizar habilidades en herramientas de CLI de AI como Claude Code, OpenClaw y OpenCode","fr":"Découvrez comment configurer Skillshare pour synchroniser les compétences dans les outils CLI d''IA tels que Claude Code, OpenClaw et OpenCode","de":"Erfahren Sie, wie Sie Skillshare konfigurieren, um Fähigkeiten in AI-CLI-Tools wie Claude Code, OpenClaw und OpenCode zu synchronisieren","pt":"Aprenda a configurar o Skillshare para sincronizar habilidades em ferramentas de CLI de IA como Claude Code, OpenClaw e OpenCode","ru":"Узнайте, как настроить Skillshare для синхронизации навыков в инструментах CLI ИИ, таких как Claude Code, OpenClaw и OpenCode","ar":"تعلم كيفية إعداد Skillshare لمزامنة المهارات في أدوات CLI للوكلاء الذكية مثل Claude Code و OpenClaw و OpenCode"},"definition":{"en":"Skillshare is a CLI tool that enables syncing of skills across multiple AI platforms, allowing for seamless project sharing and collaboration.","zh":"Skillshare CLI 是一个 AI 命令行工具，用于同步和共享技能","ja":"Skillshare CLI は、スキルを同期して共有する AI コマンドラインツールです","ko":"Skillshare CLI는 스킬을 동기화하고 공유하는 AI 명령줄 도구입니다","es":"Skillshare es una herramienta de sincronización de habilidades para herramientas de línea de comandos de inteligencia artificial","fr":"Skillshare est un outil de synchronisation de compétences pour les outils de ligne de commande d''intelligence artificielle","de":"Skillshare ist ein Tool zur Synchronisierung von Fähigkeiten für KI-Command-Line-Tools","pt":"O que é Skillshare? É uma ferramenta que sincroniza habilidades em ferramentas de CLI de IA","ru":"Что такое Skillshare? Это инструмент, который синхронизирует навыки в инструментах CLI ИИ","ar":"ما هو Skillshare؟ إنه أداة لمزامنة المهارات في أدوات CLI للوكلاء الذكية"},"features":{"en":["Auto-detects project mode when .skillshare/config.yaml exists","Supports global and project-local skill storage via ~/.config/skillshare/skills/ and .skillshare/skills/","Initiates fresh global or project setup with skillshare init command","Allows importing skills from existing CLIs using skillshare init --copy-from","Enables force mode with -p or -g flags for custom setup"],"zh":["支持 Claude Code、OpenClaw、OpenCode 等 AI 命令行工具","自动检测项目模式","支持全局和项目级别的技能同步","使用 `skillshare init` 命令进行初始化","支持从现有 CLI 导入技能"],"ja":["Claude Code、OpenClaw、OpenCode などをサポート","プロジェクトモードの自動検出","グローバルとプロジェクトレベルのスキル同期をサポート","`skillshare init` コマンドを使用して初期化","既存の CLI からスキルをインポート"],"ko":["Claude Code, OpenClaw, OpenCode 등 지원","프로젝트 모드 자동 감지","전역 및 프로젝트 수준의 스킬 동기화 지원","`skillshare init` 명령을 사용하여 초기화","既存의 CLI에서 스킬을 가져오기"],"es":["Sincroniza habilidades en herramientas de CLI de AI como Claude Code y OpenClaw","Soporta configuración global y de proyecto","Auto-detección de modo de proyecto cuando existe un archivo de configuración","Compatibilidad con varios targets de AI","Incorpora comandos para inicializar y configurar habilidades"],"fr":["Synchronise les compétences dans les outils CLI d''IA tels que Claude Code et OpenClaw","Prend en charge la configuration globale et de projet","Détection automatique du mode de projet lorsqu''un fichier de configuration existe","Compatibilité avec plusieurs cibles d''IA","Intègre des commandes pour initialiser et configurer les compétences"],"de":["Synchronisiert Fähigkeiten in AI-CLI-Tools wie Claude Code und OpenClaw","Unterstützt globale und projektbezogene Konfiguration","Automatische Projektmodus-Erkennung bei Vorhandensein einer Konfigurationsdatei","Kompatibilität mit mehreren KI-Zielen","Integriert Befehle zur Initialisierung und Konfiguration von Fähigkeiten"],"pt":["Sincronização de habilidades em ferramentas de CLI de IA","Suporte a Claude Code, OpenClaw, OpenCode e mais","Modo de projeto com auto-detectação","Forçar modo de projeto com `-p` ou `-g`","Inicialização com `skillshare init`"],"ru":["Синхронизация навыков в инструментах CLI ИИ","Поддержка Claude Code, OpenClaw, OpenCode и других","Проектный режим с авто-определением","Принудительный проектный режим с `-p` или `-g`","Инициализация с `skillshare init`"],"ar":["مزامنة المهارات في أدوات CLI للوكلاء الذكية","دعم Claude Code و OpenClaw و OpenCode وغيرها","وضع المشروع مع الكشف التلقائي","إجبار وضع المشروع مع `-p` أو `-g`","التشغيل مع `skillshare init`"]},"keywords":{"en":["how to use skillshare","skillshare setup guide","what is skillshare","skillshare alternative","skillshare vs claude code","skillshare install","sync ai cli tools","team sharing across ai platforms","ai cli tool management"],"zh":["AI 命令行工具","Skillshare CLI","Claude Code","OpenClaw","OpenCode","AI エージェント","技能同步","团队共享"],"ja":["AI コマンドラインツール","Skillshare CLI","Claude Code","OpenClaw","OpenCode","AI エージェント","スキル同期","チームシェア"],"ko":["AI 명령줄 도구","Skillshare CLI","Claude Code","OpenClaw","OpenCode","AI 에이전트","스킬 동기화","팀 공유"],"es":["herramientas de CLI de AI","sincronización de habilidades","configuración de Skillshare","Claude Code","OpenClaw","OpenCode","IA","inteligencia artificial","desarrollo de software"],"fr":["outils CLI d''IA","synchronisation de compétences","configuration de Skillshare","Claude Code","OpenClaw","OpenCode","IA","intelligence artificielle","développement de logiciels"],"de":["KI-CLI-Tools","Synchronisierung von Fähigkeiten","Skillshare-Konfiguration","Claude Code","OpenClaw","OpenCode","KI","künstliche Intelligenz","Softwareentwicklung"],"pt":["Skillshare","ferramentas de CLI de IA","Claude Code","OpenClaw","OpenCode","sincronização de habilidades","modo de projeto","auto-detectação","inicialização"],"ru":["Skillshare","инструменты CLI ИИ","Claude Code","OpenClaw","OpenCode","синхронизация навыков","проектный режим","авто-определение","инициализация"],"ar":["Skillshare","أدوات CLI للوكلاء الذكية","Claude Code","OpenClaw","OpenCode","مزامنة المهارات","وضع المشروع","الكشف التلقائي","التشغيل"]}},"owner":"runkids","repo":"skillshare","repoPath":"runkids/skillshare","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.654Z","topics":[],"category":"community","skillMd":{"name":"skillshare","description":"|","version":"v0.16.12","bodyPreview":"# Skillshare CLI\n\nGlobal: `~/.config/skillshare/skills/` → all AI CLIs. Project: `.skillshare/skills/` → repo-local.\nAuto-detects project mode when `.skillshare/config.yaml` exists. Force with `-p` or `-g`.\n\n## Recipes\n\n### Getting Started\n```bash\nskillshare init --no-copy --all-targets --git --skill  # Fresh global setup\nskillshare init -p --targets \"claude,cursor\"            # Fresh project setup\nskillshare init --copy-from claude --all-targets --git  # Import from existing CLI\nskillshare init","body":"# Skillshare CLI\n\nGlobal: `~/.config/skillshare/skills/` → all AI CLIs. Project: `.skillshare/skills/` → repo-local.\nAuto-detects project mode when `.skillshare/config.yaml` exists. Force with `-p` or `-g`.\n\n## Recipes\n\n### Getting Started\n```bash\nskillshare init --no-copy --all-targets --git --skill  # Fresh global setup\nskillshare init -p --targets \"claude,cursor\"            # Fresh project setup\nskillshare init --copy-from claude --all-targets --git  # Import from existing CLI\nskillshare init --discover --select \"windsurf\"          # Add new AI tool later\n```\n### Installing Skills\n```bash\nskillshare install user/repo -s pdf,commit       # Select specific skills\nskillshare install user/repo --all               # Install everything\nskillshare install user/repo --into frontend     # Place in subdirectory\nskillshare install gitlab.com/team/repo          # Any Git host\nskillshare install user/repo --track             # Enable `update` later\nskillshare install user/repo -s pdf -p           # Install to project\nskillshare install                               # Reinstall all tracked remotes from config\nskillshare sync                                  # Always sync after install\nskillshare sync extras                           # Sync non-skill extras (rules, commands)\nskillshare sync --all                            # Sync skills + extras together\n```\n### Creating & Discovering Skills\n```bash\nskillshare new my-skill                          # Create a new skill from template\nskillshare search \"react testing\"                # Search GitHub for skills\nskillshare collect                               # Pull target-local changes back to source\n```\n### Removing Skills\n```bash\nskillshare uninstall my-skill                    # Remove one (moves to trash)\nskillshare uninstall skill-a skill-b             # Remove multiple\nskillshare uninstall -G frontend                 # Remove entire group\nskillshare sync                                  # Always sync after uninstall\n```\n### Team / Organization\n```bash\n# Creator: init project (see Getting Started) → add skills → commit .skillshare/\nskillshare install -p && skillshare sync                  # Member: clone → install → sync\nskillshare install github.com/team/repo --track -p        # Track shared repo\nskillshare push                                           # Cross-machine: push on A\nskillshare pull                                           # Cross-machine: pull on B\n```\n### Skill Hubs\n```bash\nskillshare hub add https://example.com/hub.json          # Save a hub source\nskillshare hub add https://example.com/hub.json --label my-hub  # With custom label\nskillshare hub list                                      # List saved hubs\nskillshare hub default my-hub                            # Set default hub\nskillshare hub remove my-hub                             # Remove a hub\nskillshare hub index --source ~/.config/skillshare/skills/ --full --audit  # Build hub index\n```\n### Controlling Where Skills Go\n```bash\n# SKILL.md frontmatter: targets: [claude]        → only syncs to Claude\nskillshare target claude --add-include \"team-*\"   # glob filter\nskillshare target claude --add-exclude \"_legacy*\"  # exclude pattern\nskillshare target codex --mode copy && skillshare sync --force  # copy mode\n```\nSee [targets.md](references/targets.md) for details.\n### Updates & Maintenance\n```bash\nskillshare check                              # See what has updates\nskillshare update my-skill && skillshare sync  # Update one\nskillshare update --all && skillshare sync     # Update all\nskillshare update --all --diff                 # Show what changed\n```\n### Scripting & CI/CD\n```bash\nskillshare status --json                       # Full status as JSON\nskillshare check --json                        # Update status as JSON\nskillshare sync --json                         # Sync results as JSON\nskillshare diff --json                         # Diff results as JSON\nskillshare install user/repo --json            # Install result as JSON (implies --force --all)\nskillshare update --all --json                 # Update results as JSON\nskillshare uninstall my-skill --json           # Uninstall result as JSON (implies --force)\nskillshare collect claude --json               # Collect result as JSON (implies --force)\nskillshare target list --json                  # Target list as JSON\nskillshare list --json                         # Skill list as JSON\nskillshare search react --json                 # Search results as JSON\nskillshare audit --format json                 # Audit results as JSON\n```\n### Recovery & Troubleshooting\n```bash\nskillshare trash restore <name> && skillshare sync  # Undo delete\nskillshare sync                                     # Skill missing? Re-sync\nskillshare doctor && skillshare status              # Diagnose issues\nskillshare install user/repo --force                 # Override audit block\nskillshare install user/repo --skip-audit            # Bypass scan entirely\n```\nSee [TROUBLESHOOTING.md](references/TROUBLESHOOTING.md) for more.\n\n## Quick Lookup\n| Commands | Project? | `--json`? |\n|----------|:--------:|:---------:|\n| `status`, `diff`, `list`, `doctor` | ✓ (auto) | ✓ (except doctor) |\n| `sync`, `collect` | ✓ (auto) | ✓ |\n| `install`, `uninstall`, `update`, `check`, `search`, `new` | ✓ (`-p`) | ✓ (except new) |\n| `target`, `audit`, `trash`, `log`, `hub` | ✓ (`-p`) | ✓ (target list, audit, log) |\n| `push`, `pull`, `backup`, `restore` | ✗ | ✗ |\n| `tui`, `upgrade` | ✗ | ✗ |\n| `ui` | ✓ (`-p`) | ✗ |\n\n## AI Caller Rules\n1. **Non-interactive** — AI cannot answer prompts. Use `--force`, `--all`, `-s`, `--targets`, `--no-copy`, `--all-targets`, `--yes`.\n2. **Sync after mutations** — `install`, `uninstall`, `update`, `collect`, `target` all need `sync`.\n3. **Audit** — `install` auto-scans; CRITICAL blocks. `--force` to override, `--skip-audit` to bypass. Detects hardcoded secrets (API keys, tokens, private keys).\n4. **Uninstall safely** — moves to trash (7 days). `trash restore <name>` to undo. **NEVER** `rm -rf` symlinks.\n5. **Output** — `--json` for structured data (12 commands support it, see Quick Lookup). `--no-tui` for plain text on TUI commands (`list`, `log`, `audit`, `diff`, `trash list`, `backup list`). `tui off` disables TUI globally. `--dry-run` to preview.\n\n## References\n| Topic | File |\n|-------|------|\n| Init flags | [init.md](references/init.md) |\n| Sync/collect/push/pull | [sync.md](references/sync.md) |\n| Install/update/uninstall/new | [install.md](references/install.md) |\n| Status/diff/list/search/check | [status.md](references/status.md) |\n| Security audit | [audit.md](references/audit.md) |\n| Trash | [trash.md](references/trash.md) |\n| Operation log | [log.md](references/log.md) |\n| Targets | [targets.md](references/targets.md) |\n| Backup/restore | [backup.md](references/backup.md) |\n| Troubleshooting | [TROUBLESHOOTING.md](references/TROUBLESHOOTING.md) |\n"},"lastSynced":"2026-03-08T02:13:54.921Z","agentAnalysis":{"suitability":{"en":"Perfect for AI CLI Agents needing seamless skill synchronization across tools like Claude Code and OpenClaw.","zh":"非常适合需要在诸如 Claude Code 和 OpenClaw 之类工具中实现无缝技能同步的 AI CLI 代理。","ja":"Claude Code や OpenClaw などのツールでシームレスなスキル同期を必要とする AI CLI エージェントに最適です。","ko":"Claude Code와 OpenClaw 같은 도구에서 무결점 스킬 동기화를 필요로 하는 AI CLI 에이전트에게 완벽합니다.","es":"Perfecto para Agentes de CLI de IA que necesitan una sincronización de habilidades sin problemas a través de herramientas como Claude Code y OpenClaw.","fr":"Parfait pour les agents CLI d''IA ayant besoin d''une synchronisation de compétences transparente à travers des outils comme Claude Code et OpenClaw.","de":"Perfekt für AI-CLI-Agents, die eine nahtlose Fähigkeitssynchronisierung über Tools wie Claude Code und OpenClaw benötigen.","pt":"Perfeito para Agentes CLI de IA que precisam de sincronização de habilidades sem interrupções em ferramentas como Claude Code e OpenClaw.","ru":"Идеально для агентов CLI ИИ, которым требуется бесшовная синхронизация навыков в инструментах, таких как Claude Code и OpenClaw.","ar":"مثالي لعميل واجهة سطر الأوامر للمثبطات الاصطناعية التي تحتاج إلى تنسيق مهارات متواصل عبر أدوات مثل Claude Code و OpenClaw."},"recommendation":{"en":"Empowers agents to sync skills globally or project-locally using YAML configurations, supporting tools like Claude Code and OpenCode through a unified CLI interface, utilizing protocols like Git for version control and file formats like YAML for configuration.","zh":"赋予代理在 YAML 配置中全局或项目本地同步技能的能力，通过统一的 CLI 接口支持诸如 Claude Code 和 OpenCode 之类的工具，并利用 Git 等协议进行版本控制和 YAML 等文件格式进行配置。","ja":"YAML 構成を使用して、エージェントがグローバルまたはプロジェクトローカルにスキルを同期できるようにし、Claude Code や OpenCode などのツールをサポートする統一された CLI インターフェイスを提供し、Git などのプロトコルを使用してバージョン管理を行い、YAML などのファイル形式を使用して構成します。","ko":"에이전트가 YAML 구성에서 전역 또는 프로젝트 로컬에서 스킬을 동기화 할 수 있는 능력을 부여하고 Claude Code와 OpenCode 같은 툴을 지원하는統一된 CLI 인터페이스를 제공하며 Git 같은 프로토콜을 사용하여 버전 관리를하고 YAML 같은 파일 형식을 사용하여 구성합니다.","es":"Habilita a los agentes a sincronizar habilidades a nivel global o local del proyecto utilizando configuraciones YAML, que admiten herramientas como Claude Code y OpenCode a través de una interfaz de CLI unificada, utilizando protocolos como Git para el control de versiones y formatos de archivo como YAML para la configuración.","fr":"Permet aux agents de synchroniser des compétences à l''échelle mondiale ou locale de projet en utilisant des configurations YAML, en prenant en charge des outils comme Claude Code et OpenCode via une interface CLI unifiée, en utilisant des protocoles comme Git pour le contrôle de version et des formats de fichier comme YAML pour la configuration.","de":"Ermächtigt Agenten, Fähigkeiten global oder projektlokal mithilfe von YAML-Konfigurationen zu synchronisieren, die Tools wie Claude Code und OpenCode über eine einheitliche CLI-Schnittstelle unterstützen, wobei Protokolle wie Git für die Versionskontrolle und Dateiformate wie YAML für die Konfiguration verwendet werden.","pt":"Habilita os agentes a sincronizar habilidades globalmente ou localmente no projeto usando configurações YAML, dando suporte a ferramentas como Claude Code e OpenCode por meio de uma interface CLI unificada, utilizando protocolos como Git para controle de versão e formatos de arquivo como YAML para configuração.","ru":"Позволяет агентам синхронизировать навыки глобально или локально в проекте, используя конфигурации YAML, поддерживая инструменты, такие как Claude Code и OpenCode, через унифицированный интерфейс CLI, используя протоколы, такие как Git для контроля версий, и форматы файлов, такие как YAML для конфигурации.","ar":"تمكّن العميل من مزامنة المهارات على مستوى العالم أو محلياً في المشروع باستخدام تكوينات YAML، مع دعم أدوات مثل Claude Code و OpenCode من خلال واجهة CLI موحدة، واستخدام بروتوكولات مثل Git للتحكم في الإصدارات وتنسيقات الملفات مثل YAML للتكوين."},"useCases":{"en":["Synchronizing skills across multiple AI CLI tools","Automating project setup with unified skill sharing","Debugging skill inconsistencies between global and project-local configurations"],"zh":["跨多个 AI CLI 工具同步技能","使用统一的技能共享自动化项目设置","调试全局和项目本地配置之间的技能不一致"],"ja":["複数の AI CLI ツールでスキルを同期する","統一されたスキル共有を使用してプロジェクト設定を自動化する","グローバルとプロジェクトローカルの構成間のスキルの不一致をデバッグする"],"ko":["여러 개의 AI CLI 툴에서 스킬을 동기화하는 것","통합된 스킬 공유를 사용하여 프로젝트 설정을 자동화하는 것","전역 및 프로젝트 로컬 구성间의 스킬 불일치를 디버깅하는 것"],"es":["Sincronizar habilidades en varias herramientas de CLI de IA","Automatizar la configuración del proyecto con una compartición de habilidades unificada","Depurar las inconsistencias de habilidades entre configuraciones globales y locales del proyecto"],"fr":["Synchroniser des compétences à travers plusieurs outils CLI d''IA","Automatiser la configuration du projet avec un partage de compétences unifié","Déboguer les incohérences de compétences entre les configurations globales et locales du projet"],"de":["Fähigkeiten über mehrere AI-CLI-Tools hinweg synchronisieren","Projektkonfiguration mit einem einheitlichen Fähigkeitsaustausch automatisieren","Fähigkeitsinkonsistenzen zwischen globalen und projektlokalen Konfigurationen debuggen"],"pt":["Sincronizar habilidades em várias ferramentas CLI de IA","Automatizar a configuração do projeto com compartilhamento de habilidades unificado","Depurar inconsistências de habilidades entre configurações globais e locais do projeto"],"ru":["Синхронизировать навыки в нескольких инструментах CLI ИИ","Автоматизировать настройку проекта с унифицированным обменом навыками","Отладить несоответствия навыков между глобальными и локальными конфигурациями проекта"],"ar":["مزامنة المهارات عبر أدوات متعددة لواجهة سطر الأوامر للمثبطات الاصطناعية","آليّة إعداد المشروع مع مشاركة مهارات موحدة","تصحيح أخطاء في عدم تطابق المهارات بين التكوينات العالمية والمحلية للمشروع"]},"limitations":{"en":["Requires YAML configuration files","Dependent on CLI tools like Claude Code and OpenClaw","Needs Git for version control"],"zh":["需要 YAML 配置文件","依赖于诸如 Claude Code 和 OpenClaw 之类的 CLI 工具","需要 Git 进行版本控制"],"ja":["YAML 構成ファイルが必要","Claude Code や OpenClaw などの CLI ツールに依存する","バージョン管理のために Git が必要"],"ko":["YAML 구성 파일이 필요함","Claude Code와 OpenClaw 같은 CLI 툴에 의존함","버전 관리를 위해 Git가 필요함"],"es":["Requiere archivos de configuración YAML","Dependiente de herramientas de CLI como Claude Code y OpenClaw","Necesita Git para el control de versiones"],"fr":["Nécessite des fichiers de configuration YAML","Dépendant d''outils CLI tels que Claude Code et OpenClaw","Nécessite Git pour le contrôle de version"],"de":["Benötigt YAML-Konfigurationsdateien","Abhängig von CLI-Tools wie Claude Code und OpenClaw","Benötigt Git für die Versionskontrolle"],"pt":["Exige arquivos de configuração YAML","Dependente de ferramentas CLI como Claude Code e OpenClaw","Necessita Git para controle de versão"],"ru":["Требует файлов конфигурации YAML","Зависит от инструментов CLI, таких как Claude Code и OpenClaw","Требует Git для контроля версий"],"ar":["يتطلب ملفات تكوين YAML","يعتمد على أدوات واجهة سطر الأوامر مثل Claude Code و OpenClaw","يحتاج إلى Git للتحكم في الإصدارات"]},"version":4},"contentHash":"d77e6210916d1f408a6fa4bb472b97f5f5b3738861514148d103b2445fd3b163","qualityScore":47}');
