INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('runkids/skillshare/skillshare', 'skillshare', 'runkids', 'skillshare', 'community', 'skillshare runkids skillshare community Skillshare syncs skills across all AI CLI tools with one command, supporting tools like Claude Code, OpenClaw, and OpenCode. It benefits developers by simplifying team sharing and project setup. Skillshare CLI 是一个用于同步所有 AI 命令行工具的技能的工具，支持 Claude Code、OpenClaw、OpenCode 等 Skillshare CLI は、すべての AI コマンドラインツールのスキルを同期するツールです。Claude Code、OpenClaw、OpenCode などをサポート Skillshare CLI는 모든 AI 명령줄 도구의 스킬을 동기화하는 도구입니다. Claude Code, OpenClaw, OpenCode 등 지원 Skillshare es una herramienta que permite sincronizar habilidades en herramientas de CLI de AI. Soporta Claude Code, OpenClaw, OpenCode y más Skillshare est un outil qui permet de synchroniser les compétences dans les outils CLI d''IA. Il prend en charge Claude Code, OpenClaw, OpenCode et plus Skillshare ist ein Tool, das die Synchronisierung von Fähigkeiten in AI-CLI-Tools ermöglicht. Es unterstützt Claude Code, OpenClaw, OpenCode und mehr O Skillshare é uma ferramenta que sincroniza habilidades em ferramentas de CLI de IA. Ele suporta Claude Code, OpenClaw, OpenCode e mais. Skillshare — это инструмент, который синхронизирует навыки в инструментах CLI ИИ. Он поддерживает Claude Code, OpenClaw, OpenCode и другие. Skillshare هو أداة لمزامنة المهارات في أدوات CLI للوكلاء الذكية. يدعم Claude Code و OpenClaw و OpenCode وغيرها. how to use skillshare skillshare setup guide what is skillshare skillshare alternative skillshare vs claude code skillshare install sync ai cli tools team sharing across ai platforms ai cli tool management AI 命令行工具 Skillshare CLI Claude Code OpenClaw OpenCode AI エージェント 技能同步 团队共享 Auto-detects project mode when .skillshare/config.yaml exists Supports global and project-local skill storage via ~/.config/skillshare/skills/ and .skillshare/skills/ Initiates fresh global or project setup with skillshare init command Allows importing skills from existing CLIs using skillshare init --copy-from Enables force mode with -p or -g flags for custom setup Skillshare is a CLI tool that enables syncing of skills across multiple AI platforms, allowing for seamless project sharing and collaboration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('awakecoding/openspecs/windows-protocols', 'community', 'awakecoding', 'openspecs', 'awakecoding/openspecs', 'windows-protocols', 0, 0, 47, '2026-03-08T01:57:15.659Z', '2026-03-08T02:14:01.176Z', '17853cc650c46fe75869eb34c682edd5aeece14737bc0f7361fa57da0551342c', '{"id":"awakecoding/openspecs/windows-protocols","name":"windows-protocols","description":{"en":"The windows-protocols skill enables developers to navigate the Microsoft Open Specifications markdown corpus, providing structure-first navigation and evidence-grounded answers. This skill benefits developers working with Windows protocols.","zh":"Windows 协议 AI 工具提供结构优先导航，允许您快速找到 Microsoft Open Specifications 文档","ja":"Windows プロトコル AI エージェントは、Microsoft Open Specifications 文書の効率的な探索を実現","ko":"Windows 프로토콜 AI 도구는 기술 문서 탐색을 위한 구조优先导航을 제공","es":"El skill de Windows Protocols proporciona una forma estructurada de navegar por la documentación de Microsoft Open Specifications y ofrece respuestas basadas en evidencia","fr":"Le skill Windows Protocols offre une façon structurée de naviguer dans la documentation Microsoft Open Specifications et fournit des réponses basées sur des preuves","de":"Das Windows-Protocols-Skill ermöglicht eine strukturierte Navigation durch die Microsoft Open Specifications-Dokumentation und bietet evidenzbasierte Antworten","pt":"O Windows Protocols AI Agent é uma ferramenta para navegação estruturada de especificações abertas da Microsoft, com respostas baseadas em evidências.","ru":"ИИ Агент Windows Protocols — это инструмент для структурированного просмотра открытых спецификаций Microsoft, с ответами, основанными на доказательствах.","ar":"العميل الذكي لبروتوكولات ويندوز هو أداة للتنقل الهيكلي بالإرشادات المفتوحة من مايكروسوفت، مع إجابات مبنية على الأدلة."},"seo":{"title":{"en":"windows-protocols: Corpus Navigator Setup Guide | AI Agen...","zh":"Windows 协议 AI 工具：结构优先导航","ja":"Windows プロトコル AI エージェント：セットアップガイド","ko":"Windows 프로토콜 AI 도구: 기술 문서 탐색","es":"Guía de configuración de Windows Protocols con Microsoft ...","fr":"Guide de mise en route des protocoles Windows avec Micros...","de":"Einrichtungsleitfaden für Windows-Protokolle mit Microsof...","pt":"Guia de Configuração do Windows Protocols AI Agent","ru":"Настройка ИИ Агента Windows Protocols: Лучшие Практики","ar":"دليل إعداد العميل الذكي لبروتوكولات ويندوز"},"description":{"en":"Unlock Microsoft Open Specifications with the windows-protocols AI agent skill. Learn how to navigate the corpus and get evidence-grounded answers - start ex...","zh":"使用 Windows 协议 AI 工具实现结构优先导航，快速找到 Microsoft Open Specifications 文档","ja":"Windows プロトコル AI エージェントを使用して、Microsoft Open Specifications 文書を効率的に探索","ko":"Windows 프로토콜 AI 도구를 사용하여 기술 문서를 쉽게 탐색하고 Microsoft Open Specifications를 효율적으로 관리","es":"Navega por la documentación de Microsoft Open Specifications para Windows Protocols de manera estructurada y obtén respuestas basadas en evidencia","fr":"Naviguez dans la documentation Microsoft Open Specifications pour les protocoles Windows de manière structurée et obtenez des réponses basées sur des preuves","de":"Navigieren Sie durch die Microsoft Open Specifications-Dokumentation für Windows-Protokolle in strukturierter Form und erhalten Sie evidenzbasierte Antworten","pt":"Aprenda a configurar o Windows Protocols AI Agent para navegação estruturada de especificações abertas da Microsoft","ru":"Узнайте, как настроить ИИ Агента Windows Protocols для структурированного просмотра открытых спецификаций Microsoft","ar":"تعرف على كيفية إعداد العميل الذكي لبروتوكولات ويندوز لتنقل هيكلي للإرشادات المفتوحة من مايكروسوفت"},"definition":{"en":"windows-protocols is a skill that facilitates navigation of Microsoft Open Specifications markdown corpus, optimized for local file usage and structure-first exploration.","zh":"Windows 协议 AI 工具是一种结构优先导航工具，用于 Microsoft Open Specifications 文档","ja":"Windows プロトコル AI エージェントは、Microsoft Open Specifications 文書のための構造優先ナビゲーションツール","ko":"Windows 프로토콜 AI 도구는 Microsoft Open Specifications 문서를 위한 구조优先导航 도구","es":"Windows Protocols es un skill que permite navegar por la documentación de Microsoft Open Specifications de manera estructurada","fr":"Windows Protocols est un skill qui permet de naviguer dans la documentation Microsoft Open Specifications de manière structurée","de":"Windows-Protokolle ist ein Skill, der eine strukturierte Navigation durch die Microsoft Open Specifications-Dokumentation ermöglicht","pt":"O que é o Windows Protocols AI Agent? É uma ferramenta de navegação de especificações abertas da Microsoft.","ru":"Что такое ИИ Агент Windows Protocols? Это инструмент для просмотра открытых спецификаций Microsoft.","ar":"ما هو العميل الذكي لبروتوكولات ويندوز؟ هو أداة لتنقل بالإرشادات المفتوحة من مايكروسوفت."},"features":{"en":["Navigates Microsoft Open Specifications markdown corpus","Provides structure-first navigation of technical documents","Offers evidence-grounded answers using local files only","Utilizes README.md index with Overview and Technical Documents sections","Supports offline usage without network lookup"],"zh":["结构优先导航","Microsoft Open Specifications 文档支持","本地文件导航","无需网络查找","README.md 索引支持"],"ja":["構造優先ナビゲーション","Microsoft Open Specifications 文書対応","ローカルファイルナビゲーション","ネットワーク検索不要","README.md インデックス対応"],"ko":["구조优先导航","Microsoft Open Specifications 문서 지원","로컬 파일 탐색","네트워크 검색 불필요","README.md 색인 지원"],"es":["Navegación estructurada de la documentación de Microsoft Open Specifications","Respuestas basadas en evidencia","Uso de archivos locales sin búsqueda en red","Estructura de corpus con README.md y secciones de Overview y Technical Documents"],"fr":["Navigation structurée de la documentation Microsoft Open Specifications","Réponses basées sur des preuves","Utilisation de fichiers locaux sans recherche en réseau","Structure de corpus avec README.md et des sections Overview et Technical Documents"],"de":["Strukturierte Navigation durch die Microsoft Open Specifications-Dokumentation","Evidenzbasierte Antworten","Verwendung von lokalen Dateien ohne Netzwerksuche","Corpus-Struktur mit README.md und Abschnitten für Überblick und technische Dokumente"],"pt":["Navegação estruturada de especificações abertas da Microsoft","Respostas baseadas em evidências","Uso de arquivos locais para navegação","Índice com três seções: Visão Geral, Documentos Técnicos e Mais","Suporte a marcação de documentos Markdown","Navegação otimizada para estrutura de especificações"],"ru":["Структурированный просмотр открытых спецификаций Microsoft","Ответы, основанные на доказательствах","Использование локальных файлов для просмотра","Индекс с тремя разделами: Обзор, Технические Документы и Другое","Поддержка разметки документов Markdown","Оптимизированная навигация для структуры спецификаций"],"ar":["التنقل الهيكلي بالإرشادات المفتوحة من مايكروسوفت","إجابات مبنية على الأدلة","استخدام الملفات المحلية للتنقل","فهرس مع ثلاثة أقسام: نظرة عامة، وثائق فنية وأكثر","دعم لتنسيق المستندات Markdown","تنقل محسّن للهيكل الخاص بالإرشادات"]},"keywords":{"en":["how to use windows-protocols","windows-protocols setup guide","what is windows-protocols","windows-protocols alternative","windows-protocols vs open specifications","microsoft open specifications windows protocols"],"zh":["Windows 协议 AI 工具","结构优先导航","Microsoft Open Specifications","技术文档探索","本地文件导航","AI 工具","Windows 协议"],"ja":["Windows プロトコル AI エージェント","構造優先ナビゲーション","Microsoft Open Specifications","技術文書探索","ローカルファイルナビゲーション","AI エージェント","Windows プロトコル"],"ko":["Windows 프로토콜 AI 도구","구조优先导航","Microsoft Open Specifications","기술 문서 탐색","로컬 파일 탐색","AI 도구","Windows 프로토콜"],"es":["Windows Protocols","Microsoft Open Specifications","navegación estructurada","respuestas basadas en evidencia","documentación de Windows","desarrollo de software","herramientas de desarrollo","AI Agentes","navegación de corpus"],"fr":["Windows Protocols","Microsoft Open Specifications","navigation structurée","réponses basées sur des preuves","documentation Windows","développement de logiciels","outils de développement","Agents AI","navigation de corpus"],"de":["Windows-Protokolle","Microsoft Open Specifications","strukturierte Navigation","evidenzbasierte Antworten","Windows-Dokumentation","Software-Entwicklung","Entwicklungstools","KI-Agents","Corpus-Navigation"],"pt":["Windows Protocols AI Agent","Especificação aberta da Microsoft","Navegação estruturada","Respostas baseadas em evidências","Arquivos locais","Markdown","Índice de documentos","Guia de configuração","Melhores práticas"],"ru":["ИИ Агент Windows Protocols","Открытая спецификация Microsoft","Структурированный просмотр","Ответы, основанные на доказательствах","Локальные файлы","Markdown","Индекс документов","Руководство по настройке","Лучшие практики"],"ar":["العميل الذكي لبروتوكولات ويندوز","الإرشادات المفتوحة من مايكروسوفت","التنقل الهيكلي","إجابات مبنية على الأدلة","الملفات المحلية","Markdown","فهرس المستندات","دليل الإعداد","أفضل الممارسات"]}},"owner":"awakecoding","repo":"openspecs","repoPath":"awakecoding/openspecs","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.659Z","topics":[],"category":"community","skillMd":{"name":"windows-protocols","description":"Local Microsoft Open Specifications corpus navigator for Windows protocols. Use this skill when the user asks protocol-level questions, needs message/structure details, wants section-by-section summaries, or needs cross-references across related specifications.","bodyPreview":"# Windows Protocols Corpus Navigator\n\n## Overview\n\n- The markdown corpus is already extracted locally, next to `SKILL.md`.\n- Use local files only. Do not use network lookup for this skill.\n- Do not run download or setup commands as part of normal usage.\n\nThis skill is optimized for structure-first navigation of Microsoft Open Specifications markdown and evidence-grounded answers.\n\n## Corpus Layout\n\n- `README.md` — index with three sections: Overview Documents (domain maps), Technical Documents (","body":"# Windows Protocols Corpus Navigator\n\n## Overview\n\n- The markdown corpus is already extracted locally, next to `SKILL.md`.\n- Use local files only. Do not use network lookup for this skill.\n- Do not run download or setup commands as part of normal usage.\n\nThis skill is optimized for structure-first navigation of Microsoft Open Specifications markdown and evidence-grounded answers.\n\n## Corpus Layout\n\n- `README.md` — index with three sections: Overview Documents (domain maps), Technical Documents (full spec list), and Reference Documents. Overview Documents are at the top; use them for topical discovery.\n- `LEGAL.md` — legal and redistribution notice.\n- `<PROTOCOL-ID>/` — protocol directories (Overview, Technical, or Reference), directly under this folder.\n- `<PROTOCOL-ID>/<PROTOCOL-ID>.md` — primary markdown spec content.\n- `<PROTOCOL-ID>/media/` — extracted figures and image assets referenced by the markdown.\n\n## Corpus Document Types\n\n- **Overview Documents** — Domain maps that group related protocols under a topic (file access, authentication, storage, remote desktop, etc.). Each describes system capabilities, lists member protocols with their roles, and contains many links to specifications. Use as the primary entry point for topical discovery.\n- **Technical Documents** — Individual protocol specifications with full wire-format, message syntax, and behavior details.\n- **Reference Documents** — Supplemental references (error codes, shared types, etc.).\n\n## Protocol Clusters by Domain\n\nWhen using Overview documents for discovery, expect these cluster themes:\n\n- **Authentication**: Kerberos, NTLM, SPNEGO — core for file access, RDP, Group Policy.\n- **File Access**: SMB/CIFS family, DFS, WebDAV, shared types (FSCC, FSA).\n- **Remote Desktop**: Base + graphics pipeline, gateway, virtual channels (clipboard, devices, transport).\n- **Storage**: Disk/volume management, shadow copies, EFS, backup, removable media.\n- **Group Policy**: Core protocol + extensions; depends on AD and file access.\n- **Network Access Protection**: SoH/SoHR over PEAP; DHCP/VPN/TSGU/IPsec enforcement.\n- **Content Caching**: Peer discovery, retrieval, hosted cache; integrates with SMB/HTTP.\n- **File Services Management**: FSRM, remote VSS, classification.\n- **Rights Management**: Publish/consume protected content.\n- **Virtual Storage**: Remote shared virtual disks over SMB.\n\n## Protocol Naming and Scope\n\n- `MS-...` documents are Microsoft protocol specifications (wire formats, behavior, state machines, structures).\n- Families share prefixes (for example `MS-RDP*`, `MS-AD*`, `MS-MQ*`).\n\nWhen a user asks a broad question, start from family prefixes and narrow to specific protocol IDs.\n\n## When to Use / When Not to Use\n\nUse this skill when the user asks for:\n\n- Protocol semantics, message flow, field definitions, or sequencing rules.\n- Cross-reference analysis between related specs.\n- Security semantics and product-behavior distinctions in Open Specifications docs.\n\nDo not use this skill as the primary source for:\n\n- API usage tutorials, SDK how-to steps, or implementation quickstarts.\n- Product configuration guidance not grounded in protocol specs.\n\nIf a required protocol is missing from root-level `MS-*` directories, state that explicitly and ask the user for the exact protocol ID or a narrower feature scope.\n\n## Navigation Strategy\n\n- **Domain/topic questions** (file access, authentication, storage, remote desktop, etc.): Start with the corresponding Overview document from README. Use it as a map to identify which specifications to read. Follow its links into those specs.\n- **Protocol-ID questions**: Go directly to the spec if the ID is known.\n- **Principle**: Overview documents are the primary entry point for topical discovery. README provides the index of Overview docs and the full protocol list, but does not contain the semantic mapping (topic → protocols) found in Overviews.\n- **Anti-pattern**: Do not rely on README keyword search alone. A shallow grep of README may return protocol IDs from unrelated domains; overview documents provide the curated topic-to-protocol mapping.\n\n## Navigation Workflow\n\n1. For topical questions: Identify the domain from the question, match to an Overview document in README, read it to obtain linked member specs, then follow links into those specs.\n2. For known protocol IDs: Validate in `README.md` and directory names (`<PROTOCOL-ID>/`), then open the spec.\n3. Start from the spec TOC (`<summary>` blocks and numbered entries) before deep reading.\n4. Read sections in this order by intent: orientation/versioning, message or structure syntax, behavior and sequencing, security and product behavior notes.\n5. Cross-check base vs extension specs when requirements may be split.\n6. Answer with explicit protocol IDs and exact section headings; separate confirmed facts from inference.\n\n## Link-Following\n\n- Overview documents contain References sections (often 1.3) and extensive inline links to member specifications. Follow these links rather than guessing paths.\n- The link graph (Overview → spec → related spec) is the intended navigation structure.\n- When a spec references another spec for types, extensions, or dependencies, follow that link to reach the authoritative source.\n- Continue following links until the relevant information is found; do not stop at the first document that mentions the topic.\n\n## Canonical Spec Structure (Corpus-Guided)\n\nThe corpus is highly consistent. The most common top-level sequence is:\n\n- `1 Introduction`\n- `2 Messages`\n- `3 Protocol Details`\n- `4 Protocol Examples`\n- `5 Security`\n\nCommon `1.x` orientation subsections include:\n\n- `1.1 Glossary`, `1.2 References`, `1.3 Overview`\n- `1.4 Relationship to Other Protocols`\n- `1.5 Prerequisites/Preconditions`\n- `1.7 Versioning and Capability Negotiation`\n\nCommon `3.x.y` behavioral subsections include:\n\n- `Abstract Data Model`\n- `Timers`\n- `Initialization`\n- `Higher-Layer Triggered Events`\n- `Message Processing Events and Sequencing Rules`\n- `Timer Events`\n- `Other Local Events`\n\nUse these sections as the default reading spine unless the document is an outlier.\n\n## Section-First Reading Playbook\n\nPrioritize sections by question type:\n\n- “What is this protocol / where does it fit?” -> `1.3`, `1.4`, `1.7`\n- “How is data encoded / what are fields?” -> `2.2` (`Message Syntax`, `Common Data Types`, structures)\n- “What is the runtime behavior / state machine?” -> `3.x` details and `3.x.y` sequencing sections\n- “What security guarantees or knobs exist?” -> `5.*` security sections\n- “Implementation differences by product/version?” -> `Appendix ... Product Behavior` and change tracking sections\n\nWhen structure spans multiple specs, resolve in this order:\n\n1. Base/core protocol semantics.\n2. Extension-specific modifications.\n3. Shared type dependencies (for example `MS-DTYP`).\n\n## Outlier Handling\n\nNot all specs use the exact canonical headings. Handle these common variants:\n\n- `2 Structures`, `2 Attributes`, `2 Data Types`, `2 Message Transport` instead of `2 Messages`.\n- `3 Structure Examples`, `3 Details`, or algorithm-specific section names.\n- `4 Security` or `4 Security Considerations` when numbering shifts.\n- Appendix variants such as `Full IDL`, `Full WSDL`, `Full XML Schema`, `Full JSON Schema`.\n- Change tracking may appear as section `7`, `8`, `9`, or higher.\n\nRule: match by semantic intent first, section number second.\n\n## Quick Discovery Patterns\n\n- When the protocol ID is unknown: Identify the domain first from question keywords, then open the matching Overview document before picking specs. Use its Protocol Summary or References section to obtain the correct spec list.\n- Do not select specs from README''s flat Technical Documents list without consulting an Overview when the domain is ambiguous.\n- When the user provides a specific protocol ID: Go directly to that spec.\n- For extension behavior: Verify whether requirements are in a base protocol or an extension; Overview docs and spec cross-references help clarify dependencies.\n- For ambiguous acronyms: List 2–4 likely protocols (via Overview docs) and ask the user to choose before deep analysis.\n\n## Answer Contract (Semi-Structured)\n\nDefault answer shape:\n\n1. `Protocols consulted`: list exact IDs.\n2. `Sections used`: list exact section titles (and numbers when available).\n3. `Findings`: concise facts tied to those sections.\n4. `Inference / uncertainty`: explicit separation from confirmed text.\n\nEvidence policy:\n\n- For non-obvious, contested, or security-sensitive claims, include section-grounded evidence.\n- For straightforward facts, concise section references are enough.\n- If two specs disagree, report both and identify likely version/context scope.\n\n## Working Style\n\n- Prefer section-grounded answers over high-level paraphrase.\n- Include the exact protocol IDs used for the answer.\n- If the corpus does not clearly answer a point, state uncertainty explicitly.\n- Never present inferred behavior as normative requirement text.\n\n"},"lastSynced":"2026-03-08T02:14:01.176Z","agentAnalysis":{"suitability":{"en":"Perfect for Microsoft Ecosystem Agents needing advanced Windows protocol navigation and evidence-grounded answers.","zh":"非常适合需要高级 Windows 协议导航和基于证据的答案的 Microsoft 生态系统代理。","ja":"Microsoft エコシステム エージェントが高度な Windows プロトコル ナビゲーションと証拠に基づいた回答を必要とする場合に最適です。","ko":"고급 Windows 프로토콜 탐색과 증거 기반 답변을 필요로 하는 Microsoft 생태계 에이전트에게 적합합니다.","es":"Perfecto para agentes del ecosistema de Microsoft que necesitan una navegación avanzada de protocolos de Windows y respuestas basadas en evidencia.","fr":"Parfait pour les agents de l''écosystème Microsoft ayant besoin d''une navigation avancée de protocoles Windows et de réponses fondées sur des preuves.","de":"Perfekt für Microsoft-Ecosystem-Agents, die eine erweiterte Windows-Protokollnavigation und evidenzbasierte Antworten benötigen.","pt":"Perfeito para Agentes do Ecossistema Microsoft que necessitam de navegação avançada de protocolo do Windows e respostas baseadas em evidências.","ru":"Идеально подходит для агентов экосистемы Microsoft, которым требуется продвинутая навигация по протоколам Windows и ответы, основанные на доказательствах.","ar":"مثالي للوكلاء في نظام مايكروسوفت الذين يحتاجون إلى التنقل المتقدم في بروتوكول ويندوز والإجابات المعتمدة على الأدلة."},"recommendation":{"en":"Empowers agents to navigate the Microsoft Open Specifications markdown corpus with structure-first navigation, providing accurate and reliable information on Windows protocols, including domain maps and technical documents in markdown format.","zh":"赋予代理导航 Microsoft Open Specifications markdown 语料库的结构优先导航功能，提供有关 Windows 协议的准确可靠信息，包括以 markdown 格式的域映射和技术文档。","ja":"エージェントが Microsoft Open Specifications マークダウン コーパスを構造優先のナビゲーションで閲覧できるようにし、Windows プロトコルに関する正確で信頼性の高い情報を提供します。ドメイン マップやマークダウン形式の技術文書などが含まれます。","ko":"에이전트가 Microsoft Open Specifications markdown 코퍼스를 구조 우선 탐색으로 탐색할 수 있도록하여 Windows 프로토콜에 대한 정확하고 신뢰할 수 있는 정보를 제공합니다. 도메인 맵 및 markdown 형식의 기술 문서 등이 포함됩니다.","es":"Habilita a los agentes a navegar por el corpus de especificaciones abiertas de Microsoft en formato markdown con navegación estructurada, proporcionando información precisa y confiable sobre protocolos de Windows, incluyendo mapas de dominio y documentos técnicos en formato markdown.","fr":"Permet aux agents de naviguer dans le corpus de spécifications ouvertes de Microsoft au format markdown avec une navigation structurée, fournissant des informations précises et fiables sur les protocoles Windows, y compris les cartes de domaine et les documents techniques au format markdown.","de":"Ermöglicht es Agenten, durch das Microsoft Open Specifications-Markdown-Corpus mit strukturierter Navigation zu browsen, wodurch genaue und zuverlässige Informationen über Windows-Protokolle bereitgestellt werden, einschließlich Domänenkarten und technischer Dokumente im Markdown-Format.","pt":"Habilita os agentes a navegar pelo corpus de especificações abertas da Microsoft em markdown com navegação estruturada primeiro, fornecendo informações precisas e confiáveis sobre os protocolos do Windows, incluindo mapas de domínio e documentos técnicos no formato markdown.","ru":"Наделяет агентов возможностью навигации по корпору открытых спецификаций Microsoft в формате markdown с навигацией на основе структуры, предоставляя точную и надежную информацию о протоколах Windows, включая карты доменов и технические документы в формате markdown.","ar":"تمكن الوكلاء من التنقل في مجموعة مواصفات مايكروسوفت المفتوحة في تنسيق markdown باستخدام التنقل الهيكلي أولاً ، ومقدم معلومات دقيقة وموثوقة حول بروتوكولات ويندوز ، بما في ذلك خرائط النطاق والوثائق الفنية بتنسيق markdown."},"useCases":{"en":["Navigating Microsoft Open Specifications for Windows protocol development","Generating evidence-grounded answers for technical support","Exploring domain maps for Windows protocol integration"],"zh":["导航 Microsoft Open Specifications 以进行 Windows 协议开发","生成技术支持的基于证据的答案","探索 Windows 协议集成的域映射"],"ja":["Windows プロトコル開発のための Microsoft Open Specifications のナビゲーション","技術サポートのための証拠に基づいた回答の生成","Windows プロトコル統合のためのドメイン マップの探索"],"ko":["Windows 프로토콜 개발을 위한 Microsoft Open Specifications 탐색","기술 지원을 위한 증거 기반 답변 생성","Windows 프로토콜 통합을 위한 도메인 맵 탐색"],"es":["Navegación por las especificaciones abiertas de Microsoft para el desarrollo de protocolos de Windows","Generación de respuestas basadas en evidencia para el soporte técnico","Exploración de mapas de dominio para la integración de protocolos de Windows"],"fr":["Navigation dans les spécifications ouvertes de Microsoft pour le développement de protocoles Windows","Génération de réponses fondées sur des preuves pour le support technique","Exploration de cartes de domaine pour l''intégration de protocoles Windows"],"de":["Navigation durch die Microsoft Open Specifications für die Windows-Protokollentwicklung","Generierung evidenzbasierter Antworten für den technischen Support","Erforschung von Domänenkarten für die Windows-Protokollintegration"],"pt":["Navegando pelas Especificações Abertas da Microsoft para desenvolvimento de protocolo do Windows","Gerando respostas baseadas em evidências para suporte técnico","Explorando mapas de domínio para integração de protocolo do Windows"],"ru":["Навигация по открытым спецификациям Microsoft для разработки протокола Windows","Генерация ответов, основанных на доказательствах, для технической поддержки","Изучение карт доменов для интеграции протокола Windows"],"ar":["التنقل في مواصفات مايكروسوفت المفتوحة لتطوير بروتوكول ويندوز","توليد إجابات تقوم على الأدلة لدعم تقني","استكشاف خرائط النطاق لتكامل بروتوكول ويندوز"]},"limitations":{"en":["Requires local markdown corpus","Does not support network lookup","Limited to Microsoft Open Specifications markdown corpus"],"zh":["需要本地 markdown 语料库","不支持网络查找","仅限于 Microsoft Open Specifications markdown 语料库"],"ja":["ローカル マークダウン コーパスが必要","ネットワーク検索はサポートされていません","Microsoft Open Specifications マークダウン コーパスのみがサポートされています"],"ko":["로컬 markdown 코퍼스가 필요합니다","네트워크 조회를 지원하지 않습니다","Microsoft Open Specifications markdown 코퍼스만 지원됩니다"],"es":["Requiere un corpus de markdown local","No admite la búsqueda en red","Limitado al corpus de markdown de especificaciones abiertas de Microsoft"],"fr":["Nécessite un corpus de markdown local","Ne prend pas en charge la recherche sur le réseau","Limité au corpus de markdown des spécifications ouvertes de Microsoft"],"de":["Benötigt ein lokales Markdown-Corpus","Unterstützt keine Netzwerksuche","Begrenzt auf das Microsoft Open Specifications-Markdown-Corpus"],"pt":["Requer corpus de markdown local","Não suporta pesquisa de rede","Limitado ao corpus de markdown de Especificações Abertas da Microsoft"],"ru":["Требуется локальный корпус markdown","Не поддерживает поиск в сети","Ограничен корпусом markdown открытых спецификаций Microsoft"],"ar":["يتطلب مجموعة markdown محلية","لا يدعم البحث الشبكي","محدود بمجموعة markdown لمواصفات مايكروسوفت المفتوحة"]},"version":4},"contentHash":"17853cc650c46fe75869eb34c682edd5aeece14737bc0f7361fa57da0551342c","qualityScore":47}');
