INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('awakecoding/openspecs/windows-protocols', 'windows-protocols', 'awakecoding', 'openspecs', 'community', 'windows-protocols awakecoding openspecs community The windows-protocols skill enables developers to navigate the Microsoft Open Specifications markdown corpus, providing structure-first navigation and evidence-grounded answers. This skill benefits developers working with Windows protocols. Windows 协议 AI 工具提供结构优先导航，允许您快速找到 Microsoft Open Specifications 文档 Windows プロトコル AI エージェントは、Microsoft Open Specifications 文書の効率的な探索を実現 Windows 프로토콜 AI 도구는 기술 문서 탐색을 위한 구조优先导航을 제공 El skill de Windows Protocols proporciona una forma estructurada de navegar por la documentación de Microsoft Open Specifications y ofrece respuestas basadas en evidencia Le skill Windows Protocols offre une façon structurée de naviguer dans la documentation Microsoft Open Specifications et fournit des réponses basées sur des preuves Das Windows-Protocols-Skill ermöglicht eine strukturierte Navigation durch die Microsoft Open Specifications-Dokumentation und bietet evidenzbasierte Antworten O Windows Protocols AI Agent é uma ferramenta para navegação estruturada de especificações abertas da Microsoft, com respostas baseadas em evidências. ИИ Агент Windows Protocols — это инструмент для структурированного просмотра открытых спецификаций Microsoft, с ответами, основанными на доказательствах. العميل الذكي لبروتوكولات ويندوز هو أداة للتنقل الهيكلي بالإرشادات المفتوحة من مايكروسوفت، مع إجابات مبنية على الأدلة. how to use windows-protocols windows-protocols setup guide what is windows-protocols windows-protocols alternative windows-protocols vs open specifications microsoft open specifications windows protocols Windows 协议 AI 工具 结构优先导航 Microsoft Open Specifications 技术文档探索 本地文件导航 AI 工具 Windows 协议 Navigates Microsoft Open Specifications markdown corpus Provides structure-first navigation of technical documents Offers evidence-grounded answers using local files only Utilizes README.md index with Overview and Technical Documents sections Supports offline usage without network lookup windows-protocols is a skill that facilitates navigation of Microsoft Open Specifications markdown corpus, optimized for local file usage and structure-first exploration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Adonis0123/adonis-skills/staged-changes-review', 'community', 'Adonis0123', 'adonis-skills', 'Adonis0123/adonis-skills', 'staged-changes-review', 0, 0, 47, '2026-03-07T14:54:54Z', '2026-03-08T02:14:28.332Z', 'c349ab89600da54106c67671d618315a6b6e1880b75ef0836d9b238f658ed20b', '{"id":"Adonis0123/adonis-skills/staged-changes-review","name":"staged-changes-review","description":{"en":"The staged-changes-review skill provides a checklist-driven review of Git staged changes, benefiting developers by producing reproducible findings through grep-based scanning and closed-question semantic analysis.","zh":"该技能提供了对 Git 阶段性变更的检查清单驱动、确定性的审查，通过结合 grep 基础扫描和闭式问题语义分析生成可复现的结果","ja":"ステージド変更レビュースキルは、Git 変更のチェックリスト駆動の、決定的なレビューを提供します。grep ベースのスキャンとクローズド質問のセマンティクス分析を組み合わせて、再現可能な結果を生成します","ko":"스테이지된 변경 리뷰 스킬은 Git 변경의 체크리스트 주도형, 결정적인 리뷰를 제공합니다. grep 기반 스캔과 폐쇄적 질문의 의미 분석을 결합하여 재현 가능한 결과를 생성합니다","es":"staged-changes-review es una habilidad que utiliza análisis semántico y grep para revisar cambios en Git de manera determinista. Combina escaneo basado en grep con análisis semántico de preguntas cerradas","fr":"staged-changes-review est une compétence qui utilise l''analyse sémantique et grep pour examiner les modifications Git de manière déterministe. Elle combine un balayage basé sur grep avec une analyse sémantique de questions fermées","de":"staged-changes-review ist eine Fähigkeit, die semantische Analyse und grep verwendet, um Git-Änderungen deterministisch zu überprüfen. Sie kombiniert grep-basiertes Scannen mit semantischer Analyse geschlossener Fragen","pt":"O Staged Changes Review é uma ferramenta de IA que utiliza grep-based scanning e análise semântica para revisar alterações no Git de forma determinística e reproduzível.","ru":"Staged Changes Review - это инструмент ИИ, который использует grep-based scanning и семантический анализ для проверки изменений в Git детерминированным и воспроизводимым способом.","ar":"Staged Changes Review هي أداة ذكاء اصطناعي تستخدم فحص قائم على grep وتحليل семантиكي لمراجعة التغييرات في Git بطريقة محددة وقابلة للتكرار."},"seo":{"title":{"en":"staged-changes-review: Checklist-Driven Git Review for AI...","zh":"Git 阶段性变更审查技能 - 代码扫描和语义分析指南","ja":"ステージド変更レビュースキル - Git 変更のコードスキャンとセマンティクス分析","ko":"스테이지된 변경 리뷰 스킬 - 코드스キャ닝과 의미 분석 가이드","es":"Guía de configuración para staged-changes-review con Agen...","fr":"Configurer staged-changes-review avec les Outils d''IA pou...","de":"Einrichtungsleitfaden für staged-changes-review mit KI-Ag...","pt":"Guia de Configuração do Staged Changes Review - Ferrament...","ru":"Настройка Staged Changes Review - ИИ Агенты для разработч...","ar":"دليل إعداد Staged Changes Review - أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how staged-changes-review streamlines Git workflows with deterministic scanning and semantic analysis. Learn how to implement this AI agent skill to...","zh":"利用 Git 阶段性变更审查技能，结合 grep 基础扫描和闭式问题语义分析，实现代码变更的可复现审查","ja":"ステージド変更レビュースキルを使用して、Git 変更を効率的にレビューします。grep ベースのスキャンとクローズド質問のセマンティクス分析を組み合わせた、再現可能な結果を生成します","ko":"스테이지된 변경 리뷰 스킬을 사용하여 Git 변경을 효율적으로 리뷰하세요. grep 기반 스캔과 폐쇄적 질문의 의미 분석을 결합한 재현 가능한 결과를 생성합니다","es":"Aprende a configurar staged-changes-review para revisar cambios en Git de manera determinista con Agentes de IA y mejora tu flujo de trabajo","fr":"Découvrez comment configurer staged-changes-review pour examiner les modifications Git de manière déterministe avec les Outils d''IA et améliorer votre flux d...","de":"Erfahren Sie, wie Sie staged-changes-review einrichten, um Git-Änderungen deterministisch mit KI-Agenten zu überprüfen und Ihren Arbeitsablauf zu verbessern","pt":"Aprenda a configurar o Staged Changes Review, uma ferramenta de IA que ajuda a revisar alterações no Git de forma determinística e reproduzível.","ru":"Узнайте, как настроить Staged Changes Review, инструмент ИИ, который помогает проверять изменения в Git детерминированным и воспроизводимым способом.","ar":"تعرف على كيفية إعداد Staged Changes Review، أداة ذكاء اصطناعي تساعد في مراجعة التغييرات في Git بطريقة محددة وقابلة للتكرار."},"definition":{"en":"staged-changes-review is a skill that utilizes Git diff commands and semantic analysis to review staged changes, ensuring reproducible and accurate results.","zh":"Git 阶段性变更审查技能是一种结合代码扫描和语义分析的技术，用于对 Git 阶段性变更进行自动化审查","ja":"ステージド変更レビュースキルは、Git 変更を自動的にレビューするために、コードスキャンとセマンティクス分析を組み合わせた技術です","ko":"스테이지된 변경 리뷰 스킬은 Git 변경을 자동으로 리뷰하기 위한 코드스キャ닝과 의미 분석을 결합한 기술입니다","es":"staged-changes-review es una habilidad de Agentes de IA que realiza una revisión determinista de los cambios en Git","fr":"staged-changes-review est une compétence des Outils d''IA qui effectue une révision déterministe des modifications Git","de":"staged-changes-review ist eine Fähigkeit von KI-Agenten, die eine deterministische Überprüfung von Git-Änderungen durchführt","pt":"O Staged Changes Review é uma ferramenta de IA que revisa alterações no Git de forma determinística e reproduzível.","ru":"Staged Changes Review - это инструмент ИИ, который проверяет изменения в Git детерминированным и воспроизводимым способом.","ar":"Staged Changes Review هي أداة ذكاء اصطناعي تراجع التغييرات في Git بطريقة محددة وقابلة للتكرار."},"features":{"en":["Utilizes Git diff commands for staged changes collection","Employs grep-based scanning for deterministic findings","Performs closed-question semantic analysis for accurate results","Produces reproducible findings and code evidence","Executes an 8-step workflow for thorough review","Supports UTF-8 encoding for consistent output"],"zh":["结合 grep 基础扫描和闭式问题语义分析","生成可复现的审查结果","支持 UTF-8 编码","严格的 8 步工作流程","使用 Git diff 命令收集变更"],"ja":["grep ベースのスキャンとクローズド質問のセマンティクス分析を組み合わせ","再現可能な結果を生成","UTF-8 エンコードをサポート","厳格な 8 ステップのワークフロー","Git diff コマンドを使用して変更を収集"],"ko":["grep 기반 스캔과 폐쇄적 질문의 의미 분석을 결합","재현 가능한 결과를 생성","UTF-8 인코딩 지원","严格한 8 단계 워크플로","Git diff 명령을 사용하여 변경을 수집"],"es":["Revisión determinista de cambios en Git","Análisis semántico de preguntas cerradas","Escaneo basado en grep","Compatibilidad con UTF-8","Salida de resultados en formato profesional y conciso"],"fr":["Examen déterministe des modifications Git","Analyse sémantique de questions fermées","Balayage basé sur grep","Compatibilité avec UTF-8","Sortie des résultats au format professionnel et concis"],"de":["Deterministische Überprüfung von Git-Änderungen","Semantische Analyse geschlossener Fragen","Grep-basiertes Scannen","Unterstützung für UTF-8","Ausgabe der Ergebnisse im professionellen und knappen Format"],"pt":["Revisão de alterações no Git utilizando grep-based scanning","Análise semântica para detectar problemas","Resultados reproduzíveis e determinísticos","Integração com o Git para revisar alterações","Suporte a UTF-8 para saídas de texto","Execução de etapas em ordem estrita para garantir a precisão"],"ru":["Проверка изменений в Git с помощью grep-based scanning","Семантический анализ для обнаружения проблем","Воспроизводимые и детерминированные результаты","Интеграция с Git для проверки изменений","Поддержка UTF-8 для текстовых выводов","Выполнение шагов в строгом порядке для обеспечения точности"],"ar":["مراجعة التغييرات في Git باستخدام فحص قائم على grep","تحليل семантиكي لاكتشاف المشاكل","نتائج قابلة للتكرار ومحددة","التكامل مع Git لمراجعة التغييرات","دعم UTF-8 للنصوص الناتجة","تنفيذ الخطوات بالترتيب الصارم لضمان الدقة"]},"keywords":{"en":["how to use staged-changes-review","staged-changes-review setup guide","Git diff commands for staged changes","deterministic scanning in staged-changes-review","staged-changes-review vs traditional code review","staged-changes-review install for AI agents","semantic analysis for code review","checklist-driven Git review","reproducible findings in staged-changes-review"],"zh":["Git 阶段性变更审查","代码扫描","语义分析","grep 基础扫描","闭式问题","自动化审查","UTF-8 编码","Git diff 命令"],"ja":["ステージド変更レビュー","コードスキャン","セマンティクス分析","grep ベースのスキャン","クローズド質問","自動レビュー","UTF-8 エンコード","Git diff コマンド"],"ko":["스테이지된 변경 리뷰","코드스キャ닝","의미 분석","grep 기반 스캔","폐쇄적 질문","자동 리뷰","UTF-8 인코딩","Git diff 명령"],"es":["Agentes de IA","herramientas de desarrollo","revisión de cambios en Git","análisis semántico","grep","UTF-8","desarrollo de software","flujo de trabajo de desarrollo"],"fr":["Outils d''IA","outils de développement","examen des modifications Git","analyse sémantique","grep","UTF-8","développement de logiciels","flux de travail de développement"],"de":["KI-Agenten","Entwicklungstools","Überprüfung von Git-Änderungen","semantische Analyse","grep","UTF-8","Softwareentwicklung","Entwicklungsarbeitsablauf"],"pt":["Staged Changes Review","Ferramentas de IA para desenvolvedores","Revisão de alterações no Git","Grep-based scanning","Análise semântica","Resultados reproduzíveis","Integração com Git","Desenvolvimento de software"],"ru":["Staged Changes Review","ИИ Агенты для разработчиков","Проверка изменений в Git","Grep-based scanning","Семантический анализ","Воспроизводимые результаты","Интеграция с Git","Разработка программного обеспечения"],"ar":["Staged Changes Review","أدوات الذكاء الاصطناعي للمطورين","مراجعة التغييرات في Git","فحص قائم على grep","تحليل семантиكي","نتائج قابلة للتكرار","التكامل مع Git","تطوير البرمجيات"]}},"owner":"Adonis0123","repo":"adonis-skills","repoPath":"Adonis0123/adonis-skills","stars":0,"forks":0,"updatedAt":"2026-03-07T14:54:54Z","topics":["ai","artificial-intelligence","llm","machine-learning","skills"],"category":"community","skillMd":{"name":"staged-changes-review","description":"Checklist-driven review of staged Git changes with deterministic rule scanning and semantic analysis. Use when the user wants to review staged changes, check for errors before commit, or validate code quality before committing.","version":"2.1.0","bodyPreview":"# Staged Changes Review\n\nChecklist-driven, deterministic review of Git staged changes. Produces reproducible findings by combining grep-based scanning with closed-question semantic analysis.\n\n## 输出要求\n\n**重要：本技能必须使用中文输出所有分析结果和建议。**\n\n- **语言**: 始终使用中文回复\n- **编码**: UTF-8\n- **风格**: 专业、简洁，发现必须附带代码证据\n\n## Workflow (8 Steps)\n\nExecute steps in strict order: **0 → 0.5 → 1 → 2 → 2.5 → 3 → 4 → 5**. Do not skip or reorder any step.\n\n### Step 0: Collect Changes\n\n```bash\ngit diff --cached\ngit diff --cached --stat","body":"# Staged Changes Review\n\nChecklist-driven, deterministic review of Git staged changes. Produces reproducible findings by combining grep-based scanning with closed-question semantic analysis.\n\n## 输出要求\n\n**重要：本技能必须使用中文输出所有分析结果和建议。**\n\n- **语言**: 始终使用中文回复\n- **编码**: UTF-8\n- **风格**: 专业、简洁，发现必须附带代码证据\n\n## Workflow (8 Steps)\n\nExecute steps in strict order: **0 → 0.5 → 1 → 2 → 2.5 → 3 → 4 → 5**. Do not skip or reorder any step.\n\n### Step 0: Collect Changes\n\n```bash\ngit diff --cached\ngit diff --cached --stat\ngit diff --cached --name-status\n```\n\nIf no staged changes exist, output \"无暂存变更，审查终止。\" and stop.\n\n### Step 0.5: Detect Project Profile\n\nDetect the project type **once** to determine which rule categories to activate.\n\n```bash\n# Detect framework\npython3 -c \"\nimport json, sys\ntry:\n    with open(''package.json'') as f:\n        d = json.load(f)\n    deps = {**d.get(''dependencies'', {}), **d.get(''devDependencies'', {})}\n    if ''next'' in deps:\n        print(''react-nextjs'')\n    elif ''react'' in deps:\n        print(''react-app'')\n    else:\n        print(''generic'')\nexcept:\n    print(''generic'')\n\" 2>/dev/null || echo \"generic\"\n\n# Count staged file types\ngit diff --cached --name-only | grep -cE ''\\.(tsx|jsx)$'' || echo 0\ngit diff --cached --name-only | grep -cE ''\\.py$'' || echo 0\n```\n\nRecord the detected **profile** — it determines active rule categories:\n\n| Profile | Condition | Active Rule Categories |\n|---------|-----------|----------------------|\n| **react-nextjs** | `next` in dependencies | SEC + REACT + PERF + ASYNC + STR + LOGIC/BREAK |\n| **react-app** | `react` but no `next` | SEC + REACT + ASYNC + STR + LOGIC/BREAK |\n| **python-generic** | Python files majority, no package.json | SEC + STR + LOGIC/BREAK |\n| **generic** | No package.json or detection failed | SEC + STR + LOGIC/BREAK |\n\n**REACT-\\*** and **PERF-\\*** rules are **skipped entirely** for `python-generic` or `generic` profiles. If detection fails, default to `generic`.\n\n### Step 1: Classify Files\n\nClassify every staged file into priority tiers using the rules in `references/review-rules.md` §1.\n\n- Assign each file exactly one priority (P0–P4).\n- **Skip P4 files entirely** — do not read or scan them.\n- Sort remaining files by priority (P0 first, P3 last).\n- Record the file list for the report''s \"审查范围\" section.\n\n### Step 2: Deterministic Scan\n\nFor each file (P0 → P3 order), execute **every applicable** deterministic rule from `references/review-rules.md` §2.\n\n**Execution method:**\n1. Use grep patterns from `references/language-patterns.md` matching the file''s language.\n2. Run each grep against the **staged diff** (`git diff --cached -- <file>`) or the file itself.\n3. If a pattern matches, record a finding immediately — no subjective filtering.\n4. Use the severity from `references/review-rules.md` §4 — do NOT modify severity.\n\n**MANDATORY**: Every rule × file combination must be executed or explicitly marked N/A (wrong file type or inactive profile). Do not skip rules because \"they seem unlikely.\"\n\n### Step 2.5: Impact Scope Analysis\n\nFor P0/P1 files, run a one-time impact scope assessment and record results for the \"影响范围\" section.\n\n```bash\n# 1. New/modified exported symbols in staged diff\ngit diff --cached -U0 -- \"*.ts\" \"*.tsx\" | grep -E \"^\\+export (function|const|class|interface|type)\"\n\n# 2. API route changes\ngit diff --cached --name-only | grep -E \"app/api/|pages/api/\"\n\n# 3. Server Action changes (security impact)\ngit diff --cached -- \"*.ts\" \"*.tsx\" | grep -E ''^[+-].*(\"use server\"|''\"''\"''use server''\"''\"'')''\n\n# 4. Environment variable changes\ngit diff --cached -- \".env*\" 2>/dev/null | grep -E \"^[+-][A-Z_]+\" | head -10\n```\n\nFor each exported symbol found (up to 5 symbols), check reference count:\n\n```bash\n# Replace SYMBOL_NAME with actual symbol\ngrep -rl \"SYMBOL_NAME\" --include=\"*.ts\" --include=\"*.tsx\" src/ 2>/dev/null | wc -l\n```\n\nIf no impact scope items are detected, note \"无显著影响范围变更\" in the report.\n\n### Step 3: Semantic Review\n\nFor each file (P0 → P3 order), answer **every applicable** semantic question from `references/review-rules.md` §3.\n\n**Execution method:**\n1. Read the file''s staged diff and surrounding context (use `Read` tool for full file when needed).\n2. For each semantic rule, answer the closed question with exactly one of:\n   - **YES** — issue found. MUST provide: file:line + evidence snippet.\n   - **NO** — reviewed, no issue found.\n   - **N/A** — rule does not apply to this file type or change.\n3. Only YES answers produce findings. Use the severity from §4.\n\n**MANDATORY**: Answer every question. Do not skip questions because context seems insufficient — answer N/A with a brief reason instead.\n\n### Step 4: Merge & Deduplicate\n\n1. Collect all findings from Steps 2 and 3.\n2. Generate a fingerprint for each finding: `{ruleId}:{file}:{line}`.\n3. Deduplicate by fingerprint — if the same fingerprint appears from both a deterministic and semantic rule, keep the one with higher severity.\n4. Group findings by severity: CRITICAL → HIGH → MEDIUM → LOW.\n5. Apply output budget limits from `references/report-template.md` §3.\n\n### Step 5: Generate Report\n\nOutput the report using the exact structure from `references/report-template.md` §2.\n\n1. **审查范围**: file counts and rule counts.\n2. **发现总览**: severity summary table.\n3. **结论**: auto-select from `references/review-rules.md` §5 based on highest severity found.\n4. **分级发现**: findings in `references/report-template.md` §1 format, grouped by severity.\n5. **文件审查矩阵**: per-file summary table.\n\n## Execution Constraints (MANDATORY)\n\nThese constraints are non-negotiable. Violating any constraint invalidates the review.\n\n1. **No skipping**: Every rule must be evaluated against every applicable file. Document N/A explicitly.\n2. **No free-form analysis**: Only report findings that match a defined rule ID. Do not invent new categories.\n3. **Forced answers**: Every semantic question must receive YES, NO, or N/A. Leaving a question unanswered is forbidden.\n4. **Evidence lock**: Every YES finding must cite a specific file:line and include a code snippet. Findings without evidence are invalid.\n5. **Severity is immutable**: Use the severity from the mapping table. Do not upgrade or downgrade based on subjective judgment.\n6. **Conclusion is templated**: The conclusion must be one of the four templates in review-rules.md §5. Do not write a custom conclusion.\n7. **Fingerprint required**: Every finding must include a fingerprint in `{ruleId}:{file}:{line}` format.\n\n## Context Budget Strategy\n\nWhen staged changes are large (>500 lines or >15 files):\n\n- **P0 files**: Always read full content — security-critical.\n- **P1 files**: Read full diff. If a single file diff >200 lines, focus on: function signatures, exported symbols, error handling blocks, and security-sensitive patterns.\n- **P2 files**: Read diff only. Focus on SEC rules and BREAK-003/BREAK-004.\n- **P3 files**: Scan diff headers only. Apply STR rules only.\n- If total context would exceed capacity, process files strictly by priority and stop at capacity with a note: \"剩余 N 个低优先级文件未审查\".\n\n**REACT/ASYNC rule sampling limit**: For rules that require Read tool for semantic verification (REACT-001, REACT-003, ASYNC-001, ASYNC-002), if grep returns more than 5 matches, take the **first 5 matches only** and note \"N 处未验证（采样限制）\". This prevents excessive Read tool calls.\n\n## Validator Interface Contract\n\nThis skill''s output is consumed by `staged-review-validator`. The following fields are required for compatibility:\n\n- Finding title must include `[ruleId]` prefix (e.g., `[SEC-003] SQL 拼接风险`)\n- Each finding must include a `指纹` (Fingerprint) field\n- Severity uses 4 levels: CRITICAL / HIGH / MEDIUM / LOW\n- Report structure follows `references/report-template.md` §2\n\n## References\n\n- `references/review-rules.md` — Rule definitions, file classification, severity mapping\n- `references/report-template.md` — Finding format, report structure, output budget\n- `references/language-patterns.md` — Language-specific grep patterns by rule ID\n"},"lastSynced":"2026-03-08T02:14:28.332Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing deterministic Git staged changes analysis.","zh":"非常适合需要确定性 Git 暂存变更分析的代码审查代理。","ja":"Git のステージされた変更の分析が決定論的なコードレビューエージェントに最適です。","ko":"결정적 Git 스테이징 변경 분석이 필요한 코드审查 에이전트에 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan un análisis determinista de los cambios de Git en espera.","fr":"Parfait pour les agents de revue de code nécessitant une analyse déterministe des modifications Git en attente.","de":"Perfekt für Code-Review-Agents, die eine deterministische Analyse von Git-Staging-Änderungen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que precisam de análise de alterações estágios do Git determinísticas.","ru":"Идеально для агентов кодового обзора, которым необходим детерминированный анализ изменений Git.","ar":"مثالي للوكلاء المراجعة الكود الذي يحتاج إلى تحليل التغييرات المرحلية Git محددة"},"recommendation":{"en":"Empowers agents to perform reproducible reviews of Git staged changes using grep-based scanning and closed-question semantic analysis, ensuring high-quality code submissions through UTF-8 encoded outputs.","zh":"赋予代理执行可复现的 Git 暂存变更审查，使用基于 grep 的扫描和封闭问题语义分析，确保通过 UTF-8 编码输出提交高质量的代码。","ja":"エージェントに、grepベースのスキャニングとクローズドクエスチョンセマンティック分析を使用して、Git のステージされた変更の可再現性のあるレビューを実行する能力を提供し、UTF-8 エンコード出力を介して高品質のコードの提出を保証する。","ko":"grep 기반 스캔과 폐쇄 질문 의미 분석을 사용하여 재현 가능한 Git 스테이징 변경 리뷰를 수행할 수 있는 에이전트를 활성화하여 UTF-8 인코딩 출력을 통해 높은 품질의 코드 제출을 보장합니다.","es":"Habilita a los agentes a realizar revisiones reproducibles de los cambios de Git en espera utilizando un análisis semántico basado en grep y preguntas cerradas, garantizando la presentación de código de alta calidad a través de salidas codificadas en UTF-8.","fr":"Permet aux agents d''effectuer des revues reproductibles des modifications Git en attente en utilisant un balayage basé sur grep et une analyse sémantique à questions fermées, garantissant la soumission de code de haute qualité via des sorties codées en UTF-8.","de":"Ermächtigt Agenten, reproduzierbare Überprüfungen von Git-Staging-Änderungen durchzuführen, indem sie grep-basiertes Scannen und geschlossene semantische Analyse verwenden, um eine hochwertige Code-Einreichung durch UTF-8-codierte Ausgaben sicherzustellen.","pt":"Habilita os agentes a realizar revisões reprodutíveis das alterações estágios do Git usando varredura baseada em grep e análise semântica de perguntas fechadas, garantindo a alta qualidade das submissões de código por meio de saídas codificadas em UTF-8.","ru":"Наделяет агентов возможностью проводить воспроизводимые обзоры изменений Git, используя сканирование на основе grep и семантический анализ закрытых вопросов, обеспечивая высококачественные кодовые подачи через выходные данные, закодированные в UTF-8.","ar":"يمنح الوكلاء القدرة على إجراء مراجعات قابلة للتكرار للتغييرات المرحلية Git باستخدام مسح قائم على grep وتحليل دلالات الأسئلة المغلقة، مما يضمن جودة عالية للمساهمات في الشفرة من خلال مخرجات مشفرة في UTF-8"},"useCases":{"en":["Automating Git staged changes review for consistency and accuracy","Generating reproducible findings for code quality assurance","Debugging Git staged changes through deterministic analysis"],"zh":["自动化 Git 暂存变更的一致性和准确性审查","生成可复现的代码质量保证发现","通过确定性分析调试 Git 暂存变更"],"ja":["一貫性と精度のための Git のステージされた変更のレビューを自動化する","コード品質保