INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Adonis0123/adonis-skills/staged-changes-review', 'staged-changes-review', 'Adonis0123', 'adonis-skills', 'community', 'staged-changes-review Adonis0123 adonis-skills community ai artificial-intelligence llm machine-learning skills The staged-changes-review skill provides a checklist-driven review of Git staged changes, benefiting developers by producing reproducible findings through grep-based scanning and closed-question semantic analysis. 该技能提供了对 Git 阶段性变更的检查清单驱动、确定性的审查，通过结合 grep 基础扫描和闭式问题语义分析生成可复现的结果 ステージド変更レビュースキルは、Git 変更のチェックリスト駆動の、決定的なレビューを提供します。grep ベースのスキャンとクローズド質問のセマンティクス分析を組み合わせて、再現可能な結果を生成します 스테이지된 변경 리뷰 스킬은 Git 변경의 체크리스트 주도형, 결정적인 리뷰를 제공합니다. grep 기반 스캔과 폐쇄적 질문의 의미 분석을 결합하여 재현 가능한 결과를 생성합니다 staged-changes-review es una habilidad que utiliza análisis semántico y grep para revisar cambios en Git de manera determinista. Combina escaneo basado en grep con análisis semántico de preguntas cerradas staged-changes-review est une compétence qui utilise l''analyse sémantique et grep pour examiner les modifications Git de manière déterministe. Elle combine un balayage basé sur grep avec une analyse sémantique de questions fermées staged-changes-review ist eine Fähigkeit, die semantische Analyse und grep verwendet, um Git-Änderungen deterministisch zu überprüfen. Sie kombiniert grep-basiertes Scannen mit semantischer Analyse geschlossener Fragen O Staged Changes Review é uma ferramenta de IA que utiliza grep-based scanning e análise semântica para revisar alterações no Git de forma determinística e reproduzível. Staged Changes Review - это инструмент ИИ, который использует grep-based scanning и семантический анализ для проверки изменений в Git детерминированным и воспроизводимым способом. Staged Changes Review هي أداة ذكاء اصطناعي تستخدم فحص قائم على grep وتحليل семантиكي لمراجعة التغييرات في Git بطريقة محددة وقابلة للتكرار. how to use staged-changes-review staged-changes-review setup guide Git diff commands for staged changes deterministic scanning in staged-changes-review staged-changes-review vs traditional code review staged-changes-review install for AI agents semantic analysis for code review checklist-driven Git review reproducible findings in staged-changes-review Git 阶段性变更审查 代码扫描 语义分析 grep 基础扫描 闭式问题 自动化审查 UTF-8 编码 Git diff 命令 Utilizes Git diff commands for staged changes collection Employs grep-based scanning for deterministic findings Performs closed-question semantic analysis for accurate results Produces reproducible findings and code evidence Executes an 8-step workflow for thorough review Supports UTF-8 encoding for consistent output staged-changes-review is a skill that utilizes Git diff commands and semantic analysis to review staged changes, ensuring reproducible and accurate results.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('daominah/gostructure/review-code-and-pr', 'community', 'daominah', 'gostructure', 'daominah/gostructure', 'review-code-and-pr', 0, 0, 47, '2026-03-07T15:30:14Z', '2026-03-08T02:17:31.822Z', 'b57fbb6c7b01216500544f71734f8462cd67acc924c8916027bc027037be10d4', '{"id":"daominah/gostructure/review-code-and-pr","name":"review-code-and-pr","description":{"en":"The review-code-and-pr skill provides a template repository for starting a new Go service, separating business logic from infrastructure for easier testing and modification. It benefits developers by including common boilerplate files.","zh":"review-code-and-pr技能提供了一个Go服务模板，帮助您组织代码和处理PR","ja":"review-code-and-prスキルは、コードを整理しPRを処理するためのGoサービステンプレートを提供する","ko":"review-code-and-pr 스킬은 코드를 정리하고 PR을 처리하는 Go 서비스 템플릿을 제공합니다","es":"Revisión de código y PR para Go, con separación de lógica de negocio y infraestructura para una mayor facilidad de prueba y cambio","fr":"Examen de code et PR pour Go, avec séparation de la logique métier et de l''infrastructure pour une plus grande facilité de test et de modification","de":"Code- und PR-Überprüfung für Go, mit Trennung von Geschäftslogik und Infrastruktur für eine einfachere Test- und Änderungsmöglichkeit","pt":"O review-code-and-pr é um modelo de repositório para iniciar um novo serviço Go, separando a lógica de negócios da infraestrutura","ru":"ИИ Агент review-code-and-pr - это шаблон репозитория для начала нового сервиса Go, разделяющий бизнес-логику и инфраструктуру","ar":"وكيل المراجعة review-code-and-pr هو قالب لمستودع لبدء خدمة Go جديدة، يفصل بين منطق العمل والبنية التحتية"},"seo":{"title":{"en":"review-code-and-pr: Code Review Setup Guide | AI Agent Skill","zh":"代码审查和PR模板设置指南","ja":"コードレビューとPRのテンプレート設定ガイド","ko":"코드 리뷰와 PR 템플릿 설정 가이드","es":"Guía de configuración para revisión de código y PR con Go","fr":"Configurer