INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('daominah/gostructure/review-code-and-pr', 'review-code-and-pr', 'daominah', 'gostructure', 'community', 'review-code-and-pr daominah gostructure community The review-code-and-pr skill provides a template repository for starting a new Go service, separating business logic from infrastructure for easier testing and modification. It benefits developers by including common boilerplate files. review-code-and-pr技能提供了一个Go服务模板，帮助您组织代码和处理PR review-code-and-prスキルは、コードを整理しPRを処理するためのGoサービステンプレートを提供する review-code-and-pr 스킬은 코드를 정리하고 PR을 처리하는 Go 서비스 템플릿을 제공합니다 Revisión de código y PR para Go, con separación de lógica de negocio y infraestructura para una mayor facilidad de prueba y cambio Examen de code et PR pour Go, avec séparation de la logique métier et de l''infrastructure pour une plus grande facilité de test et de modification Code- und PR-Überprüfung für Go, mit Trennung von Geschäftslogik und Infrastruktur für eine einfachere Test- und Änderungsmöglichkeit O review-code-and-pr é um modelo de repositório para iniciar um novo serviço Go, separando a lógica de negócios da infraestrutura ИИ Агент review-code-and-pr - это шаблон репозитория для начала нового сервиса Go, разделяющий бизнес-логику и инфраструктуру وكيل المراجعة review-code-and-pr هو قالب لمستودع لبدء خدمة Go جديدة، يفصل بين منطق العمل والبنية التحتية how to use review-code-and-pr review-code-and-pr setup guide review-code-and-pr alternative review-code-and-pr vs git code review review-code-and-pr install what is review-code-and-pr review-code-and-pr for Go developers code review best practices with review-code-and-pr 代码审查 PR处理 AI工具 Go服务 代码组织 基础设施代码 业务逻辑代码 代码测试 代码修改 Separates business logic code from infrastructure for easier testing and modification Includes common boilerplate files for streamlined development Outputs review verdicts in a structured format, including APPROVE or REQUEST_CHANGES Provides a summary of changes and how they meet review criteria Lists blockers that must be resolved before merging review-code-and-pr is a template repository for initiating Go services, emphasizing separation of business logic and infrastructure for enhanced testability and maintainability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ThinkEx-OSS/thinkex/primitives', 'community', 'ThinkEx-OSS', 'thinkex', 'ThinkEx-OSS/thinkex', 'primitives', 0, 0, 47, '2026-03-06T12:59:22.295Z', '2026-03-06T15:27:25.038Z', '6fd1f89b86e7bc95754de6961dc9ec241310c5eb88623782e0977065f7c81e79', '{"id":"ThinkEx-OSS/thinkex/primitives","name":"primitives","description":{"en":"Primitives provides composable, unstyled UI components following Radix UI patterns for AI agents. It benefits developers building custom AI interfaces.","zh":"Primitives 是一种重新思考 AI 用户界面的方法，提供可组合、无样式的组件","ja":"Primitives は、AI エージェントのユーザーインターフェイスを再考する方法であり、組み合わせ可能でスタイルのないコンポーネントを提供する","ko":"Primitives 는 AI 에이전트의 사용자 인터페이스를 재고하는 방법으로, 구성 가능한 无 스타일 구성 요소를 제공합니다","es":"Primitives es un conjunto de componentes componibles y sin estilo que siguen los patrones de Radix UI para redefinir la interfaz de usuario de la IA","fr":"Primitives est un ensemble de composants componibles et sans style qui suivent les modèles de Radix UI pour réinventer l''interface utilisateur de l''IA","de":"Primitives ist ein Satz von komponiblen und ungestalteten Komponenten, die den Radix-UI-Mustern folgen, um die Benutzeroberfläche von KI neu zu definieren","pt":"Primitives é um conjunto de componentes compostáveis e sem estilos para criar interfaces de usuário personalizadas para IA. Siga o guia de configuração para começar.","ru":"Примитивы - это набор составных и нестилизованных компонентов для создания персонализированных интерфейсов пользователя для ИИ Агентов. Следуйте руководству по настройке, чтобы начать.","ar":"الأشكال الأولية هي مجموعة من المكونات القابلة للتكوين وغير المُصممة لإنشاء واجهات مستخدم مخصصة للوكلاء الذكيين. اتبع دليل الإعداد لبدء استخدامها"},"seo":{"title":{"en":"Primitives: Composable UI Components for AI Agents | AI A...","zh":"Primitives Setup Guide: 重新思考 AI 用户界面","ja":"Primitives 導入ガイド: AI エージェントのユーザーインターフェイスを再考する","ko":"Primitives 설정 가이드: AI 에이전트의 사용자 인터페이스를 재고하는 방법","es":"Primitives: Guía de configuración para interfaces de usua...","fr":"Primitives: Guide de démarrage pour les interfaces utilis...","de":"Primitives: Einrichtungsleitfaden für Benutzeroberflächen...","pt":"Primitives: Guia de Configuração para Interfaces de Usuár...","ru":"Примитивы: Руководство по Настройке Интерфейса Пользовате...","ar":"الأشكال الأولية: دليل الإعداد لواجهة المستخدم للوكلاء الذ..."},"description":{"en":"Discover how Primitives rethinks the User Interface of AI with unstyled, composable components. Learn more and get started with the latest API today!","zh":"了解 Primitives 的技术细节，包括可组合、无样式的组件和 Radix UI 模式","ja":"Primitives の技術的詳細を学ぶ、組み合わせ可能でスタイルのないコンポーネントと Radix UI パターンを含む","ko":"Primitives 의 기술적 세부 사항을 알아보세요. 구성 가능한 无 스타일 구성 요소 및 Radix UI 패턴 포함","es":"Descubre cómo redefinir la interfaz de usuario de la IA con Primitives, componentes personalizables y sin estilo que siguen los patrones de Radix UI","fr":"Découvrez comment réinventer l''interface utilisateur de l''IA avec Primitives, des composants personnalisables et sans style qui suivent les modèles de Radix UI","de":"Erfahren Sie, wie Sie die Benutzeroberfläche von KI mit Primitives neu definieren können, anpassbare und ungestaltete Komponenten, die den Radix-UI-Mustern f...","pt":"Aprenda a utilizar primitivas para criar interfaces de usuário personalizadas para IA. Descubra como integrar componentes compostáveis e sem estilos.","ru":"Узнайте, как использовать примитивы для создания персонализированных интерфейсов пользователя для ИИ Агентов. Откройте для себя, как интегрировать составные ...","ar":"تعرف على كيفية استخدام الأشكال الأولية لإنشاء واجهات مستخدم مخصصة للوكلاء الذكيين. اكتشف كيفية دمج المكونات القابلة للتكوين وغير المُصممة"},"definition":{"en":"Primitives is a set of composable, unstyled UI components for rethinking the User Interface of AI, following Radix UI patterns.","zh":"Primitives 是一种 AI 用户界面组件库，提供可组合、无样式的组件","ja":"Primitives は、AI エージェントのユーザーインターフェイスコンポーネントライブラリであり、組み合わせ可能でスタイルのないコンポーネントを提供する","ko":"Primitives 는 AI 에이전트의 사용자 인터페이스 구성 요소 라이브러리로서, 구성 가능한 无 스타일 구성 요소를 제공합니다","es":"Primitives son componentes de interfaz de usuario personalizables y sin estilo para la creación de interfaces de usuario de AI","fr":"Primitives sont des composants d''interface utilisateur personnalisables et sans style pour la création d''interfaces utilisateur d''IA","de":"Primitives sind anpassbare und ungestaltete Benutzeroberflächenkomponenten für die Erstellung von KI-Benutzeroberflächen","pt":"Primitives são componentes de interface de usuário compostáveis e sem estilos que seguem os padrões da Radix UI.","ru":"Примитивы - это составные и нестилизованные компоненты интерфейса пользователя, следующие шаблонам Radix UI.","ar":"الأشكال الأولية هي مكونات واجهة المستخدم القابلة للتكوين وغير المُصممة التي تتبع أنماط Radix UI"},"features":{"en":["Composable, unstyled components following Radix UI patterns","Includes ThreadPrimitive, ComposerPrimitive, and MessagePrimitive components","References available for deep dives into each component, such as thread.md and composer.md","Always consults the latest API at assistant-ui.com/llms.txt","Supports ActionBar component for customized actions","Follows specific UI patterns for a consistent user experience"],"zh":["可组合、无样式的组件","遵循 Radix UI 模式","提供 ThreadPrimitive、ComposerPrimitive 和 MessagePrimitive","支持最新的 API"],"ja":["組み合わせ可能でスタイルのないコンポーネント","Radix UI パターンに従った設計","ThreadPrimitive、ComposerPrimitive、MessagePrimitive を提供","最新の API をサポート"],"ko":["구성 가능한 无 스타일 구성 요소","Radix UI 패턴을 따름","ThreadPrimitive, ComposerPrimitive, MessagePrimitive 제공","최신 API 지원"],"es":["Componentes componibles que siguen los patrones de Radix UI","Sin estilo para una personalización total","Compatibilidad con la última API de assistant-ui","Referencias detalladas para ThreadPrimitive, ComposerPrimitive y MessagePrimitive","Soporte para la creación de interfaces de usuario de AI personalizadas"],"fr":["Composants componibles qui suivent les modèles de Radix UI","Sans style pour une personnalisation totale","Compatibilité avec la dernière API d''assistant-ui","Références détaillées pour ThreadPrimitive, ComposerPrimitive et MessagePrimitive","Support pour la création d''interfaces utilisateur d''IA personnalisées"],"de":["Komponible Komponenten, die den Radix-UI-Mustern folgen","Ohne Stil für eine vollständige Anpassung","Kompatibilität mit der neuesten API von assistant-ui","Detaillierte Referenzen für ThreadPrimitive, ComposerPrimitive und MessagePrimitive","Unterstützung für die Erstellung von KI-Benutzeroberflächen"],"pt":["Componentes compostáveis e sem estilos","Seguem os padrões da Radix UI","Inclui ThreadPrimitive, ComposerPrimitive e MessagePrimitive","Permite a criação de interfaces de usuário personalizadas para IA","Compatível com a API de assistente-ui"],"ru":["Составные и нестилизованные компоненты","Следуют шаблонам Radix UI","Включает ThreadPrimitive, ComposerPrimitive и MessagePrimitive","Позволяет создавать персонализированные интерфейсы пользователя для ИИ Агентов","Компатибельна с API assistente-ui"],"ar":["المكونات القابلة للتكوين وغير المُصممة","تتبع أنماط Radix UI","تتضمن ThreadPrimitive و ComposerPrimitive و MessagePrimitive","تمكن من إنشاء واجهات مستخدم مخصصة للوكلاء الذكيين","متوافقة مع واجهة برمجة التطبيقات assistente-ui"]},"keywords":{"en":["how to use primitives","primitives alternative","primitives setup guide","what is primitives","primitives vs radix ui","primitives install","composable ui components for ai","radix ui patterns","ai agent interface development"],"zh":["AI 用户界面","Primitives","可组合组件","Radix UI","ThreadPrimitive","ComposerPrimitive","MessagePrimitive","AI 에이전트"],"ja":["AI エージェント","Primitives","組み合わせ可能なコンポーネント","Radix UI","ThreadPrimitive","ComposerPrimitive","MessagePrimitive","AI ユーザーインターフェイス"],"ko":["AI 에이전트","Primitives","구성 가능한 구성 요소","Radix UI","ThreadPrimitive","ComposerPrimitive","MessagePrimitive","AI 사용자 인터페이스"],"es":["primitives ai","interfaces de usuario de ia","radix ui","componentes componibles","assistant-ui","ai herramientas","herramientas de ia para desarrolladores","creación de interfaces de usuario de ai","personalización de interfaces de usuario de ia"],"fr":["primitives ia","interfaces utilisateur d''ia","radix ui","composants componibles","assistant-ui","outils d''ia","outils d''ia pour les développeurs","création d''interfaces utilisateur d''ia","personnalisation d''interfaces utilisateur d''ia"],"de":["primitives ki","benutzeroberflächen von ki","radix ui","komponible komponenten","assistant-ui","ki tools","ki-tools für entwickler","erstellung von ki-benutzeroberflächen","anpassung von ki-benutzeroberflächen"],"pt":["primitives IA","interfaces de usuário personalizadas","componentes compostáveis","Radix UI","assistente-ui","IA agents","desenvolvimento de interfaces de usuário"],"ru":["примитивы ИИ","персонализированные интерфейсы пользователя","составные компоненты","Radix UI","assistente-ui","ИИ Агенты","разработка интерфейсов пользователя"],"ar":["الأشكال الأولية الذكية","واجهات مستخدم مخصصة","المكونات القابلة للتكوين","Radix UI","assistente-ui","الوكلاء الذكيين","تطوير واجهات المستخدم"]}},"owner":"ThinkEx-OSS","repo":"thinkex","repoPath":"ThinkEx-OSS/thinkex","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.295Z","topics":[],"category":"community","skillMd":{"name":"primitives","description":"Guide for assistant-ui UI primitives - ThreadPrimitive, ComposerPrimitive, MessagePrimitive. Use when customizing chat UI components.","version":"0.0.1","bodyPreview":"# assistant-ui Primitives\n\n**Always consult [assistant-ui.com/llms.txt](https://assistant-ui.com/llms.txt) for latest API.**\n\nComposable, unstyled components following Radix UI patterns.\n\n## References\n\n- [./references/thread.md](./references/thread.md) -- ThreadPrimitive deep dive\n- [./references/composer.md](./references/composer.md) -- ComposerPrimitive deep dive\n- [./references/message.md](./references/message.md) -- MessagePrimitive deep dive\n- [./references/action-bar.md](./references/acti","body":"# assistant-ui Primitives\n\n**Always consult [assistant-ui.com/llms.txt](https://assistant-ui.com/llms.txt) for latest API.**\n\nComposable, unstyled components following Radix UI patterns.\n\n## References\n\n- [./references/thread.md](./references/thread.md) -- ThreadPrimitive deep dive\n- [./references/composer.md](./references/composer.md) -- ComposerPrimitive deep dive\n- [./references/message.md](./references/message.md) -- MessagePrimitive deep dive\n- [./references/action-bar.md](./references/action-bar.md) -- ActionBarPrimitive deep dive\n\n## Import\n\n```tsx\nimport {\n  ThreadPrimitive,\n  ComposerPrimitive,\n  MessagePrimitive,\n  ActionBarPrimitive,\n  BranchPickerPrimitive,\n  AttachmentPrimitive,\n  ThreadListPrimitive,\n  ThreadListItemPrimitive,\n} from \"@assistant-ui/react\";\n```\n\n## Primitive Parts\n\n| Primitive | Key Parts |\n|-----------|-----------|\n| `ThreadPrimitive` | `.Root`, `.Viewport`, `.Messages`, `.Empty`, `.ScrollToBottom` |\n| `ComposerPrimitive` | `.Root`, `.Input`, `.Send`, `.Cancel`, `.Attachments` |\n| `MessagePrimitive` | `.Root`, `.Content`, `.Avatar`, `.If` |\n| `ActionBarPrimitive` | `.Copy`, `.Edit`, `.Reload`, `.Speak` |\n| `BranchPickerPrimitive` | `.Previous`, `.Next`, `.Number`, `.Count` |\n\n## Custom Thread Example\n\n```tsx\nfunction CustomThread() {\n  return (\n    <ThreadPrimitive.Root className=\"flex flex-col h-full\">\n      <ThreadPrimitive.Empty>\n        <div className=\"flex-1 flex items-center justify-center\">\n          Start a conversation\n        </div>\n      </ThreadPrimitive.Empty>\n\n      <ThreadPrimitive.Viewport className=\"flex-1 overflow-y-auto p-4\">\n        <ThreadPrimitive.Messages components={{\n          UserMessage: CustomUserMessage,\n          AssistantMessage: CustomAssistantMessage,\n        }} />\n      </ThreadPrimitive.Viewport>\n\n      <ComposerPrimitive.Root className=\"border-t p-4 flex gap-2\">\n        <ComposerPrimitive.Input className=\"flex-1 rounded-lg border px-4 py-2\" />\n        <ComposerPrimitive.Send className=\"bg-blue-500 text-white px-4 py-2 rounded-lg\">\n          Send\n        </ComposerPrimitive.Send>\n      </ComposerPrimitive.Root>\n    </ThreadPrimitive.Root>\n  );\n}\n```\n\n## Conditional Rendering\n\n```tsx\n<MessagePrimitive.If user>User only</MessagePrimitive.If>\n<MessagePrimitive.If assistant>Assistant only</MessagePrimitive.If>\n<MessagePrimitive.If running>Generating...</MessagePrimitive.If>\n<MessagePrimitive.If hasBranches>Has edit history</MessagePrimitive.If>\n\n<ComposerPrimitive.If submitting>\n  <ComposerPrimitive.Cancel>Stop</ComposerPrimitive.Cancel>\n</ComposerPrimitive.If>\n\n<ThreadPrimitive.If empty>No messages</ThreadPrimitive.If>\n```\n\n## Content Parts\n\n```tsx\n<MessagePrimitive.Content components={{\n  Text: ({ part }) => <p>{part.text}</p>,\n  Image: ({ part }) => <img src={part.image} alt=\"\" />,\n  ToolCall: ({ part }) => <div>Tool: {part.toolName}</div>,\n  Reasoning: ({ part }) => <details><summary>Thinking</summary>{part.text}</details>,\n}} />\n```\n\n## Branch Picker\n\n```tsx\n<MessagePrimitive.If hasBranches>\n  <BranchPickerPrimitive.Root className=\"flex items-center gap-1\">\n    <BranchPickerPrimitive.Previous>←</BranchPickerPrimitive.Previous>\n    <span><BranchPickerPrimitive.Number /> / <BranchPickerPrimitive.Count /></span>\n    <BranchPickerPrimitive.Next>→</BranchPickerPrimitive.Next>\n  </BranchPickerPrimitive.Root>\n</MessagePrimitive.If>\n```\n\n## Common Gotchas\n\n**Primitives not rendering**\n- Wrap in `AssistantRuntimeProvider`\n- Ensure parent primitive provides context\n\n**Styles not applying**\n- Primitives are unstyled by default\n- Add className or use `@assistant-ui/styles`\n"},"lastSynced":"2026-03-06T15:27:25.038Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Interface Developers needing customizable, composable UI components following Radix UI patterns.","zh":"非常适合需要可自定义、可组合 UI 组件的 AI 接口开发人员，遵循 Radix UI 模式。","ja":"カスタマイズ可能で構成可能な UI コンポーネントが必要な AI インターフェース開発者に最適です。Radix UI パターンに従っています。","ko":"사용자 정의 가능한 구성 가능한 UI 구성 요소를 필요로 하는 AI 인터페이스 개발자를 위한 완벽한 솔루션으로, Radix UI 패턴을 따릅니다.","es":"Perfecto para desarrolladores de interfaces de AI que necesitan componentes de UI personalizables y componibles que sigan patrones de Radix UI.","fr":"Parfait pour les développeurs d''interfaces d''IA ayant besoin de composants d''interface utilisateur personnalisables et componibles suivant les modèles de Radix UI.","de":"Perfekt für AI-Schnittstellen-Entwickler, die anpassbare, komponierbare Benutzeroberflächen-Komponenten benötigen, die Radix-UI-Mustern folgen.","pt":"Perfeito para desenvolvedores de interface de IA que necessitam de componentes de UI personalizáveis e compostos, seguindo os padrões da Radix UI.","ru":"Идеально для разработчиков интерфейса ИИ, которым необходимы настраиваемые, составные компоненты UI, следующие шаблонам Radix UI.","ar":"مثالي للمطورين واجهة الية الذكية الذين يحتاجون إلى مكونات واجهة المستخدم القابلة للتعديل والتركيب، اتباعًا لنماذج Radix UI."},"recommendation":{"en":"Empowers agents to build custom AI interfaces with unstyled, composable UI components using Radix UI patterns, enabling seamless integration with protocols like llms.txt for always-up-to-date API references.","zh":"赋予代理构建自定义 AI 接口的能力，使用无样式的、可组合的 UI 组件以及 Radix UI 模式，实现与 llms.txt 等协议的无缝集成，始终保持 API 参考的最新状态。","ja":"エージェントがカスタム AI インターフェースを構築できるようにし、スタイルが付与されていない構成可能な UI コンポーネントおよび Radix UI パターンを使用して、llms.txt などのプロトコルとのシームレスな統合を実現し、常に最新の API リファレンスを保持します。","ko":"에이전트가 사용자 정의 AI 인터페이스를 구축할 수 있도록 하며, 스타일이 지정되지 않은 구성 가능한 UI 구성 요소 및 Radix UI 패턴을 사용하여 llms.txt와 같은 프로토콜과의无缝한 통합을 구현하여 항상 최신의 API 참조를 유지합니다.","es":"Habilita a los agentes a crear interfaces de AI personalizadas con componentes de UI no estilizados y componibles que utilizan patrones de Radix UI, lo que permite una integración sin problemas con protocolos como llms.txt para referencias de API siempre actualizadas.","fr":"Permet aux agents de créer des interfaces d''IA personnalisées avec des composants d''interface utilisateur non stylisés et componibles utilisant des modèles de Radix UI, ce qui permet une intégration transparente avec des protocoles comme llms.txt pour des références d''API toujours à jour.","de":"Ermöglicht es Agenten, benutzerdefinierte AI-Schnittstellen mit ungestylten, komponierbaren Benutzeroberflächen-Komponenten zu erstellen, die Radix-UI-Muster verwenden, was eine nahtlose Integration mit Protokollen wie llms.txt für immer aktuelle API-Referenzen ermöglicht.","pt":"Permite que os agentes construam interfaces de IA personalizadas com componentes de UI não estilizados e compostos, usando padrões da Radix UI, possibilitando integração perfeita com protocolos como llms.txt para referências de API sempre atualizadas.","ru":"Наделяет агентов возможностью создавать пользовательские интерфейсы ИИ с нестилизованными, составными компонентами UI, используя шаблоны Radix UI, обеспечивая бесшовную интеграцию с протоколами, такими как llms.txt, для всегда актуальных ссылок на API.","ar":"تمكن الوكلاء من بناء واجهات لية ذكية مخصصة مع مكونات واجهة المستخدم غير المطورة والقابلة للتركيب، باستخدام نماذج Radix UI، وتمكين التكامل السلس مع البروتوكولات مثل llms.txt لمراجع API محدثة دائمًا."},"useCases":{"en":["Composing custom ThreadPrimitives for advanced conversation flows","Creating reusable ComposerPrimitives for efficient message composition","Designing intuitive MessagePrimitives for enhanced user interaction"],"zh":["组合自定义 ThreadPrimitives 以实现高级对话流程","创建可重用的 ComposerPrimitives 以实现高效的消息组成","设计直观的 MessagePrimitives 以增强用户交互"],"ja":["高度な会話フローを実現するためにカスタム ThreadPrimitives を構成する","効率的なメッセージ構成を実現するために再利用可能な ComposerPrimitives を作成する","ユーザーインタラクションを強化するために直感的な MessagePrimitives を設計する"],"ko":["고급 대화 흐름을 구현하기 위해 사용자 정의 ThreadPrimitives를 구성하는 것","효율적인 메시지 구성하기 위해 재사용 가능한 ComposerPrimitives를 생성하는 것","사용자 상호 작용을 향상시키기 위해直관적인 MessagePrimitives를 설계하는 것"],"es":["Componer ThreadPrimitives personalizados para flujos de conversación avanzados","Crear ComposerPrimitives reutilizables para una composición de mensajes eficiente","Diseñar MessagePrimitives intuitivos para una interacción del usuario mejorada"],"fr":["Composer des ThreadPrimitives personnalisés pour des flux de conversation avancés","Créer des ComposerPrimitives réutilisables pour une composition de messages efficace","Concevoir des MessagePrimitives intuitifs pour une interaction utilisateur améliorée"],"de":["Erstellen von benutzerdefinierten ThreadPrimitives für erweiterte Gesprächsflüsse","Erstellen wiederverwendbarer ComposerPrimitives für eine effiziente Nachrichtenkomposition","Entwerfen von intuitiven MessagePrimitives für eine verbesserte Benutzerinteraktion"],"pt":["Compor primitivos personalizados de Thread para fluxos de conversa avançados","Criar primitivos de Composer reutilizáveis para composição de mensagens eficiente","Projetar primitivos de Message intuitivos para interação do usuário aprimorada"],"ru":["Составление пользовательских примитивов Thread для расширенных потоков разговора","Создание многократно используемых примитивов Composer для эффективной композиции сообщений","Проектирование интуитивных примитивов Message для улучшения взаимодействия пользователя"],"ar":["تركيب بدائيات الخيط المخصصة لتدفقات الحوار المتقدمة","إنشاء بدائيات مركب قابلة لإعادة الاستخدام لتركيبة رسائل فعالة","تصميم بدائيات رسائل بديهية لتعزيز التفاعل مع المستخدم"]},"limitations":{"en":["Requires consultation of assistant-ui.com/llms.txt for latest API","Radix UI pattern compatibility required"],"zh":["需要查阅 assistant-ui.com/llms.txt 以获取最新的 API","需要兼容 Radix UI 模式"],"ja":["最新の API を取得するために assistant-ui.com/llms.txt を参照する必要がある","Radix UI パターンとの互換性が必要"],"ko":["최신 API를 얻으려면 assistant-ui.com/llms.txt를 참조해야 함","Radix UI 패턴과 호환성이 필요"],"es":["Requiere la consulta de assistant-ui.com/llms.txt para la última API","Se requiere compatibilidad con el patrón de Radix UI"],"fr":["Nécessite la consultation de assistant-ui.com/llms.txt pour la dernière API","La compatibilité avec le modèle de Radix UI est requise"],"de":["Erfordert die Konsultation von assistant-ui.com/llms.txt für die neueste API","Kompatibilität mit dem Radix-UI-Muster ist erforderlich"],"pt":["Exige consulta do assistant-ui.com/llms.txt para a última API","Compatibilidade com padrão da Radix UI é necessária"],"ru":["Требует консультации assistant-ui.com/llms.txt для последней API","Совместимость с шаблоном Radix UI обязательна"],"ar":["يتطلب استشارة assistant-ui.com/llms.txt لآخر واجهة برمجة التطبيقات","متطلبات التوافق مع نمط Radix UI"]},"version":4},"contentHash":"6fd1f89b86e7bc95754de6961dc9ec241310c5eb88623782e0977065f7c81e79","qualityScore":47}');
