INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ThinkEx-OSS/thinkex/primitives', 'primitives', 'ThinkEx-OSS', 'thinkex', 'community', 'primitives ThinkEx-OSS thinkex community Primitives provides composable, unstyled UI components following Radix UI patterns for AI agents. It benefits developers building custom AI interfaces. Primitives 是一种重新思考 AI 用户界面的方法，提供可组合、无样式的组件 Primitives は、AI エージェントのユーザーインターフェイスを再考する方法であり、組み合わせ可能でスタイルのないコンポーネントを提供する Primitives 는 AI 에이전트의 사용자 인터페이스를 재고하는 방법으로, 구성 가능한 无 스타일 구성 요소를 제공합니다 Primitives es un conjunto de componentes componibles y sin estilo que siguen los patrones de Radix UI para redefinir la interfaz de usuario de la IA Primitives est un ensemble de composants componibles et sans style qui suivent les modèles de Radix UI pour réinventer l''interface utilisateur de l''IA Primitives ist ein Satz von komponiblen und ungestalteten Komponenten, die den Radix-UI-Mustern folgen, um die Benutzeroberfläche von KI neu zu definieren Primitives é um conjunto de componentes compostáveis e sem estilos para criar interfaces de usuário personalizadas para IA. Siga o guia de configuração para começar. Примитивы - это набор составных и нестилизованных компонентов для создания персонализированных интерфейсов пользователя для ИИ Агентов. Следуйте руководству по настройке, чтобы начать. الأشكال الأولية هي مجموعة من المكونات القابلة للتكوين وغير المُصممة لإنشاء واجهات مستخدم مخصصة للوكلاء الذكيين. اتبع دليل الإعداد لبدء استخدامها how to use primitives primitives alternative primitives setup guide what is primitives primitives vs radix ui primitives install composable ui components for ai radix ui patterns ai agent interface development AI 用户界面 Primitives 可组合组件 Radix UI ThreadPrimitive ComposerPrimitive MessagePrimitive AI 에이전트 Composable, unstyled components following Radix UI patterns Includes ThreadPrimitive, ComposerPrimitive, and MessagePrimitive components References available for deep dives into each component, such as thread.md and composer.md Always consults the latest API at assistant-ui.com/llms.txt Supports ActionBar component for customized actions Follows specific UI patterns for a consistent user experience Primitives is a set of composable, unstyled UI components for rethinking the User Interface of AI, following Radix UI patterns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('comet-ml/opik/typescript-sdk', 'community', 'comet-ml', 'opik', 'comet-ml/opik', 'typescript-sdk', 17827, 1358, 46, '2026-02-26T01:28:05Z', '2026-03-06T02:31:58.561Z', 'a71faae487523ae5e9c6f5ae632977ce8d24d100bfecce45ecb6b7cfd784ae7f', '{"id":"comet-ml/opik/typescript-sdk","name":"typescript-sdk","description":{"en":"The TypeScript SDK provides comprehensive tracing, automated evaluations, and monitoring for LLM applications, RAG systems, and agentic workflows. It is designed for developers building production-ready AI applications with LangChain, LlamaIndex, and other frameworks.","zh":"该TypeScript SDK专为LLM应用和代理工作流设计，提供分层非阻塞架构和异步数据缓冲功能。支持Node.js 18+环境，包含完整的ESM和CJS构建，可与LangChain和LlamaIndex无缝集成，实现全面的跟踪和评估。","ja":"このTypeScript SDKはLLMアプリケーションとエージェントワークフロー向けに設計され、階層型非ブロッキングアーキテクチャと非同期データバッファリング機能を提供します。Node.js 18+環境をサポートし、完全なESMおよびCJSビルドを含み、LangChainやLlamaIndexとシームレスに連携し、包括的なトレースと評価を実現します。","ko":"이 TypeScript SDK는 LLM 애플리케이션과 에이전트 워크플로우를 위해 설계되었으며, 계층적 논블로킹 아키텍처와 비동기 데이터 버퍼링 기능을 제공합니다. Node.js 18+ 환경을 지원하며, 완전한 ESM 및 CJS 빌드를 포함하고 LangChain 및 LlamaIndex와 원활하게 통합되어 포괄적인 추적 및 평가를 가능하게 합니다.","es":"El TypeScript SDK permite instrumentar aplicaciones LLM, sistemas RAG y flujos de trabajo agentes con tracing detallado, evaluaciones automatizadas y dashboards listos para producción.","fr":"Le SDK TypeScript permet d''instrumenter les applications LLM, systèmes RAG et flux de travail agents avec un tracing détaillé, des évaluations automatisées et des tableaux de bord prêts pour la production.","de":"Das TypeScript SDK ermöglicht die Instrumentierung von LLM-Anwendungen, RAG-Systemen und Agenten-Workflows mit detailliertem Tracing, automatisierten Auswertungen und produktionsreifen Dashboards.","pt":"O SDK TypeScript oferece tracing abrangente, avaliações automatizadas e dashboards para monitorar aplicações de IA, sistemas RAG e fluxos de trabalho agenticos. Construído para Node.js >=18 com suporte a ESM e CJS.","ru":"TypeScript SDK предоставляет комплексное трассирование, автоматизированную оценку и дашборды для мониторинга ИИ-приложений, RAG-систем и агентских workflow. Создан для Node.js >=18 с поддержкой ESM и CJS.","ar":"يوفر TypeScript SDK تتبعًا شاملاً وتقييمات تلقائية ولوحات تحكم لمراقبة تطبيقات الذكاء الاصطناعي وأنظمة RAG وسير العمل الوكيلة. مبني لـ Node.js >=18 مع دعم ESM و CJS."},"seo":{"title":{"en":"TypeScript SDK: LLM Tracing & Evaluation Setup Guide | AI...","zh":"TypeScript SDK 设置指南 - LLM 应用调试与监控","ja":"TypeScript SDK セットアップガイド - LLMアプリのデバッグと監視","ko":"TypeScript SDK 설정 가이드 - LLM 애플리케이션 디버깅 및 모니터링","es":"TypeScript SDK Setup Guide: Traza y Evalúa LLMs","fr":"Guide TypeScript SDK : Tracez et Évaluez vos LLMs","de":"TypeScript SDK Setup Guide: LLM-Tracing und Evaluation","pt":"TypeScript SDK: Guia de Configuração para Observabilidade...","ru":"TypeScript SDK: Руководство по настройке для ИИ наблюдения","ar":"TypeScript SDK: دليل الإعداد لمراقبة أدوات الذكاء الاصطناعي"},"description":{"en":"Debug your LLM apps with the TypeScript SDK''s async tracing. Learn critical gotchas like manual flush before exit, Node.js ESM/CJS support, and how the layer...","zh":"专为LLM应用设计的TypeScript SDK，提供非阻塞架构、异步数据缓冲和跟踪功能。支持Node.js >=18，包含ESM和CJS构建，用于LangChain和LlamaIndex工作流的评估与监控。","ja":"LLMアプリ向けTypeScript SDK。非ブロッキングアーキテクチャ、非同期データバッファリング、トレース機能を提供。Node.js >=18対応、ESM/CJSビルドを含み、LangChainやLlamaIndexワークフローの評価と監視に最適。","ko":"LLM 애플리케이션을 위한 TypeScript SDK. 논블로킹 아키텍처, 비동기 데이터 버퍼링 및 추적 기능 제공. Node.js >=18 지원, ESM 및 CJS 빌드 포함, LangChain 및 LlamaIndex 워크플로우 평가 및 모니터링에 적합.","es":"SDK de TypeScript para tracing de LLMs y RAG. Arquitectura en capas no bloqueante, buffers de datos asíncronos y flush manual para CLIs. Soporta Node >=18.","fr":"SDK TypeScript pour le tracing d''LLMs et RAG. Architecture non bloquante à couches, buffers de données asynchrones et flush manuel pour les CLIs. Prend en ch...","de":"TypeScript SDK für LLM- und RAG-Tracing. Nicht-blockierende Schichtenarchitektur, asynchrone Datenpuffer und manuelles Flush für CLIs. Unterstützt Node >=18.","pt":"Configure o SDK TypeScript para debug, avaliação e monitoramento de aplicações LLM e RAG. Suporte para Node.js >=18, ESM/CJS e fluxo de dados assíncrono.","ru":"Настройте TypeScript SDK для отладки, оценки и мониторинга LLM-приложений и RAG-систем. Поддержка Node.js >=18, ESM/CJS и асинхронного потока данных.","ar":"قم بإعداد TypeScript SDK لتصحيح أخطاء وتقييم ومراقبة تطبيقات LLM وأنظمة RAG. يدعم Node.js >=18، ESM/CJS وتدفق البيانات غير المتزامن."},"definition":{"en":"typescript-sdk is an open-source library for debugging, evaluating, and monitoring LLM applications. It features a non-blocking, layered architecture that asynchronously buffers and flushes trace data to a backend, requiring Node.js >= 18 and providing both ESM and CJS builds.","zh":"TypeScript SDK是一个专门为LLM应用设计的开发工具包，提供调试、评估和监控功能。采用分层非阻塞架构，支持异步数据缓冲和批量队列处理，可与多种AI框架集成。","ja":"TypeScript SDKはLLMアプリケーション向けの開発ツールキットで、デバッグ、評価、監視機能を提供します。階層型非ブロッキングアーキテクチャを採用し、非同期データバッファリングとバッチキュー処理をサポートし、様々なAIフレームワークと連携できます。","ko":"TypeScript SDK는 LLM 애플리케이션을 위한 개발 도구 키트로, 디버깅, 평가 및 모니터링 기능을 제공합니다. 계층적 논블로킹 아키텍처를 채택하고 비동기 데이터 버퍼링 및 배치 큐 처리를 지원하며 다양한 AI 프레임워크와 통합될 수 있습니다.","es":"El typescript-sdk es una biblioteca de código abierto para desarrolladores que necesitan debugging, evaluación y monitorización de aplicaciones LLM y AI Agents. Proporciona tracing comprehensivo, integra con LangChain y LlamaIndex, y requiere Node.js 18 o superior.","fr":"Le typescript-sdk est une bibliothèque open-source pour les développeurs ayant besoin de déboguer, évaluer et surveiller les applications LLM et outils d''IA. Il fournit un tracing complet, s''intègre avec LangChain et LlamaIndex, et nécessite Node.js 18 ou supérieur.","de":"Das typescript-sdk ist eine Open-Source-Bibliothek für Entwickler, die Debugging, Evaluation und Monitoring von LLM-Anwendungen und AI Tools benötigen. Es bietet umfassendes Tracing, Integration mit LangChain und LlamaIndex und erfordert Node.js 18 oder höher.","pt":"O TypeScript SDK é uma biblioteca de desenvolvedor para debug, avaliação e monitoramento de aplicações de LLM e sistemas RAG. Oferece tracing detalhado, fluxo de dados assíncrono e integração com backends via REST.","ru":"TypeScript SDK — это библиотека для разработчиков, предназначенная для отладки, оценки и мониторинга LLM-приложений и RAG-систем. Предоставляет детальное трассирование, асинхронный поток данных и интеграцию с бэкендами через REST.","ar":"TypeScript SDK هي مكتبة مطور لتصحيح الأخطاء وتقييم ومراقبة تطبيقات LLM وأنظمة RAG. توفر تتبعًا مفصلاً، وتدفق بيانات غير متزامن، وتكاملًا مع الخلفيات عبر REST."},"features":{"en":["Non-blocking async data buffering and flushing to backend","Layered architecture flow: Public API → OpikClient → Domain → BatchQueues → REST Client","Requires manual flush before process exit (e.g., in CLI/tests)","Supports Node.js >= 18 with both ESM and CJS builds","Integrates with LangChain and LlamaIndex for LLM observability","Provides production-ready dashboards for tracing and evaluations"],"zh":["分层非阻塞架构设计，确保高性能数据处理","异步数据缓冲和批量刷新机制，优化网络传输","完整支持Node.js >=18环境和ESM/CJS模块系统","与LangChain和LlamaIndex框架深度集成","提供全面的LLM工作流跟踪和评估能力","生产就绪的监控仪表板和调试工具"],"ja":["高性能データ処理を確保する階層型非ブロッキングアーキテクチャ","ネットワーク転送を最適化する非同期データバッファリングとバッチフラッシュメカニズム","Node.js >=18環境とESM/CJSモジュールシステムの完全サポート","LangChainおよびLlamaIndexフレームワークとの深度連携","包括的なLLMワークフロートレースと評価機能の提供","プロダクション対応の監視ダッシュボードとデバッグツール"],"ko":["고성능 데이터 처리를 보장하는 계층적 논블로킹 아키텍처","네트워크 전송을 최적화하는 비동기 데이터 버퍼링 및 배치 플러시 메커니즘","Node.js >=18 환경 및 ESM/CJS 모듈 시스템 완전 지원","LangChain 및 LlamaIndex 프레임워크와의 심층 통합","포괄적인 LLM 워크플로우 추적 및 평가 기능 제공","프로덕션 준비된 모니터링 대시보드 및 디버깅 도구"],"es":["Arquitectura en capas no bloqueante por defecto para máximo rendimiento","Buffering de datos asíncrono y flush automático al backend para eficiencia","Requisito de flush manual (`.awa`) esencial para aplicaciones CLI y tests","Soporte para Node.js versión 18 y superiores, con builds ESM y CJS","Flujo de datos: API Pública → OpikClient → Domain (Trace/Span) → BatchQueues → REST Client → Backend","Integración con ecosistemas populares de LLM como LangChain y LlamaIndex"],"fr":["Architecture à couches non bloquante par défaut pour des performances maximales","Buffering de données asynchrone et flush automatique vers le backend pour l''efficacité","Exigence de flush manuel (`.awa`) essentiel pour les applications CLI et les tests","Prise en charge de Node.js version 18 et supérieures, avec des builds ESM et CJS","Flux de données : API Publique → OpikClient → Domain (Trace/Span) → BatchQueues → REST Client → Backend","Intégration avec les écosystèmes LLM populaires comme LangChain et LlamaIndex"],"de":["Nicht-blockierende Schichtenarchitektur standardmäßig für maximale Leistung","Asynchroner Datenpuffer und automatisches Flush zum Backend für Effizienz","Manuelles Flush-Erfordernis (`.awa`) entscheidend für CLI-Anwendungen und Tests","Unterstützung für Node.js Version 18 und höher, mit ESM- und CJS-Builds","Datenfluss: Public API → OpikClient → Domain (Trace/Span) → BatchQueues → REST Client → Backend","Integration mit populären LLM-Ökosystemen wie LangChain und LlamaIndex"],"pt":["Arquitetura em camadas e não-bloqueante por padrão","Dados armazenados em buffer e enviados assincronamente para o backend","Suporte para Node.js >=18 e builds ESM + CJS","Fluxo de dados: API Pública → OpikClient → Domínio (Trace/Span) → BatchQueues → REST Client","Requer flush explícito (`.await`) antes da saída em CLIs e testes","Integração com LangChain e LlamaIndex para avaliação de LLM"],"ru":["Многоуровневая архитектура, неблокирующая по умолчанию","Данные буферизуются и асинхронно отправляются в бэкенд","Поддержка Node.js >=18 и сборок ESM + CJS","Поток данных: Public API → OpikClient → Domain (Trace/Span) → BatchQueues → REST Client","Требует явного сброса (`.await`) перед выходом в CLI и тестах","Интеграция с LangChain и LlamaIndex для оценки LLM"],"ar":["هندسة معمارية متعددة الطبقات وغير مانعة بشكل افتراضي","يتم تخزين البيانات في المخزن مؤقتًا وإرسالها غير متزامن إلى الخلفية","يدعم Node.js >=18 وبناء ESM + CJS","تدفق البيانات: واجهة برمجة التطبيقات العامة → OpikClient → المجال (Trace/Span) → BatchQueues → REST Client","يتطلب flush صريح (`.await`) قبل الخروج في CLI والاختبارات","التكامل مع LangChain و LlamaIndex لتقييم LLM"]},"keywords":{"en":["how to use typescript-sdk flush","typescript-sdk vs langsmith","typescript-sdk install node 18","what is typescript-sdk architecture","typescript-sdk setup guide esm cjs","typescript-sdk alternative for llm evaluation","typescript-sdk automated evaluations","typescript-sdk rag monitoring","typescript-sdk trace span domain"],"zh":["TypeScript SDK安装","LLM应用监控","LangChain集成","LlamaIndex调试","AI代理工具","Node.js LLM开发","异步数据缓冲","生产环境LLMOps"],"ja":["TypeScript SDKインストール","LLMアプリ監視","LangChain連携","LlamaIndexデバッグ","AIエージェントツール","Node.js LLM開発","非同期データバッファリング","本番環境LLMOps"],"ko":["TypeScript SDK 설치","LLM 애플리케이션 모니터링","LangChain 통합","LlamaIndex 디버깅","AI 에이전트 도구","Node.js LLM 개발","비동기 데이터 버퍼링","프로덕션 환경 LLMOps"],"es":["typescript sdk llm tracing","evaluacion rag typescript","debugging ai agents con node","monitorizacion langchain typescript","llama-index tracing sdk","opikclient api referencia","node 18 llm observability","flush manual cli tests","arquitectura no bloqueante sdk","batchqueues datos asincronos"],"fr":["sdk typescript tracing llm","evaluation rag typescript","debugging outils ia avec node","monitoring langchain typescript","llama-index tracing sdk","reference api opikclient","node 18 observabilite llm","flush manuel cli tests","architecture non bloquante sdk","batchqueues donnees asynchrones"],"de":["typescript sdk llm tracing","evaluation rag typescript","debugging ai tools mit node","monitoring langchain typescript","llama-index tracing sdk","opikclient api referenz","node 18 llm observability","manuelles flush cli tests","nicht-blockierende architektur sdk","batchqueues asynchrone daten"],"pt":["typescript sdk observabilidade","debug aplicações llm","monitoramento sistemas rag","tracing typescript ai","avaliação automatizada llm","nodejs esm cjs builds","langchain llamaindex integração","flush assíncrono dados","opikclient api","hacktoberfest2025"],"ru":["typescript sdk observability","отладка llm приложений","мониторинг rag систем","трассировка typescript ИИ","автоматизированная оценка llm","nodejs esm cjs сборки","langchain llamaindex интеграция","асинхронный сброс данных","opikclient api","hacktoberfest2025"],"ar":["typescript sdk مراقبة","تصحيح تطبيقات llm","مراقبة أنظمة rag","تتبع typescript الذكاء الاصطناعي","تقييم آلي llm","nodejs esm cjs بناء","langchain llamaindex تكامل","flush غير متزامن للبيانات","opikclient api","hacktoberfest2025"]}},"owner":"comet-ml","repo":"opik","repoPath":"comet-ml/opik","stars":17827,"forks":1358,"updatedAt":"2026-02-26T01:28:05Z","topics":["evaluation","hacktoberfest","hacktoberfest2025","langchain","llama-index","llm","llm-evaluation","llm-observability","llmops","open-source","openai","playground","prompt-engineering"],"category":"community","skillMd":{"name":"typescript-sdk","description":"TypeScript SDK patterns for Opik. Use when working in sdks/typescript.","bodyPreview":"# TypeScript SDK\n\n## Architecture\n- Layered, non-blocking by default\n- Data buffered and flushed async to backend\n- Node >= 18, ESM + CJS builds\n\n## Layer Flow\n```\nPublic API → OpikClient → Domain (Trace/Span) → BatchQueues → REST Client → Backend\n```\n\n## Critical Gotchas\n- When changing dependencies or minimum versions, update and verify version references in `README.md` and integration README files in the same PR.\n\n### Flush Before Exit\n```typescript\n// ✅ REQUIRED - especially in CLI/tests\nawa","body":"# TypeScript SDK\n\n## Architecture\n- Layered, non-blocking by default\n- Data buffered and flushed async to backend\n- Node >= 18, ESM + CJS builds\n\n## Layer Flow\n```\nPublic API → OpikClient → Domain (Trace/Span) → BatchQueues → REST Client → Backend\n```\n\n## Critical Gotchas\n- When changing dependencies or minimum versions, update and verify version references in `README.md` and integration README files in the same PR.\n\n### Flush Before Exit\n```typescript\n// ✅ REQUIRED - especially in CLI/tests\nawait client.flush();\n// or globally:\nawait flushAll();\n```\n\n### Domain Objects Don''t Do HTTP\n```typescript\n// ✅ GOOD - domain objects enqueue, not HTTP\ntrace.update({ metadata: { key: ''value'' } }); // Enqueues update\ntrace.end();  // Enqueues update\n\n// ❌ BAD - don''t call REST directly from domain\n```\n\n### Never Leak rest_api\n```typescript\n// ✅ GOOD - export from public API\nexport { Opik, track, flushAll } from ''opik'';\n\n// ❌ BAD - don''t expose generated clients\nimport { TracesApi } from ''opik/rest_api'';  // Internal!\n```\n\n## Batching Semantics\n- Updates wait for pending creates\n- Deletes wait for creates and updates\n- `flush()` flushes all queues in order\n- Debounce window configurable via `OpikConfig`\n\n## Error Handling\n- HTTP failures: `OpikApiError`, `OpikApiTimeoutError`\n- 404s translate to domain errors: `DatasetNotFoundError`, `ExperimentNotFoundError`\n- Never swallow errors, include context in logs\n\n## Integration Guidelines\n- Integrations wrap public API only\n- Keep adapters thin, non-blocking\n- Provide `flush()` escape hatch if needed\n\n## Reference Files\n- [testing.md](testing.md) - Vitest patterns, mocking, flush timing\n"},"lastSynced":"2026-03-06T02:31:58.561Z","agentAnalysis":{"suitability":{"en":"Essential for TypeScript-based AI Agents requiring production-grade observability for LLM applications, RAG systems, and agentic workflows.","zh":"对于基于TypeScript、需要为LLM应用程序、RAG系统和智能体工作流提供生产级可观测性的AI智能体而言，这是必不可少的。","ja":"TypeScriptベースで、LLMアプリケーション、RAGシステム、エージェントワークフローに対するプロダクショングレードの観測性を必要とするAIエージェントにとって必須です。","ko":"TypeScript 기반이며 LLM 애플리케이션, RAG 시스템, 에이전트 워크플로우를 위한 프로덕션급 가시성을 필요로 하는 AI 에이전트에게 필수적입니다.","es":"Esencial para agentes de IA basados en TypeScript que requieren observabilidad de grado de producción para aplicaciones LLM, sistemas RAG y flujos de trabajo agenticos.","fr":"Essentiel pour les agents d''IA basés sur TypeScript nécessitant une observabilité de qualité production pour les applications LLM, les systèmes RAG et les flux de travail agentiques.","de":"Essenziell für TypeScript-basierte KI-Agenten, die Produktions-Observability für LLM-Anwendungen, RAG-Systeme und agentenbasierte Workflows benötigen.","pt":"Essencial para AI Agents baseados em TypeScript que requerem observabilidade de grau de produção para aplicações LLM, sistemas RAG e workflows agentic.","ru":"Необходимо для AI Agents на TypeScript, требующих промышленного уровня наблюдаемости для LLM-приложений, систем RAG и агентских рабочих процессов.","ar":"أساسي لوكيل الذكاء الاصطناعي القائم على TypeScript والذي يتطلب إمكانية مراقبة على مستوى الإنتاج لتطبيقات LLM، وأنظمة RAG، وسير العمل الوكيلية."},"recommendation":{"en":"Provides comprehensive tracing, automated evaluations, and monitoring capabilities for AI applications built with LangChain, LlamaIndex, and other frameworks. Its non-blocking, layered architecture ensures high performance with async data buffering and flushing to the backend.","zh":"为使用LangChain、LlamaIndex及其他框架构建的AI应用程序提供全面的追踪、自动化评估和监控能力。其非阻塞的分层架构通过异步数据缓冲和后端刷新确保了高性能。","ja":"LangChain、LlameIndex、その他のフレームワークで構築されたAIアプリケーションに対して、包括的なトレーシング、自動化された評価、および監視機能を提供します。その非ブロッキングで階層化されたアーキテクチャは、非同期データバッファリングとバックエンドへのフラッシュにより高性能を保証します。","ko":"LangChain, LlamaIndex 및 기타 프레임워크로 구축된 AI 애플리케이션을 위한 포괄적인 추적, 자동화된 평가 및 모니터링 기능을 제공합니다. 논블로킹(non-blocking) 계층적 아키텍처는 비동기 데이터 버퍼링 및 백엔드로의 플러싱(flushing)을 통해 높은 성능을 보장합니다.","es":"Proporciona capacidades integrales de tracing, evaluaciones automatizadas y monitorización para aplicaciones de IA construidas con LangChain, LlamaIndex y otros frameworks. Su arquitectura no bloqueante y en capas garantiza alto rendimiento con buffering asíncrono de datos y flushing al backend.","fr":"Fournit des capacités complètes de tracing, d''évaluations automatisées et de monitoring pour les applications d''IA construites avec LangChain, LlamaIndex et autres frameworks. Son architecture non bloquante et superposée assure des performances élevées avec un buffering asynchrone des données et un flushing vers le backend.","de":"Bietet umfassende Tracing-Funktionen, automatisierte Evaluierungen und Monitoring-Fähigkeiten für KI-Anwendungen, die mit LangChain, LlamaIndex und anderen Frameworks gebaut wurden. Seine nicht-blockierende, geschichtete Architektur gewährleistet hohe Leistung mit asynchroner Datenpufferung und Flushing zum Backend.","pt":"Fornece tracing abrangente, avaliações automatizadas e capacidades de monitoramento para aplicações de IA construídas com LangChain, LlamaIndex e outros frameworks. Sua arquitetura não bloqueante e em camadas garante alto desempenho com buffer de dados assíncrono e flushing para o backend.","ru":"Обеспечивает комплексный трейсинг, автоматизированную оценку и возможности мониторинга для AI-приложений, построенных на LangChain, LlamaIndex и других фреймворках. Его неблокирующая многоуровневая архитектура обеспечивает высокую производительность с асинхронной буферизацией данных и сбросом в бэкенд.","ar":"يوفر تتبعًا شاملاً، وتقييمات آلية، وإمكانيات مراقبة لتطبيقات الذكاء الاصطناعي المبنية باستخدام LangChain وLlamaIndex وأطر العمل الأخرى. تضمن بنيتها غير المعيقة والمطبقة على طبقات أداءً عاليًا مع تخزين مؤقت للبيانات غير متزامن وإرسال إلى الخلفية."},"useCases":{"en":["Monitoring RAG system performance in real-time","Automating evaluations for LLM application quality","Tracing complex agentic workflows for debugging","Flushing trace data before CLI/test exit to prevent data loss"],"zh":["实时监控RAG系统性能","自动化评估LLM应用程序质量","追踪复杂的智能体工作流以进行调试","在CLI/测试退出前刷新追踪数据以防止数据丢失"],"ja":["RAGシステムのパフォーマンスをリアルタイムで監視","LLMアプリケーションの品質に関する評価を自動化","デバッグのための複雑なエージェントワークフローのトレーシング","データ損失を防ぐためのCLI/テスト終了前のトレースデータのフラッシュ"],"ko":["RAG 시스템 성능 실시간 모니터링","LLM 애플리케이션 품질에 대한 자동화된 평가 수행","디버깅을 위한 복잡한 에이전트 워크플로우 추적","데이터 손실을 방지하기 위해 CLI/테스트 종료 전 추적 데이터 플러싱(flushing)"],"es":["Monitorización del rendimiento del sistema RAG en tiempo real","Automatización de evaluaciones para la calidad de aplicaciones LLM","Tracing de flujos de trabajo agenticos complejos para depuración","Flushing de datos de trace antes de la salida de CLI/test para prevenir pérdida de datos"],"fr":["Surveillance des performances du système RAG en temps réel","Automatisation des évaluations pour la qualité des applications LLM","Tracing des flux de travail agentiques complexes pour le débogage","Flushing des données de trace avant la sortie de CLI/test pour éviter la perte de données"],"de":["Echtzeit-Monitoring der Leistung von RAG-Systemen","Automatisierung von Evaluierungen für die Qualität von LLM-Anwendungen","Tracing komplexer agentenbasierter Workflows für Debugging-Zwecke","Flushing von Trace-Daten vor CLI/Test-Beendigung zur Vermeidung von Datenverlust"],"pt":["Monitoramento do desempenho do sistema RAG em tempo real","Automatização de avaliações para a qualidade da aplicação LLM","Tracing de workflows agentic complexos para debugging","Flushing de dados de trace antes da saída do CLI/test para evitar perda de dados"],"ru":["Мониторинг производительности системы RAG в реальном времени","Автоматизация оценок качества LLM-приложения","Трейсинг сложных агентских рабочих процессов для отладки","Сброс данных трейсинга перед завершением работы CLI/теста для предотвращения потери данных"],"ar":["مراقبة أداء نظام RAG في الوقت الفعلي","أتمتة التقييمات لجودة تطبيق LLM","تتبع سير العمل الوكيلية المعقدة لتصحيح الأخطاء","إرسال بيانات التتبع قبل خروج واجهة سطر الأوامر/الاختبار لمنع فقدان البيانات"]},"limitations":{"en":["Requires explicit flush before process exit (critical for CLI/tests)","Node.js >= 18 runtime environment only","ESM and CJS builds must be correctly configured"],"zh":["需要在进程退出前显式刷新（对CLI/测试至关重要）","仅支持Node.js >= 18运行时环境","必须正确配置ESM和CJS构建"],"ja":["プロセス終了前の明示的なフラッシュが必要（CLI/テストに極めて重要）","Node.js >= 18 ランタイム環境のみ対応","ESMとCJSビルドを正しく設定する必要がある"],"ko":["프로세스 종료 전 명시적 플러시(flush) 필요 (CLI/테스트에 매우 중요)","Node.js >= 18 런타임 환경만 지원","ESM 및 CJS 빌드를 올바르게 구성해야 함"],"es":["Requiere un flush explícito antes de la salida del proceso (crítico para CLI/tests)","Solo entorno de ejecución Node.js >= 18","Las builds ESM y CJS deben estar configuradas correctamente"],"fr":["Nécessite un flush explicite avant la sortie du processus (critique pour CLI/tests)","Environnement d''exécution Node.js >= 18 uniquement","Les builds ESM et CJS doivent être configurées correctement"],"de":["Erfordert explizites Flush vor Prozessende (kritisch für CLI/Tests)","Nur Node.js >= 18 Laufzeitumgebung","ESM- und CJS-Builds müssen korrekt konfiguriert sein"],"pt":["Requer flush explícito antes da saída do processo (crítico para CLI/testes)","Ambiente de execução Node.js >= 18 exclusivamente","Builds ESM e CJS devem ser configuradas corretamente"],"ru":["Требует явного сброса перед завершением процесса (критично для CLI/тестов)","Только среда выполнения Node.js >= 18","Сборки ESM и CJS должны быть правильно настроены"],"ar":["يتطلب إرسالًا صريحًا قبل إنهاء العملية (أمر بالغ الأهمية لواجهة سطر الأوامر/الاختبارات)","بيئة تشغيل Node.js >= 18 فقط","يجب تكوين بنائات ESM وCJS بشكل صحيح"]},"version":4},"contentHash":"a71faae487523ae5e9c6f5ae632977ce8d24d100bfecce45ecb6b7cfd784ae7f","qualityScore":46}');
DELETE FROM skills_fts WHERE id = 'comet-ml/opik/typescript-sdk';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('comet-ml/opik/typescript-sdk', 'typescript-sdk', 'comet-ml', 'opik', 'community', 'typescript-sdk comet-ml opik community evaluation hacktoberfest hacktoberfest2025 langchain llama-index llm llm-evaluation llm-observability llmops open-source openai playground prompt-engineering The TypeScript SDK provides comprehensive tracing, automated evaluations, and monitoring for LLM applications, RAG systems, and agentic workflows. It is designed for developers building production-ready AI applications with LangChain, LlamaIndex, and other frameworks. 该TypeScript SDK专为LLM应用和代理工作流设计，提供分层非阻塞架构和异步数据缓冲功能。支持Node.js 18+环境，包含完整的ESM和CJS构建，可与LangChain和LlamaIndex无缝集成，实现全面的跟踪和评估。 このTypeScript SDKはLLMアプリケーションとエージェントワークフロー向けに設計され、階層型非ブロッキングアーキテクチャと非同期データバッファリング機能を提供します。Node.js 18+環境をサポートし、完全なESMおよびCJSビルドを含み、LangChainやLlamaIndexとシームレスに連携し、包括的なトレースと評価を実現します。 이 TypeScript SDK는 LLM 애플리케이션과 에이전트 워크플로우를 위해 설계되었으며, 계층적 논블로킹 아키텍처와 비동기 데이터 버퍼링 기능을 제공합니다. Node.js 18+ 환경을 지원하며, 완전한 ESM 및 CJS 빌드를 포함하고 LangChain 및 LlamaIndex와 원활하게 통합되어 포괄적인 추적 및 평가를 가능하게 합니다. El TypeScript SDK permite instrumentar aplicaciones LLM, sistemas RAG y flujos de trabajo agentes con tracing detallado, evaluaciones automatizadas y dashboards listos para producción. Le SDK TypeScript permet d''instrumenter les applications LLM, systèmes RAG et flux de travail agents avec un tracing détaillé, des évaluations automatisées et des tableaux de bord prêts pour la production. Das TypeScript SDK ermöglicht die Instrumentierung von LLM-Anwendungen, RAG-Systemen und Agenten-Workflows mit detailliertem Tracing, automatisierten Auswertungen und produktionsreifen Dashboards. O SDK TypeScript oferece tracing abrangente, avaliações automatizadas e dashboards para monitorar aplicações de IA, sistemas RAG e fluxos de trabalho agenticos. Construído para Node.js >=18 com suporte a ESM e CJS. TypeScript SDK предоставляет комплексное трассирование, автоматизированную оценку и дашборды для мониторинга ИИ-приложений, RAG-систем и агентских workflow. Создан для Node.js >=18 с поддержкой ESM и CJS. يوفر TypeScript SDK تتبعًا شاملاً وتقييمات تلقائية ولوحات تحكم لمراقبة تطبيقات الذكاء الاصطناعي وأنظمة RAG وسير العمل الوكيلة. مبني لـ Node.js >=18 مع دعم ESM و CJS. how to use typescript-sdk flush typescript-sdk vs langsmith typescript-sdk install node 18 what is typescript-sdk architecture typescript-sdk setup guide esm cjs typescript-sdk alternative for llm evaluation typescript-sdk automated evaluations typescript-sdk rag monitoring typescript-sdk trace span domain TypeScript SDK安装 LLM应用监控 LangChain集成 LlamaIndex调试 AI代理工具 Node.js LLM开发 异步数据缓冲 生产环境LLMOps Non-blocking async data buffering and flushing to backend Layered architecture flow: Public API → OpikClient → Domain → BatchQueues → REST Client Requires manual flush before process exit (e.g., in CLI/tests) Supports Node.js >= 18 with both ESM and CJS builds Integrates with LangChain and LlamaIndex for LLM observability Provides production-ready dashboards for tracing and evaluations typescript-sdk is an open-source library for debugging, evaluating, and monitoring LLM applications. It features a non-blocking, layered architecture that asynchronously buffers and flushes trace data to a backend, requiring Node.js >= 18 and providing both ESM and CJS builds.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('team-attention/stanford-cs146s-kr/wrap', 'community', 'team-attention', 'stanford-cs146s-kr', 'team-attention/stanford-cs146s-kr', 'wrap', 261, 18, 46, '2026-03-05T02:05:28Z', '2026-03-06T06:29:10.461Z', '2937cb78b52ef5fdf3f878a5b1b6d18d402eb72bcc0cb3a507787bf0086aab6d', '{"id":"team-attention/stanford-cs146s-kr/wrap","name":"wrap","description":{"en":"The wrap skill automates code cleanup for AI agents, streamlining the development process. It benefits developers by simplifying code organization and management.","zh":"Wrap技能是一种自动化代码分析和提交的工具，可以通过CLI命令快速实现代码检查和提交","ja":"Wrapスキルはコード分析とコミットの自動化ツールであり、CLIコマンドを使用してコードチェックとコミットを迅速に実行できる","ko":"Wrap 스킬은 코드 분석 및 커밋 자동화를 수행하는 도구로 CLI 명령어를 통해 빠르게 코드 체크 및 커밋을 수행할 수 있습니다","es":"wrap es una habilidad que automatiza la limpieza y el análisis de proyectos al finalizar una sesión","fr":"wrap est une compétence qui automatise le nettoyage et l''analyse des projets à la fin d''une session","de":"wrap ist eine Fähigkeit, die die Bereinigung und Analyse von Projekten am Ende einer Sitzung automatisiert","pt":"O wrap é uma ferramenta que automatiza a limpeza de código ao final de uma sessão, melhorando a produtividade do desenvolvedor. Saiba mais sobre como usá-lo","ru":"Инструмент Wrap автоматически очищает код в конце сессии, повышая производительность разработчика. Узнайте больше о его использовании для ИИ Агентов","ar":"اداة Wrap تتيح آلي لإنهاء الجلسات وتحسين الكود، مما يزيد من إنتاجية المطور. تعرف على المزيد حول كيفية استخدامها لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"wrap: Automated Code Cleanup for AI Agents | AI Agent Skill","zh":"Wrap技能设置指南：自动化代码分析和提交","ja":"Wrapスキルセットアップガイド：コード分析とコミットの自動化","ko":"Wrap 스킬 설정 가이드: 코드 분석 및 커밋 자동화","es":"Guía de configuración de wrap para desarrolladores","fr":"Guide d''installation de wrap pour les développeurs","de":"Einrichtungsleitfaden für wrap-Entwickler","pt":"Guia de Configuração do Wrap: Automatize a Limpeza de Código","ru":"Настройка инструмента Wrap: Автоматическая очистка кода д...","ar":"دليل إعداد Wrap: آلي لإنهاء الجلسات وتحسين الكود"},"description":{"en":"Discover how to simplify code management with wrap. Learn how to automate cleanup and get started with our setup guide today!","zh":"了解Wrap技能的功能和用法，实现代码分析和提交的自动化，提高开发效率","ja":"Wrapスキルの機能と使い方を学び、コード分析とコミットの自動化を実現し、開発効率を向上させる","ko":"Wrap 스킬의 기능과 사용법을 알아보고 코드 분석 및 커밋 자동화를 구현하여 개발 효율성을 향상시키세요","es":"Aprende a utilizar wrap para automatizar tareas de limpieza y análisis en tus proyectos de desarrollo","fr":"Découvrez comment utiliser wrap pour automatiser les tâches de nettoyage et d''analyse dans vos projets de développement","de":"Erfahren Sie, wie Sie wrap verwenden können, um Aufgaben zur Bereinigung und Analyse in Ihren Entwicklungsprojekten zu automatisieren","pt":"Aprenda a usar o wrap para automatizar a limpeza de código e melhorar a produtividade do desenvolvedor com exemplos práticos e dicas de especialista","ru":"Узнайте, как использовать инструмент Wrap для автоматической очистки кода и повышения производительности разработчика с примерами и советами экспертов для ИИ...","ar":"تعرف على كيفية استخدام Wrap لآلي لإنهاء الجلسات وتحسين الكود باستخدام أمثلة عملية ونصائح من الخبراء لادوات الذكاء الاصطناعي"},"definition":{"en":"wrap is a skill that performs automatic code cleanup at the end of a session, eliminating the need for manual organization.","zh":"Wrap技能是一种自动化代码分析和提交的工具，用于提高开发效率","ja":"Wrapスキルはコード分析とコミットの自動化ツールであり、開発効率を向上させるために使用される","ko":"Wrap 스킬은 코드 분석 및 커밋 자동화를 수행하는 도구로 개발 효율성을 향상시키기 위해 사용됩니다","es":"wrap es una herramienta de automatización para desarrolladores que realiza tareas de limpieza y análisis","fr":"wrap est un outil d''automatisation pour les développeurs qui effectue des tâches de nettoyage et d''analyse","de":"wrap ist ein Automatisierungstool für Entwickler, das Bereinigungs- und Analyseaufgaben ausführt","pt":"O wrap é uma ferramenta de automação de limpeza de código que executa análises paralelas e commit","ru":"Инструмент Wrap - это средство автоматической очистки кода, которое выполняет параллельный анализ и коммит для ИИ Агентов","ar":"اداة Wrap هي أداة آلي لإنهاء الجلسات وتحسين الكود التي تقوم بتحليلات متوازيّة وتوفر خيارات للتعامل مع الكود"},"features":{"en":["Performs automatic code cleanup at the end of a session","Supports quick mode for rapid CLAUDE.md checks","Allows for optional commit exclusion using the --no-commit flag","Executes parallel analysis for efficient code review","Utilizes command-line interface for easy execution and customization"],"zh":["支持CLI命令","自动代码分析","快速提交","支持--quick和--no-commit选项","实现代码检查和提交的自动化"],"ja":["CLIコマンドに対応","自動コード分析","迅速なコミット","--quickと--no-commitオプションに対応","コードチェックとコミットの自動化を実現"],"ko":["CLI 명령어 지원","자동 코드 분석","빠른 커밋","--quick 및 --no-commit 옵션 지원","코드 체크 및 커밋 자동화 구현"],"es":["Análisis paralelo de proyectos","Opción de análisis rápido con --quick","Opción para excluir la confirmación con --no-commit","Compatibilidad con CLI","Automatización de tareas de limpieza","Soporte para proyectos de desarrollo"],"fr":["Analyse parallèle de projets","Option d''analyse rapide avec --quick","Option pour exclure la confirmation avec --no-commit","Compatibilité avec CLI","Automatisation des tâches de nettoyage","Prise en charge des projets de développement"],"de":["Parallele Analyse von Projekten","Option für schnelle Analyse mit --quick","Option zum Ausschließen der Bestätigung mit --no-commit","Kompatibilität mit CLI","Automatisierung von Bereinigungsaufgaben","Unterstützung für Entwicklungsprojekte"],"pt":["Análise paralela de código","Opção de commit automático","Modo rápido para análise de CLAUDE.md","Suporte a várias opções de linha de comando","Integração com fluxos de trabalho de desenvolvimento"],"ru":["Параллельный анализ кода","Автоматический коммит","Быстрый режим для анализа CLAUDE.md","Поддержка нескольких опций командной строки","Интеграция с рабочими процессами разработки для ИИ Агентов"],"ar":["تحليل متوازي للكود","خيار للتعامل الآلي مع الكود","وضع سريع لتحليل CLAUDE.md","دعم لعدة خيارات سطر الأوامر","تكامل مع عمليات عمل التطوير لأدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use wrap","wrap setup guide","automated code cleanup","wrap alternative","wrap vs manual cleanup","wrap install","what is wrap","wrap benefits for developers","wrap skill for AI agents"],"zh":["AI工具","代码分析","自动提交","CLI命令","开发效率","Wrap技能","代码检查","自动化工具"],"ja":["AIエージェント","コード分析","自動コミット","CLIコマンド","開発効率","Wrapスキル","コードチェック","自動化ツール"],"ko":["AI 에이전트","코드 분석","자동 커밋","CLI 명령어","개발 효율성","Wrap 스킬","코드 체크","자동화 도구"],"es":["herramientas de automatización para desarrolladores","wrap para desarrolladores","análisis de proyectos","limpieza de proyectos","CLI para desarrolladores","automatización de tareas","desarrollo de software","herramientas de desarrollo","wrap skill"],"fr":["outils d''automatisation pour les développeurs","wrap pour les développeurs","analyse de projets","nettoyage de projets","CLI pour les développeurs","automatisation de tâches","développement de logiciels","outils de développement","compétence wrap"],"de":["Automatisierungstools für Entwickler","wrap für Entwickler","Projektanalyse","Projektbereinigung","CLI für Entwickler","Automatisierung von Aufgaben","Softwareentwicklung","Entwicklungstools","wrap-Fähigkeit"],"pt":["wrap skill","automação de limpeza de código","análise paralela","commit automático","desenvolvimento de software","ferramentas de desenvolvimento","produtividade do desenvolvedor"],"ru":["инструмент Wrap","автоматическая очистка кода","параллельный анализ","автоматический коммит","разработка программного обеспечения","инструменты разработки","производительность разработчика","ИИ Агенты"],"ar":["اداة Wrap","آلي لإنهاء الجلسات","تحليل متوازي","تعامل آلي مع الكود","تطوير البرمجيات","أدوات التطوير","إنتاجية المطور","ادوات الذكاء الاصطناعي"]}},"owner":"team-attention","repo":"stanford-cs146s-kr","repoPath":"team-attention/stanford-cs146s-kr","stars":261,"forks":18,"updatedAt":"2026-03-05T02:05:28Z","topics":[],"category":"community","skillMd":{"name":"wrap","description":"|","bodyPreview":"# wrap Skill\n\nClaude Code 세션 종료 시 자동 정리를 수행하는 스킬입니다.\n\"이거 CLAUDE.md에 적어야 하나?\"라는 반복적인 고민을 해결합니다.\n\n## 사용법\n\n```\n/wrap                    # 전체 분석\n/wrap --quick            # 간단 모드 (CLAUDE.md만)\n/wrap --no-commit        # 커밋 옵션 제외\n```\n\n## 예시\n\n```bash\n# 세션 마무리 시\n/wrap\n\n# 빠르게 CLAUDE.md만 체크\n/wrap --quick\n\n# 분석만 하고 커밋은 나중에\n/wrap --no-commit\n```\n\n## 워크플로우\n\n```\n/wrap\n    │\n    ▼\n┌─────────────────────────────────────────────────────────────┐\n│                    Phase 1: 병렬 분석                        │\n├──────","body":"# wrap Skill\n\nClaude Code 세션 종료 시 자동 정리를 수행하는 스킬입니다.\n\"이거 CLAUDE.md에 적어야 하나?\"라는 반복적인 고민을 해결합니다.\n\n## 사용법\n\n```\n/wrap                    # 전체 분석\n/wrap --quick            # 간단 모드 (CLAUDE.md만)\n/wrap --no-commit        # 커밋 옵션 제외\n```\n\n## 예시\n\n```bash\n# 세션 마무리 시\n/wrap\n\n# 빠르게 CLAUDE.md만 체크\n/wrap --quick\n\n# 분석만 하고 커밋은 나중에\n/wrap --no-commit\n```\n\n## 워크플로우\n\n```\n/wrap\n    │\n    ▼\n┌─────────────────────────────────────────────────────────────┐\n│                    Phase 1: 병렬 분석                        │\n├──────────────┬──────────────┬──────────────┬───────────────┤\n│ doc-updater  │ automation-  │ learning-    │ followup-     │\n│              │ scout        │ extractor    │ suggester     │\n│ CLAUDE.md    │ 반복 패턴    │ 배운 것      │ 미완성 작업   │\n│ 업데이트     │ 자동화       │ 실수/발견    │ 우선순위      │\n└──────┬───────┴──────┬───────┴──────┬───────┴───────┬───────┘\n       │              │              │               │\n       └──────────────┴──────────────┴───────────────┘\n                              │\n                              ▼\n┌─────────────────────────────────────────────────────────────┐\n│              Phase 2: 중복 검증 및 정리                      │\n│                   duplicate-checker                          │\n│     기존 CLAUDE.md와 비교하여 중복 항목 제거                  │\n└─────────────────────────────────────────────────────────────┘\n                              │\n                              ▼\n┌─────────────────────────────────────────────────────────────┐\n│              Phase 3: 사용자 선택                            │\n│  AskUserQuestion으로 다음 중 선택:                           │\n│  1. CLAUDE.md 업데이트                                       │\n│  2. 자동화 스킬 생성                                         │\n│  3. 커밋 생성                                                │\n│  4. 결과만 확인 (아무 작업 안 함)                            │\n└─────────────────────────────────────────────────────────────┘\n```\n\n## 실행 지침\n\n### Step 0: 사전 준비\n\n1. CLAUDE.md 파일 읽기\n   ```\n   Read: /Users/junchan/Documents/GitHub/stanford-cs146s-kr/CLAUDE.md\n   ```\n\n2. `--quick` 모드인 경우 Phase 1에서 doc-updater만 실행\n\n### Step 1: Phase 1 - 병렬 분석\n\n4개의 에이전트를 **병렬로** 실행합니다.\n각 에이전트에게 현재 대화 컨텍스트를 전달합니다.\n\n**중요**: 현재 대화의 핵심 내용을 요약하여 에이전트에게 전달해야 합니다.\n- 수행한 작업들\n- 발생한 문제들과 해결 방법\n- 사용한 명령어나 패턴\n- 미완료된 작업\n\n```\nTask (4개 병렬 호출):\n\n1. doc-updater\n   - subagent_type: \"general-purpose\"\n   - description: \"CLAUDE.md 업데이트 분석\"\n   - prompt: .claude/agents/wrap/doc-updater.md 지침 + 세션 요약 + 현재 CLAUDE.md 내용\n\n2. automation-scout\n   - subagent_type: \"general-purpose\"\n   - description: \"반복 패턴 자동화 기회 탐지\"\n   - prompt: .claude/agents/wrap/automation-scout.md 지침 + 세션 요약\n\n3. learning-extractor\n   - subagent_type: \"general-purpose\"\n   - description: \"학습 내용 추출\"\n   - prompt: .claude/agents/wrap/learning-extractor.md 지침 + 세션 요약\n\n4. followup-suggester\n   - subagent_type: \"general-purpose\"\n   - description: \"미완성 작업 정리\"\n   - prompt: .claude/agents/wrap/followup-suggester.md 지침 + 세션 요약\n```\n\n### Step 2: Phase 2 - 중복 검증\n\nPhase 1의 모든 결과를 수집한 후, duplicate-checker 에이전트를 실행합니다.\n\n```\nTask:\n- subagent_type: \"general-purpose\"\n- description: \"중복 검증 및 정리\"\n- prompt: .claude/agents/wrap/duplicate-checker.md 지침 + Phase 1 결과 + 현재 CLAUDE.md 내용\n```\n\n### Step 3: Phase 3 - 결과 정리 및 사용자 선택\n\n중복이 제거된 결과를 정리하여 사용자에게 보여주고 선택을 받습니다.\n\n**결과 출력 형식**:\n\n```markdown\n## 세션 정리 결과\n\n### CLAUDE.md 업데이트 제안 (N건)\n- [섹션명] 내용 요약\n- ...\n\n### 자동화 기회 (N건)\n- \"패턴 설명\" (N회 반복) → `/suggested-skill` 스킬 제안\n- ...\n\n### 배운 것 (N건)\n- [발견/실수/인사이트] 내용\n- ...\n\n### 미완성 작업 (N건)\n- [P0/P1/P2] 작업 설명\n- ...\n```\n\n**AskUserQuestion으로 선택**:\n\n```\nAskUserQuestion:\n- question: \"어떤 작업을 수행할까요?\"\n- header: \"Action\"\n- options:\n  - label: \"CLAUDE.md 업데이트 (Recommended)\"\n    description: \"제안된 내용을 CLAUDE.md에 추가합니다\"\n  - label: \"자동화 스킬 생성\"\n    description: \"반복 패턴을 스킬로 만듭니다\"\n  - label: \"커밋 생성\" (--no-commit이면 제외)\n    description: \"현재 변경사항을 커밋합니다\"\n  - label: \"아무것도 안 함\"\n    description: \"결과만 확인하고 종료합니다\"\n- multiSelect: true\n```\n\n### Step 4: 선택된 작업 수행\n\n사용자 선택에 따라 작업을 수행합니다.\n\n**CLAUDE.md 업데이트 선택 시**:\n1. 현재 CLAUDE.md 읽기\n2. 적절한 섹션에 새 내용 추가\n3. Edit tool로 파일 수정\n4. 결과 확인\n\n**자동화 스킬 생성 선택 시**:\n1. 사용자에게 생성할 스킬 선택 받기 (여러 개인 경우)\n2. 선택된 패턴에 대해 스킬 뼈대 생성\n3. `.claude/skills/{skill-name}/SKILL.md` 생성\n4. 필요시 에이전트 파일 생성\n\n**커밋 생성 선택 시**:\n1. `/commit` 스킬 호출과 동일한 워크플로우 수행\n2. git status 확인\n3. 커밋 메시지 생성\n4. 사용자 확인 후 커밋\n\n## 에러 처리\n\n| 상황 | 처리 |\n|------|------|\n| CLAUDE.md 없음 | 새로 생성할지 사용자에게 확인 |\n| 에이전트 실패 | 해당 섹션 스킵하고 경고 표시 |\n| 제안 사항 없음 | \"이번 세션에서 추가할 내용이 없습니다\" 메시지 |\n| 선택 취소 | 정상 종료 |\n\n## 에이전트 파일\n\n| 에이전트 | 파일 경로 |\n|----------|----------|\n| doc-updater | `.claude/agents/wrap/doc-updater.md` |\n| automation-scout | `.claude/agents/wrap/automation-scout.md` |\n| learning-extractor | `.claude/agents/wrap/learning-extractor.md` |\n| followup-suggester | `.claude/agents/wrap/followup-suggester.md` |\n| duplicate-checker | `.claude/agents/wrap/duplicate-checker.md` |\n\n## 참고\n\n- 원본: [session-wrap 플러그인](https://www.linkedin.com/feed/update/urn:li:activity:7415878861919379456/)\n- 관련 스킬: `/commit`\n"},"lastSynced":"2026-03-06T06:29:10.461Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Management Agents needing automated code cleanup and organization capabilities.","zh":"非常适合需要自动代码清理和组织功能的代码管理代理。","ja":"コード管理エージェントが自動化されたコードのクリーンアップと整理機能を必要とする場合に最適です。","ko":"자동 코드 정리 및 조직 기능이 필요한 코드 관리 에이전트에 적합합니다.","es":"Perfecto para agentes de gestión de código que necesitan capacidades de limpieza y organización de código automatizadas.","fr":"Parfait pour les agents de gestion de code ayant besoin de capacités de nettoyage et d''organisation de code automatisées.","de":"Perfekt für Code-Management-Agents, die automatisierte Code-Reinigungs- und Organisationsfunktionen benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Código que necessitam de capacidades de limpeza e organização de código automatizadas.","ru":"Идеально подходит для агентов управления кодом, которым необходимы автоматические возможности очистки и организации кода.","ar":"مثالي للوكلاء إدارة الكود الذين يحتاجون إلى قدرات تنظيف وتنظيم الكود الآلي."},"recommendation":{"en":"Empowers agents to streamline development processes using automated code analysis and cleanup, supporting options like quick mode and commit exclusion, and integrating with files like CLAUDE.md.","zh":"赋予代理简化开发流程的能力，使用自动代码分析和清理，支持快速模式和提交排除等选项，并与CLAUDE.md文件等集成。","ja":"エージェントに開発プロセスを簡素化する能力を与え、自動コード分析とクリーンアップを使用し、クイックモードやコミットの除外などのオプションをサポートし、CLAUDE.mdファイルなどのファイルと統合します。","ko":"에이전트가 자동 코드 분석 및 정리와 같은 개발 프로세스를简化할 수 있는 능력을 부여하며, 빠른 모드 및 커밋 제외와 같은 옵션을 지원하고, CLAUDE.md 파일과 같은 파일과 통합합니다.","es":"Habilita a los agentes a simplificar los procesos de desarrollo utilizando análisis y limpieza de código automatizados, con opciones como modo rápido y exclusión de compromiso, e integración con archivos como CLAUDE.md.","fr":"Permet aux agents de simplifier les processus de développement en utilisant l''analyse et la nettoyage de code automatisés, avec des options comme le mode rapide et l''exclusion de commit, et en intégrant des fichiers comme CLAUDE.md.","de":"Ermächtigt Agents, Entwicklungsprozesse mithilfe automatisierter Code-Analyse und -Reinigung zu rationalisieren, mit Optionen wie Schnellmodus und Commit-Ausschluss, und integriert Dateien wie CLAUDE.md.","pt":"Habilita os agentes a otimizar os processos de desenvolvimento usando análise e limpeza de código automatizadas, suportando opções como modo rápido e exclusão de commit, e integrando-se com arquivos como CLAUDE.md.","ru":"Наделяет агентов возможностью оптимизировать процессы разработки с помощью автоматического анализа и очистки кода, поддерживая такие опции, как быстрый режим и исключение коммита, и интегрируясь с файлами типа CLAUDE.md.","ar":"يمنح الوكلاء القدرة على تحسين عمليات التطوير باستخدام تحليل وتنظيف الكود الآليين، ودعم الخيارات مثل الوضع السريع واستثناء Commit، ودمجها مع الملفات مثل CLAUDE.md."},"useCases":{"en":["Automating code cleanup at the end of Claude Code sessions","Quickly checking CLAUDE.md files for consistency","Analyzing code without immediate commit"],"zh":["在Claude Code会话结束时自动执行代码清理","快速检查CLAUDE.md文件的一致性","不提交立即分析代码"],"ja":["Claude Codeセッション終了時に自動コードクリーンアップを実行する","CLAUDE.mdファイルの整合性を迅速に確認する","コミットせずにコードを分析する"],"ko":["Claude Code 세션 종료 시 자동 코드 정리 수행","CLAUDE.md 파일의 일관성을 빠르게 확인","すぐに 커밋하지 않고 코드 분석"],"es":["Automatizar la limpieza de código al final de las sesiones de Claude Code","Comprobar rápidamente los archivos CLAUDE.md para garantizar la coherencia","Analizar código sin compromiso inmediato"],"fr":["Automatiser le nettoyage de code à la fin des sessions de Claude Code","Vérifier rapidement les fichiers CLAUDE.md pour la cohérence","Analyser le code sans commit immédiat"],"de":["Automatisieren der Code-Reinigung am Ende von Claude Code-Sitzungen","Schnell prüfen der CLAUDE.md-Dateien auf Konsistenz","Analysieren von Code ohne sofortigen Commit"],"pt":["Automatizar a limpeza de código no final das sessões de Claude Code","Verificar rapidamente os arquivos CLAUDE.md para consistência","Analisar código sem commit imediato"],"ru":["Автоматизировать очистку кода в конце сессий Claude Code","Быстро проверять файлы CLAUDE.md на согласованность","Анализировать код без немедленного коммита"],"ar":["تأتمتة تنظيف الكود في نهاية جلسات الكلود كود","التحقق بسرعة من ملفات CLAUDE.md على الاتساق","تحليل الكود بدون التزام الفوري"]},"limitations":{"en":["Requires Claude Code session context","Limited to specific file and commit interactions"],"zh":["需要Claude Code会话上下文","仅限特定文件和提交交互"],"ja":["Claude Codeセッションのコンテキストが必要","特定のファイルとコミットのやり取りのみ"],"ko":["Claude Code 세션 컨텍스트가 필요","특정 파일 및 커밋 상호 작용만"],"es":["Requiere contexto de sesión de Claude Code","Limitado a interacciones de archivos y commit específicas"],"fr":["Nécessite un contexte de session de Claude Code","Limité à des interactions de fichiers et de commit spécifiques"],"de":["Benötigt Kontext einer Claude Code-Sitzung","Begrenzt auf spezifische Datei- und Commit-Interaktionen"],"pt":["Exige contexto de sessão de Claude Code","Limitado a interações de arquivo e commit específicas"],"ru":["Требует контекста сессии Claude Code","Ограничен конкретными взаимодействиями файла и коммита"],"ar":["يتطلب سياق جلسة كلود كود","محدود بالتفاعلات المحددة للملف والالتزام"]},"version":4},"contentHash":"2937cb78b52ef5fdf3f878a5b1b6d18d402eb72bcc0cb3a507787bf0086aab6d","qualityScore":46}');
