INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('team-attention/stanford-cs146s-kr/wrap', 'wrap', 'team-attention', 'stanford-cs146s-kr', 'community', 'wrap team-attention stanford-cs146s-kr community The wrap skill automates code cleanup for AI agents, streamlining the development process. It benefits developers by simplifying code organization and management. Wrap技能是一种自动化代码分析和提交的工具，可以通过CLI命令快速实现代码检查和提交 Wrapスキルはコード分析とコミットの自動化ツールであり、CLIコマンドを使用してコードチェックとコミットを迅速に実行できる Wrap 스킬은 코드 분석 및 커밋 자동화를 수행하는 도구로 CLI 명령어를 통해 빠르게 코드 체크 및 커밋을 수행할 수 있습니다 wrap es una habilidad que automatiza la limpieza y el análisis de proyectos al finalizar una sesión wrap est une compétence qui automatise le nettoyage et l''analyse des projets à la fin d''une session wrap ist eine Fähigkeit, die die Bereinigung und Analyse von Projekten am Ende einer Sitzung automatisiert O wrap é uma ferramenta que automatiza a limpeza de código ao final de uma sessão, melhorando a produtividade do desenvolvedor. Saiba mais sobre como usá-lo Инструмент Wrap автоматически очищает код в конце сессии, повышая производительность разработчика. Узнайте больше о его использовании для ИИ Агентов اداة Wrap تتيح آلي لإنهاء الجلسات وتحسين الكود، مما يزيد من إنتاجية المطور. تعرف على المزيد حول كيفية استخدامها لأدوات الذكاء الاصطناعي how to use wrap wrap setup guide automated code cleanup wrap alternative wrap vs manual cleanup wrap install what is wrap wrap benefits for developers wrap skill for AI agents AI工具 代码分析 自动提交 CLI命令 开发效率 Wrap技能 代码检查 自动化工具 Performs automatic code cleanup at the end of a session Supports quick mode for rapid CLAUDE.md checks Allows for optional commit exclusion using the --no-commit flag Executes parallel analysis for efficient code review Utilizes command-line interface for easy execution and customization wrap is a skill that performs automatic code cleanup at the end of a session, eliminating the need for manual organization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('edrickleong/obsidian-calendar-bases/obsidian-cli', 'community', 'edrickleong', 'obsidian-calendar-bases', 'edrickleong/obsidian-calendar-bases', 'obsidian-cli', 133, 9, 46, '2026-03-04T23:38:19Z', '2026-03-06T06:30:14.676Z', 'b54257cdc0e5d04488b35b0c797bfe427b24359f0848d3c73924dcacf8da6358', '{"id":"edrickleong/obsidian-calendar-bases/obsidian-cli","name":"obsidian-cli","description":{"en":"The obsidian-cli skill allows developers to interact with a running Obsidian instance using the `obsidian` command-line interface. It provides a range of commands for creating and managing notes.","zh":"Obsidian CLI是一个强大的命令行工具，用于与运行中的Obsidian实例交互。它提供了创建、管理和操作笔记的功能","ja":"Obsidian CLIは、実行中のObsidianインスタンスと対話するための強力なコマンドラインツールです。ノートの作成、管理、操作機能を提供します","ko":"Obsidian CLI는 실행 중인 Obsidian 인스턴스와 상호 작용하기 위한 강력한 명령줄 도구입니다. 노트 생성, 관리 및 조작 기능을 제공합니다","es":"La línea de comandos de Obsidian permite a los desarrolladores interactuar con instancias de Obsidian. Utilice comandos como ''create'' y ''help'' para administrar notas.","fr":"L''interface de ligne de commande d''Obsidian permet aux développeurs d''interagir avec des instances Obsidian. Utilisez des commandes comme ''create'' et ''help'' pour gérer des notes.","de":"Die Kommandozeile von Obsidian ermöglicht es Entwicklern, mit Obsidian-Instanzen zu interagieren. Verwenden Sie Befehle wie ''create'' und ''help'', um Notizen zu verwalten.","pt":"O Obsidian CLI é uma ferramenta de linha de comando para interagir com instâncias em execução do Obsidian.","ru":"Obsidian CLI — это инструмент командной строки для взаимодействия с запущенными экземплярами Obsidian для ИИ Агентов.","ar":"Obsidian CLI هو أداة سطر أوامر للتفاعل مع مثيلات تشغيل Obsidian لأدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"obsidian-cli: Setup Guide for AI Agents | AI Agent Skill","zh":"Obsidian CLI Setup Guide - AI工具快速入门","ja":"Obsidian CLI ベストプラクティス - AIエージェントの活用方法","ko":"Obsidian CLI 사용자 가이드 - AI 툴을 위한 CLI 명령어","es":"Guía de configuración de obsidian-cli para desarrolladores","fr":"Guide de démarrage rapide pour obsidian-cli","de":"Einrichtungsanleitung für obsidian-cli-Entwickler","pt":"Guia de Configuração do Obsidian CLI","ru":"Настройка Obsidian CLI: Инструмент для ИИ Агентов","ar":"دليل إعداد Obsidian CLI لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock the full potential of Obsidian with the obsidian-cli skill. Learn how to interact with a running Obsidian instance and automate tasks. Get started now!","zh":"了解Obsidian CLI的命令参考、语法和功能，快速掌握AI工具的使用方法","ja":"Obsidian CLIのコマンドリファレンス、シンタックス、機能をマスターして、AIエージェントの活用を始めましょう","ko":"Obsidian CLI의 명령어 참조, 구문 및 기능을 알아보고 AI 툴의 사용 방법을 익히세요","es":"Aprende a utilizar la línea de comandos de Obsidian para interactuar con instancias de Obsidian. Descubre los comandos y parámetros disponibles.","fr":"Découvrez comment utiliser l''interface de ligne de commande d''Obsidian pour interagir avec des instances Obsidian. Consultez les commandes et les paramètres ...","de":"Erfahren Sie, wie Sie die Kommandozeile von Obsidian verwenden, um mit Obsidian-Instanzen zu interagieren. Entdecken Sie die verfügbaren Befehle und Parameter.","pt":"Aprenda a usar o Obsidian CLI para interagir com instâncias em execução e explore os comandos disponíveis","ru":"Узнайте, как использовать Obsidian CLI для взаимодействия с запущенными экземплярами и изучите доступные команды для ИИ Агентов","ar":"تعرف على كيفية استخدام Obsidian CLI للتفاعل مع مثيلات تشغيل وأدوات الذكاء الاصطناعي"},"definition":{"en":"obsidian-cli is a command-line interface for interacting with a running Obsidian instance, providing a range of commands for note creation and management.","zh":"Obsidian CLI是一种用于与Obsidian交互的命令行工具，提供了创建和管理笔记的功能","ja":"Obsidian CLIは、Obsidianと対話するためのコマンドラインツールであり、ノートの作成と管理機能を提供します","ko":"Obsidian CLI는 Obsidian과 상호 작용하기 위한 명령줄 도구로 노트 생성과 관리 기능을 제공합니다","es":"La línea de comandos de Obsidian es una herramienta de línea de comandos que permite a los desarrolladores interactuar con instancias de Obsidian.","fr":"L''interface de ligne de commande d''Obsidian est un outil de ligne de commande qui permet aux développeurs d''interagir avec des instances Obsidian.","de":"Die Kommandozeile von Obsidian ist ein Kommandozeilen-Tool, das es Entwicklern ermöglicht, mit Obsidian-Instanzen zu interagieren.","pt":"O que é Obsidian CLI? É uma ferramenta de linha de comando para interagir com o Obsidian.","ru":"Что такое Obsidian CLI? Это инструмент командной строки для взаимодействия с Obsidian для ИИ Агентов.","ar":"ما هو Obsidian CLI? هو أداة سطر أوامر للتفاعل مع Obsidian لأدوات الذكاء الاصطناعي."},"features":{"en":["Runs `obsidian help` to display all available commands","Supports parameter values with `=` and quoted values with spaces","Uses flags as boolean switches with no value","Creates new notes with `obsidian create` command","Allows silent overwriting of existing notes"],"zh":["支持创建和管理笔记","提供命令参考和语法指导","支持参数和标志的使用","可以与运行中的Obsidian实例交互"],"ja":["ノートの作成と管理機能を提供","コマンドリファレンスとシンタックスガイドを提供","パラメータとフラグの使用をサポート","実行中のObsidianインスタンスと対話可能"],"ko":["노트 생성과 관리 기능을 제공","명령어 참조와 구문 가이드를 제공","매개변수와 플래그의 사용을 지원","실행 중인 Obsidian 인스턴스와 상호 작용 가능"],"es":["Soporte para parámetros con valores","Uso de banderas booleanas sin valor","Comando ''create'' para crear notas","Comando ''help'' para ver la ayuda","Compatibilidad con valores con espacios","Documentación completa en https://help.obsidian.md/cli"],"fr":["Prise en charge des paramètres avec des valeurs","Utilisation de commutateurs booléens sans valeur","Commande ''create'' pour créer des notes","Commande ''help'' pour afficher l''aide","Compatibilité avec des valeurs contenant des espaces","Documentation complète sur https://help.obsidian.md/cli"],"de":["Unterstützung für Parameter mit Werten","Verwendung von booleschen Flags ohne Wert","Befehl ''create'' zum Erstellen von Notizen","Befehl ''help'' zur Anzeige der Hilfe","Kompatibilität mit Werten mit Leerzeichen","Vollständige Dokumentation unter https://help.obsidian.md/cli"],"pt":["Parâmetros com valores atribuídos com =","Flags booleanos sem valor","Comando create para criar notas","Comando help para visualizar comandos disponíveis","Suporte a valores com espaços quoting","Integração com instâncias em execução do Obsidian"],"ru":["Параметры с присвоенными значениями с =","Булевые флаги без значения","Команда create для создания заметок","Команда help для просмотра доступных команд для ИИ Агентов","Поддержка значений с пробелами quoting","Интеграция с запущенными экземплярами Obsidian"],"ar":["معاملات مع قيم معينة بالمساواة =","أعلام منطقية بدون قيمة","أمر create لإنشاء ملاحظات","أمر help لعرض الأوامر المتاحة لأدوات الذكاء الاصطناعي","دعم للقيم مع مسافات quoting","التكامل مع مثيلات تشغيل Obsidian"]},"keywords":{"en":["how to use obsidian-cli","obsidian-cli setup guide","obsidian-cli alternative","obsidian-cli vs other note-taking tools","obsidian-cli install","what is obsidian-cli","obsidian-cli documentation","obsidian-cli commands","obsidian-cli flags"],"zh":["Obsidian CLI","AI工具","命令行工具","笔记管理","Obsidian命令参考","CLI语法","AIエージェント","Obsidian实例"],"ja":["Obsidian CLI","AIエージェント","コマンドラインツール","ノート管理","Obsidianコマンドリファレンス","CLIシンタックス","対話式ツール","Obsidianインスタンス"],"ko":["Obsidian CLI","AI 툴","명령줄 도구","노트 관리","Obsidian 명령어 참조","CLI 구문","상호 작용 도구","Obsidian 인스턴스"],"es":["obsidian cli","herramientas de línea de comandos","desarrollo de notas","comandos de obsidian","parámetros de línea de comandos","banderas booleanas","crear notas con cli","ayuda de obsidian cli","documentación de obsidian cli"],"fr":["obsidian cli","outils de ligne de commande","développement de notes","commandes d''obsidian","paramètres de ligne de commande","commutateurs booléens","créer des notes avec cli","aide d''obsidian cli","documentation d''obsidian cli"],"de":["obsidian cli","kommandozeilen-tools","notizen-entwicklung","obsidian-befehle","kommandozeilen-parameter","boolesche flags","notizen mit cli erstellen","hilfe von obsidian cli","dokumentation von obsidian cli"],"pt":["Obsidian CLI","ferramenta de linha de comando","interagir com instâncias em execução","comandos disponíveis","parâmetros com valores","flags booleanos","comando create","comando help"],"ru":["Obsidian CLI","инструмент командной строки","взаимодействие с запущенными экземплярами","доступные команды для ИИ Агентов","параметры с присвоенными значениями","булевые флаги","команда create","команда help"],"ar":["Obsidian CLI","أداة سطر أوامر","التفاعل مع مثيلات تشغيل","أوامر متاحة لأدوات الذكاء الاصطناعي","معاملات مع قيم معينة","أعلام منطقية","أمر create","أمر help"]}},"owner":"edrickleong","repo":"obsidian-calendar-bases","repoPath":"edrickleong/obsidian-calendar-bases","stars":133,"forks":9,"updatedAt":"2026-03-04T23:38:19Z","topics":[],"category":"community","skillMd":{"name":"obsidian-cli","description":"Interact with Obsidian vaults using the Obsidian CLI to read, create, search, and manage notes, tasks, properties, and more. Also supports plugin and theme development with commands to reload plugins, run JavaScript, capture errors, take screenshots, and inspect the DOM. Use when the user asks to interact with their Obsidian vault, manage notes, search vault content, perform vault operations from the command line, or develop and debug Obsidian plugins and themes.","bodyPreview":"# Obsidian CLI\n\nUse the `obsidian` CLI to interact with a running Obsidian instance. Requires Obsidian to be open.\n\n## Command reference\n\nRun `obsidian help` to see all available commands. This is always up to date. Full docs: https://help.obsidian.md/cli\n\n## Syntax\n\n**Parameters** take a value with `=`. Quote values with spaces:\n\n```bash\nobsidian create name=\"My Note\" content=\"Hello world\"\n```\n\n**Flags** are boolean switches with no value:\n\n```bash\nobsidian create name=\"My Note\" silent overwrit","body":"# Obsidian CLI\n\nUse the `obsidian` CLI to interact with a running Obsidian instance. Requires Obsidian to be open.\n\n## Command reference\n\nRun `obsidian help` to see all available commands. This is always up to date. Full docs: https://help.obsidian.md/cli\n\n## Syntax\n\n**Parameters** take a value with `=`. Quote values with spaces:\n\n```bash\nobsidian create name=\"My Note\" content=\"Hello world\"\n```\n\n**Flags** are boolean switches with no value:\n\n```bash\nobsidian create name=\"My Note\" silent overwrite\n```\n\nFor multiline content use `\\n` for newline and `\\t` for tab.\n\n## File targeting\n\nMany commands accept `file` or `path` to target a file. Without either, the active file is used.\n\n- `file=<name>` — resolves like a wikilink (name only, no path or extension needed)\n- `path=<path>` — exact path from vault root, e.g. `folder/note.md`\n\n## Vault targeting\n\nCommands target the most recently focused vault by default. Use `vault=<name>` as the first parameter to target a specific vault:\n\n```bash\nobsidian vault=\"My Vault\" search query=\"test\"\n```\n\n## Common patterns\n\n```bash\nobsidian read file=\"My Note\"\nobsidian create name=\"New Note\" content=\"# Hello\" template=\"Template\" silent\nobsidian append file=\"My Note\" content=\"New line\"\nobsidian search query=\"search term\" limit=10\nobsidian daily:read\nobsidian daily:append content=\"- [ ] New task\"\nobsidian property:set name=\"status\" value=\"done\" file=\"My Note\"\nobsidian tasks daily todo\nobsidian tags sort=count counts\nobsidian backlinks file=\"My Note\"\n```\n\nUse `--copy` on any command to copy output to clipboard. Use `silent` to prevent files from opening. Use `total` on list commands to get a count.\n\n## Plugin development\n\n### Develop/test cycle\n\nAfter making code changes to a plugin or theme, follow this workflow:\n\n1. **Reload** the plugin to pick up changes:\n   ```bash\n   obsidian plugin:reload id=my-plugin\n   ```\n2. **Check for errors** — if errors appear, fix and repeat from step 1:\n   ```bash\n   obsidian dev:errors\n   ```\n3. **Verify visually** with a screenshot or DOM inspection:\n   ```bash\n   obsidian dev:screenshot path=screenshot.png\n   obsidian dev:dom selector=\".workspace-leaf\" text\n   ```\n4. **Check console output** for warnings or unexpected logs:\n   ```bash\n   obsidian dev:console level=error\n   ```\n\n### Additional developer commands\n\nRun JavaScript in the app context:\n\n```bash\nobsidian eval code=\"app.vault.getFiles().length\"\n```\n\nInspect CSS values:\n\n```bash\nobsidian dev:css selector=\".workspace-leaf\" prop=background-color\n```\n\nToggle mobile emulation:\n\n```bash\nobsidian dev:mobile on\n```\n\nRun `obsidian help` to see additional developer commands including CDP and debugger controls.\n"},"lastSynced":"2026-03-06T06:30:14.676Z","agentAnalysis":{"suitability":{"en":"Perfect for Note-Taking Agents requiring seamless integration with Obsidian instances for advanced note management capabilities.","zh":"非常适合需要与Obsidian实例进行无缝集成以实现高级笔记管理功能的笔记记录代理。","ja":"Obsidianインスタンスとのシームレスな統合を必要とするノートテイキングエージェントに最適です。","ko":"Obsidian 인스턴스와의无缝 통합을 필요로 하는 노트 기록 에이전트에게 적합합니다.","es":"Perfecto para agentes de toma de notas que requieren una integración perfecta con instancias de Obsidian para capacidades de gestión de notas avanzadas.","fr":"Parfait pour les agents de prise de notes nécessitant une intégration parfaite avec des instances Obsidian pour des capacités de gestion de notes avancées.","de":"Perfekt für Notiz-Agents, die eine nahtlose Integration mit Obsidian-Instanzen für erweiterte Notizmanagementfunktionen erfordern.","pt":"Perfeito para Agentes de Notas que exigem integração sem interrupções com instâncias do Obsidian para capacidades avançadas de gerenciamento de notas.","ru":"Идеально подходит для агентов заметок, требующих бесшовной интеграции с экземплярами Obsidian для расширенных возможностей управления заметками.","ar":"مثالي للوكلاء ملاحظة المتطلبات التكامل السلس مع مثيلات Obsidian لتقديم إمكانيات متقدمة لإدارة الملاحظات."},"recommendation":{"en":"Empowers agents to create and manage notes using the `obsidian` command-line interface, supporting parameters and flags for customized note creation, such as setting note names and content, and utilizing commands like `obsidian create` for efficient note generation.","zh":"赋予代理创建和管理笔记的能力，使用`obsidian`命令行接口，支持参数和标志以实现自定义笔记创建，例如设置笔记名称和内容，并利用命令如`obsidian create`进行高效的笔记生成。","ja":"エージェントにノートを作成および管理する機能を提供します。`obsidian`コマンドラインインターフェイスを使用し、パラメータおよびフラグをサポートして、ノート名およびコンテンツの設定などのカスタムノート作成を実現します。さらに、`obsidian create`などのコマンドを使用して効率的なノート生成を実現します。","ko":"에이전트에게 노트를 생성하고 관리할 수 있는 능력을 부여합니다. `obsidian` 명령줄 인터페이스를 사용하여 매개변수와 플래그를 지원하여 노트 이름 및 내용 설정 등의 사용자 지정 노트 생성을 가능하게 하며, `obsidian create`와 같은 명령을 사용하여 효율적인 노트 생성을实现합니다.","es":"Habilita a los agentes a crear y gestionar notas utilizando la interfaz de línea de comandos `obsidian`, que admite parámetros y opciones para la creación personalizada de notas, como establecer nombres y contenido de notas, y utilizar comandos como `obsidian create` para una generación eficiente de notas.","fr":"Permet aux agents de créer et de gérer des notes en utilisant l''interface de ligne de commande `obsidian`, qui prend en charge les paramètres et les indicateurs pour la création personnalisée de notes, tels que définir les noms et le contenu des notes, et en utilisant des commandes comme `obsidian create` pour une génération efficace de notes.","de":"Ermöglicht es Agents, Notizen zu erstellen und zu verwalten, indem sie die `obsidian`-Kommandozeilenoberfläche verwenden, die Parameter und Flaggen für die personalisierte Notizerstellung unterstützt, wie z.B. das Festlegen von Notiznamen und -inhalt und die Verwendung von Befehlen wie `obsidian create` für eine effiziente Notizgenerierung.","pt":"Habilita os agentes a criarem e gerenciarem notas usando a interface de linha de comando `obsidian`, suportando parâmetros e sinalizadores para criação personalizada de notas, como definir nomes e conteúdo de notas, e utilizando comandos como `obsidian create` para geração eficiente de notas.","ru":"Наделяет агентов возможностью создавать и управлять заметками с помощью командной строки `obsidian`, поддерживая параметры и флаги для настройки создания заметок, такие как задание имен и содержания заметок, и использует команды как `obsidian create` для эффективного создания заметок.","ar":"يمنح الوكلاء القدرة على إنشاءnotes وإدارتها باستخدام واجهة سطر الأوامر `obsidian`، ودعم المعاملات والflags لإنشاء ملاحظات مخصصة، مثل تعيين أسماء المحتوى الملاحظات، واستخدام أوامر مثل `obsidian create` لإنشاء ملاحظات فعالة."},"useCases":{"en":["Automating note creation with specific names and content","Managing existing notes using the `obsidian` CLI","Integrating Obsidian with other tools for enhanced workflow automation"],"zh":["使用特定名称和内容自动创建笔记","使用`obsidian` CLI管理现有笔记","将Obsidian与其他工具集成以增强工作流自动化"],"ja":["特定の名前と内容で自動的にノートを作成する","`obsidian` CLIを使用して既存のノートを管理する","Obsidianを他のツールと統合してワークフロー自動化を強化する"],"ko":["특정 이름과 내용으로 자동으로 노트를 생성하는 것","`obsidian` CLI를 사용하여 기존 노트를 관리하는 것","Obsidian을 다른 도구와 통합하여 워크플로 자동화를 강화하는 것"],"es":["Automatización de la creación de notas con nombres y contenido específicos","Gestión de notas existentes mediante la interfaz de línea de comandos `obsidian`","Integración de Obsidian con otras herramientas para una automatización de flujo de trabajo mejorada"],"fr":["Automatisation de la création de notes avec des noms et un contenu spécifiques","Gestion de notes existantes à l''aide de l''interface de ligne de commande `obsidian`","Intégration d''Obsidian avec d''autres outils pour une automatisation améliorée du flux de travail"],"de":["Automatisierung der Notizerstellung mit spezifischen Namen und Inhalten","Verwaltung von bestehenden Notizen mithilfe der `obsidian`-Kommandozeilenoberfläche","Integration von Obsidian mit anderen Tools für eine verbesserte Workflow-Automatisierung"],"pt":["Automatizar a criação de notas com nomes e conteúdo específicos","Gerenciar notas existentes usando a CLI `obsidian`","Integrar o Obsidian com outras ferramentas para automação de fluxo de trabalho aprimorada"],"ru":["Автоматизировать создание заметок с конкретными именами и содержанием","Управлять существующими заметками с помощью CLI `obsidian`","Интегрировать Obsidian с другими инструментами для улучшения автоматизации рабочего процесса"],"ar":["توفير автоматизация إنشاء الملاحظات بأسماء ومحتوى محددة","إدارة الملاحظات الحالية باستخدام CLI `obsidian`","دمج Obsidian مع أدوات أخرى لتحسين آليّة تدفق العمل"]},"limitations":{"en":["Requires Obsidian to be open and running","Limited to interacting with a single running Obsidian instance at a time"],"zh":["需要Obsidian打开并运行","仅限与单个运行中的Obsidian实例进行交互"],"ja":["Obsidianが開かれ、実行されている必要がある","一度に1つの実行中のObsidianインスタンスのみと対話することができる"],"ko":["Obsidian이 열리고 실행되어야 함","한 번에 하나의 실행 중인 Obsidian 인스턴스만과 상호 작용할 수 있음"],"es":["Requiere que Obsidian esté abierto y en ejecución","Limitado a interactuar con una sola instancia de Obsidian en ejecución a la vez"],"fr":["Nécessite que Obsidian soit ouvert et en cours d''exécution","Limité à l''interaction avec une seule instance Obsidian en cours d''exécution à la fois"],"de":["Erfordert, dass Obsidian geöffnet und ausgeführt wird","Begrenzt auf die Interaktion mit einer einzigen laufenden Obsidian-Instanz gleichzeitig"],"pt":["Exige que o Obsidian esteja aberto e em execução","Limitado a interagir com uma única instância do Obsidian em execução por vez"],"ru":["Требует открытия и запуска Obsidian","Ограничен взаимодействием с одной запущенной экземпляром Obsidian за раз"],"ar":["يتطلب أن يكون Obsidian مفتوحاً ويعمل","محدود بالتفاعل مع مثيل واحد من Obsidian يعمل في الوقت نفسه"]},"version":4},"contentHash":"b54257cdc0e5d04488b35b0c797bfe427b24359f0848d3c73924dcacf8da6358","qualityScore":46}');
