INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('edrickleong/obsidian-calendar-bases/obsidian-cli', 'obsidian-cli', 'edrickleong', 'obsidian-calendar-bases', 'community', 'obsidian-cli edrickleong obsidian-calendar-bases community The obsidian-cli skill allows developers to interact with a running Obsidian instance using the `obsidian` command-line interface. It provides a range of commands for creating and managing notes. Obsidian CLI是一个强大的命令行工具，用于与运行中的Obsidian实例交互。它提供了创建、管理和操作笔记的功能 Obsidian CLIは、実行中のObsidianインスタンスと対話するための強力なコマンドラインツールです。ノートの作成、管理、操作機能を提供します Obsidian CLI는 실행 중인 Obsidian 인스턴스와 상호 작용하기 위한 강력한 명령줄 도구입니다. 노트 생성, 관리 및 조작 기능을 제공합니다 La línea de comandos de Obsidian permite a los desarrolladores interactuar con instancias de Obsidian. Utilice comandos como ''create'' y ''help'' para administrar notas. L''interface de ligne de commande d''Obsidian permet aux développeurs d''interagir avec des instances Obsidian. Utilisez des commandes comme ''create'' et ''help'' pour gérer des notes. Die Kommandozeile von Obsidian ermöglicht es Entwicklern, mit Obsidian-Instanzen zu interagieren. Verwenden Sie Befehle wie ''create'' und ''help'', um Notizen zu verwalten. O Obsidian CLI é uma ferramenta de linha de comando para interagir com instâncias em execução do Obsidian. Obsidian CLI — это инструмент командной строки для взаимодействия с запущенными экземплярами Obsidian для ИИ Агентов. Obsidian CLI هو أداة سطر أوامر للتفاعل مع مثيلات تشغيل Obsidian لأدوات الذكاء الاصطناعي. how to use obsidian-cli obsidian-cli setup guide obsidian-cli alternative obsidian-cli vs other note-taking tools obsidian-cli install what is obsidian-cli obsidian-cli documentation obsidian-cli commands obsidian-cli flags Obsidian CLI AI工具 命令行工具 笔记管理 Obsidian命令参考 CLI语法 AIエージェント Obsidian实例 Runs `obsidian help` to display all available commands Supports parameter values with `=` and quoted values with spaces Uses flags as boolean switches with no value Creates new notes with `obsidian create` command Allows silent overwriting of existing notes obsidian-cli is a command-line interface for interacting with a running Obsidian instance, providing a range of commands for note creation and management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('marketcalls/vectorbt-backtesting-skills/strategy-compare', 'community', 'marketcalls', 'vectorbt-backtesting-skills', 'marketcalls/vectorbt-backtesting-skills', 'strategy-compare', 92, 22, 46, '2026-03-05T15:37:54Z', '2026-03-06T06:32:08.151Z', '48d10a4fffc959a7e3ac14c33f61cc2984baab792faaa6b922d73ccc001c3513', '{"id":"marketcalls/vectorbt-backtesting-skills/strategy-compare","name":"strategy-compare","description":{"en":"The strategy-compare skill allows developers to backtest trading strategies using VectorBT, supporting Indian, US, and Crypto markets. It benefits developers and traders who need to compare and optimize their strategies.","zh":"使用策略比较工具，比较不同的交易策略，支持VectorBT，包括现实的交易成本建模和12个预制的策略模板","ja":"戦略比較ツールを使用して、異なる取引戦略を比較します。VectorBTをサポートし、現実的な取引コストモデリングと12の戦略テンプレートを備えています","ko":"전략 비교 도구를 사용하여 다른 거래 전략을 비교합니다. VectorBT를 지원하며 실제 거래 비용 모델링 및 12개의 전략 템플릿을 제공합니다","es":"La habilidad strategy-compare permite a los desarrolladores comparar estrategias de trading utilizando VectorBT y QuantStats en diferentes mercados","fr":"La compétence strategy-compare permet aux développeurs de comparer des stratégies de trading à l''aide de VectorBT et QuantStats sur différents marchés","de":"Die Fähigkeit strategy-compare ermöglicht es Entwicklern, Handelsstrategien mit VectorBT und QuantStats in verschiedenen Märkten zu vergleichen","pt":"O strategy-compare é uma habilidade de codificação agente para testar estratégias de negociação usando VectorBT","ru":"Strategy-compare - это навык агентского кодирования для тестирования торговых стратегий с помощью VectorBT","ar":"strategy-compare هو مهارة ترميز وكلية لاختبار استراتيجيات التداول باستخدام VectorBT"},"seo":{"title":{"en":"strategy-compare: Backtesting Trading Strategies Setup Gu...","zh":"策略比较工具 - 使用VectorBT进行交易策略优化","ja":"戦略比較ツール - VectorBTを使用した取引戦略の最適化","ko":"전략 비교 도구 - VectorBT를 사용한 거래 전략 최적화","es":"Guía de configuración de strategy-compare para agentes de IA","fr":"Configurer strategy-compare pour les outils d''IA","de":"Einrichtungsleitfaden für strategy-compare mit KI-Agenten","pt":"Guia de Configuração do strategy-compare para Análise de ...","ru":"Настройка strategy-compare для сравнения торговых стратег...","ar":"دليل إعداد strategy-compare لتحليل استراتيجيات التداول مع..."},"description":{"en":"Discover how to compare trading strategies with strategy-compare, featuring VectorBT, QuantStats, and realistic transaction cost modeling. Get started now!","zh":"使用VectorBT的策略比较工具，支持印度、美国和加密货币市场，具有现实的交易成本建模和12个预制的策略模板","ja":"VectorBTを使用した戦略比較ツール。インド、米国、および暗号通貨市場をサポートし、現実的な取引コストモデリングと12の戦略テンプレートを備えています","ko":"VectorBT를 사용한 전략 비교 도구. 인도, 미국 및 암호화폐 시장 지원, 실제 거래 비용 모델링 및 12개의 전략 템플릿","es":"Aprende a comparar estrategias de trading con VectorBT y QuantStats en mercados indios, estadounidenses y de criptomonedas","fr":"Découvrez comment comparer des stratégies de trading avec VectorBT et QuantStats sur les marchés indiens, américains et de crypto","de":"Erfahren Sie, wie Sie Handelsstrategien mit VectorBT und QuantStats in indischen, US-amerikanischen und Kryptomärkten vergleichen","pt":"Aprenda a configurar o strategy-compare para comparar estratégias de negociação usando VectorBT e QuantStats","ru":"Узнайте, как настроить strategy-compare для сравнения торговых стратегий с помощью VectorBT и QuantStats","ar":"تعرف على كيفية إعداد strategy-compare لتحليل استراتيجيات التداول باستخدام VectorBT و QuantStats"},"definition":{"en":"strategy-compare is a coding skill for backtesting trading strategies using VectorBT, supporting multiple markets and featuring realistic transaction cost modeling.","zh":"策略比较工具是一种使用VectorBT的AI工具，用于比较不同的交易策略","ja":"戦略比較ツールは、VectorBTを使用したAIツールであり、異なる取引戦略を比較するために使用されます","ko":"전략 비교 도구는 VectorBT를 사용하는 AI 도구로, 다른 거래 전략을 비교하는 데 사용됩니다","es":"Strategy-compare es una habilidad de agente de IA para comparar estrategias de trading","fr":"Strategy-compare est une compétence d''outil d''IA pour comparer des stratégies de trading","de":"Strategy-compare ist eine Fähigkeit von KI-Agenten zum Vergleichen von Handelsstrategien","pt":"O que é strategy-compare? É uma habilidade de codificação agente para comparar estratégias de negociação","ru":"Что такое strategy-compare? Это навык агентского кодирования для сравнения торговых стратегий","ar":"ما هو strategy-compare؟ إنه مهارة ترميز وكلية لمقارنة استراتيجيات التداول"},"features":{"en":["Supports backtesting of trading strategies using VectorBT","Features realistic transaction cost modeling for accurate results","Includes 12 ready-made strategy templates for easy comparison","Utilizes QuantStats tearsheets for in-depth strategy analysis","Allows for Monte-Carlo simulations and walk-forward optimization","Supports TA-Lib indicators for technical analysis"],"zh":["支持VectorBT","现实的交易成本建模","12个预制的策略模板","支持印度、美国和加密货币市场","TA-Lib指标支持","QuantStats tearsheets支持"],"ja":["VectorBTをサポート","現実的な取引コストモデリング","12の戦略テンプレート","インド、米国、および暗号通貨市場をサポート","TA-Lib指標のサポート","QuantStats tearsheetsのサポート"],"ko":["VectorBT 지원","실제 거래 비용 모델링","12개의 전략 템플릿","인도, 미국 및 암호화폐 시장 지원","TA-Lib 지표 지원","QuantStats tearsheets 지원"],"es":["Soporte para mercados indios, estadounidenses y de criptomonedas","Modelado de costos de transacción realista","Indicadores TA-Lib","Informes QuantStats","12 plantillas de estrategias predefinidas"],"fr":["Prise en charge des marchés indiens, américains et de crypto","Modélisation de coûts de transaction réaliste","Indicateurs TA-Lib","Feuilles de route QuantStats","12 modèles de stratégies prédéfinis"],"de":["Unterstützung für indische, US-amerikanische und Kryptomärkte","Realistisches Transaktionskostenmodell","TA-Lib-Indikatoren","QuantStats-Berichte","12 vordefinierte Strategietemplates"],"pt":["Suporte a mercados indianos, americanos e de criptomoedas","Modelagem de custos de transação realista","Indicadores TA-Lib","Tearsheets QuantStats","12 modelos de estratégia prontos para uso"],"ru":["Поддержка индийских, американских и криптовалютных рынков","Реалистичная модель транзакционных издержек","Индикаторы TA-Lib","Tearsheets QuantStats","12 готовых шаблонов стратегий"],"ar":["دعم الأسواق الهندية والأمريكية و أسواق العملات الرقمية","نماذج التكلفة التحويلية الواقعية","مؤشرات TA-Lib","الورق المالي QuantStats","12 نموذج جاهز للاستراتيجيات"]},"keywords":{"en":["how to use strategy-compare","strategy-compare alternative","strategy-compare setup guide","what is strategy-compare","strategy-compare vs backtrader","vectorbt backtesting","quantstats tearsheets","trading strategy optimization","monte-carlo simulation in trading","walk-forward optimization"],"zh":["策略比较工具","VectorBT","交易策略优化","AI工具","量化交易","Python编程","TA-Lib指标","QuantStats tearsheets"],"ja":["戦略比較ツール","VectorBT","取引戦略の最適化","AIツール","量化取引","Pythonプログラミング","TA-Lib指標","QuantStats tearsheets"],"ko":["전략 비교 도구","VectorBT","거래 전략 최적화","AI 도구","량화 거래","Python 프로그래밍","TA-Lib 지표","QuantStats tearsheets"],"es":["agentes de IA para trading","estrategias de trading","VectorBT","QuantStats","mercados indios","mercados estadounidenses","mercados de criptomonedas","modelado de costos de transacción"],"fr":["outils d''IA pour le trading","stratégies de trading","VectorBT","QuantStats","marchés indiens","marchés américains","marchés de crypto","modélisation de coûts de transaction"],"de":["KI-Agenten für Trading","Handelsstrategien","VectorBT","QuantStats","indische Märkte","US-amerikanische Märkte","Kryptomärkte","Transaktionskostenmodellierung"],"pt":["strategy-compare","análise de estratégias de negociação","VectorBT","QuantStats","mercados indianos","mercados americanos","criptomoedas","modelagem de custos de transação"],"ru":["strategy-compare","сравнение торговых стратегий","VectorBT","QuantStats","индийские рынки","американские рынки","криптовалюты","моделирование транзакционных издержек"],"ar":["strategy-compare","تحليل استراتيجيات التداول","VectorBT","QuantStats","الأسواق الهندية","الأسواق الأمريكية","العملات الرقمية","نماذج التكلفة التحويلية"]}},"owner":"marketcalls","repo":"vectorbt-backtesting-skills","repoPath":"marketcalls/vectorbt-backtesting-skills","stars":92,"forks":22,"updatedAt":"2026-03-05T15:37:54Z","topics":["agent-skills","backtesting","monte-carlo","optimization","python","quantstats","robustness","tearsheets","vectorbt","walk-forward"],"category":"community","skillMd":{"name":"strategy-compare","description":"Compare multiple strategies or directions (long vs short vs both) on the same symbol. Generates side-by-side stats table.","bodyPreview":"Create a strategy comparison script.\n\n## Arguments\n\nParse `$ARGUMENTS` as: symbol followed by strategy names\n\n- `$0` = symbol (e.g., SBIN, RELIANCE, NIFTY)\n- Remaining args = strategies to compare (e.g., ema-crossover rsi donchian)\n\nIf only a symbol is given with no strategies, compare: ema-crossover, rsi, donchian, supertrend.\nIf \"long-vs-short\" is one of the strategies, compare longonly vs shortonly vs both for the first real strategy.\n\n## Instructions\n\n1. Read the vectorbt-expert skill rules","body":"Create a strategy comparison script.\n\n## Arguments\n\nParse `$ARGUMENTS` as: symbol followed by strategy names\n\n- `$0` = symbol (e.g., SBIN, RELIANCE, NIFTY)\n- Remaining args = strategies to compare (e.g., ema-crossover rsi donchian)\n\nIf only a symbol is given with no strategies, compare: ema-crossover, rsi, donchian, supertrend.\nIf \"long-vs-short\" is one of the strategies, compare longonly vs shortonly vs both for the first real strategy.\n\n## Instructions\n\n1. Read the vectorbt-expert skill rules for reference patterns\n2. Create `backtesting/strategy_comparison/` directory if it doesn''t exist (on-demand)\n3. Create a `.py` file in `backtesting/strategy_comparison/` named `{symbol}_strategy_comparison.py`\n3. The script must:\n   - Fetch data once via OpenAlgo\n   - If user provides a DuckDB path, load data directly via `duckdb.connect(path, read_only=True)`. See vectorbt-expert `rules/duckdb-data.md`.\n   - If `openalgo.ta` is not importable (standalone DuckDB), use inline `exrem()` fallback.\n   - **Use TA-Lib for ALL indicators** (never VectorBT built-in)\n   - **Use OpenAlgo ta** for specialty indicators (Supertrend, Donchian, etc.)\n   - Clean signals with `ta.exrem()` (always `.fillna(False)` before exrem)\n   - Run each strategy on the same data\n   - **Indian delivery fees**: `fees=0.00111, fixed_fees=20` for delivery equity\n   - Collect key metrics from each into a side-by-side DataFrame\n   - **Include NIFTY benchmark** in the comparison table (via OpenAlgo `NSE_INDEX`)\n   - **Print Strategy vs Benchmark comparison table**: Total Return, Sharpe, Sortino, Max DD, Win Rate, Trades, Profit Factor\n   - **Explain results** in plain language - which strategy performed best and why\n   - Plot overlaid equity curves for all strategies using Plotly (`template=\"plotly_dark\"`)\n   - Save comparison to CSV\n4. Never use icons/emojis in code or logger output\n\n## Example Usage\n\n`/strategy-compare RELIANCE ema-crossover rsi donchian`\n`/strategy-compare SBIN long-vs-short ema-crossover`\n"},"lastSynced":"2026-03-06T06:32:08.151Z","agentAnalysis":{"suitability":{"en":"Perfect for Trading Agents needing advanced backtesting and strategy comparison capabilities using VectorBT","zh":"非常适合需要使用 VectorBT 进行高级回测和策略比较的交易代理","ja":"VectorBT を使用した高度なバックテストと戦略比較機能を必要とするトレーディング エージェントに最適","ko":"VectorBT를 사용한 고급 백테스팅 및 전략 비교 기능이 필요한 트레이딩 에이전트에게 최적","es":"Perfecto para Agentes de Trading que necesitan capacidades de retroanálisis y comparación de estrategias avanzadas utilizando VectorBT","fr":"Parfait pour les Agents de Trading ayant besoin de capacités de backtesting et de comparaison de stratégies avancées utilisant VectorBT","de":"Perfekt für Trading-Agents, die erweiterte Backtesting- und Strategievergleichsfunktionen mit VectorBT benötigen","pt":"Perfeito para Agentes de Negociação que necessitam de capacidades avançadas de backtesting e comparação de estratégias usando VectorBT","ru":"Идеально подходит для торговых агентов, которым необходимы продвинутые возможности тестирования и сравнения стратегий с использованием VectorBT","ar":"مثالي لويكلاء التداول الذين يحتاجون إلى قابليات اختبار وتقارن متقدمة للاستراتيجيات باستخدام VectorBT"},"recommendation":{"en":"Empowers agents to backtest and compare multiple trading strategies across Indian, US, and Crypto markets, utilizing technical indicators like ema-crossover, rsi, and donchian, and supporting long-vs-short strategy comparisons with libraries like VectorBT","zh":"使代理能够使用技术指标（如 ema-crossover、rsi 和 donchian）在印度、美国和加密货币市场中回测和比较多个交易策略，并支持使用 VectorBT 等库进行长短策略比较","ja":"エージェントがインド、米国、クリプト通貨市場で複数のトレーディング戦略をテクニカルインジケーター（ema-crossover、rsi、donchian など）を使用してバックテストおよび比較できるようにし、VectorBT などのライブラリを使用したロングショート戦略の比較をサポート","ko":"에이전트가 기술 지표(ema-crossover, rsi, donchian 등)를 사용하여 인도, 미국, 암호화폐 시장에서 여러 트레이딩 전략을 백테스팅하고 비교할 수 있도록 하며, VectorBT와 같은 라이브러리를 사용한 롱숏 전략 비교를 지원","es":"Habilita a los agentes a probar y comparar múltiples estrategias de trading en los mercados indio, estadounidense y de criptomonedas, utilizando indicadores técnicos como ema-crossover, rsi y donchian, y soportando comparaciones de estrategias largas vs cortas con bibliotecas como VectorBT","fr":"Permet aux agents de backtester et de comparer plusieurs stratégies de trading sur les marchés indien, américain et de crypto-monnaies, en utilisant des indicateurs techniques comme ema-crossover, rsi et donchian, et en supportant des comparaisons de stratégies longues vs courtes avec des bibliothèques comme VectorBT","de":"Ermächtigt Agenten, mehrere Handelsstrategien auf den indischen, US-amerikanischen und Kryptomärkten zu testen und zu vergleichen, unter Verwendung technischer Indikatoren wie ema-crossover, rsi und donchian, und unterstützt Vergleiche von langen vs kurzen Strategien mit Bibliotheken wie VectorBT","pt":"Habilita agentes a testar e comparar múltiplas estratégias de negociação em mercados Indiano, EUA e Crypto, utilizando indicadores técnicos como ema-crossover, rsi e donchian, e suportando comparações de estratégias long-vs-short com bibliotecas como VectorBT","ru":"Наделяет агентов возможностью тестировать и сравнивать несколько торговых стратегий на индийском, американском и криптовалютном рынках, используя технические индикаторы, такие как ema-crossover, rsi и donchian, и поддерживающие сравнения стратегий long-vs-short с помощью библиотек, таких как VectorBT","ar":"تمكن الوكلاء من اختبار و比較 استراتيجيات تداول متعددة في أسواق الهند والولايات المتحدة والعملات الرقمية، باستخدام المؤشرات الفنية مثل ema-crossover و rsi و donchian، ودعم مقارنة استراتيجيات طويلة مقابل قصيرة باستخدام المكتبات مثل VectorBT"},"useCases":{"en":["Backtesting trading strategies for optimal performance","Comparing multiple strategies across different markets and symbols","Optimizing strategy parameters using VectorBT''s backtesting capabilities"],"zh":["回测交易策略以获得最佳性能","比较不同市场和符号的多个策略","使用 VectorBT 的回测功能优化策略参数"],"ja":["最適なパフォーマンスを得るためのトレーディング戦略のバックテスト","異なる市場とシンボルの複数の戦略を比較","VectorBT のバックテスト機能を使用して戦略パラメータを最適化"],"ko":["최적의 성능을 얻기 위한 트레이딩 전략의 백테스팅","다른 시장과 심볼에 대한 여러 전략의 비교","VectorBT의 백테스팅 기능을 사용하여 전략 파라미터 최적화"],"es":["Prueba de estrategias de trading para un rendimiento óptimo","Comparación de múltiples estrategias en diferentes mercados y símbolos","Optimización de parámetros de estrategia utilizando las capacidades de backtesting de VectorBT"],"fr":["Test de stratégies de trading pour une performance optimale","Comparaison de plusieurs stratégies sur différents marchés et symboles","Optimisation des paramètres de stratégie en utilisant les capacités de backtesting de VectorBT"],"de":["Testen von Handelsstrategien für optimale Leistung","Vergleich mehrerer Strategien auf verschiedenen Märkten und Symbolen","Optimierung von Strategieparametern unter Verwendung der Backtesting-Funktionen von VectorBT"],"pt":["Testar estratégias de negociação para desempenho ótimo","Comparar múltiplas estratégias em diferentes mercados e símbolos","Otimizar parâmetros de estratégia usando as capacidades de backtesting do VectorBT"],"ru":["Тестирование торговых стратегий для оптимальной производительности","Сравнение нескольких стратегий на разных рынках и символах","Оптимизация параметров стратегии с помощью возможностей тестирования VectorBT"],"ar":["اختبار استراتيجيات التداول لأداء مثالي","مقارنة استراتيجيات متعددة في أسواق ورموز مختلفة","تحسين معلمات الاستراتيجية باستخدام إمكانيات اختبار VectorBT"]},"limitations":{"en":["Requires VectorBT library","Limited to Indian, US, and Crypto markets","Default strategies used if no strategies are provided"],"zh":["需要 VectorBT 库","仅限印度、美国和加密货币市场","如果没有提供策略，则使用默认策略"],"ja":["VectorBT ライブラリが必要","インド、米国、クリプト通貨市場のみ","戦略が提供されていない場合はデフォルトの戦略が使用される"],"ko":["VectorBT 라이브러리가 필요","인도, 미국, 암호화폐 시장만 해당","전략이 제공되지 않는 경우 기본 전략을 사용"],"es":["Requiere la biblioteca VectorBT","Limitado a los mercados indio, estadounidense y de criptomonedas","Estrategias predeterminadas se utilizan si no se proporcionan estrategias"],"fr":["Nécessite la bibliothèque VectorBT","Limité aux marchés indien, américain et de crypto-monnaies","Stratégies par défaut utilisées si aucune stratégie n''est fournie"],"de":["Benötigt die VectorBT-Bibliothek","Begrenzt auf die indischen, US-amerikanischen und Kryptomärkte","Standardstrategien werden verwendet, wenn keine Strategien bereitgestellt werden"],"pt":["Requer a biblioteca VectorBT","Limitado a mercados Indiano, EUA e Crypto","Estratégias padrão usadas se nenhuma estratégia for fornecida"],"ru":["Требует библиотеки VectorBT","Ограничен индийским, американским и криптовалютным рынками","Используются стратегии по умолчанию, если не предоставлены стратегии"],"ar":["يتطلب مكتبة VectorBT","محدود بالأسواق الهندية والأمريكية والعملات الرقمية","تستخدم استراتيجيات افتراضية إذا لم يتم توفير استراتيجيات"]},"version":4},"contentHash":"48d10a4fffc959a7e3ac14c33f61cc2984baab792faa